local __bundle_require, __bundle_loaded, __bundle_register, __bundle_modules = (function(superRequire)
	local loadingPlaceholder = {[{}] = true}

	local register
	local modules = {}

	local require
	local loaded = {}

	register = function(name, body)
		if not modules[name] then
			modules[name] = body
		end
	end

	require = function(name)
		local loadedModule = loaded[name]

		if loadedModule then
			if loadedModule == loadingPlaceholder then
				return nil
			end
		else
			if not modules[name] then
				if not superRequire then
					local identifier = type(name) == 'string' and '\"' .. name .. '\"' or tostring(name)
					error('Tried to require ' .. identifier .. ', but no such module has been registered')
				else
					return superRequire(name)
				end
			end

			loaded[name] = loadingPlaceholder
			loadedModule = modules[name](require, loaded, register, modules)
			loaded[name] = loadedModule
		end

		return loadedModule
	end

	return require, loaded, register, modules
end)(require)
__bundle_register("__root", function(require, _LOADED, __bundle_register, __bundle_modules)
if not shared then
	return
end

local services = {
	Players = game:GetService("Players"),
	CollectionService = game:GetService("CollectionService"),
}

if not game:IsLoaded() then
	game.Loaded:Wait()
end

-- Was a blind `task.wait(3)`. Instead wait for the client to actually be ready -- LocalPlayer +
-- PlayerScripts (where the anti-cheat lives, so Hooking can neutralize it) --
-- capped at the same 3s ceiling so worst-case behaviour is unchanged. On a normal load these exist
-- in well under a second, so this shaves ~2s off every startup.
do
	local deadline = os.clock() + 3

	repeat
		task.wait()

		local localPlayer = services.Players.LocalPlayer

		if localPlayer and localPlayer:FindFirstChild("PlayerScripts") then
			break
		end
	until os.clock() >= deadline
end

loadstring("getfenv().LPH_NO_VIRTUALIZE = function(...) return ... end")()

getfenv().PP_SCRAMBLE_NUM = function(...)
	return ...
end

getfenv().PP_SCRAMBLE_STR = function(...)
	return ...
end

getfenv().PP_SCRAMBLE_RE_NUM = function(...)
	return ...
end

---@module Utility.Profiler
local Profiler = require("Utility/Profiler")

---@module Luma
local Luma
do
	local ok, result = xpcall(function()
		return require("Luma")
	end, function(e)
		warn("[Luma/diag] require(Luma) LOAD ERROR: " .. tostring(e))
		warn("[Luma/diag] " .. debug.traceback())
		return e
	end)
	if not ok then
		return
	end
	Luma = result
end

local function initializeScript()
	if shared.Luma then
		pcall(shared.Luma.detach)

		Luma.queued = shared.Luma.queued
	end

	shared.Luma = Luma
	shared.Luma.init()
end

---@param error string
local function onInitializeError(error)
	warn("[Luma/diag] INIT ERROR: " .. tostring(error))
	warn("[Luma/diag] " .. debug.traceback())
	pcall(Luma.detach)
end

Profiler.run("Main_InitializeScript", function(...)
	return xpcall(initializeScript, onInitializeError, ...)
end)

end)
__bundle_register("Luma", function(require, _LOADED, __bundle_register, __bundle_modules)
local Luma = { queued = false, silent = false, dpscanning = false, norpc = false, verbose = false }

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.JSON
local JSON = require("Utility/JSON")

---@module Utility.TaskSpawner
local TaskSpawner = require("Utility/TaskSpawner")

---@module Utility.Environment
local Environment = require("Utility/Environment")

---@module Game.Hooking
local Hooking = require("Game/Hooking")

---@module GUI.Library
local Library = require("GUI/Library")

---@module Menu
local Menu = require("Menu")

---@module Features
local Features = require("Features")

---@module Utility.ControlModule
local ControlModule = require("Utility/ControlModule")

---@module Game.InputClient
local InputClient = require("Game/InputClient")

---@module Game.PlayerScanning
local PlayerScanning = require("Game/PlayerScanning")

---@module Game.Timings.SaveManager
local SaveManager = require("Game/Timings/SaveManager")

---@module Features.Combat.StateListener
local StateListener = require("Features/Combat/StateListener")

---@module Game.EffectDispatcher
local EffectDispatcher = require("Game/EffectDispatcher")

---@module Features.Admin
local Admin = require("Features/Admin")

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Game.KeyHandling
local KeyHandling = require("Game/KeyHandling")

---@module Game.QueuedBlocking
local QueuedBlocking = require("Game/QueuedBlocking")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Game.Timings.ModuleManager
local ModuleManager = require("Game/Timings/ModuleManager")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")

---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")

---@module Game.Wipe
local Wipe = require("Game/Wipe")

---@module Features.Automation.EchoFarm
local EchoFarm = require("Features/Automation/EchoFarm")

---@module Features.Automation.AutoLayer2
local AutoLayer2 = require("Features/Automation/AutoLayer2")

---@module Features.Automation.Objects.General
local General = require("Features/Automation/Objects/General")

local lumaMaid = Maid.new()

local LOBBY_PLACE_ID = 4111023553
local DEPTHS_PLACE_ID = 5735553160
local CHIME_LOBBY_PLACE_ID = 12559711136

local replicatedStorage = game:GetService("ReplicatedStorage")
local playersService = game:GetService("Players")

local startTimestamp = os.clock()

local function get_bloxstrap_rpc()
	local modules = replicatedStorage:FindFirstChild("Modules")
	local rpc = modules and modules:FindFirstChild("BloxstrapRPC")
	if not rpc then
		return nil
	end

	local ok, module = pcall(require, rpc)
	return ok and module or nil
end

---@note: Stops every farm but keeps its resume flag, so a reload restarts exactly one copy via the resume blocks in init.
local function stop_farms()
	local farms = {
		{ require("Features/Automation/EchoFarm"), "efdata" },
		{ require("Features/Automation/AutoLayer2"), "l2data" },
		{ require("Features/Automation/AutoTo1"), "to1data" },
		{ require("Features/Automation/AutoVoI"), "voidata" },
		{ require("Features/Automation/AutoFerryman"), "afdata" },
		{ require("Features/Automation/AutoTitus"), "titusdata" },
		{ require("Features/Automation/AutoAuthority"), "authoritydata" },
		{ require("Features/Automation/AutoDuke"), "dukedata" },
		{ require("Features/Automation/AutoMooneyrie"), "mooneyriedata" },
		{ require("Features/Automation/AutoNotes"), "notesdata" },
		{ require("Features/Automation/AutoSaramed"), "sarameddata" },
	}

	for _, farm in ipairs(farms) do
		local module, key = farm[1], farm[2]
		local saved = PersistentData.get(key)

		pcall(module.stop)

		if saved ~= nil and PersistentData.get(key) ~= saved then
			pcall(PersistentData.set, key, saved)
		end
	end
end

function Luma.init()
	local localPlayer = nil

	repeat
		task.wait()
	until game:IsLoaded()

	-- Client prep -- the loading-screen A-spam (resume-gated) and the LocalPlayer/PlayerScripts/Character
	-- wait -- now runs in the loader (luarmor VM) BEFORE the core is executed, so the client is already
	-- ready here. We just resolve LocalPlayer (instant) and hook.
	repeat
		localPlayer = playersService.LocalPlayer
		task.wait()
	until localPlayer ~= nil

	if game.PlaceId ~= LOBBY_PLACE_ID then
		-- Start the init timer here. The character wait already happened in the loader, so this measures
		-- actual script loading, not the spawn wait.
		startTimestamp = os.clock()

		Hooking.earlyInit()
	end

	if isfile and isfile("smarker.txt") then
		Luma.silent = true
	end

	if isfile and isfile("dpscanning.txt") then
		Luma.dpscanning = true
	end

	if isfile and isfile("norpc.txt") then
		Luma.norpc = true
	end

	if isfile and isfile("verbose.txt") then
		Luma.verbose = true
	end

	Library:SetSilentMode(Luma.silent)
	Library.AutomationDefaultVisible = not Luma.silent

	if game.PlaceId == CHIME_LOBBY_PLACE_ID then
		return Logger.warn("Script has initialized in the Chime lobby.")
	end

	if game.PlaceId ~= LOBBY_PLACE_ID then
		KeyHandling.init()

		Hooking.init()
	end

	CoreGuiManager.set()

	PersistentData.init()

	if game.PlaceId == LOBBY_PLACE_ID then
		Logger.warn("Script has initialized in the lobby.")
	end

	if game.PlaceId == LOBBY_PLACE_ID then
		if PersistentData.get("shslot") then
			return ServerHop.lobby()
		end

		if PersistentData.get("wdata") then
			return Wipe.lobby()
		end
	end

	PersistentData.set("shslot", nil)

	if game.PlaceId == DEPTHS_PLACE_ID then
		if PersistentData.get("wdata") then
			Wipe.depths()
		end
	end

	if PersistentData.get("efdata") then
		EchoFarm.start()
	end

	if PersistentData.get("l2data") then
		AutoLayer2.start()
	end

	if game.PlaceId == LOBBY_PLACE_ID then
		return
	end

	QueuedBlocking.init()

	SaveManager.init()

	ModuleManager.refresh()

	ControlModule.init()

	Features.init()

	Menu.init()

	PlayerScanning.init()

	StateListener.init()

	-- Single shared EffectReplicator connection for every always-on consumer (StateListener, Removal, ...).
	-- Connect AFTER they've registered their hooks above so the initial replay reaches all of them.
	EffectDispatcher.init()

	-- Developer-only admin command layer (whitelist-gated inside the module).
	pcall(function()
		Admin.init()
	end)

	-- Resume Auto Builder after a server hop (abdata survives the teleport via MemStorage). Only
	-- resumes if it was active on this same data slot; reloads the same link + target and restarts.
	if PersistentData.get("abdata") then
		task.spawn(function()
			local AutoBuilder = require("Features/Automation/AutoBuilder")

			-- Wait for the character's DataSlot to be available before checking the slot match.
			local deadline = os.clock() + 60
			repeat
				task.wait(1)
			until AutoBuilder.currentSlot() ~= nil or os.clock() >= deadline

			local build = AutoBuilder.resume()
			if build then
				pcall(function()
					require("Menu/AutoBuilderWindow").show(build, AutoBuilder.classified)
				end)
			end
		end)
	end

	-- Resume Auto To1 after a server hop / place teleport (to1data survives via MemStorage). Wait
	-- until we're in a place it can run (Etrean Luminant or the Trial arena) before restarting.
	if PersistentData.get("to1data") then
		task.spawn(function()
			local AutoTo1 = require("Features/Automation/AutoTo1")
			local deadline = os.clock() + 60
			repeat
				task.wait(1)
			until AutoTo1.inValidPlace() or os.clock() >= deadline

			if AutoTo1.inValidPlace() then
				AutoTo1.start()
			end
		end)
	end

	-- Resume Auto VoI after a server hop / place teleport (voidata survives via MemStorage). Wait until
	-- we're in a place it can run (the VoI place or the Shogun arena).
	if PersistentData.get("voidata") then
		task.spawn(function()
			local AutoVoI = require("Features/Automation/AutoVoI")
			local deadline = os.clock() + 60
			repeat
				task.wait(1)
			until AutoVoI.inValidPlace() or os.clock() >= deadline

			if AutoVoI.inValidPlace() then
				AutoVoI.start()
			end
		end)
	end

	-- Resume Auto Ferryman after a server hop (afdata survives the teleport via MemStorage). Wait
	-- until we're actually in the Eastern Luminant (ValleyExit may still be streaming in) before
	-- restarting the farm.
	if PersistentData.get("afdata") then
		task.spawn(function()
			local AutoFerryman = require("Features/Automation/AutoFerryman")
			local deadline = os.clock() + 60
			repeat
				task.wait(1)
			until AutoFerryman.inEasternLuminant() or AutoFerryman.inBossDungeon() or os.clock() >= deadline

			if AutoFerryman.inEasternLuminant() or AutoFerryman.inBossDungeon() then
				AutoFerryman.start()
			end
		end)
	end

	-- Resume Auto Titus after a server hop / merit<->dungeon teleport (titusdata survives via MemStorage).
	-- Wait until we're back in the merit hub or the Titus dungeon before restarting.
	if PersistentData.get("titusdata") then
		task.spawn(function()
			local AutoTitus = require("Features/Automation/AutoTitus")
			local deadline = os.clock() + 60
			repeat
				task.wait(1)
			until AutoTitus.inValidPlace() or os.clock() >= deadline

			if AutoTitus.inValidPlace() then
				AutoTitus.start()
			end
		end)
	end

	-- Resume Auto Authority after a server hop (authoritydata survives via MemStorage). Wait until we're
	-- back in the Eastern Luminant before restarting.
	if PersistentData.get("authoritydata") then
		task.spawn(function()
			local AutoAuthority = require("Features/Automation/AutoAuthority")
			local deadline = os.clock() + 60
			repeat
				task.wait(1)
			until AutoAuthority.inValidPlace() or os.clock() >= deadline

			if AutoAuthority.inValidPlace() then
				AutoAuthority.start()
			end
		end)
	end

	-- Resume Auto Duke after a server hop / dungeon teleport (dukedata survives via MemStorage).
	if PersistentData.get("dukedata") then
		task.spawn(function()
			local AutoDuke = require("Features/Automation/AutoDuke")
			local deadline = os.clock() + 60
			repeat
				task.wait(1)
			until AutoDuke.inValidPlace() or (localPlayer and localPlayer:GetAttribute("Dungeon")) or os.clock() >= deadline

			AutoDuke.start()
		end)
	end

	-- Resume Auto Mooneyrie after a server hop (mooneyriedata survives via MemStorage).
	if PersistentData.get("mooneyriedata") then
		task.spawn(function()
			local AutoMooneyrie = require("Features/Automation/AutoMooneyrie")
			local deadline = os.clock() + 60
			repeat
				task.wait(1)
			until AutoMooneyrie.inValidPlace() or os.clock() >= deadline

			if AutoMooneyrie.inValidPlace() then
				AutoMooneyrie.start()
			end
		end)
	end

	-- Resume Auto Notes after a server hop / wipe (notesdata survives via MemStorage).
	if PersistentData.get("notesdata") then
		task.spawn(function()
			local AutoNotes = require("Features/Automation/AutoNotes")
			local deadline = os.clock() + 60
			repeat
				task.wait(1)
			until AutoNotes.inValidPlace() or os.clock() >= deadline

			if AutoNotes.inValidPlace() then
				AutoNotes.start()
			end
		end)
	end

	-- Resume Auto Saramed after a server hop / dungeon teleport (sarameddata survives via MemStorage).
	if PersistentData.get("sarameddata") then
		task.spawn(function()
			local AutoSaramed = require("Features/Automation/AutoSaramed")
			local deadline = os.clock() + 60
			repeat
				task.wait(1)
			until AutoSaramed.inValidPlace() or os.clock() >= deadline

			if AutoSaramed.inValidPlace() then
				AutoSaramed.start()
			end
		end)
	end

	if not Luma.silent then
		Logger.notify("Script has been initialized in %ims.", (os.clock() - startTimestamp) * 1000)
	end

	if not PersistentData.get("fli") then
		PersistentData.set("fli", os.time())
	end

	local bloxstrapRPCModule = get_bloxstrap_rpc()

	if not bloxstrapRPCModule then
		return
	end

	if Luma.norpc then
		return
	end

	bloxstrapRPCModule.SetRichPresence({
		details = "Luma (Attached)",
		state = string.format(
			"Currently attached to the script - time elapsed is a session of %s time spent.",
			Environment.isTester() and "developing" or "using"
		),
		timeStart = PersistentData.get("fli") or os.time(),
		largeImage = {
			assetId = Environment.isTester() and 11289930484 or 109802578297970,
			hoverText = Environment.isTester() and "Developing Deepwoken" or "Using Deepwoken",
		},
		smallImage = {
			assetId = Environment.isTester() and 15828456271 or 17278571027,
			hoverText = Environment.isTester() and "Developing Deepwoken" or "Using Deepwoken",
		},
	})

	local playerRemovingSignal = Signal.new(playersService.PlayerRemoving)

	lumaMaid:mark(playerRemovingSignal:connect("Luma_OnLocalPlayerRemoved", function(player)
		if player ~= playersService.LocalPlayer then
			return
		end

		bloxstrapRPCModule.SetRichPresence({
			details = "",
			state = "",
			timeStart = 0,
			timeEnd = 0,
			largeImage = {
				clear = true,
			},
			smallImage = {
				clear = true,
			},
		})
	end))
end

function Luma.detach()
	pcall(lumaMaid.clean, lumaMaid)

	pcall(stop_farms)

	pcall(ModuleManager.detach)

	pcall(Menu.detach)

	pcall(QueuedBlocking.detach)

	pcall(ControlModule.detach)

	pcall(InputClient.detach)

	pcall(Features.detach)

	pcall(SaveManager.detach)

	pcall(PlayerScanning.detach)

	pcall(CoreGuiManager.clear)

	pcall(StateListener.detach)

	pcall(EffectDispatcher.detach)

	local bloxstrapRPCModule = get_bloxstrap_rpc()

	if bloxstrapRPCModule then
		pcall(bloxstrapRPCModule.SetRichPresence, {
			details = "Luma (Detached)",
			state = Environment.isTester() and "Detached from script - something broke, fixing a bug, or a hot-reload."
				or "Detached from script - something broke or a hot-reload.",
			timeStart = PersistentData.get("fli") or os.time(),
			largeImage = {
				assetId = Environment.isTester() and 11289930484 or 109802578297970,
				hoverText = Environment.isTester() and "Developing Deepwoken" or "Not Using Deepwoken",
			},
			smallImage = {
				assetId = Environment.isTester() and 15828456271 or 17278571027,
				hoverText = Environment.isTester() and "Developing Deepwoken" or "Not Using Deepwoken",
			},
		})
	end

	pcall(Hooking.detach)

	Logger.warn("Script has been detached.")
end

return Luma

end)
__bundle_register("Features/Automation/AutoSaramed", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto Saramed: a luma port of project-rain-oss's `auto_saramed.lua`, on the AutomationStruct +
-- StateMachine framework. Enters the Saramed deepdrill dungeon (via Malisae in the Eastern Luminant),
-- clears the mobs, mines the magma ore, deposits it into the drill, loots, then resets the dungeon and
-- repeats. Keeps hunger/thirst topped up (gather + craft bread, drink at the well).
--
-- Public surface:
--   AutoSaramed.start() / .stop() / .inValidPlace()  (Eastern Luminant or the Saramed dungeon)
-- Persistence key: "sarameddata" { slot, startedAt }.
local AutoSaramed = {}

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")
---@module Utility.Prompt
local Prompt = require("Utility/Prompt")
---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")
---@module Features.Game.Tweening
local Tweening = require("Features/Game/Tweening")
---@module Utility.Logger
local Logger = require("Utility/Logger")
---@module Utility.Configuration
local Configuration = require("Utility/Configuration")
---@module GUI.Library
local Library = require("GUI/Library")
---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")
---@module Utility.Maid
local Maid = require("Utility/Maid")
---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")
---@module Features.Automation.Objects.StateMachine
local StateMachine = require("Features/Automation/Objects/StateMachine")
---@module Features.Automation.Objects.AutomationStruct
local AutomationStruct = require("Features/Automation/Objects/AutomationStruct")

---@module Features.Automation.Objects.AutomationHud
local AutomationHud = require("Features/Automation/Objects/AutomationHud")
---@module Features.Automation.Objects.General
local General = require("Features/Automation/Objects/General")
---@module Features.Automation.Objects.Teleports
local Teleport = require("Features/Game/Teleport")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

local SARAMED_PLACE_ID = 8668476218 -- the deepdrill (Saramed) dungeon.
local EASTERN_PLACE_ID = 6473861193 -- Eastern Luminant (Malisae, the dungeon entrance).
local MAIN_GAME_PLACE_ID = 6032399813 -- Etrean overworld (route back to Eastern from here).
local DEPTHS_PLACE_ID = 5735553160 -- The Depths (should never be here; stop if we are).

local MOVE_ID = "AutoSaramed_Move"
local MIN_HEALTH = 0.5 -- retreat/bail on the fight at or below this health fraction (raised from PR's 0.25 -- retreat earlier, at half HP).
local DEFAULT_ATTACH_DISTANCE = 12

local running = false
local struct = nil
local combatTarget = nil
AutoSaramed.attachDistanceOverride = nil
local maid = Maid.new()
local hud, elapsedLabel = nil, nil
local autoDepositThread = nil
local disconnectHandlerSet = false
local previousAutoDefense = nil -- EnableAutoDefense state before the run, restored on stop
local routingToEastern = false

local function isSaramed()
	return game.PlaceId == SARAMED_PLACE_ID or workspace:FindFirstChild("Deepdrill") ~= nil
end

local ETREAN_REALM_ALIASES = { "EtreanLuminant", "Etrean Luminant" }

local function isEasternLuminant()
	local valleyExit = workspace:FindFirstChild("ValleyExit")
	local teleporter = valleyExit
		and (valleyExit:FindFirstChild("RealmTeleport") or valleyExit:FindFirstChild("RealmTeleporter"))
	local realm = teleporter and teleporter:GetAttribute("Realm")
	return table.find(ETREAN_REALM_ALIASES, realm) ~= nil
end

-- =========================================================================================================
-- Accessors.
-- =========================================================================================================
local function localPlayer()
	return players.LocalPlayer
end
local function character()
	local lp = localPlayer()
	return lp and lp.Character
end
local function root()
	local c = character()
	return c and c:FindFirstChild("HumanoidRootPart")
end
local function attachDistance()
	return math.clamp(
		tonumber(AutoSaramed.attachDistanceOverride)
			or tonumber(Configuration.expectOptionValue("SaramedAttachDistance"))
			or DEFAULT_ATTACH_DISTANCE,
		1,
		30
	)
end
local function humanoid()
	local c = character()
	return c and c:FindFirstChildOfClass("Humanoid")
end
local function backpack()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("Backpack")
end
local function playerGui()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end
local function currentSlot()
	local lp = localPlayer()
	return lp and lp:GetAttribute("DataSlot")
end
local function isRunning()
	return running
end
function AutoSaramed.inValidPlace()
	return game.PlaceId == SARAMED_PLACE_ID or game.PlaceId == EASTERN_PLACE_ID or game.PlaceId == MAIN_GAME_PLACE_ID
end

function AutoSaramed.getCombatTarget()
	local target = combatTarget
	local hum = target and target:FindFirstChildOfClass("Humanoid")
	if not running or not target or not target.Parent or not hum or hum.Health <= 0 then
		return nil
	end
	return target
end

local function getEffectReplicator()
	local ok, mod = pcall(function()
		return require(replicatedStorage:WaitForChild("EffectReplicator"))
	end)
	return ok and mod or nil
end

-- =========================================================================================================
-- Overlay.
-- =========================================================================================================
local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end
local function mk(class, props, parent)
	local instance = Instance.new(class)
	for k, v in pairs(props) do
		instance[k] = v
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end
local function buildOverlay()
	if hud then
		hud:show()
		return
	end
	hud = AutomationHud.new({ title = "Auto Saramed", onStop = AutoSaramed.stop })
	elapsedLabel = hud:addLine("Elapsed: 0s")
	hud:show()
end
local function destroyOverlay()
	if hud then
		hud:hide()
	end
end
local function setStage(name)
	if hud then
		hud:setStatus(name)
	end
end

local function formatDuration(seconds)
	seconds = math.floor(seconds)
	if seconds < 60 then
		return seconds .. "s"
	end
	local minutes = math.floor(seconds / 60)
	if seconds < 3600 then
		return minutes .. "m " .. (seconds % 60) .. "s"
	end
	return math.floor(minutes / 60) .. "h " .. (minutes % 60) .. "m"
end

local function runElapsed()
	while running do
		local data = PersistentData.get("sarameddata")
		if elapsedLabel and data then
			elapsedLabel.Text = "Elapsed: " .. formatDuration(math.max(0, os.time() - (data.startedAt or os.time())))
		end
		task.wait(0.5)
	end
end

-- =========================================================================================================
-- Movement + helpers.
-- =========================================================================================================
local function setSpeed(value)
	value = (Options and Options.SaramedTweenSpeed and Options.SaramedTweenSpeed.Value) or 100
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end
local function tempTween(cframe, speed)
	setSpeed(speed or 170)
	Tweening.goal(MOVE_ID, cframe, false)
	local goalPos = cframe.Position
	while running do
		local r = root()
		if r and (r.Position - goalPos).Magnitude <= 4 then
			break
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
end
local function tweenGoal(cframe, speed)
	setSpeed(speed or 100)
	Tweening.goal(MOVE_ID, cframe, false)
end
local function playerCheck(mag, custom)
	local origin = custom or (root() and root().Position)
	if not origin then
		return false
	end
	for _, player in next, players:GetPlayers() do
		if player ~= localPlayer() and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
			if (origin - player.Character.HumanoidRootPart.Position).Magnitude <= mag then
				return true
			end
		end
	end
	return false
end
local function serverHop()
	pcall(function()
		ServerHop.hop(currentSlot(), true)
	end)
end
local function playerSafeTween(cf, speed)
	if playerCheck(200) then
		serverHop()
		while task.wait() do
		end
		return
	end
	local r = root()
	if not r then
		return
	end
	local y = math.random(10000, 30000)
	r.CFrame = r.CFrame + Vector3.new(0, y, 0)
	tempTween(cf + Vector3.new(0, y, 0), speed)
	if playerCheck(200, cf.Position) then
		serverHop()
		while task.wait() do
		end
		return
	end
	r = root()
	if r then
		r.CFrame = cf
	end
	task.wait(0.3)
end
local function readyWeapon()
	pcall(function()
		character().CharacterHandler.Requests.DrawWeapon:FireServer(true)
	end)
end
local function m1Hold(state)
	local feat = struct and struct.active_features and struct.active_features["m1_hold"]
	if feat then
		feat.held = state
	end
end
local function healthCheck(percent)
	local hum = humanoid()
	return hum ~= nil and hum.Health <= (hum.MaxHealth * percent)
end
local function statValue(name)
	local c = character()
	return c and c:FindFirstChild(name)
end
local function clampCFrame(cf)
	return CFrame.new(Vector3.new(cf.Position.X, math.clamp(cf.Position.Y, 0, 1000), cf.Position.Z))
end

-- (Food/water refill removed -- hunger and thirst upkeep both dropped.)

-- =========================================================================================================
-- Combat + mining.
-- =========================================================================================================
local function foundMobs()
	for _, mob in next, workspace:WaitForChild("Live"):GetChildren() do
		if mob:GetAttribute("MOB_rich_name") then
			return true
		end
	end
	return false
end

local function closestMob()
	local live = workspace:FindFirstChild("Live")
	if not live then
		return nil
	end
	local closest, shortest = nil, math.huge
	for _, model in next, live:GetChildren() do
		if model:IsA("Model") and model ~= character() and model.Name:sub(1, 1) == "." then
			local r = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
			local hum = model:FindFirstChildOfClass("Humanoid")
			if r and hum and hum.Health > 0 then
				local torso = model:FindFirstChild("Torso")
				if not (torso and torso:FindFirstChild("RagdollAttach")) then
					local dist = (r.Position - (root() and root().Position or Vector3.zero)).Magnitude
					if dist < shortest then
						shortest = dist
						closest = model
					end
				end
			end
		end
	end
	return closest
end

local function killTarget(target)
	if not target or not target:IsA("Model") then
		return
	end
	if target.Name:match(localPlayer().Name) then
		return
	end

	combatTarget = target
	readyWeapon()
	if target:FindFirstChild("HumanoidRootPart") then
		tempTween(target.HumanoidRootPart.CFrame, 170)
	end

	local attach = task.spawn(function()
		local activeTween = false
		while running do
			if not target.Parent then
					break
				end
				local hrp = target:FindFirstChild("HumanoidRootPart")
				if not hrp then
					task.wait()
					continue
				end
				local cf
			local distance = attachDistance()
			if target.Name:lower():find("buncle") then
				cf = clampCFrame(hrp.CFrame) * CFrame.new(0, distance, 0) * CFrame.Angles(math.rad(-90), 0, 0)
			elseif target.Name:lower():find("knight") then
				cf = clampCFrame(hrp.CFrame) * CFrame.new(0, -distance, 0) * CFrame.Angles(math.rad(90), 0, 0)
			else
				cf = clampCFrame(hrp.CFrame) * CFrame.new(0, distance, 0) * CFrame.Angles(math.rad(-90), 0, 0)
			end
			local r = root()
			if r then
				r.AssemblyLinearVelocity = Vector3.zero
				if (r.Position - cf.Position).Magnitude > 30 then
					tweenGoal(cf, 100)
					activeTween = true
				else
					if activeTween then
						Tweening.stop(MOVE_ID)
						activeTween = false
					end
					r.CFrame = cf
				end
			end
			task.wait()
		end
		Tweening.stop(MOVE_ID)
	end)

	m1Hold(true)
	local startedAt = tick()
	repeat
		task.wait()
		m1Hold(true)
		local hum = target:FindFirstChildOfClass("Humanoid")
	until healthCheck(MIN_HEALTH) or target.Parent == nil or (hum and hum.Health <= 0) or (tick() - startedAt > 20) or not running
	pcall(function()
		task.cancel(attach)
	end)
	m1Hold(false)
	Tweening.stop(MOVE_ID)
	if combatTarget == target then
		combatTarget = nil
	end
	return healthCheck(MIN_HEALTH)
end

local function closestOre()
	local closest
	for _, ore in next, workspace:GetDescendants() do
		if ore:IsA("MeshPart") and ore.Name:match("MagmaOre") and ore:FindFirstChild("InteractPrompt") then
			if not closest then
				closest = ore
			elseif (root().Position - ore.Position).Magnitude < (root().Position - closest.Position).Magnitude then
				closest = ore
			end
		end
	end
	return closest
end

local function mineOre(target)
	if not target or target.Parent == nil or not target:IsA("MeshPart") or not target.Name:match("MagmaOre") then
		return false
	end
	tempTween(target.CFrame, 170)
	local r = root()
	if r then
		r.CFrame = target.CFrame
	end
	xpcall(function()
		for _ = 1, 60 do
			if not running then
				break
			end
			if root() then
				root().CFrame = target.CFrame
			end
			pcall(function()
				local prompt = target:FindFirstChild("InteractPrompt")
				if prompt then
					Prompt.interact(prompt)
				end
			end)
			task.wait()
		end
		local debounce = tick()
		repeat
			task.wait()
		until not target:FindFirstChild("InteractPrompt") or tick() - debounce > 5 or not running
	end, function() end)
	return true
end

local function depositOre()
	local deepdrill = workspace:FindFirstChild("Deepdrill")
	local dungeondrill = deepdrill and deepdrill:FindFirstChild("DungeonDrill")
	local fuelport = dungeondrill and dungeondrill:FindFirstChild("FuelPort")
	local hit = fuelport and fuelport:FindFirstChild("Hit")
	if hit then
		tempTween(hit.CFrame, 170)
		task.wait(1)
	end
end

local function grabChest()
	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		return
	end
	for _, chest in next, thrown:GetChildren() do
		if chest:FindFirstChild("Lid") then
			tempTween(chest.Lid.CFrame, 170)
			local t = tick()
			repeat
				task.wait(0.1)
				pcall(function()
					Prompt.interact(chest:FindFirstChildWhichIsA("ProximityPrompt"))
				end)
				pcall(function()
					tempTween(chest.Lid.CFrame, 170)
				end)
			until (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running or tick() - t > 5
			local t2 = tick()
			repeat
				task.wait(0.1)
			until not (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running or tick() - t2 > 5
			break
		end
	end
end

-- =========================================================================================================
-- Stages.
-- =========================================================================================================
local function pathToSaramed()
	if isSaramed() then
		return
	end
	if game.PlaceId == EASTERN_PLACE_ID or isEasternLuminant() then
		setStage("entering Saramed")
		local malisaeCF = CFrame.new(-2835.7998046875, 136.5481414794922, 3442.84814453125, 0.541101158, 0, -0.840957522, 0, 1, 0, 0.840957522, 0, 0.541101158)
		playerSafeTween(malisaeCF, 170)
		task.wait(0.5)
		repeat
			task.wait()
		until workspace.NPCs:FindFirstChild("Malisae") or not running
		pcall(function()
			Prompt.interact(workspace.NPCs.Malisae.InteractPrompt)
		end)
		task.wait(3)
		pcall(function()
			replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer({ choice = "Enter alone." })
		end)
		task.wait(5)
	end
end

local function checkPlayerStatus()
	-- Food/water upkeep removed; nothing to do here now. Kept as a no-op so the _status state's call to it
	-- stays valid.
end

local function startDungeon()
	if not isSaramed() then
		return
	end
	setStage("waiting for character")
	repeat
		task.wait()
	until character() or not running
	if not running then return end

	if not (backpack() and backpack():FindFirstChild("Pickaxe")) and not (character() and character():FindFirstChild("Pickaxe")) then
		setStage("get a pickaxe and restart")
		Logger.notify("Auto Saramed: get a pickaxe and restart.")
		repeat
			task.wait()
		until (backpack() and backpack():FindFirstChild("Pickaxe"))
			or (character() and character():FindFirstChild("Pickaxe"))
			or not running
	end
	if not running then return end

	setStage("waiting for drill area")
	local deepdrill = workspace:FindFirstChild("Deepdrill")
	local drillMachine, evatorMachine, drillSwitch, evatorSwitch
	while running do
		deepdrill = workspace:FindFirstChild("Deepdrill")
		drillMachine = deepdrill and deepdrill:FindFirstChild("DungeonDrill")
		evatorMachine = deepdrill and deepdrill:FindFirstChild("Drillevator")
		local drillSwitchModel = drillMachine and drillMachine:FindFirstChild("Switch")
		local evatorSwitchModel = evatorMachine and evatorMachine:FindFirstChild("Switch")
		drillSwitch = drillSwitchModel and drillSwitchModel:FindFirstChild("Case")
		evatorSwitch = evatorSwitchModel and evatorSwitchModel:FindFirstChild("Case")
		if drillSwitch and evatorSwitch then break end
		task.wait(0.5)
	end
	if not running then return end

	local drillDist = (drillSwitch.Position - (root() and root().Position or Vector3.zero)).Magnitude
	local evatorDist = (evatorSwitch.Position - (root() and root().Position or Vector3.zero)).Magnitude

	setStage("starting dungeon")
	-- Use the nearer switch (DungeonDrill vs Drillevator).
	local useDrill = drillDist < evatorDist
	local switchCase = useDrill and drillSwitch or evatorSwitch
	local switchObj = useDrill and drillMachine.Switch or evatorMachine.Switch
	-- Keep pressing it until the drill actually starts (mobs spawn). A single press sometimes misses -- the
	-- tween hasn't landed or the prompt is briefly out of range -- and nothing retried, so completeDungeon
	-- then waited forever on mobs that never came and the farm just stopped. Re-tween + re-press each pass.
	repeat
		if root() then
			root().CFrame = CFrame.new(root().CFrame.X, switchCase.CFrame.Y, root().CFrame.Z)
		end
		-- Nudge the stand spot 2 studs right (+X) and 1 stud forward (-Z, the lever's LookVector) relative
		-- to the lever, so we land on the interactable side instead of on top of the Case.
		tempTween(switchCase.CFrame * CFrame.new(2, 0, -1), 170)
		task.wait(1)
		pcall(function()
			Prompt.interact(switchObj.InteractPrompt)
		end)
		task.wait(2)
	until foundMobs() or not running
end

local function completeDungeon()
	if not isSaramed() then
		return
	end
	setStage("clearing mobs")
	repeat
		task.wait()
	until foundMobs() or not running

	repeat
		pcall(function()
			killTarget(closestMob())
		end)
		if healthCheck(MIN_HEALTH) or not running then
			break
		end
		task.wait()
	until not foundMobs()

	if not running or healthCheck(MIN_HEALTH) then
		return
	end

	setStage("mining ore")
	for _ = 0, 5 do
		local ore
		repeat
			ore = closestOre()
			task.wait()
		until ore ~= nil or not running
		if not running then
			break
		end
		mineOre(ore)
	end
	if not running then
		return
	end

	depositOre()

	-- Keep mining until the fuel bar is full (green).
	local function fuelFull()
		local ok, full = pcall(function()
			local bar = workspace.Deepdrill.DungeonDrill.FuelPort.Display.SurfaceGui.Bar
			return bar.BackgroundColor3:ToHex() == Color3.fromRGB(141, 239, 112):ToHex()
		end)
		return ok and full
	end
	if not fuelFull() then
		repeat
			for _, ore in next, workspace:GetDescendants() do
				if ore:IsA("MeshPart") and ore.Name:match("MagmaOre") then
					if not running then
						break
					end
					mineOre(ore)
					break
				end
			end
			depositOre()
			task.wait()
		until fuelFull() or not running
	end

	if not running then
		return
	end
	setStage("looting")
	grabChest()
end

local function resetDungeon()
	if not isSaramed() or not running then
		return
	end
	setStage("resetting dungeon")
	local deepdrill = workspace:FindFirstChild("Deepdrill")
	local dungeondrill = deepdrill and deepdrill:FindFirstChild("DungeonDrill")
	local radio = dungeondrill and dungeondrill:FindFirstChild("Radio")
	local destructibles = workspace:FindFirstChild("Destructibles")
	if not radio or not destructibles then
		return
	end

	-- Retreat uses the radio (workspace.Deepdrill.DungeonDrill.Radio), NOT the lever -- the lever is for
	-- going deeper, the radio is for retreating. Tween onto the RADIO itself (GetPivot handles part-or-model)
	-- and press E on it (same as every other interaction) until the retreat ChoicePrompt shows, then confirm.
	tempTween(radio:GetPivot(), 170)
	local vim = Instance.new("VirtualInputManager")
	repeat
		task.wait()
		pcall(function()
			vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
			task.wait(0.1)
			vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
		end)
		tempTween(radio:GetPivot(), 170)
	until (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running
	vim:Destroy()
	pcall(function()
		playerGui().ChoicePrompt.Choice:FireServer(true)
	end)

	local campfire = destructibles:FindFirstChild("Campfire")
	if not campfire then
		return
	end
	local dist = math.huge
	repeat
		task.wait()
		local part = campfire:FindFirstChildWhichIsA("Part")
		if part then
			dist = (part.Position - (root() and root().Position or Vector3.zero)).Magnitude
		end
	until dist <= 150 or not running

	if not healthCheck(0.7) then
		return
	end

	local er = getEffectReplicator()
	repeat
		tempTween(campfire.Part.CFrame, 170)
		if root() then
			root().CFrame = campfire.Part.CFrame * CFrame.new(0, 1, 0)
		end
		task.wait(1)
		pcall(function()
			Prompt.interact(campfire.InteractPrompt)
		end)
		task.wait(1)
	until (er and er:FindEffect("Resting")) or not running
	repeat
		task.wait()
	until (humanoid() and humanoid().Health >= humanoid().MaxHealth * 0.7) or not running
	local vim = Instance.new("VirtualInputManager")
	pcall(function()
		vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
		task.wait(0.1)
		vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
	end)
	task.wait(1)
	vim:Destroy()
end

-- On a Roblox disconnect (kick), keep the slot in MemStorage and server-hop to reconnect (PR resilience).
local function setupDisconnectHandler()
	if disconnectHandlerSet then
		return
	end
	disconnectHandlerSet = true
	local guiService = game:GetService("GuiService")
	maid:mark(guiService.ErrorMessageChanged:Connect(function()
		local ok, code = pcall(function()
			return guiService:GetErrorCode().Value
		end)
		if ok and code and code >= Enum.ConnectionError.DisconnectErrors.Value then
			pcall(function()
				local memStorage = game:GetService("MemStorageService")
				memStorage:SetItem("DataSlot", localPlayer():GetAttribute("DataSlot"))
			end)
			while task.wait() do
				pcall(serverHop)
			end
		end
	end))
end

-- Auto-deposit any MagmaOre we're carrying (runs the whole time we're in the dungeon).
local function startAutoDeposit()
	if autoDepositThread then
		return
	end
	autoDepositThread = task.spawn(function()
		while running do
			if isSaramed() and character() and character():FindFirstChild("MagmaOre") then
				pcall(function()
					local hit = workspace.Deepdrill.DungeonDrill.FuelPort.Hit
					firetouchinterest(character().MagmaOre, hit, 0)
					firetouchinterest(character().MagmaOre, hit, 1)
				end)
			end
			task.wait(0.2)
		end
	end)
	maid:mark(autoDepositThread)
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "path", from = "_check_area", to = "_path" },
		{ name = "status", from = "_path", to = "_status" },
		{ name = "dungeonStart", from = "_status", to = "_start_dungeon" },
		{ name = "dungeonComplete", from = "_start_dungeon", to = "_complete_dungeon" },
		{ name = "dungeonContinuation", from = "_complete_dungeon", to = "_start_dungeon" },
		{ name = "dungeonReset", from = "_complete_dungeon", to = "_reset_dungeon" },
		{ name = "fullReset", from = "_reset_dungeon", to = "_check_area" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			setStage("check area")
			setupDisconnectHandler()
			startAutoDeposit()

			-- Somehow ended up in the Depths -> stop (PR kicks here).
			if game.PlaceId == DEPTHS_PLACE_ID then
				Logger.notify("Auto Saramed: ended up in the Depths -- stopping.")
				return AutoSaramed.stop()
			end

			-- Etrean overworld -> route to Eastern.
			if game.PlaceId == MAIN_GAME_PLACE_ID and not isEasternLuminant() and not isSaramed() then
				setStage("routing to Eastern")
				routingToEastern = true
				Teleport.start("EasternLuminant")
				task.spawn(function()
					while running and not isEasternLuminant() and not isSaramed() do
						task.wait(0.5)
					end
					if not running then return end
					if Teleport.destination == "EasternLuminant" then
						Teleport.stop()
					end
					routingToEastern = false
					self:path()
				end)
				return
			end

			self:path()
		end,
		onenter_path = function(self)
			if not running then
				return
			end
			pathToSaramed()
			self:status()
		end,
		onenter_status = function(self)
			if not running then
				return
			end
			checkPlayerStatus()
			self:dungeonStart()
		end,
		onenter_start_dungeon = function(self)
			if not running then
				return
			end
			startDungeon()
			self:dungeonComplete()
		end,
		onenter_complete_dungeon = function(self)
			if not running then
				return
			end
			completeDungeon()

			-- Keep diving unless we're low or hit the bottom (2.00 depth).
			local atBottom = false
			pcall(function()
				atBottom = workspace.Deepdrill.DungeonDrill.DepthDisplay.SurfaceGui.TextLabel.Text:find("2.00") ~= nil
			end)
			if not healthCheck(MIN_HEALTH) and not atBottom then
				task.defer(function()
					self:dungeonContinuation()
				end)
			else
				task.defer(function()
					self:dungeonReset()
				end)
			end
		end,
		onenter_reset_dungeon = function(self)
			if not running then
				return
			end
			resetDungeon()
			self:fullReset()
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "auto_saramed",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"no_fall",
			"noclip",
			"fly",
			"no_fire",
			"no_stun",
			"fast_swing",
			"m1_hold",
			"auto_equip_weapon",
			"auto_log",
		},
	})
end

-- Force Auto Defense (the parry/block engine) on for the run, remembering its previous state so stopping
-- the farm puts it back to whatever it was. Auto Saramed fights the dungeon mobs, so it wants defense up.
local function applyAutoDefense()
	if not Toggles or not Toggles.EnableAutoDefense then
		return
	end
	previousAutoDefense = Toggles.EnableAutoDefense.Value
	Toggles.EnableAutoDefense:SetValue(true)
end

local function restoreAutoDefense()
	if previousAutoDefense ~= nil and Toggles and Toggles.EnableAutoDefense then
		Toggles.EnableAutoDefense:SetValue(previousAutoDefense)
	end
	previousAutoDefense = nil
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================
function AutoSaramed.start()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	if not AutoSaramed.inValidPlace() then
		return Logger.notify("Auto Saramed: not in the Eastern Luminant or the Saramed dungeon.")
	end
	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Saramed: no data slot found.")
	end

	local data = PersistentData.get("sarameddata") or {}
	data.slot = slot
	data.startedAt = data.startedAt or os.time()
	PersistentData.set("sarameddata", data)

	running = true
	combatTarget = nil
	applyAutoDefense()
	buildOverlay()
	AntiAFK.start("AutoSaramed")

	maid:mark(task.spawn(runElapsed))

	stateMachine.current = "idle"
	stateMachine.asyncState = StateMachine.NONE
	stateMachine.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function AutoSaramed.stop()
	if not running then
		return
	end
	running = false
	combatTarget = nil
	restoreAutoDefense()
	if routingToEastern and Teleport.destination == "EasternLuminant" then
		Teleport.stop()
	end
	routingToEastern = false
	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end
	Tweening.stop(MOVE_ID)
	pcall(function()
		AntiAFK.stop("AutoSaramed")
	end)
	maid:clean()
	autoDepositThread = nil
	disconnectHandlerSet = false
	destroyOverlay()
	PersistentData.set("sarameddata", nil)
end

return AutoSaramed

end)
__bundle_register("Features/Game/Teleport", function(require, _LOADED, __bundle_register, __bundle_modules)
---@note: Teleports in Deepwoken do not work the same. They lag you back, obviously. This is a utility module to handle repeatedly teleporting for a specific purpose.
local Teleport = { destination = nil, gdp = nil }

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.TaskSpawner
local TaskSpawner = require("Utility/TaskSpawner")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.Prompt
local Prompt = require("Utility/Prompt")

---@module Features.Game.Tweening
local Tweening = require("Features/Game/Tweening")

local replicatedStorage = game:GetService("ReplicatedStorage")
local runService = game:GetService("RunService")
local players = game:GetService("Players")

local tmaid = Maid.new()

Teleport.activeTween = nil

---Shared-Tweening queue id for the "Teleport To Location" glide (one slot, same mechanism the automations use).
local TELEPORT_MOVE_ID = "Teleport_SafeTween"

local DEPTHS_PLACE_ID = 5735553160
local teleportFrameCount = 0
local SPAM_FRAMES = 30
local PAUSE_FRAMES = 15
local STREAM_REQUEST_INTERVAL = 1.0
local REALM_ALIASES = {
	EasternLuminant = { "EastLuminant", "East Luminant", "EasternLuminant", "Eastern Luminant" },
	EtreanLuminant = { "EtreanLuminant", "Etrean Luminant" },
}
local REALM_TELEPORTER_PATHS = {
	{ "ValleyExit", "RealmTeleport" },
	{ "ValleyExit", "RealmTeleporter" },
}
local teleporterCache = {}
local streamRequestTimes = {}

---@note: Ported from Project Rain. Rather than waiting for the realm teleporter
local LUMINANT_TARGETS = {
	EasternLuminant = CFrame.new(
		-2637.4563,
		721.632935,
		-6722.51953,
		-0.757481456,
		0,
		-0.652856648,
		0,
		1,
		0,
		0.652856648,
		0,
		-0.757481456
	),
	EtreanLuminant = CFrame.new(-528.434814, 704.674194, -4760.4292),
}

local noClipSetByTeleport = false

---@param child Instance
local function onPlayerGuiDescendantAdded(child)
	if not child:IsA("TextLabel") then
		return
	end

	local coords = string.split(child.Text, ", ")
	local x, y, z = tonumber(coords[1]), tonumber(coords[2]), tonumber(coords[3])
	if not x or not y or not z then
		return
	end

	local position = Vector3.new(x, y, z)

	if (position - Vector3.new(-20000, 20000, -20000)).Magnitude <= 20 and Teleport.destination == "Voidheart" then
		return Teleport.stop()
	end

	if (position - Vector3.new(1596.1, 555.7, 2849.9)).Magnitude <= 20 and Teleport.destination == "LowerErisia" then
		return Teleport.stop()
	end

	if Teleport.gdp and (position - Teleport.gdp).Magnitude <= 20 and Teleport.destination == "GuildDoor" then
		return Teleport.stop()
	end
end

---@note: First instance is the entrance door. The second instance is the exit door.
---@param name string
---@return Instance?, Instance?
local function getGuildDoors(name)
	for _, instance in next, workspace:GetChildren() do
		if not instance.Name:match("GuildDoor") then
			continue
		end

		local guildName = instance:GetAttribute("GuildName")
		if not guildName then
			continue
		end

		if not guildName:lower():match(name:lower()) then
			continue
		end

		return instance, workspace:FindFirstChild(string.gsub(instance.Name, "GuildDoor", "GuildExitDoor"))
	end

	return nil
end

---@param character Model
---@param part BasePart
local function fireTouchOn(character, part)
	local hrp = character:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return
	end

	pcall(firetouchinterest, hrp, part, 0)
	pcall(firetouchinterest, hrp, part, 1)
	pcall(firetouchinterest, hrp, part, 0)
	pcall(firetouchinterest, hrp, part, 1)
end

---@note: Ported from Project Rain -- deliberately no 'Realm' attribute check.
---@return BasePart?
local function getValleyRealmTeleport()
	local valleyExit = workspace:FindFirstChild("ValleyExit")
	if not valleyExit then
		return nil
	end

	local teleporter = valleyExit:FindFirstChild("RealmTeleport") or valleyExit:FindFirstChild("RealmTeleporter")
	if not teleporter or not teleporter:IsA("BasePart") then
		return nil
	end

	return teleporter
end

---@note: Ported from Project Rain. The game rubber-bands a character it thinks
---@param character Model
local function spoofMoveDirection(character)
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then
		return
	end

	pcall(sethiddenproperty, humanoid, "MoveDirectionInternal", Vector3.one)
end

---@note: Ported from Project Rain -- stops geometry from blocking the run.
local function ensureNoClip()
	if noClipSetByTeleport then
		return
	end

	if not Toggles or not Toggles.NoClip then
		return
	end

	if Toggles.NoClip.Value then
		return
	end

	noClipSetByTeleport = true
	Toggles.NoClip:SetValue(true)
end

local function restoreNoClip()
	if not noClipSetByTeleport then
		return
	end

	noClipSetByTeleport = false

	if Toggles and Toggles.NoClip then
		Toggles.NoClip:SetValue(false)
	end
end

local function resetTeleportState()
	teleportFrameCount = 0
	teleporterCache = {}
	streamRequestTimes = {}

	restoreNoClip()
end

---@param label string
---@param position Vector3
local function requestStreamAround(label, position)
	local timestamp = os.clock()
	local lastRequestTime = streamRequestTimes[label]
	if lastRequestTime and timestamp - lastRequestTime < STREAM_REQUEST_INTERVAL then
		return
	end

	streamRequestTimes[label] = timestamp
	tmaid:add(
		TaskSpawner.spawn(
			label,
			players.LocalPlayer.RequestStreamAroundAsync,
			players.LocalPlayer,
			position,
			0.1
		)
	)
end

---@param realm string
---@param destination string
---@return boolean
local function isRealmName(realm, destination)
	for _, alias in next, REALM_ALIASES[destination] or { destination } do
		if realm == alias then
			return true
		end
	end

	return false
end

---@param path table
---@return Instance?
local function getWorkspacePath(path)
	local current = workspace
	for _, name in next, path do
		current = current:FindFirstChild(name)
		if not current then
			return nil
		end
	end

	return current
end

---@param realm string
---@return BasePart?
local function getRealmTeleporter(realm)
	local cachedTeleporter = teleporterCache[realm]
	if cachedTeleporter and cachedTeleporter.Parent and isRealmName(cachedTeleporter:GetAttribute("Realm"), realm) then
		return cachedTeleporter
	end

	for _, path in next, REALM_TELEPORTER_PATHS do
		local teleporter = getWorkspacePath(path)
		if not teleporter or not teleporter:IsA("BasePart") then
			continue
		end

		if not isRealmName(teleporter:GetAttribute("Realm"), realm) then
			continue
		end

		teleporterCache[realm] = teleporter
		return teleporter
	end

	return nil
end

---@return BasePart?
local function scanVoidheartTeleporter()
	local warpPoints = workspace:FindFirstChild("WarpPoints")
	local voidheartWarpPoint = warpPoints and warpPoints:FindFirstChild("Voidheart", true)
	if voidheartWarpPoint and voidheartWarpPoint:IsA("BasePart") then
		return voidheartWarpPoint
	end
	local warpPart = voidheartWarpPoint and voidheartWarpPoint:FindFirstChildWhichIsA("BasePart", true)
	if warpPart then
		return warpPart
	end

	local voidheart = workspace:FindFirstChild("Voidheart")
	local voidheartVoidWarp = voidheart and voidheart:FindFirstChild("VoidheartVoidWarp", true)
	if voidheartVoidWarp and voidheartVoidWarp:IsA("BasePart") then
		return voidheartVoidWarp
	end
	local voidWarpPart = voidheartVoidWarp and voidheartVoidWarp:FindFirstChildWhichIsA("BasePart", true)
	if voidWarpPart then
		return voidWarpPart
	end

	return nil
end

---@return BasePart?
local function getVoidheartTeleporter()
	local cachedTeleporter = teleporterCache.Voidheart
	if cachedTeleporter and cachedTeleporter.Parent then
		return cachedTeleporter
	end

	local teleporter = scanVoidheartTeleporter()
	if teleporter then
		teleporterCache.Voidheart = teleporter
	end

	return teleporter
end

local onTeleportLoop = LPH_NO_VIRTUALIZE(function()
	local dest = Teleport.destination
	if not dest then
		return
	end

	local localPlayer = players.LocalPlayer
	local character = localPlayer.Character
	if not character then
		return
	end

	---@note: Ported from Project Rain. We move onto the destination every frame
	local luminantTarget = LUMINANT_TARGETS[dest]
	if luminantTarget then
		requestStreamAround(string.format("Teleport_%sStream", dest), luminantTarget.Position)

		ensureNoClip()
		spoofMoveDirection(character)

		local hrp = character:FindFirstChild("HumanoidRootPart")
		if not hrp then
			return
		end

		hrp.AssemblyLinearVelocity = Vector3.one * (math.random() / 100)
		hrp.CFrame = luminantTarget * CFrame.new(math.random() / 100, math.random() / 100, math.random() / 100)

		local realmTeleport = getValleyRealmTeleport()
		if realmTeleport then
			fireTouchOn(character, realmTeleport)
		end

		return
	end

	if dest == "Depths" then
		if game.PlaceId == DEPTHS_PLACE_ID then
			return Teleport.stop()
		end

		requestStreamAround("Teleport_DepthsStream", Vector3.new(39911.3672, 39980.9375, 39708.3203))

		local modOffice = workspace:FindFirstChild("ModOffice", true)
		local officePit = modOffice and modOffice:FindFirstChild("OfficePit", true)
		local officePitPart = officePit and (
			officePit:IsA("BasePart") and officePit
			or officePit:FindFirstChildWhichIsA("BasePart", true)
		)
		local hrp = character:FindFirstChild("HumanoidRootPart")
		if not officePitPart or not hrp then
			return
		end

		ensureNoClip()
		spoofMoveDirection(character)
		hrp.AssemblyLinearVelocity = Vector3.one * (math.random() / 100)
		hrp.CFrame = officePitPart.CFrame
		fireTouchOn(character, officePitPart)
		return
	end

	if dest == "Voidheart" then
		local voidheartTeleporter = getVoidheartTeleporter()
		requestStreamAround(
			"Teleport_VoidheartStream",
			voidheartTeleporter and voidheartTeleporter.Position or Vector3.new(-20000.0, 19713.9609, -20000.0)
		)

		if not voidheartTeleporter then
			return
		end

		local vhCFrame = voidheartTeleporter.CFrame
		teleportFrameCount = teleportFrameCount + 1
		local cycleFrame = (teleportFrameCount - 1) % (SPAM_FRAMES + PAUSE_FRAMES)

		if cycleFrame < SPAM_FRAMES then
			local hrp = character:FindFirstChild("HumanoidRootPart")
			if not hrp then
				return
			end

			ensureNoClip()
			spoofMoveDirection(character)
			hrp.AssemblyLinearVelocity = Vector3.one * (math.random() / 100)
			hrp.CFrame = vhCFrame
			fireTouchOn(character, voidheartTeleporter)
			return
		end

		if cycleFrame == SPAM_FRAMES + PAUSE_FRAMES - 1 then
			local hrp = character:FindFirstChild("HumanoidRootPart")
			if hrp and (hrp.Position - vhCFrame.Position).Magnitude <= 20 then
				return Teleport.stop()
			end
		end
	end

	if dest == "TrialOfOne" then
		tmaid:add(
			TaskSpawner.spawn(
				"Teleport_TrialStream",
				players.LocalPlayer.RequestStreamAroundAsync,
				players.LocalPlayer,
				Vector3.new(-959.787659, 146.996887, -6659.63037),
				0.1
			)
		)

		local oneEntrance = workspace:FindFirstChild("OneEntrance")
		if not oneEntrance then
			return
		end

		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		if not effectReplicator then
			return
		end

		local effectReplicatorModule = require(effectReplicator)
		if not effectReplicatorModule then
			return
		end

		if effectReplicatorModule:FindEffect("Knocked") then
			return Teleport.stop()
		end

		character:PivotTo(oneEntrance.CFrame)
	end

	---@note: Ported from Project Rain. Instead of dropping below the base bounds
	if dest == "GuildDoor" then
		local guildName = Configuration.expectOptionValue("GuildDoorName")
		if not guildName or #guildName <= 0 then
			return
		end

		local entranceDoor, exitDoor = getGuildDoors(guildName)
		if not entranceDoor or not exitDoor then
			return
		end

		local hrp = character:FindFirstChild("HumanoidRootPart")
		if not hrp then
			return
		end

		if (hrp.Position - entranceDoor.Position).Magnitude < 20 then
			hrp.AssemblyLinearVelocity = Vector3.zero
			return Teleport.stop()
		end

		requestStreamAround("Teleport_GuildBaseStream", exitDoor.Position)

		ensureNoClip()
		spoofMoveDirection(character)

		hrp.CFrame = exitDoor.CFrame

		local interactPrompt = exitDoor:FindFirstChild("InteractPrompt")
			or exitDoor:FindFirstChildWhichIsA("ProximityPrompt", true)

		if interactPrompt then
			Prompt.fire(interactPrompt)
		end

		return
	end
end)

---Glide to a CFrame using the shared Tweening module -- the exact same movement the automations (Auto Titus,
---Ferryman, etc.) use. Tweening.update (driven every frame off Movement's Heartbeat) steps the root toward the
---goal at the menu "Tween Speed" slider (Options.TweenStudsPerSecond). We travel at a fixed altitude
---(TRAVEL_HEIGHT) so the glide clears map geometry, then drop straight onto the target. NoClip is forced on for
---the trip and restored after, and the Tween Speed slider is pinned to `speed` for the trip and handed back
---when the glide ends.
---@param target_cframe CFrame
---@param speed number? Pins the shared Tween Speed for this trip (restored after). Omit to use the slider as-is.
function Teleport.Safetweenstart(target_cframe, speed)
    Teleport.Safetweenstop()

    if typeof(target_cframe) ~= "CFrame" then
        return
    end

    -- Pin the shared Tween Speed slider for the trip (the automations do the same via setSpeed), remembering
    -- the user's value so we can hand it back when the glide ends.
    local previousSpeed = nil
    if speed and Options and Options.TweenStudsPerSecond then
        previousSpeed = Options.TweenStudsPerSecond.Value
        if previousSpeed ~= speed then
            Options.TweenStudsPerSecond:SetValue(speed)
        end
    end

    ensureNoClip()

    -- Travel at a fixed altitude, then drop. The shared Tweening module (smoothY off) snaps us up to the goal's
    -- Y on the first frame and glides us flat across to the column above the target.
    local TRAVEL_HEIGHT = 2000
    local travelCFrame = target_cframe.Rotation + Vector3.new(target_cframe.X, TRAVEL_HEIGHT, target_cframe.Z)
    local goalPos = travelCFrame.Position

    local cleaned = false
    local arrived = false
    local function cleanup()
        if cleaned then
            return
        end
        cleaned = true
        Tweening.stop(TELEPORT_MOVE_ID)
        -- Cancelled before arrival (manual Stop / timeout): don't leave us floating at travel height -- drop to
        -- the target's height in our current column.
        if not arrived then
            local character = players.LocalPlayer and players.LocalPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if root then
                root.AssemblyLinearVelocity = Vector3.zero
                root.CFrame = CFrame.new(root.Position.X, target_cframe.Y, root.Position.Z)
            end
        end
        restoreNoClip()
        if previousSpeed ~= nil and Options and Options.TweenStudsPerSecond then
            Options.TweenStudsPerSecond:SetValue(previousSpeed)
        end
    end

    -- Queue the goal in the shared Tweening module. swc=false: we poll arrival ourselves (like tempTween) and
    -- stop it in cleanup, so an already-on-target teleport can't leave a goal stuck in the queue.
    Tweening.goal(TELEPORT_MOVE_ID, travelCFrame, false)

    -- Timeout scaled to the trip so a long glide at a low Tween Speed can't strand us before we arrive.
    local effectiveSpeed = speed or (Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value) or 200
    local startRoot = players.LocalPlayer and players.LocalPlayer.Character
        and players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    local estDistance = startRoot and (goalPos - startRoot.Position).Magnitude or 0
    local timeout = math.max(20, estDistance / math.max(effectiveSpeed, 1) + 15)
    local startedAt = os.clock()

    -- Arrival watcher: glide to the column above the target, drop onto it, then restore noclip + Tween Speed so
    -- the caller doesn't have to press Stop.
    tmaid:add(TaskSpawner.spawn("Teleport_SafeTweenWatch", function()
        while not cleaned do
            if not Tweening.get(TELEPORT_MOVE_ID) then
                break
            end

            local character = players.LocalPlayer and players.LocalPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if root and (root.Position - goalPos).Magnitude <= 10 then
                arrived = true
                break
            end

            if os.clock() - startedAt > timeout then
                break
            end

            task.wait()
        end

        if arrived then
            Tweening.stop(TELEPORT_MOVE_ID)
            local character = players.LocalPlayer and players.LocalPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if root then
                root.AssemblyLinearVelocity = Vector3.zero
                root.CFrame = target_cframe
            end
        end

        cleanup()
    end))

    Teleport.activeTween = { stop = cleanup }
end

function Teleport.Safetweenstop()
    if Teleport.activeTween then
        Teleport.activeTween.stop()
        Teleport.activeTween = nil
    end
end

---@param destination string
function Teleport.start(destination)
	if not destination then
		return error("Destination must be provided for teleporting.")
	end

	resetTeleportState()
	Teleport.destination = destination
end

function Teleport.stop()
	resetTeleportState()
	Teleport.destination = nil
end

function Teleport.init()
	local localPlayer = players.LocalPlayer
	local playerGui = localPlayer:WaitForChild("PlayerGui")
	local descendantAddedSignal = Signal.new(playerGui.DescendantAdded)
	tmaid:mark(descendantAddedSignal:connect("Teleport_PlayerGui_DescendantAdded", onPlayerGuiDescendantAdded))

	local renderStepped = Signal.new(runService.RenderStepped)
	tmaid:mark(renderStepped:connect("Teleport_RenderStepped", onTeleportLoop))
end

function Teleport.detach()
	Teleport.Safetweenstop()
	tmaid:clean()
end

return Teleport

end)
__bundle_register("Features/Game/Tweening", function(require, _LOADED, __bundle_register, __bundle_modules)
local Tweening = { active = false, queue = {} }

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

local players = game:GetService("Players")

---@param dt number
Tweening.update = LPH_NO_VIRTUALIZE(function(dt)
	Tweening.active = false

	local current = Tweening.current()
	if not current then
		return
	end

	local part = typeof(current.goal) == "Instance" and current.goal or nil
	if part and not part.Parent then
		return Tweening.stop(current.identifier)
	end

	local localPlayer = players.LocalPlayer
	local character = localPlayer and localPlayer.Character
	if not character then
		return
	end

	local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return
	end

	Tweening.active = true

	local startPosition = humanoidRootPart.Position
	local targetCFrame = typeof(current.goal) == "Instance" and current.goal.CFrame or current.goal
	local targetPosition = targetCFrame.Position

	local distanceToTarget = (targetPosition - startPosition).Magnitude

	if distanceToTarget <= 0.01 then
		return
	end

	local direction = (targetPosition - startPosition) / distanceToTarget
	local moveDistance = (Configuration.expectOptionValue("TweenStudsPerSecond") or 200) * dt

	local newPosition = nil

	if moveDistance >= distanceToTarget then
		newPosition = targetPosition
	else
		newPosition = startPosition + (direction * moveDistance)
		if not current.smoothY then
			newPosition = Vector3.new(newPosition.X, targetPosition.Y, newPosition.Z)
		end
	end

	local rotation = (targetCFrame - targetCFrame.Position)

	local _, _, _, m00, m01, m02, m10, m11, m12, m20, m21, m22 = rotation:GetComponents()

	if
		m00 == m00
		and m01 == m01
		and m02 == m02
		and m10 == m10
		and m11 == m11
		and m12 == m12
		and m20 == m20
		and m21 == m21
		and m22 == m22
	then
		humanoidRootPart.CFrame = CFrame.new(newPosition) * rotation
	else
		humanoidRootPart.CFrame = CFrame.new(newPosition)
	end

	local newDistanceToTarget = (targetPosition - newPosition).Magnitude

	current.reached = false

	if newDistanceToTarget >= 1.0 then
		return
	end

	if current.swc then
		return Tweening.stop(current.identifier)
	end

	current.reached = true
end)

---@param identifier string
---@return number, table?
function Tweening.get(identifier)
	for idx, data in next, Tweening.queue do
		if data.identifier ~= identifier then
			continue
		end

		return idx, data
	end

	return nil
end

---@param identifier string
function Tweening.wait(identifier)
	local _, data = Tweening.get(identifier)
	if not data then
		return
	end

	repeat
		task.wait()
	until data.reached
end

---@return table?
function Tweening.current()
	return Tweening.queue[#Tweening.queue]
end

---@param identifier string
---@param goal BasePart|CFrame
---@param swc boolean Whether or not to stop when we reach the goal.
---@param smoothY boolean? Interpolate vertical movement instead of snapping to the target height.
function Tweening.goal(identifier, goal, swc, smoothY)
	local _, data = Tweening.get(identifier)

	if data then
		data.goal = goal
		data.swc = swc
		data.smoothY = smoothY == true
		data.reached = false
	else
		table.insert(Tweening.queue, 1, {
			identifier = identifier,
			goal = goal,
			swc = swc,
			smoothY = smoothY == true,
			reached = false,
		})
	end
end

---@param identifier string
function Tweening.stop(identifier)
	local idx, _ = Tweening.get(identifier)
	if not idx then
		return
	end

	table.remove(Tweening.queue, idx)
end

---Drop every queued tween whose identifier isn't `identifier`, leaving it the sole -- and therefore the
---current() / driven -- tween. An exclusive tweener (e.g. Auto Ferryman, which already commandeers fly /
---noclip / tween-speed for its run) calls this each frame so a stale or foreign tween still sitting in
---the queue can't sit at the back and starve ours (update() only ever drives queue[#queue], so a leftover
---entry would freeze our tween until its hard timeout). No-op when ours is already the only one.
---@param identifier string
function Tweening.keepOnly(identifier)
	for idx = #Tweening.queue, 1, -1 do
		if Tweening.queue[idx].identifier ~= identifier then
			table.remove(Tweening.queue, idx)
		end
	end
end

return Tweening

end)
__bundle_register("Utility/Configuration", function(require, _LOADED, __bundle_register, __bundle_modules)
local Configuration = {}

---@param key string
---@return any?
Configuration.expectToggleValue = LPH_NO_VIRTUALIZE(function(key)
	if not Toggles then
		return nil
	end

	local toggle = Toggles[key]

	if not toggle then
		return nil
	end

	return toggle.Value
end)

---@param key string
---@return any?
Configuration.expectOptionValue = LPH_NO_VIRTUALIZE(function(key)
	if not Options then
		return nil
	end

	local option = Options[key]

	if not option then
		return nil
	end

	return option.Value
end)

---@param key string
---@return any?
Configuration.expectOptionValues = LPH_NO_VIRTUALIZE(function(key)
	if not Options then
		return nil
	end

	local option = Options[key]

	if not option then
		return nil
	end

	return option.Values
end)

---@param identifier string
---@param topLevelIdentifier string
---@return string
Configuration.identify = LPH_NO_VIRTUALIZE(function(identifier, topLevelIdentifier)
	return identifier .. topLevelIdentifier
end)

local composedKeyCache = {}

---@param identifier string
---@param topLevelIdentifier string
---@return string
local resolveKey = LPH_NO_VIRTUALIZE(function(identifier, topLevelIdentifier)
	local sub = composedKeyCache[identifier]
	if not sub then
		sub = {}
		composedKeyCache[identifier] = sub
	end

	local key = sub[topLevelIdentifier]
	if not key then
		key = identifier .. topLevelIdentifier
		sub[topLevelIdentifier] = key
	end

	return key
end)

---@param identifier string
---@param topLevelIdentifier string
---@return any
Configuration.idToggleValue = LPH_NO_VIRTUALIZE(function(identifier, topLevelIdentifier)
	if not Toggles then
		return nil
	end

	local toggle = Toggles[resolveKey(identifier, topLevelIdentifier)]
	if not toggle then
		return nil
	end

	return toggle.Value
end)

---@param identifier string
---@param topLevelIdentifier string
---@return any
Configuration.idOptionValue = LPH_NO_VIRTUALIZE(function(identifier, topLevelIdentifier)
	if not Options then
		return nil
	end

	local option = Options[resolveKey(identifier, topLevelIdentifier)]
	if not option then
		return nil
	end

	return option.Value
end)

---@param identifier string
---@param topLevelIdentifier string
---@return any
Configuration.idOptionValues = LPH_NO_VIRTUALIZE(function(identifier, topLevelIdentifier)
	if not Options then
		return nil
	end

	local option = Options[resolveKey(identifier, topLevelIdentifier)]
	if not option then
		return nil
	end

	return option.Values
end)

return Configuration

end)
__bundle_register("Utility/Prompt", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Hardened ProximityPrompt firing.
--
-- Why this exists: bare `fireproximityprompt(prompt)` "works for some users and
-- fails for others" on the SAME executor because the failures are game-state, not
-- executor. Deepwoken runs with StreamingEnabled, so a prompt's part may not be
-- streamed in for a given client yet (slower stream = further away / lower memory /
-- lower graphics / fired too soon after a teleport), and firing against a
-- streamed-out part silently no-ops. On top of that the engine enforces
-- RequiresLineOfSight / MaxActivationDistance / Enabled / HoldDuration at trigger
-- time, and whether those bite depends on the player's camera, morph/accessories
-- obstructing the line of sight, and how the executor implements the function.
--
-- Prompt.fire() removes every one of those variables: it requests streaming around
-- the prompt, forces the prompt open (LOS off, huge distance, no hold, enabled),
-- fires, then restores the originals so the game's own UI/logic is untouched.
local Prompt = {}

local players = game:GetService("Players")

---Request the world region around a part to stream in, so the part is resident
---(has physics + a valid trigger) before we fire. No-op on non-streaming games.
---@param part BasePart?
local function ensureStreamedIn(part)
	if not part then
		return
	end
	local localPlayer = players.LocalPlayer
	if not localPlayer then
		return
	end
	pcall(function()
		if localPlayer.RequestStreamingAround then
			localPlayer:RequestStreamingAround(part.Position)
		end
	end)
end

---Fire a ProximityPrompt reliably.
---@param prompt Instance? A ProximityPrompt, or any instance to search under for one.
---@return boolean fired
function Prompt.fire(prompt)
	if not prompt then
		return false
	end

	-- Accept a model/part and dig out the prompt so callers don't have to.
	if not prompt:IsA("ProximityPrompt") then
		local found = prompt:FindFirstChildWhichIsA("ProximityPrompt", true)
		if not found then
			return false
		end
		prompt = found
	end

	local part = prompt:FindFirstAncestorWhichIsA("BasePart") or prompt.Parent
	if typeof(part) == "Instance" and part:IsA("BasePart") then
		ensureStreamedIn(part)
	end

	local fireProx = fireproximityprompt

	local fired = false
	pcall(function()
		-- Snapshot the properties the engine checks at trigger time and force them
		-- into the state that always allows a fire. ProximityPrompt property writes
		-- from the client are local-only (never replicate), so this only affects our
		-- own trigger path and is restored immediately after.
		local origEnabled = prompt.Enabled
		local origLOS = prompt.RequiresLineOfSight
		local origDist = prompt.MaxActivationDistance
		local origHold = prompt.HoldDuration

		prompt.Enabled = true
		prompt.RequiresLineOfSight = false
		prompt.MaxActivationDistance = math.max(origDist, 1000)
		prompt.HoldDuration = 0

		if fireProx then
			fireProx(prompt)
			fired = true
		elseif prompt.InputHoldBegin then
			prompt:InputHoldBegin()
			task.wait(origHold or 0)
			prompt:InputHoldEnd()
			fired = true
		end

		prompt.Enabled = origEnabled
		prompt.RequiresLineOfSight = origLOS
		prompt.MaxActivationDistance = origDist
		prompt.HoldDuration = origHold
	end)

	return fired
end

-- =========================================================================================================
-- Interact-key press (used by the automations instead of firing ProximityPrompts directly).
--
-- Rather than fireproximityprompt(), the automations press the real interact key -- like a human -- after
-- they've tweened to the target. The key is configurable under the Automations panel ("Interact Key",
-- default E). We still stream the target's part in and read its HoldDuration so a hold-prompt registers.
-- =========================================================================================================
local DEFAULT_INTERACT_KEY = Enum.KeyCode.E

local function resolveInteractKey()
	local picker = Options and Options.AutomationInteractKey
	local name = picker and picker.Value
	if type(name) == "string" and name ~= "" and name ~= "None" and name ~= "N/A" then
		local ok, code = pcall(function()
			return Enum.KeyCode[name]
		end)
		if ok and code then
			return code
		end
	end
	return DEFAULT_INTERACT_KEY
end

---Press the configured interact key. `prompt` is optional, used only to stream the target in and read its
---HoldDuration (so a hold-prompt is held long enough); the actual interaction is the key press.
---@param prompt Instance?
---@return boolean pressed
function Prompt.interact(prompt)
	local holdDuration = 0

	if typeof(prompt) == "Instance" then
		local resolved = prompt
		if not resolved:IsA("ProximityPrompt") then
			resolved = resolved:FindFirstChildWhichIsA("ProximityPrompt", true)
		end
		if resolved and resolved:IsA("ProximityPrompt") then
			holdDuration = resolved.HoldDuration or 0
			local part = resolved:FindFirstAncestorWhichIsA("BasePart")
			if part then
				ensureStreamedIn(part)
			end
		elseif prompt:IsA("BasePart") then
			ensureStreamedIn(prompt)
		end
	end

	local key = resolveInteractKey()
	local pressed = false
	pcall(function()
		local vim = Instance.new("VirtualInputManager")
		vim:SendKeyEvent(true, key, false, game)
		task.wait(holdDuration + 0.06)
		vim:SendKeyEvent(false, key, false, game)
		pressed = true
	end)
	return pressed
end

return Prompt

end)
__bundle_register("Utility/TaskSpawner", function(require, _LOADED, __bundle_register, __bundle_modules)
local TaskSpawner = {}

---@module Utility.Profiler
local Profiler = require("Utility/Profiler")

---@module Utility.Logger
local Logger = require("Utility/Logger")

local RunService = game:GetService("RunService")

---@param label string
---@param delay function
---@param callback function
---@vararg any
function TaskSpawner.delay(label, delay, callback, ...)
	---@param error string
	local function onTaskFunctionError(error)
		Logger.trace("onTaskFunctionError - (%s) - %s", label, error)
	end

	local taskFunction = Profiler.wrap(
		label,
		LPH_NO_VIRTUALIZE(function(...)
			local timestamp = os.clock()

			while os.clock() - timestamp < delay() do
				RunService.RenderStepped:Wait()
			end

			return xpcall(callback, onTaskFunctionError, ...)
		end)
	)

	return task.spawn(taskFunction, ...)
end

---@param label string
---@param callback function
---@vararg any
function TaskSpawner.spawn(label, callback, ...)
	---@param error string
	local function onTaskFunctionError(error)
		Logger.trace("onTaskFunctionError - (%s) - %s", label, error)
	end

	local taskFunction = Profiler.wrap(
		label,
		LPH_NO_VIRTUALIZE(function(...)
			return xpcall(callback, onTaskFunctionError, ...)
		end)
	)

	return task.spawn(taskFunction, ...)
end

return TaskSpawner

end)
__bundle_register("Utility/Logger", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local Logger = {}
	Logger.__index = Logger

	---@module GUI.Library
	local Library = require("GUI/Library")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@param str string
	---@return function
	function Logger.mnnotify(str, ...)
		return Library:ManuallyManagedNotify(string.format(str, ...))
	end

	---@param str string
	function Logger.qnotify(str, ...)
		local quickNotificationSpeed = Configuration.expectOptionValue("QuickNotificationSpeed") or 0.5
		Library:Notify(string.format(str, ...), quickNotificationSpeed)
	end

	---@param str string
	function Logger.notify(str, ...)
		Library:Notify(string.format(str, ...), 3.0)
	end

	---@param str string
	function Logger.longNotify(str, ...)
		Library:Notify(string.format(str, ...), 30.0)
	end

	-- warn/trace are no-ops. They used to emit "[Luma Recode]"-prefixed lines to the Roblox LogService
	-- (via warn/print), which the anticheat exfiltrates from GetLogHistory and bans on. Kept as empty
	-- functions so every existing call site is a cheap no-op. Notifications (notify/qnotify/longNotify/
	-- mnnotify) still work -- they go to luma's own UI, never LogService.
	---@param str string
	function Logger.warn(str, ...) end

	---@param str string
	function Logger.trace(str, ...) end

	return Logger
end)()

end)
__bundle_register("GUI/Library", function(require, _LOADED, __bundle_register, __bundle_modules)
-- [Luma] Integrated as GUI/Library.lua for the Deepwoken build.
-- Quiet (no welcome toast) and no auto-demo window; the script builds its own window.
if getgenv then local g = getgenv(); g.LumaQuiet = true; g.LumaDemo = false end

--[[
    Matcha Modern UI library  (Roblox, executor UI library)

    QUICK START
        local Library = loadstring(game:HttpGet("<your raw url>"))()

        local Window = Library:CreateWindow({ Title = "My Script", User = game.Players.LocalPlayer.Name, License = "Lifetime" })
        local tab = Window:AddTab("Combat", "crosshair")              -- name, lucide icon, optional { Group, Pages, Order, Hidden }
        local sec = tab:AddSection("left", "Aimbot")                  -- side ("left"/"right" are balanced automatically), title, [page]
        sec:AddToggle({ Name = "Enabled", Display = "Aimbot", Callback = function(v) end }):AddKeybind({ Default = "rmb", Mode = "Hold" })
        sec:AddSlider({ Name = "FOV", Min = 0, Max = 360, Default = 90, Callback = function(v) end })
        sec:AddDropdown({ Name = "Part", Values = { "Head", "Torso" }, Default = "Head", Callback = function(v) end })
        sec:AddButton({ Name = "Do thing", Callback = function() end })
        Window:SetVisible(true)                                       -- LEFT ALT toggles it (Library:SetMenuKey("rshift") to change)

        Library.Flags["Combat.Aimbot/Enabled"]                        -- every control writes its value to Library.Flags

    ELEMENTS   AddToggle  AddSlider  AddDropdown  AddButton  AddButtonRow  AddLabel  AddColor  AddKeybind
               AddNav  AddDivider  AddTextbox  AddListBox  AddUserCard  AddInfoRow
               toggle:AddKeybind({...})  toggle:AddColorPicker({...})      (opts.Hint = true adds a "?" mark)
    WIDGETS    Library:CreateWatermark({ User })   Library:CreateHotkeyList()   Library:CreateArrayList()
               Library:CreateKeystrokes()   Library:CreateLagNotifier()   Library:CreateMusicOverlay()
               Library:CreateTargetHUD()    tab:AddSidePanel(...)   Library:CreateESPPreview(tab)
               Library:SetWidget("Watermark"|"Hotkeys"|"ArrayList"|"Keystrokes"|"Music"|"LagNotifier", bool)
    MISC       Library:Notify(title, body, seconds, icon)   Library:SetAccent(c1, c2)   Library:ApplyTheme("Ocean")
               Library:SetScale(n)  Library:SetBlur(bool)  Library:SetDarkBackground(bool)  Library:Unload()
    SECTIONS   click a section header to collapse / expand it;  tab:AddSection("left", "Title", "Page", { Collapsed = true })
    COLORS     every colour picker has a Transparency slider:  Library.Flags[flag .. "_Alpha"] (1 = solid) / "_Transparency" (0 = solid),
               picker.Alpha, and the callback receives (color, alpha). Both are saved in configs.
    CONFIGS    the config button is in the top bar of every tab; type a name + "Save config", or use Load / Overwrite / Delete on a row.
    LOOK       Library:SetGlassAlpha(0..0.9) changes how see-through the window is.
    WINDOW     drag the title bar (an outline follows your cursor, the window glides over on release),
               drag any corner to resize, Window:SetSize(w, h), Window:Toggle(), Window:SetVisible(bool)

    Features you want listed in the hotkey list / array list need  Display = "Name"  on the toggle.
    Lucide icons load in the background (getgenv().MatchaIcons = false to disable).

    LOGO: the logo is Library.LogoId. If you save your PNG as  Luma/logo.png  in your executor workspace it is used first,
          otherwise the asset id below is used (Decal ids are auto-resolved to their real image).
]]


-- cloneref hygiene: wrap every service/instance handle so the game can't detect the menu by comparing
-- a held reference against its own game:GetService(...) (identity-based detection / GetService hooks).
-- cloneref is transparent for all property, method and child access -- only `==` identity differs; it
-- falls back to a pass-through on executors without the primitive.
local cloneReference = cloneref or function(o) return o end

local Players = cloneReference(game:GetService("Players"))
local UIS = cloneReference(game:GetService("UserInputService"))
local RunService = cloneReference(game:GetService("RunService"))
local TweenService = cloneReference(game:GetService("TweenService"))
local TextService = cloneReference(game:GetService("TextService"))
local Stats = cloneReference(game:GetService("Stats"))
local CoreGui = cloneReference(game:GetService("CoreGui"))
local Lighting = cloneReference(game:GetService("Lighting"))
local Debris = cloneReference(game:GetService("Debris"))
local HttpService = cloneReference(game:GetService("HttpService"))
local LocalizationService = cloneReference(game:GetService("LocalizationService"))

local LocalPlayer = cloneReference(Players.LocalPlayer)

local genv = (getgenv and getgenv()) or _G
-- single instance
if genv.MatchaLibrary then
    pcall(function() genv.MatchaLibrary:Unload() end)
end
-- Anti-detection: keep a cloneref to whatever parent we resolve (cloneReference is defined up top with
-- the service handles) so the game can't reach our container by reference comparison, and prefer the
-- most hidden parent this executor offers.

-- Mark the ScreenGui as protected so the game's own scripts can't see it even outside a hidden
-- container. Must run BEFORE parenting on Synapse. Every variant is pcall'd; absence is just a no-op.
local function protectGui(gui)
    if syn and syn.protect_gui then
        pcall(syn.protect_gui, gui)
    end
    if protect_gui then
        pcall(protect_gui, gui)
    end
    if protectgui then
        pcall(protectgui, gui)
    end
end

-- Per-session random name: the ScreenGui carries no static "MatchaUI" string for a name scan to match.
-- Persisted in genv so a re-execution in the same session can still find + destroy the previous one.
local function randomGuiName()
    -- Random.new() (no seed) draws a fresh os-seeded sequence per call, so the name differs every
    -- session and we don't disturb the global math.random state other code relies on.
    local rng = Random.new()
    local chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
    local parts = {}
    for i = 1, rng:NextInteger(10, 18) do
        local n = rng:NextInteger(1, #chars)
        parts[i] = chars:sub(n, n)
    end
    return table.concat(parts)
end
genv.MatchaGuiName = genv.MatchaGuiName or randomGuiName()
local GUI_NAME = genv.MatchaGuiName

local function GetParent()
    -- gethui(): hidden, non-enumerable container -- the game can't :GetChildren() it. Best option and
    -- present on most modern executors; some expose the same thing under a different name.
    for _, getter in ipairs({ gethui, get_hidden_gui, gethiddenui }) do
        if getter then
            local ok, ui = pcall(getter)
            if ok and ui then
                return cloneReference(ui)
            end
        end
    end
    -- CoreGui: the game can't normally read it; with protectGui() this is safe where gethui is missing.
    local ok, cg = pcall(function() return CoreGui end)
    if ok and cg then
        return cloneReference(cg)
    end
    -- Last resort: PlayerGui IS enumerable by the game, so here we lean entirely on the random name +
    -- protectGui(); still better than erroring out with no UI.
    return cloneReference(LocalPlayer:WaitForChild("PlayerGui"))
end
pcall(function()
    local p = GetParent()
    local old = p:FindFirstChild(GUI_NAME)
    if old then old:Destroy() end
    local b = Lighting:FindFirstChild("MatchaBlur")
    if b then b:Destroy() end
    local d = Lighting:FindFirstChild("MatchaPanelDOF")
    if d then d:Destroy() end
    local cam = workspace.CurrentCamera
    local pb = cam and cam:FindFirstChild("MatchaPanelBlur")
    if pb then pb:Destroy() end
end)

local Library = {
    Flags = {},
    Options = {},
    Keybinds = {},
    Features = {},
    Widgets = {},
    Panels = {},
    PlayerStatus = {},
    Callbacks = {},
    Conns = {},
    Scale = 1,
    TopZ = 10,
    BlurOn = false,
    BlurSize = 20,
    DarkOn = false,
    DimAmount = 0.42,
    UseAccent2 = false, -- second accent colour is OFF by default; Library:SetUseAccent2(true) turns it on (never used on the sidebar, sliders or toggles)
    GlassAlpha = tonumber(genv.MatchaGlassAlpha) or 0.12, -- window transparency (0 = solid, 1 = invisible); also Library:SetGlassAlpha(n)
    GlassOff = true, -- glass is OFF by default (turn it on with the Glass toggle)
    Cards = {},      -- section cards (re-tinted when the transparency changes)
    Collapsed = {},  -- remembered collapsed sections
    TargetHudOn = false,
    TargetFollow = false,
    FontFamily = "",
    TextBoost = tonumber(genv.MatchaTextBoost) or 0, -- added to EVERY text size (getgenv().MatchaTextBoost = 2 for even bigger)
    Style = "Modern",
    ArrayCfg = { TextSize = 13, Background = true, AccentLine = false, Style = "Clean", Gradient = true, GradSpeed = 0.45 },
    Theme = {
        Background = Color3.fromRGB(25, 26, 34),
        Section = Color3.fromRGB(36, 37, 47),
        Element = Color3.fromRGB(54, 56, 68),
        ElementOff = Color3.fromRGB(60, 62, 74),
        Track = Color3.fromRGB(44, 46, 58),
        Stroke = Color3.fromRGB(255, 255, 255),
        Text = Color3.fromRGB(238, 238, 242),
        TextDim = Color3.fromRGB(152, 154, 168),
        Accent = Color3.fromRGB(255, 255, 255),
        Accent2 = Color3.fromRGB(255, 255, 255), -- stays white unless the user (or a config) changes it
        Enemy = Color3.fromRGB(255, 90, 90),
        Friend = Color3.fromRGB(120, 220, 140),
        Popup = Color3.fromRGB(28, 29, 38),
        Widget = Color3.fromRGB(17, 18, 24),
    },
    MenuKey = Enum.KeyCode.LeftAlt,
    Popup = nil,
    Dead = false,
}


local function Track(c)
    Library.Conns[#Library.Conns + 1] = c
    if Library.Scope then Library.Scope[#Library.Scope + 1] = c end -- menu-scoped: disconnected when the menu is rebuilt
    return c
end

-- fonts
-- Try these by setting getgenv().MatchaFont BEFORE executing, e.g.
--   getgenv().MatchaFont = "Montserrat"
local FAMILIES = {
    Inter = "rbxasset://fonts/families/Inter.json",
    Gotham = "rbxasset://fonts/families/GothamSSm.json",
    Montserrat = "rbxasset://fonts/families/Montserrat.json",
    Nunito = "rbxasset://fonts/families/Nunito.json",
    Roboto = "rbxasset://fonts/families/Roboto.json",
    SourceSans = "rbxasset://fonts/families/SourceSansPro.json",
    Ubuntu = "rbxasset://fonts/families/Ubuntu.json",
    Arimo = "rbxasset://fonts/families/Arimo.json",
}

-- If you have the real TTF (put it in your executor's workspace folder):
--   getgenv().MatchaFontFile = "Matcha/font.ttf"
-- Roblox needs a family json, so we generate one that points every weight at that file.
local function CustomFamily(path, boldPath)
    if not (path and writefile and getcustomasset and isfile and isfile(path)) then return nil end
    local ok, result = pcall(function()
        local asset = getcustomasset(path)
        local boldAsset = (boldPath and isfile(boldPath)) and getcustomasset(boldPath) or asset
        local faces = {}
        for _, w in ipairs({ 100, 200, 300, 400, 500, 600, 700, 800, 900 }) do
            faces[#faces + 1] = { name = tostring(w), weight = w, style = "normal", assetId = (w >= 600) and boldAsset or asset }
        end
        local jsonPath = "MatchaFont_family.json"
        writefile(jsonPath, game:GetService("HttpService"):JSONEncode({ name = "MatchaCustom", faces = faces }))
        return getcustomasset(jsonPath)
    end)
    return ok and result or nil
end

-- getgenv().MatchaFontURL = "https://.../ProggyClean.ttf"  (direct link to a .ttf)
-- downloads it once into your workspace and uses it for every weight
local fontFile = genv.MatchaFontFile
if genv.MatchaFontURL then
    fontFile = fontFile or "Matcha/font.ttf"
    pcall(function()
        if makefolder and isfolder and not isfolder("Matcha") then makefolder("Matcha") end
        if not isfile(fontFile) then writefile(fontFile, game:HttpGet(genv.MatchaFontURL)) end
    end)
end

-- optional: a separate bold TTF used for SemiBold and heavier (single-weight fonts can't get bolder otherwise)
--   getgenv().MatchaFontBoldFile = "Matcha/font_bold.ttf"   or   getgenv().MatchaFontBoldURL = "https://.../bold.ttf"
local boldFile = genv.MatchaFontBoldFile
if genv.MatchaFontBoldURL then
    boldFile = boldFile or "Matcha/font_bold.ttf"
    pcall(function()
        if makefolder and isfolder and not isfolder("Matcha") then makefolder("Matcha") end
        if not isfile(boldFile) then writefile(boldFile, game:HttpGet(genv.MatchaFontBoldURL)) end
    end)
end

-- Default to Gotham (GothamSSm): it's the engine's built-in UI font family, resident in every client, so it
-- never hits "rbxasset://fonts/families/Inter.json failed to load: temp read failed" -- some executors can't
-- read the Inter family descriptor, and because Font.new() succeeds up front (the read only fails later, at
-- render), the MakeFont pcall below can't catch it, so a bad default just spams + breaks text. Inter is still
-- available on request via getgenv().MatchaFont = "Inter".
Library.FontFamily = CustomFamily(fontFile, boldFile)
    or FAMILIES[tostring(genv.MatchaFont)]
    or tostring(genv.MatchaFont or FAMILIES.Gotham)

local function MakeFont(weight)
    local ok, f = pcall(Font.new, Library.FontFamily, weight)
    if ok and f then return f end
    return Font.new("rbxasset://fonts/families/GothamSSm.json", weight)
end
-- every weight is shifted one step heavier (set getgenv().MatchaWeightShift = false to undo)
local SHIFT = genv.MatchaWeightShift ~= false
local F_REG = MakeFont(SHIFT and Enum.FontWeight.Medium or Enum.FontWeight.Regular)
local F_MED = MakeFont(SHIFT and Enum.FontWeight.SemiBold or Enum.FontWeight.Medium)
local F_SEMI = MakeFont(SHIFT and Enum.FontWeight.Bold or Enum.FontWeight.SemiBold)
local F_BOLD = MakeFont(SHIFT and Enum.FontWeight.ExtraBold or Enum.FontWeight.Bold)
local F_HEAVY = MakeFont(Enum.FontWeight.Heavy)
-- Guard the code font. Font.fromEnum / Enum.Font.RobotoMono can be absent on executors pinned to an older
-- Roblox client, and the bare Enum index throws at load (before any pcall), which bricked the whole UI on
-- those executors after the port. Evaluate it inside a pcall and fall back to the normal UI font.
local okCode, codeFont = pcall(function() return Font.fromEnum(Enum.Font.RobotoMono) end)
local F_CODE = (okCode and codeFont) or F_MED

-- helpers
local function New(class, props, kids)
    local o = Instance.new(class)
    for k, v in pairs(props or {}) do
        if k ~= "Parent" then o[k] = v end
    end
    if props and props.TextSize and (class == "TextLabel" or class == "TextButton" or class == "TextBox") then
        o.TextSize = props.TextSize + Library.TextBoost
    end
    for _, c in ipairs(kids or {}) do c.Parent = o end
    if props and props.Parent then o.Parent = props.Parent end
    return o
end

Library.DragFade = 0 -- how see-through the window gets while you move it (0..0.95). 0 = off: fading tweens EVERY descendant on drag-start, which stutters badly on a large menu, so it is disabled by default.
Library.CloseFade = false -- fade-to-transparent on close tweens every descendant (stutters a large menu); off by default, the scale+slide still animates the close.
Library.HudAnimations = true
Library.WindowAnimating = false
Library.AutomationTasks = {}
Library.AutomationDefaultVisible = true
Library.AutomationWindowWasVisible = nil
Library.SilentMode = false
Library.SilentWindows = {}
Library.SilentWidgetVisibility = {}

function Library:IsAutomationActive()
    return next(self.AutomationTasks) ~= nil
end

function Library:SetAutomationActive(key, active)
    local wasActive = self:IsAutomationActive()
    if active then
        self.AutomationTasks[key] = true
    else
        self.AutomationTasks[key] = nil
    end

    local isActive = self:IsAutomationActive()
    if isActive then
        if not wasActive then
            self.AutomationWindowWasVisible = self.Window and self.Window:IsOpen()
        end
        if self.Window then
            self.Window:SetVisible(false)
        end
    elseif wasActive then
        local restoreVisible = self.AutomationWindowWasVisible
        if restoreVisible == nil then
            restoreVisible = self.AutomationDefaultVisible
        end
        self.AutomationWindowWasVisible = nil
        if self.Window then
            self.Window:SetVisible(restoreVisible == true)
        end
    end
end

Library.Roundness = 1 -- Library:SetRoundness(0..1.6) scales every corner radius (0 = boxy, 1 = default, 1.6 = very round)
local function Corner(o, r)
    local c = New("UICorner", { CornerRadius = UDim.new(0, r * Library.Roundness), Parent = o })
    c:SetAttribute("BaseR", r)
    return c
end

local function Stroke(o, transparency, color)
    return New("UIStroke", {
        Color = color or Library.Theme.Stroke, Transparency = transparency or 0.92, Thickness = 1,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = o,
    })
end

local function Pad(o, l, t, r, b)
    return New("UIPadding", {
        PaddingLeft = UDim.new(0, l or 0), PaddingTop = UDim.new(0, t or 0),
        PaddingRight = UDim.new(0, r or 0), PaddingBottom = UDim.new(0, b or 0), Parent = o,
    })
end

local H = Enum.FillDirection.Horizontal
local V = Enum.FillDirection.Vertical
local LEFT, CENTER, RIGHT = Enum.HorizontalAlignment.Left, Enum.HorizontalAlignment.Center, Enum.HorizontalAlignment.Right
local TOP, VCENTER, BOTTOM = Enum.VerticalAlignment.Top, Enum.VerticalAlignment.Center, Enum.VerticalAlignment.Bottom
local TLEFT, TCENTER, TRIGHT = Enum.TextXAlignment.Left, Enum.TextXAlignment.Center, Enum.TextXAlignment.Right
local WHITE = Color3.new(1, 1, 1)

local function List(o, padding, dir, ha, va)
    return New("UIListLayout", {
        Padding = UDim.new(0, padding or 0), FillDirection = dir or V,
        HorizontalAlignment = ha or LEFT, VerticalAlignment = va or TOP,
