end

local function Text(parent, text, props)
    props = props or {}
    return New("TextLabel", {
        BackgroundTransparency = 1, Text = text,
        TextColor3 = props.Color or Library.Theme.Text, TextSize = props.Size or 12,
        FontFace = props.Font or F_MED,
        TextXAlignment = props.AlignX or TLEFT,
        TextYAlignment = Enum.TextYAlignment.Center,
        Size = props.SizeUDim or UDim2.new(1, 0, 1, 0),
        Position = props.Position or UDim2.new(), AnchorPoint = props.AnchorPoint or Vector2.new(),
        RichText = true, TextTruncate = props.Truncate or Enum.TextTruncate.None, Parent = parent,
    })
