local function AutoText(parent, text, color, size, font)
    return New("TextLabel", {
        BackgroundTransparency = 1, Text = text, TextColor3 = color or Library.Theme.Text,
        TextSize = size or 12, FontFace = font or F_MED, RichText = true,
