local function Rgb(c)
    return ("rgb(%d,%d,%d)"):format(math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
end

-- text width measurement (cached). Used wherever we need FIXED sizes instead of AutomaticSize.
local MeasureCache = {}
local function Measure(text, size, font)
    text = (tostring(text):gsub("<[^>]+>", ""))
    local key = size .. "|" .. tostring(font.Weight) .. "|" .. text
    local hit = MeasureCache[key]
    if hit then return hit end
    local w
    -- SYNCHRONOUS measure only. GetTextBoundsAsync YIELDS until the font asset is
    -- registered with the client; on a cold inject a not-yet-loaded font can leave
    -- that yield hanging forever, and a pcall can't catch a dead yield -- that was the
    -- intermittent "freezes while loading" lock. GetTextSize never yields, so the build
    -- thread can't stall here. This is only a width reservation (real labels use
    -- AutomaticSize), so an Enum.Font proxy is close enough.
    pcall(function()
        local sz = size + Library.TextBoost
        w = TextService:GetTextSize(text, sz, Enum.Font.Gotham, Vector2.new(10000, sz * 2)).X
    end)
    if not w then w = #text * size * 0.58 end
    w = math.ceil(w)
    MeasureCache[key] = w
    return w
end

-- icons (Lucide)
local ICON_URL = "https://raw.githubusercontent.com/deividcomsono/lucide-roblox-direct/refs/heads/main/source.lua"
local ICON_ALIASES = {
    ["triangle-alert"] = { "triangle-alert", "alert-triangle" },
    ["wand-sparkles"] = { "wand-sparkles", "wand-2", "sparkles" },
    ["paintbrush"] = { "paintbrush", "brush", "pen-tool" },
    ["folder-tree"] = { "folder-tree", "folders", "folder" },
    ["person-standing"] = { "person-standing", "user" },
    ["settings"] = { "settings", "sliders-horizontal", "cog" },
    ["monitor"] = { "monitor", "gauge", "activity" },
    ["signal"] = { "signal", "wifi", "activity" },
    ["fingerprint"] = { "fingerprint", "fingerprint-pattern", "shield-check", "bell" },
    ["terminal"] = { "terminal", "square-terminal", "code" },
    ["crosshair"] = { "crosshair", "target" },
    ["save"] = { "save", "floppy-disk", "folder" },
    ["map-pin"] = { "map-pin", "map-pinned", "globe" },
    ["play"] = { "play", "triangle-right" },
}

local IconLabels = {}
local function ApplyIcon(img, name)
    if not name or name == "" then return end
    if name:find("rbxasset", 1, true) or name:find("http", 1, true) or name:match("^%d+$") then
        img.Image = name:match("^%d+$") and ("rbxassetid://" .. name) or name
        return
    end
    local mod = Library.IconModule
    if not mod then return end
    for _, n in ipairs(ICON_ALIASES[name] or { name }) do
        local ok, a = pcall(mod.GetAsset, n)
        if ok and a and a.Url then
            img.Image = a.Url
            if a.ImageRectSize then img.ImageRectSize = a.ImageRectSize end
            if a.ImageRectOffset then img.ImageRectOffset = a.ImageRectOffset end
            return
        end
    end
end

local function Icon(parent, name, size, color)
    local img = New("ImageLabel", {
        BackgroundTransparency = 1, Image = "", ImageColor3 = color or Library.Theme.TextDim,
        ScaleType = Enum.ScaleType.Fit, Size = UDim2.new(0, size or 12, 0, size or 12), Parent = parent,
    })
    if name and name ~= "" then
        IconLabels[#IconLabels + 1] = { Img = img, Name = name }
        ApplyIcon(img, name)
    end
    return img
end

function Library:SetIcon(img, name)
    IconLabels[#IconLabels + 1] = { Img = img, Name = name }
    ApplyIcon(img, name)
end

function Library:RefreshIcons()
    for i = #IconLabels, 1, -1 do
        local e = IconLabels[i]
        if e.Img.Parent then ApplyIcon(e.Img, e.Name) else table.remove(IconLabels, i) end
    end
end

-- bring your own icon module: needs :GetAsset(name) -> { Url, ImageRectSize, ImageRectOffset }
function Library:SetIconModule(mod)
    Library.IconModule = mod
    Library:RefreshIcons()
end

-- Opt-in diagnostics for load-time network calls: getgenv().LumaDebug = true prints a [luma-lib] marker
-- at each stage, so a freeze-on-inject can be pinned to the exact call. Silent otherwise.
local LUMA_DEBUG = (getgenv and getgenv().LumaDebug) and true or false
local function ldbg(s) if LUMA_DEBUG then warn("[luma-lib] " .. s) end end

-- Several asset/HTTP calls run in the background at load (icons, logo, drag logo). On a cold inject each
-- can BLOCK the VM instead of yielding -- game:HttpGet, game:GetObjects and PreloadAsync all can -- and a
-- pcall cannot catch a dead yield. That is the intermittent "freezes on inject" lock, raw source included.
-- Gate each behind a real readiness signal first: game loaded + a spawned Character with a HumanoidRootPart
-- means the client/server link (and HTTP) is up. Bounded, proceeds on timeout, so it never hangs itself.
local function waitForNetwork(tag)
    ldbg(tag .. ": wait game.Loaded")
    if not game:IsLoaded() then game.Loaded:Wait() end
    ldbg(tag .. ": wait character")
    local deadline = os.clock() + 60
    while not Library.Dead and os.clock() < deadline do
        local char = LocalPlayer and LocalPlayer.Character
        if char and char:FindFirstChild("HumanoidRootPart") then break end
        task.wait(0.1)
    end
    ldbg(tag .. ": ready")
end

task.spawn(function()
    if genv.MatchaIcons == false then return end
    waitForNetwork("icons")
    if Library.Dead then return end
    ldbg("icons: fetching")
    local ok, mod = pcall(function() return loadstring(game:HttpGet(ICON_URL))() end)
    ldbg("icons: done")
    if ok and type(mod) == "table" and mod.GetAsset and not Library.Dead then
        Library:SetIconModule(mod)
    end
end)

local function Chevron(parent, pos, color)
    local c = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(0, 10, 0, 8), AnchorPoint = Vector2.new(0.5, 0.5), Position = pos, Parent = parent })
    for _, r in ipairs({ 42, -42 }) do
        local l = New("Frame", {
            BackgroundColor3 = color, BorderSizePixel = 0, Size = UDim2.new(0, 6, 0, 1.5),
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, r > 0 and -2 or 2, 0.5, 0), Rotation = r, Parent = c,
        })
        Corner(l, 1)
    end
    return c
end

-- logo
-- Library.LogoId: a local file (Luma/logo.png in your executor workspace) is used first, otherwise the asset id below.
-- If the id is a Decal id (renders nothing in an ImageLabel) it is resolved to the Decal's real image automatically.
Library.LogoAsset = "rbxassetid://136865077398497"
Library.LogoId = Library.LogoAsset
pcall(function()
    local f = tostring(genv.LumaLogo or "Luma/logo.png")
    if not f:find("://", 1, true) and not f:match("^%d+$") and isfile and getcustomasset and isfile(f) then
        Library.LogoId = getcustomasset(f)
    elseif f:match("^%d+$") then
        Library.LogoId = "rbxassetid://" .. f
    end
end)
Library.LogoImages = {}

-- creates a logo ImageLabel that is kept in sync with Library.LogoId
function Library.Logo(props)
    props = props or {}
    props.Image = Library.LogoId
    local img = New("ImageLabel", props)
    Library.LogoImages[#Library.LogoImages + 1] = img
    return img
end

task.spawn(function()
    waitForNetwork("logo")
    if Library.Dead then return end
    if Library.LogoId:match("^rbxassetid://%d+$") and game.GetObjects then
        -- a Decal id renders nothing in an ImageLabel: swap in the Decal's real image
        ldbg("logo: GetObjects")
        local ok, objs = pcall(function() return game:GetObjects(Library.LogoId) end)
        local o = ok and type(objs) == "table" and objs[1] or nil
        if o and (o:IsA("Decal") or o:IsA("Texture")) and o.Texture ~= "" then
            Library.LogoId = o.Texture
            for _, img in ipairs(Library.LogoImages) do
                if img.Parent then img.Image = o.Texture end
            end
        end
        if o then pcall(function() o:Destroy() end) end
    end
    ldbg("logo: preload")
    local first
    for _, img in ipairs(Library.LogoImages) do
        if img.Parent then first = img break end
    end
    if first then
        pcall(function() game:GetService("ContentProvider"):PreloadAsync({ first }) end)
    end
end)

local function Tween(o, props, t, style, dir)
    local duration = Library.HudAnimations and (t or 0.15) or 0
    local tw = TweenService:Create(o, TweenInfo.new(duration, style or Enum.EasingStyle.Quad, dir or Enum.EasingDirection.Out), props)
    tw:Play()
    return tw
end

local function Inside(frame, pos)
    local p, s = frame.AbsolutePosition, frame.AbsoluteSize
    return pos.X >= p.X and pos.X <= p.X + s.X and pos.Y >= p.Y and pos.Y <= p.Y + s.Y
end

-- Pointer position in the same space as AbsolutePosition (the ScreenGui ignores the GUI inset,
-- and InputObject.Position does NOT, so we always use GetMouseLocation for mouse input).
local function Pt(i)
    if i and i.UserInputType == Enum.UserInputType.Touch then return Vector2.new(i.Position.X, i.Position.Y) end
    return UIS:GetMouseLocation()
end

local function BindDrag(frame, cb, onEnd)
    local dragging = false
    frame.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            if Library.WindowDragging then return end -- never grab a slider while the window is being moved
            dragging = true
            Library.ElementDragging = true            -- ...and never move the window while a slider is held
            cb(Pt(i))
        end
    end)
    Track(UIS.InputChanged:Connect(function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
            cb(Pt(i))
        end
    end))
    Track(UIS.InputEnded:Connect(function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then
            dragging = false
            Library.ElementDragging = false
            if onEnd then onEnd() end
        end
    end))
end

local function KeyName(input)
    local ut = input.UserInputType
    if ut == Enum.UserInputType.MouseButton1 then return "lmb" end
    if ut == Enum.UserInputType.MouseButton2 then return "rmb" end
    if ut == Enum.UserInputType.MouseButton3 then return "mmb" end
    if input.KeyCode ~= Enum.KeyCode.Unknown then
        local n = input.KeyCode.Name
        local map = { LeftControl = "control", RightControl = "rcontrol", LeftShift = "shift", RightShift = "rshift",
            LeftAlt = "alt", RightAlt = "ralt", Insert = "ins", Delete = "del", Return = "enter", Backspace = "bksp" }
        return (map[n] or n):lower()
    end
end

local function Cap(s) return (s:sub(1, 1):upper() .. s:sub(2)) end

-- animation core
local Anim = {}
local WindowAnim = {}
local AccentGradients = {}
local AnimTime = 0
local animationElapsed = 0
local windowAnimCleanupElapsed = 0

function Library.GetAccent2()
    return Library.UseAccent2 and Library.Theme.Accent2 or Library.Theme.Accent
end
local function AccentSeq(solid, highlight)
    local T = Library.Theme
    local c2 = highlight and T.Accent:Lerp(Color3.new(0, 0, 0), 0.55) or ((solid or not Library.UseAccent2) and T.Accent or T.Accent2)
    return ColorSequence.new({
        ColorSequenceKeypoint.new(0, T.Accent),
        ColorSequenceKeypoint.new(0.5, c2),
        ColorSequenceKeypoint.new(1, T.Accent),
    })
end

-- kind "slide": offset sweeps -1..1 ; kind "rotate": rotation spins
local function Animate(g, speed, phase, kind)
    local main = Library.CreatingWindowMain or (Library.Window and Library.Window.Main)
    if main and not g:IsDescendantOf(main) then main = nil end
    local animations = main and WindowAnim or Anim
    animations[#animations + 1] = { G = g, Speed = speed or 0.4, Phase = phase or 0, Kind = kind or "slide", WindowMain = main }
end

-- solid = true: always the primary accent only (used on the sidebar, sliders, toggles)
local function AccentGradient(parent, speed, phase, rotation, solid, highlight)
    local g = New("UIGradient", { Color = AccentSeq(solid, highlight), Rotation = rotation or 0, Parent = parent })
    if solid then g:SetAttribute("Solid", true) end
    if highlight then g:SetAttribute("Highlight", true) end
    Animate(g, speed or 0.4, phase or 0)
    AccentGradients[#AccentGradients + 1] = g
    return g
end

-- things that should always wear the accent colour (widget icons, pressed keys...): Library.Tint(instance, "ImageColor3")
local AccentTints = {}
function Library.Tint(inst, prop, darken)
    AccentTints[#AccentTints + 1] = { I = inst, P = prop, D = darken }
    inst[prop] = darken and Library.Theme.Accent:Lerp(Color3.new(0, 0, 0), darken) or Library.Theme.Accent
    return inst
end

function Library:SetAccent(c1, c2)
    Library.Theme.Accent = c1 or Library.Theme.Accent
    Library.Theme.Accent2 = c2 or Library.Theme.Accent2
    for i = #AccentTints, 1, -1 do
        local t = AccentTints[i]
        if t.I.Parent then
            local c = t.D and Library.Theme.Accent:Lerp(Color3.new(0, 0, 0), t.D) or Library.Theme.Accent
            Tween(t.I, { [t.P] = c }, 0.2)
        else
            table.remove(AccentTints, i)
        end
    end
    for i = #AccentGradients, 1, -1 do
        local g = AccentGradients[i]
        if g.Parent then g.Color = AccentSeq(g:GetAttribute("Solid"), g:GetAttribute("Highlight")) else table.remove(AccentGradients, i) end
    end
    if Library.RefreshArray then Library.RefreshArray(true) end
    if Library.SideFill and Library.SideFill.Parent then
        Tween(Library.SideFill, { BackgroundColor3 = Library.SideColor() }, 0.25)
    end
    if Library.RefreshHotkeys then Library.RefreshHotkeys() end
end

-- sidebar colour: a deep version of the window colour, washed with the accent hue (stays neutral for white/grey accents)
function Library.SideColor()
    local T = Library.Theme
    local base = T.Widget:Lerp(Color3.new(0, 0, 0), 0.55)
    local h, s = T.Accent:ToHSV()
    return base:Lerp(Color3.fromHSV(h, math.clamp(s, 0, 1), 0.55), 0.2 * s)
end

function Library:SetUseAccent2(on)
    Library.UseAccent2 = on and true or false
    Library:SetAccent(nil, nil) -- repaint every gradient
end
function Library:SetHudAnimations(on)
    Library.HudAnimations = on == true
end

local function updateAnimations(animations, window, windowVisible)
    for i = #animations, 1, -1 do
        local a = animations[i]
        if not a.G.Parent then
            table.remove(animations, i)
        elseif not a.WindowMain or (windowVisible and window.Main == a.WindowMain) then
            if a.Kind == "rotate" then
                a.G.Rotation = ((AnimTime * a.Speed + a.Phase) * 360) % 360
            else
                a.G.Offset = Vector2.new(((AnimTime * a.Speed + a.Phase) % 2) - 1, 0)
            end
        end
    end
end

Track(RunService.Heartbeat:Connect(function(dt)
    if not Library.HudAnimations or Library.WindowDragging or Library.WindowAnimating then return end
    AnimTime = AnimTime + (dt)
    animationElapsed = animationElapsed + dt
    if animationElapsed < 1 / 30 then return end
    animationElapsed = animationElapsed % (1 / 30)
    local window = Library.Window
    local windowVisible = window and window.Main and window.Main.Visible
    updateAnimations(Anim, window, windowVisible)
    if windowVisible then
        windowAnimCleanupElapsed = 0
        updateAnimations(WindowAnim, window, true)
    else
        windowAnimCleanupElapsed = windowAnimCleanupElapsed + dt
        if windowAnimCleanupElapsed >= 1 then
            windowAnimCleanupElapsed = windowAnimCleanupElapsed % 1
            updateAnimations(WindowAnim, window, false)
        end
    end
end))

-- root gui
local Camera = workspace.CurrentCamera

local Gui = New("ScreenGui", {
    Name = GUI_NAME, ResetOnSpawn = false, IgnoreGuiInset = true,
    ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 999,
})
-- Protect BEFORE parenting (Synapse requires it), then parent into the most hidden container available.
protectGui(Gui)
Gui.Parent = GetParent()
Library.Gui = Gui

do
    local vp = Camera and Camera.ViewportSize or Vector2.new(1920, 1080)
    local auto = 1 -- real Matcha is 1:1; fractional scales blur the text (use getgenv().MatchaScale or the UI Scale slider to change)
    local forced = genv.MatchaScale
    Library.Scale = tonumber(forced) or auto
end

local Root = New("Frame", {
    Name = "Root", BackgroundTransparency = 1,
    Size = UDim2.new(1 / Library.Scale, 0, 1 / Library.Scale, 0), Parent = Gui,
})
local ScaleObj = New("UIScale", { Scale = Library.Scale, Parent = Root })

function Library:SetScale(n)
    Library.Scale = n
    ScaleObj.Scale = n
    Root.Size = UDim2.new(1 / n, 0, 1 / n, 0)
end

local function Viewport()
    local v = Gui.AbsoluteSize
    if v.Y < 100 then
        local cam = workspace.CurrentCamera
        v = cam and cam.ViewportSize or Vector2.new(1920, 1080)
    end
    return v / Library.Scale
end

local Blur = New("BlurEffect", { Name = "MatchaBlur", Size = 0, Enabled = false, Parent = Lighting })
function Library:SetBlur(on)
    Library.BlurOn = on
    local vis = Library.Window ~= nil and Library.Window.Main.Visible
    Blur.Enabled = on and vis
    if on and vis then Tween(Blur, { Size = Library.BlurSize }, 0.3) end
end
function Library:SetBlurSize(n)
    Library.BlurSize = n
    if Blur.Enabled then Tween(Blur, { Size = n }, 0.2) end
end

-- panel blur (only behind the window)
-- A near-invisible glass part is stretched over the window, and a DepthOfField that only blurs things right in front of
-- the camera makes that part (and what shows through it) soft. The rest of the screen stays sharp.
Library.PanelBlurOn = genv.MatchaPanelBlur ~= false
Library.PanelBlurAmount = tonumber(genv.MatchaPanelBlurAmount) or 0.85 -- 0..1
local PB = {}
Library.PanelBlurState = PB
local panelBlurElapsed = 0
function Library:SetPanelBlur(on) Library.PanelBlurOn = on and true or false end
function Library:SetPanelBlurAmount(n) Library.PanelBlurAmount = math.clamp(tonumber(n) or 0.55, 0, 1) end
Track(RunService.RenderStepped:Connect(function(dt)
    local w = Library.Window
    local f = w and w.Main
    local cam = workspace.CurrentCamera
    if not (Library.PanelBlurOn and not Library.Dead and not Library.WindowAnimating and f and f.Parent and f.Visible and cam) then
        panelBlurElapsed = 0
        if PB.Part and PB.Part.Parent then PB.Part.Parent = nil end
        if PB.Dof and PB.Dof.Enabled then PB.Dof.Enabled = false end
        return
    end
    panelBlurElapsed = panelBlurElapsed + dt
    if panelBlurElapsed < 1 / 30 then return end
    panelBlurElapsed = panelBlurElapsed % (1 / 30)
    pcall(function()
        if not (PB.Dof and PB.Dof.Parent) then
            PB.Dof = New("DepthOfFieldEffect", {
                Name = "MatchaPanelDOF", FarIntensity = 0, FocusDistance = 51.6, InFocusRadius = 50,
                NearIntensity = Library.PanelBlurAmount, Parent = Lighting,
            })
        end
        PB.Dof.Enabled = true
        PB.Dof.NearIntensity = Library.PanelBlurAmount
        if not PB.Part then
            PB.Part = New("Part", {
                Name = "MatchaPanelBlur", Anchored = true, CanCollide = false, CanQuery = false, CanTouch = false,
                CastShadow = false, Material = Enum.Material.Glass, Transparency = 0.98, Color = Color3.new(1, 1, 1),
            })
        end
        local pos, size = f.AbsolutePosition, f.AbsoluteSize
        local m = 4 -- stay just inside the rounded corners
        local sx, sy = math.max(size.X - m * 2, 1), math.max(size.Y - m * 2, 1)
        local d = 0.25
        local look = cam.CFrame.LookVector
        local r = cam:ViewportPointToRay(pos.X + m + sx / 2, pos.Y + m + sy / 2)
        local center = r.Origin + r.Direction * (d / r.Direction:Dot(look))
        local px = 2 * d * math.tan(math.rad(cam.FieldOfView) / 2) / cam.ViewportSize.Y -- studs per pixel at depth d
        PB.Part.Size = Vector3.new(sx * px, sy * px, 0.001)
        PB.Part.CFrame = CFrame.new(center) * cam.CFrame.Rotation
        if PB.Part.Parent ~= cam then PB.Part.Parent = cam end
    end)
end))

-- backdrop dim (separate from snow)
-- The full-screen dim belongs to the "Dark Background" option. Snow is just flakes.
local Dim = New("Frame", {
    Name = "Dim", BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = Library.DimAmount,
    BorderSizePixel = 0, Size = UDim2.new(1, 0, 1, 0), ZIndex = 1, Visible = false, Parent = Root,
})

function Library:RefreshBackdrop()
    local vis = Library.Window ~= nil and Library.Window.Main.Visible
    Dim.Visible = (vis and Library.DarkOn) and true or false
end
function Library:SetRoundness(k)
    k = math.clamp(tonumber(k) or 1, 0, 1.6)
    Library.Roundness = k
    for _, d in ipairs(Library.Gui:GetDescendants()) do
        if d:IsA("UICorner") and not (d.Parent and d.Parent.Parent and tostring(d.Parent.Parent.Name):find("Shadow", 1, true)) then
            local base = d:GetAttribute("BaseR")
            if not base then
                if d.CornerRadius.Scale ~= 0 then continue end
                base = d.CornerRadius.Offset
                d:SetAttribute("BaseR", base)
            end
            d.CornerRadius = UDim.new(0, base * k)
        end
    end
end

function Library:SetDarkBackground(on)
    Library.DarkOn = on
    Library:RefreshBackdrop()
end
function Library:SetDim(a)
    Library.DimAmount = a
    Dim.BackgroundTransparency = a
end
-- window transparency: 0 = solid ... 0.9 = see-through (the Glass toggle must be on)
function Library:SetGlassAlpha(a)
    Library.GlassAlpha = math.clamp(tonumber(a) or Library.GlassAlpha, 0, 0.9)
    if Library.ApplyGlass then Library.ApplyGlass(nil) end
end

-- Drag pattern for widgets: a static diagonal hatch + soft accent glow inside the drag outline (no logo - that is main-window only).
local function AttachDragPattern(ghost, radius, step)
    step = step or 14
    local group = New("CanvasGroup", {
        Name = "DragPattern", BackgroundTransparency = 1, GroupTransparency = 1, Size = UDim2.new(1, 0, 1, 0), ZIndex = 190, Parent = ghost,
    })
    New("UICorner", { CornerRadius = radius, Parent = group })
    local glow = New("Frame", {
        BackgroundColor3 = Library.Theme.Accent, BorderSizePixel = 0, BackgroundTransparency = 0.82,
        Size = UDim2.new(1, 0, 1, 0), ZIndex = 190, Parent = group,
    })
    New("UIGradient", {
        Rotation = 90, Parent = glow,
        Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0.15) }),
    })
    local stripes = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 0), ZIndex = 190, Parent = group })
    local built
    local P = {}
    function P.Rebuild(w, h)
        if built and built.X == w and built.Y == h then return end
        built = Vector2.new(w, h)
        stripes:ClearAllChildren()
        local len = w + h
        local t, n = -h / 2 - step * 4, 0
        while t <= w + h / 2 + step * 4 do
            n = n + (1)
            New("Frame", {
                BackgroundColor3 = Library.Theme.Accent, BorderSizePixel = 0,
                BackgroundTransparency = (n % 4 == 0) and 0.72 or 0.86,
                AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(t, h / 2),
                Size = UDim2.fromOffset(len, (n % 4 == 0) and 2 or 1), Rotation = -45, ZIndex = 190, Parent = stripes,
            })
            t = t + (step)
        end
    end
    function P.Show()
        glow.BackgroundColor3 = Library.Theme.Accent
        for _, f in ipairs(stripes:GetChildren()) do f.BackgroundColor3 = Library.Theme.Accent end
        Tween(group, { GroupTransparency = 0 }, 0.3)
    end
    function P.Hide() Tween(group, { GroupTransparency = 1 }, 0.35) end
    return P
end

-- Widget dragging = same look as the main window: an outline follows the cursor, the widget glides over on release.
local function MakeDraggable(handle, target, canDrag, onStart)
    local dragging, pending, start, origin, goal, glide = false, false, nil, nil, nil, nil
    local ghost, ghostScale, ghostStroke, pattern
    local function prep()
        if ghost and ghost.Parent then return end
        local cr = target:FindFirstChildOfClass("UICorner")
        ghost = New("Frame", {
            Name = "DragGhost", BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0,
            Visible = false, ZIndex = 190, Parent = target.Parent,
        })
        New("UICorner", { CornerRadius = cr and cr.CornerRadius or UDim.new(0, 10), Parent = ghost })
        New("UIGradient", {
            Rotation = 90, Parent = ghost,
            Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.9), NumberSequenceKeypoint.new(1, 0.97) }),
        })
        ghostScale = New("UIScale", { Scale = 1, Parent = ghost })
        ghostStroke = Stroke(ghost, 1, WHITE)
        ghostStroke.Thickness = 2
        AccentGradient(ghostStroke, 0.5)
        pattern = AttachDragPattern(ghost, cr and cr.CornerRadius or UDim.new(0, 10), 28)
    end
    local function begin()
        dragging = true
        prep()
        local sc = Library.Scale
        ghost.AnchorPoint = target.AnchorPoint
        ghost.Size = UDim2.new(0, target.AbsoluteSize.X / sc, 0, target.AbsoluteSize.Y / sc)
        ghost.Position = target.Position
        ghost.Visible = true
        pattern.Rebuild(target.AbsoluteSize.X / sc, target.AbsoluteSize.Y / sc)
        pattern.Show()
        ghostScale.Scale = 0.985
        Tween(ghostScale, { Scale = 1 }, 0.35, Enum.EasingStyle.Quint)
        Tween(ghostStroke, { Transparency = 0.05 }, 0.15)
        Tween(ghost, { BackgroundTransparency = 0 }, 0.15)
        if onStart then onStart() end
    end
    handle.InputBegan:Connect(function(i)
        if i.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
        if Library.WindowDragging or Library.ElementDragging then return end
        if canDrag and not canDrag() then return end
        if glide then glide:Cancel() glide = nil end
        pending = true
        start, origin = Vector2.new(i.Position.X, i.Position.Y), target.Position
        goal = origin
    end)
    Track(UIS.InputChanged:Connect(function(i)
        if (pending or dragging) and i.UserInputType == Enum.UserInputType.MouseMovement then
            local cur = Vector2.new(i.Position.X, i.Position.Y)
            if pending and (cur - start).Magnitude >= 4 then
                pending = false
                begin()
            end
            if dragging then
                local d = (cur - start) / Library.Scale
                goal = UDim2.new(origin.X.Scale, origin.X.Offset + d.X, origin.Y.Scale, origin.Y.Offset + d.Y)
                ghost.Position = goal
            end
        end
    end))
    Track(UIS.InputEnded:Connect(function(i)
        if (pending or dragging) and i.UserInputType == Enum.UserInputType.MouseButton1 then
            pending = false
            if not dragging then return end
            dragging = false
            glide = Tween(target, { Position = goal }, 0.6, Enum.EasingStyle.Quint)
            Tween(ghost, { Position = goal, BackgroundTransparency = 1 }, 0.5, Enum.EasingStyle.Quint)
            Tween(ghostStroke, { Transparency = 1 }, 0.45)
            pattern.Hide()
            task.delay(0.55, function()
                if not dragging and ghost then ghost.Visible = false end
            end)
        end
    end))
end

-- shadows
-- Soft drop shadows built from stacked FILLED rounded rects. Each layer's alpha is solved so the
-- combined darkness in every ring follows a smooth falloff. (The old version used hollow stroked rings,
-- which left visible hairline seams - "lines" - around every widget.)
local Shadows = {}

local function Falloff(j, N) -- 1 at the edge -> 0 at the outer limit (smoothstep)
    local t = math.clamp((j - 1) / N, 0, 1)
    return 1 - t * t * (3 - 2 * t)
end

-- alpha of layer j (1 = innermost) so the cumulative darkness in ring j equals S * Falloff(j)
local function LayerAlpha(j, N, S)
    local a1 = S * Falloff(j, N)
    local a2 = S * Falloff(j + 1, N)
    return math.clamp(1 - (1 - a1) / (1 - a2), 0, 1)
end

-- opts: Spread (px of falloff), Offset (px downward), Strength (0..1), Color (default black)
-- The shadow lives in Root, follows its target every frame, hides with it and fades with its transparency.
local function Shadow(target, radius, opts)
    opts = opts or {}
    local spread = opts.Spread or 12
    local N = math.clamp(math.floor(spread * 1.6), 10, 26)
    local step = spread / N
    local dy = opts.Offset or 3
    local holder = New("Frame", {
        Name = "Shadow", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(),
        Visible = false, ZIndex = 1, Parent = Root,
    })
    local layers = {}
    for j = 1, N do
        local e = j * step
        layers[j] = New("Frame", {
            BackgroundColor3 = opts.Color or Color3.new(0, 0, 0), BackgroundTransparency = 1, BorderSizePixel = 0,
            Position = UDim2.new(0, -e, 0, -e + dy), Size = UDim2.new(1, e * 2, 1, e * 2), Parent = holder,
        })
        New("UICorner", { CornerRadius = UDim.new(0, (radius or 8) + e), Parent = layers[j] })
    end
    local window = Library.Window
    local windowMain = Library.CreatingWindowMain or (window and window.Main)
    if not (windowMain and target:IsDescendantOf(windowMain)) then windowMain = nil end
    Shadows[#Shadows + 1] = {
        Target = target, Holder = holder, Layers = layers, N = N,
        Strength = opts.Strength or 0.4, F = -1, WindowMain = windowMain,
    }
    return holder
end

-- Same look for the big window: it mirrors the target through property signals (no per-frame lag while dragging/resizing).
local function ShadowFill(target, radius, opts)
    opts = opts or {}
    local spread, S, dy = opts.Spread or 18, opts.Strength or 0.5, opts.Offset or 4
    local N = 40
    local step = spread / N
    local holder = New("Frame", {
        Name = "ShadowFill", BackgroundTransparency = 1, BorderSizePixel = 0,
        AnchorPoint = target.AnchorPoint, Position = target.Position, Size = target.Size,
        Visible = target.Visible, ZIndex = math.max(target.ZIndex - 1, 1), Parent = Root,
    })
    for j = 1, N do
        local e = j * step
        local layer = New("Frame", {
            BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1 - LayerAlpha(j, N, S),
            BorderSizePixel = 0, Position = UDim2.new(0, -e, 0, -e + dy), Size = UDim2.new(1, e * 2, 1, e * 2),
            Parent = holder,
        })
        New("UICorner", { CornerRadius = UDim.new(0, (radius or 8) + e), Parent = layer })
    end
    local function sync(force)
        if not force and Library.WindowAnimating then return end
        holder.AnchorPoint = target.AnchorPoint
        holder.Position = target.Position
        holder.Size = target.Size
        holder.Visible = target.Visible
        holder.ZIndex = math.max(target.ZIndex - 1, 1)
    end
    if target == Library.CreatingWindowMain then Library.WindowShadowSync = sync end
    for _, prop in ipairs({ "Position", "Size", "AnchorPoint", "Visible", "ZIndex" }) do
        target:GetPropertyChangedSignal(prop):Connect(function() sync() end)
    end
    target.Destroying:Connect(function() holder:Destroy() end)
    return holder
end

local shadowElapsed = 0
Track(RunService.RenderStepped:Connect(function(dt)
    shadowElapsed = shadowElapsed + dt
    if shadowElapsed < 1 / 30 then return end
    shadowElapsed = shadowElapsed % (1 / 30)
    local sc = Library.Scale
    local main = Library.Window and Library.Window.Main
    local skipWindowShadows = main and (not main.Visible or Library.WindowDragging or Library.WindowAnimating)
    for i = #Shadows, 1, -1 do
        local s = Shadows[i]
        local t, h = s.Target, s.Holder
        if not t or not h.Parent or not t:IsDescendantOf(Root) then
            h:Destroy()
            table.remove(Shadows, i)
        elseif skipWindowShadows and s.WindowMain == main then
            if h.Visible then h.Visible = false end
            s.F = -1
        elseif not t.Visible then
            if h.Visible then h.Visible = false end
            s.F = -1
        else
            local cur, top, vis = t, t, true
            while cur and cur ~= Root do
                if cur:IsA("GuiObject") and not cur.Visible then vis = false end
                top = cur
                cur = cur.Parent
            end
            local size = t.AbsoluteSize / sc
            if size.X < 2 or size.Y < 2 then vis = false end
            local f = vis and math.clamp(1 - t.BackgroundTransparency, 0, 1) or 0
            if f > 0 and t:IsA("CanvasGroup") then f = f * (1 - t.GroupTransparency) end
            if f < 0.03 then
                if h.Visible then h.Visible = false end
                s.F = -1
            else
                if not h.Visible then h.Visible = true end
                local p = (t.AbsolutePosition - Root.AbsolutePosition) / sc
                local pos = UDim2.new(0, p.X, 0, p.Y)
                if h.Position ~= pos then h.Position = pos end
                local sz = UDim2.new(0, size.X, 0, size.Y)
                if h.Size ~= sz then h.Size = sz end
                local z = math.max(top.ZIndex - 1, 1)
                if h.ZIndex ~= z then h.ZIndex = z end
                if math.abs(f - s.F) > 0.015 then
                    s.F = f
                    for j, layer in ipairs(s.Layers) do
                        layer.BackgroundTransparency = 1 - LayerAlpha(j, s.N, s.Strength * f)
                    end
                end
            end
        end
    end
end))

-- shine / pop
-- Bright sweep across a rounded element.
-- IMPORTANT: if the target is driven by a UIListLayout/AutomaticSize, a scale-sized child would be
-- laid out as a real child and corrupt the layout, so in that case the sweep is drawn as a
-- free-floating overlay on the root instead.
local function SweepOverlay(parent, radius, strength, z)
    local o = New("Frame", {
        BackgroundColor3 = WHITE, BorderSizePixel = 0, Size = UDim2.new(1, 0, 1, 0), ZIndex = z, Parent = parent,
    })
    if radius then Corner(o, radius) end
    local g = New("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, strength or 0.78), NumberSequenceKeypoint.new(1, 1),
        }),
        Rotation = 20, Offset = Vector2.new(-1, 0), Parent = o,
    })
    Tween(g, { Offset = Vector2.new(1, 0) }, 0.5, Enum.EasingStyle.Quad)
    Debris:AddItem(o, 0.6)
    return o
end

local function Shine(target, radius, strength)
    if not Library.HudAnimations or not target or not target.Parent then return end
    local layoutDriven = target.AutomaticSize ~= Enum.AutomaticSize.None
        or target:FindFirstChildOfClass("UIListLayout") ~= nil
        or target:FindFirstChildOfClass("UIGridLayout") ~= nil
    if not layoutDriven then
        SweepOverlay(target, radius, strength, target.ZIndex + 3)
        return
    end
    task.spawn(function()
        RunService.Heartbeat:Wait()
        if Library.Dead or not target.Parent then return end
        local size = target.AbsoluteSize
        if size.X < 2 or size.Y < 2 then return end
        local o = SweepOverlay(Root, radius, strength, 320)
        local sc = Library.Scale
        local rp = target.AbsolutePosition - Root.AbsolutePosition
        o.Position = UDim2.new(0, rp.X / sc, 0, rp.Y / sc)
        o.Size = UDim2.new(0, size.X / sc, 0, size.Y / sc)
    end)
end

local function Pop(o, size)
    o.Size = UDim2.new(0, size - 7, 0, size - 7)
    Tween(o, { Size = UDim2.new(0, size, 0, size) }, 0.3, Enum.EasingStyle.Back)
end

-- show/hide with a slide that can never drift, even if toggled rapidly
local RevealState = setmetatable({}, { __mode = "k" })
local function Reveal(frame, v, dy)
    local st = RevealState[frame]
    if not st then st = {}; RevealState[frame] = st end
    if st.Tween then
        st.Tween:Cancel()
        st.Tween = nil
        if st.Rest then frame.Position = st.Rest end
    end
    if v then
        if frame.Visible then return end
        st.Rest = frame.Position
        frame.Position = st.Rest + UDim2.new(0, 0, 0, dy or 14)
        frame.Visible = true
        local tw = Tween(frame, { Position = st.Rest }, 0.32, Enum.EasingStyle.Quint)
        st.Tween = tw
        tw.Completed:Connect(function() if st.Tween == tw then st.Tween = nil end end)
    else
        frame.Visible = false
    end
end

-- popups
-- Popups are CanvasGroups: they fade + scale in with a soft Quint ease and fade out instead of snapping.
local function ClosePopup(instant)
    local pp = Library.Popup
    if not pp then return end
    Library.Popup = nil
    Library.PopupClosed = { Frame = pp.Frame, T = os.clock() }
    local f = pp.Frame
    if pp.OnClose then pcall(pp.OnClose) end
    if instant == true or not f:IsA("CanvasGroup") then f.Visible = false return end
    local sc = f:FindFirstChildOfClass("UIScale")
    Tween(f, { GroupTransparency = 1 }, 0.14)
    if sc then Tween(sc, { Scale = 0.96 }, 0.14) end
    task.delay(0.15, function()
        if not (Library.Popup and Library.Popup.Frame == f) then f.Visible = false end
    end)
end

local function OpenPopup(frame, owner, onClose, ownerCloses)
    ClosePopup(true)
    local target = frame.Position
    frame.Position = target + UDim2.new(0, 0, 0, -8)
    if frame:IsA("CanvasGroup") then
        local sc = frame:FindFirstChildOfClass("UIScale") or New("UIScale", { Parent = frame })
        sc.Scale = 0.94
        frame.GroupTransparency = 1
        Tween(sc, { Scale = 1 }, 0.3, Enum.EasingStyle.Quint)
        Tween(frame, { GroupTransparency = 0 }, 0.2)
    end
    frame.Visible = true
    Tween(frame, { Position = target }, 0.3, Enum.EasingStyle.Quint)
    Library.Popup = { Frame = frame, Owner = owner, OnClose = onClose, OwnerCloses = ownerCloses, Opened = os.clock() }
end

Track(UIS.InputBegan:Connect(function(i)
    if Library.Popup and i.UserInputType == Enum.UserInputType.MouseButton1 then
        -- never close while a key is being rebound or something inside is being dragged
        if Library.ListeningKeybind or Library.ElementDragging or Library.WindowDragging then return end
        local p, pos = Library.Popup, Pt(i)
        local inOwner = p.Owner and Inside(p.Owner, pos)
        -- popups scale in over ~0.3s, so their on-screen rect is smaller at first: give them a margin (bigger while opening)
        local m = (p.Opened and os.clock() - p.Opened < 0.4) and 30 or 8
        local fp, fs = p.Frame.AbsolutePosition, p.Frame.AbsoluteSize
        local inFrame = pos.X >= fp.X - m and pos.X <= fp.X + fs.X + m and pos.Y >= fp.Y - m and pos.Y <= fp.Y + fs.Y + m
        if p.OwnerCloses and inOwner then
            ClosePopup()
        elseif not inFrame and not inOwner then
            ClosePopup()
        end
    end
end))

-- panel z-order (click to focus)
-- Panels always get EVEN z-indexes; their shadows use the odd number just below.
local function NormalizeZ()
    table.sort(Library.Panels, function(a, b) return a.ZIndex < b.ZIndex end)
    for i, p in ipairs(Library.Panels) do p.ZIndex = 8 + i * 2 end
    Library.TopZ = 8 + #Library.Panels * 2
end

local function BringToFront(frame)
    if frame.ZIndex >= Library.TopZ then return end
    Library.TopZ = Library.TopZ + (2)
    frame.ZIndex = Library.TopZ
    if Library.TopZ > 88 then NormalizeZ() end
end

local function RegisterPanel(frame)
    Library.TopZ = Library.TopZ + (2)
    frame.ZIndex = Library.TopZ
    table.insert(Library.Panels, frame)
end

Track(UIS.InputBegan:Connect(function(i)
    if i.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
    local pos, best = Pt(i), nil
    for _, p in ipairs(Library.Panels) do
        if p.Parent and p.Visible and Inside(p, pos) and (not best or p.ZIndex > best.ZIndex) then best = p end
    end
    if best then BringToFront(best) end
end))

-- elements
-- modern style helpers
ICON_ALIASES.swords = { "swords", "sword", "crosshair" }
ICON_ALIASES["sliders-horizontal"] = { "sliders-horizontal", "settings-2", "settings" }
ICON_ALIASES.keyboard = { "keyboard" }
ICON_ALIASES.droplet = { "droplet", "droplets" }
ICON_ALIASES.image = { "image", "images" }
ICON_ALIASES.layers = { "layers", "layers-2", "copy" }
ICON_ALIASES["circle-dot"] = { "circle-dot", "disc", "circle" }
ICON_ALIASES.contrast = { "contrast", "sun-moon", "moon" }
ICON_ALIASES.snowflake = { "snowflake", "sparkles" }
ICON_ALIASES["chevron-right"] = { "chevron-right", "arrow-right" }

-- objects created while a menu is being built (popups parented to Root); destroyed when the menu is rebuilt
function Library.Own(inst)
    if Library.ScopeObjs then Library.ScopeObjs[#Library.ScopeObjs + 1] = inst end
    return inst
end

function Library:SetMenuKey(name)
    name = tostring(name or ""):lower()
    local alias = {
        ins = "Insert", del = "Delete", enter = "Return", bksp = "Backspace", control = "LeftControl", rcontrol = "RightControl",
        shift = "LeftShift", rshift = "RightShift", alt = "LeftAlt", ralt = "RightAlt",
    }
    local want = alias[name]
    for _, kc in ipairs(Enum.KeyCode:GetEnumItems()) do
        if (want and kc.Name == want) or kc.Name:lower() == name then
            Library.MenuKey = kc
            return true
        end
    end
    return false
end

-- "..." button (three dots) used by the modern skin
local function DotsButton(parent)
    local b = New("TextButton", {
        Text = "", AutoButtonColor = false, BackgroundTransparency = 1, Size = UDim2.new(0, 22, 0, 20), Parent = parent,
    })
    local dots = {}
    for i = 1, 3 do
        local d = New("Frame", {
            BackgroundColor3 = Library.Theme.TextDim, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0.5, (i - 2) * 6, 0.5, 0), Size = UDim2.new(0, 3, 0, 3), Parent = b,
        })
        Corner(d, 2)
        dots[i] = d
    end
    b.MouseEnter:Connect(function() for _, d in ipairs(dots) do Tween(d, { BackgroundColor3 = Library.Theme.Text }, 0.1) end end)
    b.MouseLeave:Connect(function() for _, d in ipairs(dots) do Tween(d, { BackgroundColor3 = Library.Theme.TextDim }, 0.1) end end)
    return b
end

local function BuildElements(container, prefix, skin)
    local E = {}
    local T = Library.Theme
    local modern = skin ~= nil
    -- Deepwoken's code editor (TimingBuilderTab) parents raw instances into the section body;
    -- expose the content frame so `tab.Container` resolves on a native section.
    E.Container = container

    local function flagOf(opts)
        return opts.Flag or ((prefix and (prefix .. "/") or "") .. (opts.Name or "?"))
    end

    local rowCount = 0
    local function Row(height)
        local r = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, height), Parent = container })
        rowCount = rowCount + (1)
        if modern then
            if skin.Reveal then skin.Reveal() end
            if skin.OnRow then skin.OnRow(height) end
            if rowCount > 1 and not skin.NoDividers then
                New("Frame", {
                    BackgroundColor3 = T.Stroke, BackgroundTransparency = 0.93, BorderSizePixel = 0,
                    Size = UDim2.new(1, 0, 0, 1), Parent = r,
                })
            end
        end
        return r
    end

    -- color picker
    local function AttachColorPicker(holder, flag, default, callback, noAlpha, deferCallback)
        default = default or WHITE
        local h, s, v = default:ToHSV()
        local a = 1 -- opacity (1 = solid). The slider below the picker shows it as "Transparency".
        local obj = { Value = default, Alpha = 1, Transparency = 0 }

        local swatch = New("TextButton", {
            Text = "", AutoButtonColor = false, BackgroundColor3 = default, Size = UDim2.new(0, 18, 0, 18), Parent = holder,
        })
        Corner(swatch, 6); Stroke(swatch, 0.85)

        local pop = New("CanvasGroup", {
            Visible = false, BackgroundColor3 = T.Popup, BackgroundTransparency = 0.08,
            Size = UDim2.new(0, 172, 0, 190), ZIndex = 200, Parent = Root,
        })
        Corner(pop, 10); Stroke(pop, 0.82)
        Shadow(pop, 10, { Spread = 10, Offset = 3, Strength = 0.4 })
        Library.Own(pop)

        local sv = New("Frame", {
            BackgroundColor3 = Color3.fromHSV(h, 1, 1), Position = UDim2.new(0, 10, 0, 10),
            Size = UDim2.new(1, -20, 0, 108), ZIndex = 201, Parent = pop,
        })
        Corner(sv, 6)
        local white = New("Frame", { BackgroundColor3 = WHITE, Size = UDim2.new(1, 0, 1, 0), ZIndex = 202, Parent = sv })
        Corner(white, 6)
        New("UIGradient", { Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) }), Parent = white })
        local black = New("Frame", { BackgroundColor3 = Color3.new(0, 0, 0), Size = UDim2.new(1, 0, 1, 0), ZIndex = 203, Parent = sv })
        Corner(black, 6)
        New("UIGradient", { Rotation = 90, Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) }), Parent = black })
        local svDot = New("Frame", { BackgroundColor3 = WHITE, Size = UDim2.new(0, 8, 0, 8), AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 205, Parent = sv })
        Corner(svDot, 4); Stroke(svDot, 0.2, Color3.new(0, 0, 0))

        local hue = New("Frame", {
            BackgroundColor3 = WHITE, Position = UDim2.new(0, 10, 0, 130),
            Size = UDim2.new(1, -20, 0, 10), ZIndex = 201, Parent = pop,
        })
        Corner(hue, 5)
        local seq = {}
        for i = 0, 6 do seq[#seq + 1] = ColorSequenceKeypoint.new(i / 6, Color3.fromHSV(math.min(i / 6, 0.999), 1, 1)) end
        New("UIGradient", { Color = ColorSequence.new(seq), Parent = hue })
        local hueDot = New("Frame", { BackgroundColor3 = WHITE, Size = UDim2.new(0, 4, 1, 4), AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 205, Parent = hue })
        Corner(hueDot, 2); Stroke(hueDot, 0.2, Color3.new(0, 0, 0))

        -- transparency slider (small, under the hue bar): left = solid, right = fully transparent
        local aBack = New("Frame", {
            BackgroundColor3 = Color3.fromRGB(74, 74, 82), Position = UDim2.new(0, 10, 0, 150),
            Size = UDim2.new(1, -20, 0, 8), ZIndex = 201, Parent = pop,
        })
        Corner(aBack, 4)
        -- tiny checkerboard so transparency is visible
        for cx = 0, 10 do
            local sq = New("Frame", {
                BackgroundColor3 = Color3.fromRGB(120, 120, 128), BorderSizePixel = 0, ZIndex = 202,
                Position = UDim2.new(cx / 11, 0, (cx % 2) * 0.5, 0), Size = UDim2.new(1 / 11, 0, 0.5, 0), Parent = aBack,
            })
        end
        local aBar = New("Frame", {
            BackgroundColor3 = default, Size = UDim2.new(1, 0, 1, 0), ZIndex = 203, Parent = aBack,
        })
        Corner(aBar, 4)
        New("UIGradient", { Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) }), Parent = aBar })
        local aDot = New("Frame", { BackgroundColor3 = WHITE, Size = UDim2.new(0, 4, 1, 4), AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 205, Parent = aBack })
        Corner(aDot, 2); Stroke(aDot, 0.2, Color3.new(0, 0, 0))
        local aLbl = New("TextLabel", {
            BackgroundTransparency = 1, Text = "Transparency 0%", TextColor3 = T.TextDim, TextSize = 10, FontFace = F_MED,
            TextXAlignment = TLEFT, Position = UDim2.new(0, 10, 0, 163), Size = UDim2.new(1, -20, 0, 16), ZIndex = 201, Parent = pop,
        })

        if noAlpha then -- colours that have no use for opacity (theme colours...) hide the Transparency slider
            aBack.Visible, aLbl.Visible = false, false
            pop.Size = UDim2.new(0, 172, 0, 152)
        end

        local pendingCallback, callbackScheduled, callbackGeneration
        callbackGeneration = 0
        local function flushDragCallback()
            callbackGeneration = callbackGeneration + 1
            callbackScheduled = false
            local pending = pendingCallback
            pendingCallback = nil
            if pending and callback then
                task.spawn(callback, pending.Color, pending.Alpha)
            end
        end
        local function queueDragCallback(c, alpha, deferUntilEnd)
            pendingCallback = { Color = c, Alpha = alpha }
            if deferUntilEnd or callbackScheduled then return end
            callbackScheduled = true
            callbackGeneration = callbackGeneration + 1
            local generation = callbackGeneration
            task.delay(1 / 10, function()
                if generation == callbackGeneration then flushDragCallback() end
            end)
        end

        local function apply(fire, fromDrag)
            local c = Color3.fromHSV(h, s, v)
            obj.Value = c
            obj.Alpha, obj.Transparency = a, 1 - a
            swatch.BackgroundColor3 = c
            swatch.BackgroundTransparency = math.clamp(1 - a, 0, 0.8) -- never fully invisible, so it can still be clicked
            sv.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
            svDot.Position = UDim2.new(s, 0, 1 - v, 0)
            hueDot.Position = UDim2.new(h, 0, 0.5, 0)
            aBar.BackgroundColor3 = c
            aDot.Position = UDim2.new(1 - a, 0, 0.5, 0)
            aLbl.Text = ("Transparency %d%%"):format(math.floor((1 - a) * 100 + 0.5))
            if flag then
                Library.Flags[flag] = c
                Library.Flags[flag .. "_Alpha"] = a            -- opacity: 1 = solid
                Library.Flags[flag .. "_Transparency"] = 1 - a -- Roblox style: 0 = solid
            end
            if fire and callback then
                if fromDrag then
                    queueDragCallback(c, a, deferCallback)
                else
                    task.spawn(callback, c, a)
                end
            end
        end
        BindDrag(sv, function(p)
            s = math.clamp((p.X - sv.AbsolutePosition.X) / sv.AbsoluteSize.X, 0, 1)
            v = 1 - math.clamp((p.Y - sv.AbsolutePosition.Y) / sv.AbsoluteSize.Y, 0, 1)
            apply(true, true)
        end, flushDragCallback)
        BindDrag(hue, function(p)
            h = math.clamp((p.X - hue.AbsolutePosition.X) / hue.AbsoluteSize.X, 0, 1)
            apply(true, true)
        end, flushDragCallback)
        BindDrag(aBack, function(p)
            a = 1 - math.clamp((p.X - aBack.AbsolutePosition.X) / aBack.AbsoluteSize.X, 0, 1)
            apply(true, true)
        end, flushDragCallback)
        swatch.MouseButton1Click:Connect(function()
            if Library.Popup and Library.Popup.Frame == pop then ClosePopup() return end
            local sc, p = Library.Scale, swatch.AbsolutePosition - Root.AbsolutePosition
            local x = math.min(p.X, Gui.AbsoluteSize.X - 182 * sc)
            pop.Position = UDim2.new(0, x / sc, 0, (p.Y + 26 * sc) / sc)
            OpenPopup(pop, swatch)
            Shine(swatch, 6)
        end)
        function obj:Set(c, fire, alpha)
            h, s, v = c:ToHSV()
            if alpha ~= nil then a = math.clamp(tonumber(alpha) or 1, 0, 1) end
            apply(fire == true)
        end
        function obj:SetAlpha(alpha, fire) a = math.clamp(tonumber(alpha) or 1, 0, 1); apply(fire == true) end
        apply(false)
        if flag then Library.Options[flag] = obj end
        return obj
    end

    -- keybind pill
    local function AttachKeybind(holder, flag, default, onPress, onRelease, onChange)
        local obj = { Key = default or "none", Value = default or "none", Listening = false, Pressed = false }
        local btn = New("TextButton", {
            Text = obj.Key, AutoButtonColor = false, BackgroundColor3 = T.Element, BackgroundTransparency = 0.4,
            TextColor3 = T.TextDim, TextSize = 11, FontFace = F_MED,
            Size = UDim2.new(0, 0, 0, 20), AutomaticSize = Enum.AutomaticSize.X, Parent = holder,
        })
        Corner(btn, 10); Pad(btn, 10, 0, 10, 0); Stroke(btn, 0.85)
        -- plain (static) border while waiting for a key
        local ls = Stroke(btn, 0.35)
        ls.Enabled = false
        if flag then Library.Flags[flag] = obj.Key end

        local function set(k)
            obj.Key = k
            obj.Value = k
            obj.Pressed = false
            btn.Text = k
            if flag then Library.Flags[flag] = k end
            if onChange then task.spawn(onChange, k) end
            if Library.RefreshHotkeys then Library.RefreshHotkeys() end
        end
        btn.MouseButton1Click:Connect(function()
            obj.Listening = true
            Library.ListeningKeybind = obj
            ls.Enabled = true
            btn.Text = "..."
            btn.TextColor3 = T.Text
        end)
        Track(UIS.InputBegan:Connect(function(i, gp)
            if obj.Listening then
                if i.UserInputType == Enum.UserInputType.MouseButton1 and Inside(btn, Pt(i)) then return end
                local k = KeyName(i)
                if k then
                    obj.Listening = false
                    if Library.ListeningKeybind == obj then Library.ListeningKeybind = nil end
                    ls.Enabled = false
                    btn.TextColor3 = T.TextDim
                    if i.KeyCode == Enum.KeyCode.Escape or i.KeyCode == Enum.KeyCode.Backspace then k = "none" end
                    set(k)
                end
            elseif not gp and obj.Key ~= "none" and KeyName(i) == obj.Key then
                obj.Pressed = true
                if onPress then task.spawn(onPress) end
            end
        end))
        Track(UIS.InputEnded:Connect(function(i)
            if not obj.Listening and obj.Key ~= "none" and KeyName(i) == obj.Key then
                obj.Pressed = false
                if onRelease then task.spawn(onRelease) end
            end
        end))
        -- Window focus loss (alt-tab, OS focus steal) can swallow the key's InputEnded, leaving a Hold
        -- keybind logically stuck "down" -- which keeps a Hold-mode toggle (e.g. Auto Assassination) armed
        -- and firing in the background. Treat a lost focus as a release so held keys can't stick on.
        Track(UIS.WindowFocusReleased:Connect(function()
            if obj.Pressed then
                obj.Pressed = false
                if onRelease then task.spawn(onRelease) end
            end
        end))
        function obj:Set(k) set(k) end
        function obj:GetState() return obj.Pressed == true end
        if flag then Library.Options[flag] = obj end
        return obj
    end

    -- buttons
    local function MakeButton(parent, text, size, cb)
        local b = New("TextButton", {
            Text = text, AutoButtonColor = false, BackgroundColor3 = T.Element, BackgroundTransparency = 0.55,
            TextColor3 = T.TextDim, TextSize = 12, FontFace = F_MED, Size = size, Parent = parent,
        })
        Corner(b, 8); Stroke(b, 0.9)
        b.MouseEnter:Connect(function() Tween(b, { BackgroundTransparency = 0.35, TextColor3 = T.Text }) end)
        b.MouseLeave:Connect(function() Tween(b, { BackgroundTransparency = 0.55, TextColor3 = T.TextDim }) end)
        b.MouseButton1Click:Connect(function()
            Shine(b, 8)
            if cb then task.spawn(cb) end
        end)
        return b
    end

    -- session card: centered name + outlined pill
    function E:AddUserCard(opts)
        opts = opts or {}
        local row = Row(62)
        Text(row, opts.Name or LocalPlayer.Name, {
            SizeUDim = UDim2.new(1, 0, 0, 24), AlignX = TCENTER, Font = F_SEMI, Size = 12,
        })
        local pill = New("Frame", {
            BackgroundColor3 = T.Element, BackgroundTransparency = 0.5, AnchorPoint = Vector2.new(0.5, 0),
            Position = UDim2.new(0.5, 0, 0, 28), Size = UDim2.new(0, 0, 0, 22), AutomaticSize = Enum.AutomaticSize.X, Parent = row,
        })
        Corner(pill, 11); Stroke(pill, 0.72); Pad(pill, 12, 0, 12, 0)
        AutoText(pill, opts.Badge or "Standard", T.Text, 11, F_SEMI)
        return row
    end

    -- info row with a Copy bubble (Game ID / Place ID)
    function E:AddInfoRow(opts)
        opts = opts or {}
        local row = Row(28)
        local value = tostring(opts.Value or "")
        Text(row, opts.Name or "Info", { SizeUDim = UDim2.new(0.4, 0, 1, 0), Color = Color3.fromRGB(105, 105, 113) })
        local copy
        if opts.Copy ~= false then
            copy = New("TextButton", {
                Text = "Copy", AutoButtonColor = false, BackgroundColor3 = T.Element, BackgroundTransparency = 0.55,
                TextColor3 = Color3.fromRGB(115, 115, 123), TextSize = 10, FontFace = F_MED,
                AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.new(0, 46, 0, 20), Parent = row,
            })
            Corner(copy, 10); Stroke(copy, 0.88)
        end
        local val = Text(row, value, {
            Position = UDim2.new(0.4, 0, 0, 0), SizeUDim = UDim2.new(0.6, copy and -54 or 0, 1, 0), AlignX = TRIGHT,
            Color = opts.Bright and T.Text or T.TextDim, Font = opts.Bright and F_SEMI or F_MED,
        })
        if copy then
            copy.MouseEnter:Connect(function() Tween(copy, { BackgroundTransparency = 0.35, TextColor3 = T.Text }, 0.12) end)
            copy.MouseLeave:Connect(function() Tween(copy, { BackgroundTransparency = 0.55, TextColor3 = Color3.fromRGB(115, 115, 123) }, 0.12) end)
            copy.MouseButton1Click:Connect(function()
                pcall(function() if setclipboard then setclipboard(value) end end)
                copy.Text = "Copied"
                Shine(copy, 10, 0.7)
                task.delay(1.2, function() if copy.Parent then copy.Text = "Copy" end end)
            end)
        end
        return val
    end

    function E:AddTextbox(opts)
        opts = opts or {}
        local row = Row(opts.Label and 58 or 36)
        local y = 0
        if opts.Label then
            Text(row, opts.Label, { SizeUDim = UDim2.new(1, 0, 0, 18), Color = T.TextDim })
            y = 22
        end
        local tb = New("TextBox", {
            Text = opts.Default or "", PlaceholderText = opts.Placeholder or "", PlaceholderColor3 = T.TextDim,
            ClearTextOnFocus = false, BackgroundColor3 = T.Element, BackgroundTransparency = 0.55,
            TextColor3 = T.Text, TextSize = 12, FontFace = F_MED, TextXAlignment = TLEFT,
            Position = UDim2.new(0, 0, 0, y), Size = UDim2.new(1, 0, 0, 28), Parent = row,
        })
        Corner(tb, 8); Stroke(tb, 0.9); Pad(tb, 12, 0, 12, 0)
        -- Returns a value object (obj.Value stays live with the text) so the Deepwoken menu's
        -- AddInput call sites (which read `input.Value`) keep working.
        local o = { Value = tb.Text }
        local function sync()
            o.Value = tb.Text
            if opts.Flag then Library.Flags[opts.Flag] = tb.Text end
        end
        tb:GetPropertyChangedSignal("Text"):Connect(sync)
        tb.FocusLost:Connect(function()
            sync()
            if opts.Callback then task.spawn(opts.Callback, tb.Text) end
        end)
        function o:Set(v)
            tb.Text = tostring(v or "")
            sync()
            if opts.Callback then task.spawn(opts.Callback, tb.Text) end
        end
        -- Set the text WITHOUT firing the callback (the Text-changed signal still syncs o.Value / Flags).
        -- Mirrors the slider/dropdown :SetRawValue contract the Deepwoken forms rely on.
        function o:SetRawValue(v)
            tb.Text = tostring(v or "")
        end
        function o:Get() return tb.Text end
        o.SetValue = o.Set -- Obsidian-API compat: e.g. CustomTab calls textbox:SetValue
        o.Instance = tb
        if opts.Flag then
            Library.Flags[opts.Flag] = tb.Text
            Library.Options[opts.Flag] = o
        end
        return o
    end

    -- list box (selectable rows, like the real Config List)
    -- opts: Name (label above), Height, Callback(name) on selection.  obj:SetValues(list), obj:Select(name), obj.Value
    function E:AddListBox(opts)
        opts = opts or {}
        local height = opts.Height or 150
        local labelH = opts.Name and 22 or 0
        local row = Row(labelH + height + 6)
        if opts.Name then Text(row, opts.Name, { SizeUDim = UDim2.new(1, 0, 0, 18), Color = T.TextDim }) end
        local box = New("Frame", {
            BackgroundColor3 = T.Element, BackgroundTransparency = 0.6,
            Position = UDim2.new(0, 0, 0, labelH), Size = UDim2.new(1, 0, 0, height), Parent = row,
        })
        Corner(box, 10); Stroke(box, 0.9)
        local scroll = New("ScrollingFrame", {
            BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 1, 0), CanvasSize = UDim2.new(),
            AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 2, ScrollBarImageColor3 = T.TextDim,
            ScrollingDirection = Enum.ScrollingDirection.Y, Parent = box,
        })
        Pad(scroll, 8, 8, 8, 8); List(scroll, 2)

        local obj = { Value = nil }
        local items = {}
        local function paint(name, on)
            local it = items[name]
            if not it then return end
            it.Bar.Visible = on
            it.Btn.FontFace = on and F_SEMI or F_MED
            Tween(it.Btn, { BackgroundTransparency = on and 0.55 or 1, TextColor3 = on and T.Text or T.TextDim }, 0.12)
        end
        function obj:Select(name, fire)
            if obj.Value and obj.Value ~= name then paint(obj.Value, false) end
            obj.Value = name
            if name then paint(name, true) end
            if fire ~= false and name and opts.Callback then task.spawn(opts.Callback, name) end
        end
        function obj:SetValues(list)
            for _, it in pairs(items) do it.Btn:Destroy() end
            items = {}
            for i, name in ipairs(list or {}) do
                local b = New("TextButton", {
                    Text = name, AutoButtonColor = false, BackgroundColor3 = T.Element, BackgroundTransparency = 1,
                    TextColor3 = T.TextDim, TextSize = 12, FontFace = F_MED, TextXAlignment = TLEFT,
                    LayoutOrder = i, Size = UDim2.new(1, 0, 0, 28), Parent = scroll,
                })
                Corner(b, 6); Pad(b, 14, 0, 0, 0)
                local bar = New("Frame", {
                    BackgroundColor3 = WHITE, BorderSizePixel = 0, Visible = false,
                    AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, -10, 0.5, 0), Size = UDim2.new(0, 3, 0, 18), Parent = b,
                })
                Corner(bar, 2)
                items[name] = { Btn = b, Bar = bar }
                b.MouseEnter:Connect(function() if obj.Value ~= name then Tween(b, { BackgroundTransparency = 0.8 }, 0.1) end end)
                b.MouseLeave:Connect(function() if obj.Value ~= name then Tween(b, { BackgroundTransparency = 1 }, 0.1) end end)
                b.MouseButton1Click:Connect(function() obj:Select(name) end)
            end
            if obj.Value and items[obj.Value] then paint(obj.Value, true) else obj.Value = nil end
        end
        function obj:Get() return obj.Value end
        return obj
    end

    -- MODERN SKIN
    do
        local RH = skin.RowH or 36
        local LBL = Color3.fromRGB(212, 212, 218)

        local function rowLabel(row, opts, rightPad)
            local x = 0
            if opts.Icon then
                local ic = Icon(row, opts.Icon, 15, T.TextDim)
                ic.AnchorPoint = Vector2.new(0, 0.5)
                ic.Position = UDim2.new(0, 0, 0.5, 0)
                x = 26
            end
            local lbl = Text(row, opts.Name or "", {
                Position = UDim2.new(0, x, 0, 0), SizeUDim = UDim2.new(1, -(x + rightPad), 1, 0),
                Color = opts.Color or LBL, Truncate = Enum.TextTruncate.AtEnd,
            })
            return lbl, x
        end

        -- right-aligned strip for swatches / dots; xOff leaves room for a switch
        local function newHolder(row, xOff)
            local h = New("Frame", {
                BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, xOff or 0, 0.5, 0),
                Size = UDim2.new(0, 0, 0, 20), AutomaticSize = Enum.AutomaticSize.X, Parent = row,
            })
            List(h, 8, H, RIGHT, VCENTER)
            return h
        end

        -- the pill switch
        local function Switch(parent)
            local sw = New("TextButton", {
                Text = "", AutoButtonColor = false, BackgroundColor3 = Color3.fromRGB(58, 58, 66),
                AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.new(0, 34, 0, 18), Parent = parent,
            })
            Corner(sw, 9)
            local sheen = New("UIGradient", { Color = AccentSeq(true), Parent = sw }) -- static accent tint (no animation)
            sheen:SetAttribute("Solid", true)
            AccentGradients[#AccentGradients + 1] = sheen
            sheen.Enabled = false
            local knob = New("Frame", {
                BackgroundColor3 = Color3.fromRGB(138, 138, 148), AnchorPoint = Vector2.new(0, 0.5),
                Position = UDim2.new(0, 3, 0.5, 0), Size = UDim2.new(0, 12, 0, 12), ZIndex = 2, Parent = sw,
            })
            Corner(knob, 6)
            local function paint(on, animate)
                sheen.Enabled = on
                local dur = animate and 0.18 or 0
                Tween(sw, { BackgroundColor3 = on and WHITE or Color3.fromRGB(58, 58, 66) }, dur)
                Tween(knob, {
                    Position = on and UDim2.new(1, -15, 0.5, 0) or UDim2.new(0, 3, 0.5, 0),
                    BackgroundColor3 = on and Color3.fromRGB(30, 31, 40) or Color3.fromRGB(138, 138, 148), -- dark knob on the bright track = crisper contrast
                }, dur, Enum.EasingStyle.Quint)
            end
            return sw, paint
        end

        -- toggle
        function E:AddToggle(opts)
            opts = opts or {}
            local flag = flagOf(opts)
            local row = Row(RH)
            local lbl, lx = rowLabel(row, opts, 56)
            local sw, paint = Switch(row)
            local hit = New("TextButton", { Text = "", BackgroundTransparency = 1, Size = UDim2.new(1, -60, 1, 0), Parent = row })
            local obj = { Value = false, Flag = flag }
            local holder
            local function widen() lbl.Size = UDim2.new(1, -(lx + 130), 1, 0) end

            local function set(v, fire)
                obj.Value = v
                Library.Flags[flag] = v
                paint(v, fire ~= false)
                if fire ~= false then
                    if v then Shine(sw, 9, 0.55) end
                    if opts.Callback then task.spawn(opts.Callback, v) end
                end
                if Library.RefreshHotkeys then Library.RefreshHotkeys() end
                if Library.RefreshArray then Library.RefreshArray() end
            end
            sw.MouseButton1Click:Connect(function() set(not obj.Value) end)
            hit.MouseButton1Click:Connect(function() set(not obj.Value) end)

            function obj:Set(v) set(v) end
            function obj:SetRawValue(v) set(v and true or false, false) end
            function obj:Get() return obj.Value end
            -- Obsidian-API compat: feature/automation code flips toggles via :SetValue (identical to :Set here).
            obj.SetValue = obj.Set

            -- "..." opens a small settings popup: key + mode
            function obj:AddKeybind(kopts)
                kopts = kopts or {}
                holder = holder or newHolder(row, -40)
                widen()
                local mode = kopts.Mode or "Toggle"
                local entry = { Toggle = obj, Name = kopts.Name or opts.Display or opts.Name, Mode = mode, Held = false }

                local dots = DotsButton(holder)
                dots.LayoutOrder = -1

                local pop = Library.Own(New("CanvasGroup", {
                    Visible = false, BackgroundColor3 = T.Popup, BackgroundTransparency = 0.06,
                    Size = UDim2.new(0, 196, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, ZIndex = 200, Parent = Root,
                }))
                Corner(pop, 10); Stroke(pop, 0.85); Pad(pop, 12, 8, 12, 8); List(pop, 4)
                Shadow(pop, 10, { Spread = 10, Offset = 3, Strength = 0.4 })

                local kRow = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 28), LayoutOrder = 1, Parent = pop })
                Text(kRow, "Key", { SizeUDim = UDim2.new(0.5, 0, 1, 0), Color = T.TextDim })
                local kHold = New("Frame", {
                    BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0),
                    Size = UDim2.new(0, 0, 0, 20), AutomaticSize = Enum.AutomaticSize.X, Parent = kRow,
                })
                List(kHold, 0, H, RIGHT, VCENTER)

                local mRow = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 28), LayoutOrder = 2, Parent = pop })
                Text(mRow, "Mode", { SizeUDim = UDim2.new(0.4, 0, 1, 0), Color = T.TextDim })
                local seg = New("Frame", {
                    BackgroundColor3 = T.Section, BackgroundTransparency = 0.3, AnchorPoint = Vector2.new(1, 0.5),
                    Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.new(0, 116, 0, 22), Parent = mRow,
                })
                Corner(seg, 7)
                local modeBtns = {}
                local function paintModes()
                    for m, b in pairs(modeBtns) do
                        local on = (mode == m)
                        b.BackgroundTransparency = on and 0.25 or 1
                        b.TextColor3 = on and T.Text or T.TextDim
                    end
                end
                for idx, m in ipairs({ "Toggle", "Hold" }) do
                    local b = New("TextButton", {
                        Text = m, AutoButtonColor = false, BackgroundColor3 = T.Element, BackgroundTransparency = 1,
                        TextColor3 = T.TextDim, TextSize = 11, FontFace = F_MED,
                        Position = UDim2.new((idx - 1) * 0.5, 2, 0, 2), Size = UDim2.new(0.5, -4, 1, -4), Parent = seg,
                    })
                    Corner(b, 5)
                    modeBtns[m] = b
                    b.MouseButton1Click:Connect(function()
                        mode = m
                        entry.Mode = m
                        paintModes()
                        if Library.RefreshHotkeys then Library.RefreshHotkeys() end
                    end)
                end
                paintModes()

                entry.Bind = AttachKeybind(kHold, flag .. "_Key", kopts.Default or "none",
                    function()
                        if mode == "Toggle" then
                            set(not obj.Value)
                        else
                            -- Hold: press drives the toggle value ON (that's what feature code reads --
                            -- entry.Held alone never reaches the feature), release drives it OFF.
                            entry.Held = true
                            if not obj.Value then set(true) end
                        end
                    end,
                    function()
                        if mode == "Hold" then
                            entry.Held = false
                            if obj.Value then set(false) end
                        end
                    end,
                    kopts.Callback)
                function entry:IsActive() return obj.Value and (mode == "Toggle" or entry.Held) end
                Library.Keybinds[flag] = entry

                dots.MouseButton1Click:Connect(function()
                    if Library.Popup and Library.Popup.Frame == pop then ClosePopup() return end
                    local sc = Library.Scale
                    local rp = dots.AbsolutePosition - Root.AbsolutePosition
                    pop.AnchorPoint = Vector2.new(1, 0)
                    pop.Position = UDim2.new(0, (rp.X + dots.AbsoluteSize.X) / sc, 0, (rp.Y + dots.AbsoluteSize.Y + 6) / sc)
                    OpenPopup(pop, dots)
                end)
                if Library.RefreshHotkeys then Library.RefreshHotkeys() end
                return obj
            end

            function obj:AddColorPicker(copts)
                copts = copts or {}
                holder = holder or newHolder(row, -40)
                widen()
                AttachColorPicker(holder, copts.Flag or (flag .. "_Color" .. tostring(#holder:GetChildren())), copts.Default, copts.Callback, copts.NoAlpha, copts.DeferDragCallback)
                return obj
            end

            if opts.Display then Library.Features[flag] = { Toggle = obj, Name = opts.Display, InfoFlag = opts.InfoFlag } end
            Library.Options[flag] = obj
            set(opts.Default or false, false)
            return obj
        end

        -- slider: label | thin slider | editable value box
        function E:AddSlider(opts)
            opts = opts or {}
            local flag = flagOf(opts)
            local min, max, inc = opts.Min or 0, opts.Max or 100, opts.Increment or 1
            local row = Row(RH)
            rowLabel(row, opts, 170)
            local box = New("TextBox", {
                Text = "", ClearTextOnFocus = false, BackgroundColor3 = T.Section, BackgroundTransparency = 0.3,
                TextColor3 = T.Text, TextSize = 12, FontFace = F_MED, AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.new(0, 46, 0, 24), Parent = row,
            })
            Corner(box, 6)
            local hit = New("Frame", {
                BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -56, 0.5, 0),
                Size = UDim2.new(0, 104, 0, 24), Parent = row,
            })
            local bar = New("Frame", {
                BackgroundColor3 = T.Track, AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0),
                Size = UDim2.new(1, 0, 0, 4), Parent = hit,
            })
            Corner(bar, 2)
            local fill = New("Frame", { BackgroundColor3 = WHITE, Size = UDim2.new(0, 0, 1, 0), Parent = bar })
            Corner(fill, 2)
            AccentGradient(fill, 0.35, math.random(), nil, true)
            local knob = New("Frame", {
                BackgroundColor3 = WHITE, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0, 0, 0.5, 0),
                Size = UDim2.new(0, 10, 0, 10), ZIndex = 2, Parent = bar,
            })
            Corner(knob, 5)
            local obj = { Value = min }

            local function set(v, fire)
                v = math.clamp(math.floor(v / inc + 0.5) * inc, min, max)
                obj.Value = v
                Library.Flags[flag] = v
                local shown = (inc < 1) and string.format("%." .. (opts.Decimals or 2) .. "f", v) or tostring(v)
                box.Text = shown .. (opts.Suffix or "")
                local f = (max > min) and (v - min) / (max - min) or 0
                Tween(fill, { Size = UDim2.new(f, 0, 1, 0) }, 0.08)
                Tween(knob, { Position = UDim2.new(f, 0, 0.5, 0) }, 0.08)
                if fire ~= false and opts.Callback then task.spawn(opts.Callback, v) end
            end
            BindDrag(hit, function(p)
                set(min + (max - min) * math.clamp((p.X - hit.AbsolutePosition.X) / hit.AbsoluteSize.X, 0, 1))
            end)
            box.FocusLost:Connect(function()
                local n = tonumber(box.Text:match("%-?[%d%.]+"))
                if n then set(n) else set(obj.Value, false) end
            end)
            function obj:Set(v) set(v) end
            function obj:SetRawValue(v) set(v, false) end
            function obj:Get() return obj.Value end
            obj.SetValue = obj.Set -- Obsidian-API compat: feature code calls slider:SetValue
            Library.Options[flag] = obj
            set(opts.Default or min, false)
            return obj
        end

        -- dropdown: label | compact box on the right
        -- Dropdown (Deepwoken build): supports single + Multi selection, a mutable option list
        -- (SetValues / SetValue / Display / .Values), AllowNull, and index-or-string defaults, so the
        -- menu's obsidian-style dropdowns port over unchanged. Searchable/SaveValues are accepted and
        -- behave (search box when flagged); multi selection is a set { [name] = true } in both .Value and Library.Flags.
        function E:AddDropdown(opts)
            opts = opts or {}
            local flag = flagOf(opts)
            local multi = opts.Multi == true
            local allowNull = opts.AllowNull == true
            local row = Row(RH)
            rowLabel(row, opts, 148)
            local box = New("TextButton", {
                Text = "", AutoButtonColor = false, BackgroundColor3 = T.Section, BackgroundTransparency = 0.3,
                AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.new(0, 132, 0, 24), Parent = row,
            })
            Corner(box, 6); Stroke(box, 0.9)
            box.MouseEnter:Connect(function() Tween(box, { BackgroundTransparency = 0.12 }, 0.12) end)
            box.MouseLeave:Connect(function() Tween(box, { BackgroundTransparency = 0.3 }, 0.12) end)
            local cur = Text(box, "", { Position = UDim2.new(0, 10, 0, 0), SizeUDim = UDim2.new(1, -28, 1, 0), Color = T.Text, Truncate = Enum.TextTruncate.AtEnd })
            local chev = Chevron(box, UDim2.new(1, -12, 0.5, 0), T.TextDim)

            local list = Library.Own(New("CanvasGroup", {
                Visible = false, BackgroundColor3 = T.Popup, BackgroundTransparency = 0.1, Size = UDim2.new(0, 100, 0, 0),
                ZIndex = 200, Parent = Root,
            }))
            Corner(list, 10)
            Stroke(list, 0.82)
            Shadow(list, 10, { Spread = 10, Offset = 3, Strength = 0.4 })
            local scroll = New("ScrollingFrame", {
                BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 2, ScrollBarImageColor3 = T.TextDim,
                ScrollingDirection = Enum.ScrollingDirection.Y, CanvasSize = UDim2.new(),
                AutomaticCanvasSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 1, 0), Parent = list,
            })
            Pad(scroll, 5, 5, 5, 5); List(scroll, 2)

            local obj = { Value = multi and {} or nil, Values = {} }
            local buttons = {}

            local function displayText()
                if multi then
                    local names = {}
                    for _, name in ipairs(obj.Values) do if obj.Value[name] then names[#names + 1] = name end end
                    return (#names > 0) and table.concat(names, ", ") or "---"
                end
                return (obj.Value ~= nil and obj.Value ~= "" and tostring(obj.Value)) or "---"
            end
            local function paint()
                for name, b in pairs(buttons) do
                    local on = multi and (obj.Value[name] == true) or (obj.Value == name)
                    b.TextColor3 = on and T.Text or T.TextDim
                    b.BackgroundTransparency = on and 0.45 or 1
                end
            end
            local function fireCb()
                Library.Flags[flag] = obj.Value
                if opts.Callback then task.spawn(opts.Callback, obj.Value) end
                if Library.RefreshArray then Library.RefreshArray() end
            end
            local function pick(name, fire)
                if multi then
                    if obj.Value[name] then obj.Value[name] = nil else obj.Value[name] = true end
                else
                    if allowNull and obj.Value == name then obj.Value = nil else obj.Value = name end
                end
                cur.Text = displayText()
                paint()
                if fire ~= false then Shine(box, 6, 0.8); fireCb() else Library.Flags[flag] = obj.Value end
            end
            local function rebuild()
                for _, b in pairs(buttons) do b:Destroy() end
                buttons = {}
                for i, name in ipairs(obj.Values) do
                    local b = New("TextButton", {
                        Text = name, AutoButtonColor = false, BackgroundColor3 = T.Element, BackgroundTransparency = 1,
                        TextColor3 = T.TextDim, TextSize = 12, FontFace = F_MED, TextXAlignment = TLEFT,
                        LayoutOrder = i, Size = UDim2.new(1, 0, 0, 26), Parent = scroll,
                    })
                    Corner(b, 6); Pad(b, 10, 0, 0, 0)
                    b.MouseEnter:Connect(function() Tween(b, { BackgroundTransparency = 0.7 }, 0.1) end)
                    b.MouseLeave:Connect(function()
                        local on = multi and (obj.Value[name] == true) or (obj.Value == name)
                        Tween(b, { BackgroundTransparency = on and 0.45 or 1 }, 0.1)
                    end)
                    b.MouseButton1Click:Connect(function()
                        pick(name)
                        if not multi then ClosePopup() end
                    end)
                    buttons[name] = b
                end
                paint()
            end
            box.MouseButton1Click:Connect(function()
                if Library.Popup and Library.Popup.Frame == list then ClosePopup() return end
                local sc = Library.Scale
                local w = math.max(box.AbsoluteSize.X / sc, 132)
                local rows = #obj.Values
                local h = math.clamp(rows * 28 + 10, 30, 230)
                list.Size = UDim2.new(0, w, 0, h)
                list.AnchorPoint = Vector2.new(0.5, 0)
                local rp = box.AbsolutePosition - Root.AbsolutePosition
                list.Position = UDim2.new(0, rp.X / sc + box.AbsoluteSize.X / sc / 2, 0, (rp.Y + box.AbsoluteSize.Y + 4 * sc) / sc)
                Tween(chev, { Rotation = 180 }, 0.25, Enum.EasingStyle.Quint)
                OpenPopup(list, box, function() Tween(chev, { Rotation = 0 }, 0.2, Enum.EasingStyle.Quint) end)
            end)

            local function setValue(v, fire)
                if multi then
                    local set = {}
                    if type(v) == "table" then
                        if v[1] ~= nil then
                            for _, n in ipairs(v) do set[n] = true end
                        else
                            for k, val in pairs(v) do if val then set[k] = true end end
                        end
                    end
                    obj.Value = set
                else
                    if type(v) == "number" then v = obj.Values[v] end
                    obj.Value = v
                end
                cur.Text = displayText()
                paint()
                Library.Flags[flag] = obj.Value
                if fire then fireCb() end
            end

            function obj:SetValues(listv)
                obj.Values = {}
                for i, v in ipairs(listv or {}) do obj.Values[i] = v end
                if multi then
                    for name in pairs(obj.Value) do
                        if not table.find(obj.Values, name) then obj.Value[name] = nil end
                    end
                elseif obj.Value ~= nil and not table.find(obj.Values, obj.Value) then
                    obj.Value = nil
                end
                rebuild()
                Library.Flags[flag] = obj.Value
                cur.Text = displayText()
            end
            obj.SetValue = function(_, v, fire) setValue(v, fire == true) end
            obj.SetValues = obj.SetValues
            function obj:Set(v, fire) setValue(v, fire ~= false) end
            function obj:SetRawValue(v) setValue(v, false) end
            function obj:Display() cur.Text = displayText(); paint() end
            function obj:Get() return obj.Value end
            Library.Options[flag] = obj

            obj:SetValues(opts.Values or {})
            if multi then
                if type(opts.Default) == "table" then setValue(opts.Default, false) end
            else
                if opts.Default ~= nil then
                    setValue(opts.Default, false)
                elseif not allowNull and obj.Values[1] ~= nil then
                    setValue(1, false)
                end
            end
            cur.Text = displayText()
            return obj
        end

        -- buttons / labels / colour / keybind / nav / divider
        function E:AddButton(opts)
            opts = opts or {}
            local row = Row(RH)
            local b = MakeButton(row, opts.Name or "Button", UDim2.new(1, 0, 0, 28), opts.Callback)
            b.AnchorPoint = Vector2.new(0, 0.5)
            b.Position = UDim2.new(0, 0, 0.5, 0)
            return b
        end

        function E:AddButtonRow(list)
            local row = Row(RH)
            local n = #list
            local holder = New("Frame", {
                BackgroundTransparency = 1, AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0),
                Size = UDim2.new(1, 0, 0, 28), Parent = row,
            })
            List(holder, 6, H)
            for _, o in ipairs(list) do
                MakeButton(holder, o.Name, UDim2.new(1 / n, -(6 * (n - 1)) / n, 0, 28), o.Callback)
            end
            return row
        end

        function E:AddLabel(text, color)
            local row = Row(30)
            return Text(row, text, { Color = color or T.TextDim })
        end

        function E:AddColor(opts)
            opts = opts or {}
            local row = Row(RH)
            rowLabel(row, opts, 50)
            return AttachColorPicker(newHolder(row, 0), flagOf(opts), opts.Default, opts.Callback, opts.NoAlpha, opts.DeferDragCallback)
        end

        function E:AddKeybind(opts)
            opts = opts or {}
            local row = Row(RH)
            rowLabel(row, opts, 110)
            local flag = flagOf(opts)
            local bind = AttachKeybind(newHolder(row, 0), flag, opts.Default or "none", opts.Callback, nil, opts.OnChange)
            -- HideFromList: keep the key live + saved (it still lives in Library.Options/Flags) but don't
            -- register it in Library.Keybinds, so it never shows on the on-screen hotkey list.
            if not opts.HideFromList then
                Library.Keybinds[flag or bind] = {
                    Name = opts.Name or flag or "Keybind",
                    Bind = bind,
                }
            end
            if Library.RefreshHotkeys then Library.RefreshHotkeys() end
            return bind
        end

        function E:AddNav(opts)
            opts = opts or {}
            local row = Row(RH)
            local lbl = rowLabel(row, opts, 30)
            local ch = Icon(row, "chevron-right", 14, T.TextDim)
            ch.AnchorPoint = Vector2.new(1, 0.5)
            ch.Position = UDim2.new(1, 0, 0.5, 0)
            local hit = New("TextButton", { Text = "", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 0), Parent = row })
            hit.MouseEnter:Connect(function() Tween(lbl, { TextColor3 = T.Text }, 0.1) end)
            hit.MouseLeave:Connect(function() Tween(lbl, { TextColor3 = opts.Color or LBL }, 0.1) end)
            hit.MouseButton1Click:Connect(function() if opts.Callback then task.spawn(opts.Callback) end end)
            return row
        end

        function E:AddDivider()
            local r = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 9), Parent = container })
            New("Frame", {
                BackgroundColor3 = T.Stroke, BackgroundTransparency = 0.9, BorderSizePixel = 0,
                AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(1, 0, 0, 1), Parent = r,
            })
        end
    end

    -- Dependency box (Deepwoken build): the old library hid/showed a group of controls based on a
    -- parent toggle. This remake has no such primitive, so a dependency box simply forwards every
    -- Add* call to the same section (all controls are always visible) and SetupDependencies is a no-op.
    function E:AddDependencyBox()
        local D = setmetatable({}, {
            __index = function(_, k)
                local f = E[k]
                if type(f) == "function" then
                    return function(_, ...) return f(E, ...) end
                end
                return f
            end,
        })
        function D:SetupDependencies() end
        function D:AddDependencyBox() return E:AddDependencyBox() end
        return D
    end

    return E
end

-- MODERN WINDOW (sidebar layout)
-- window / sidebar / card transparency, all derived from Library.GlassAlpha (Library:SetGlassAlpha changes it live)
function Library.GlassValues()
    if Library.GlassOff then return 0, 0.3, 0.24 end
    local a = Library.GlassAlpha
    return a, math.clamp(a + 0.28, 0, 0.95), math.clamp(a + 0.12, 0, 0.95)
end

-- Same API as the classic window, different skin. Switch with the Style dropdown (Options > User Interface)
-- or getgenv().MatchaStyle = "Modern" before executing.
-- Sections are collapsible: click the header (or pass { Collapsed = true } as the 4th argument of tab:AddSection).
local function MakeModernSection(tab, title, prefix, pageName, sopts)
    local T = Library.Theme
    local S = {}
    sopts = sopts or {}
    -- A group = bright uppercase header + rounded card + small gap. Nothing is parented until its first row exists;
    -- then it drops into the lighter column of its page (balanced columns, or one column for "Single" pages).
    local function group(label, pgName, gopts)
        gopts = gopts or {}
        local pg = tab:GetPage(pgName or pageName)
        local DIM = Color3.fromRGB(122, 124, 140)
        local head = New("TextLabel", {
            BackgroundTransparency = 1, Text = string.upper(label), TextColor3 = WHITE, TextSize = 13,
            FontFace = F_SEMI, TextXAlignment = TLEFT, Size = UDim2.new(1, 0, 0, 30),
        })
        Pad(head, 3, 0, 0, 0)
        local card = New("Frame", {
            BackgroundColor3 = T.Background, BackgroundTransparency = select(3, Library.GlassValues()), Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y, ClipsDescendants = true,
        })
        Corner(card, 10); Pad(card, 11, 0, 11, 0)
        -- "lit from above" border: brighter at the top edge, fading out towards the bottom
        local cardStroke = Stroke(card, 0)
        New("UIGradient", {
            Rotation = 90, Parent = cardStroke,
            Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.8), NumberSequenceKeypoint.new(1, 0.88) }),
        })
        local layout = List(card, 0)
        Library.Cards[#Library.Cards + 1] = card
        local gap = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 7) })

        -- collapse / expand
        local key = tostring(tab.Name) .. ":" .. tostring(label)
        local collapsed = Library.Collapsed[key]
        if collapsed == nil then collapsed = gopts.Collapsed == true end
        local lastH, anim = 0, 0
        local chev = Chevron(head, UDim2.new(1, -10, 0.5, 0), DIM)
        chev.Rotation = collapsed and -90 or 0
        local hit = New("TextButton", { Text = "", AutoButtonColor = false, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 0), Parent = head })
        hit.MouseEnter:Connect(function()
            Tween(head, { TextColor3 = T.Text }, 0.12)
            for _, l in ipairs(chev:GetChildren()) do Tween(l, { BackgroundColor3 = T.Text }, 0.12) end
        end)
        hit.MouseLeave:Connect(function()
            Tween(head, { TextColor3 = WHITE }, 0.12)
            for _, l in ipairs(chev:GetChildren()) do Tween(l, { BackgroundColor3 = DIM }, 0.12) end
        end)
        layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            if card.Visible and anim == 0 then lastH = layout.AbsoluteContentSize.Y / Library.Scale end
        end)
        if collapsed then card.Visible = false end

        local function setCollapsed(c, instant)
            c = c and true or false
            if c == collapsed and not instant then return end
            collapsed = c
            Library.Collapsed[key] = c
            anim = anim + (1)
            local my = anim
            if instant or not card.Parent then
                card.Visible = not c
                chev.Rotation = c and -90 or 0
                if not c then card.AutomaticSize = Enum.AutomaticSize.Y; card.Size = UDim2.new(1, 0, 0, 0) end
                return
            end
            Tween(chev, { Rotation = c and -90 or 0 }, 0.22, Enum.EasingStyle.Quint)
            if c then
                local h = math.max(card.AbsoluteSize.Y / Library.Scale, 1)
                lastH = h
                card.AutomaticSize = Enum.AutomaticSize.None
                card.Size = UDim2.new(1, 0, 0, h)
                Tween(card, { Size = UDim2.new(1, 0, 0, 0) }, 0.24, Enum.EasingStyle.Quint)
                task.delay(0.25, function()
                    if anim == my and collapsed then card.Visible = false end
                end)
            else
                if lastH <= 0 then -- never measured: just show it
                    card.AutomaticSize = Enum.AutomaticSize.Y
                    card.Visible = true
                    return
                end
                card.AutomaticSize = Enum.AutomaticSize.None
                card.Size = UDim2.new(1, 0, 0, 0)
                card.Visible = true
                Tween(card, { Size = UDim2.new(1, 0, 0, lastH) }, 0.28, Enum.EasingStyle.Quint)
                task.delay(0.3, function()
                    if anim == my and not collapsed then
                        card.AutomaticSize = Enum.AutomaticSize.Y
                        card.Size = UDim2.new(1, 0, 0, 0)
                    end
                end)
            end
        end
        hit.MouseButton1Click:Connect(function() setCollapsed(not collapsed) end)

        local placed, colIdx = false, 1
        local skin = {
            RowH = 36,
            Reveal = function()
                if placed then return end
                placed = true
                local col
                col, colIdx = pg.Pick()
                head.Parent, card.Parent, gap.Parent = col, col, col
                local n = #pg.Groups + 1
                head.LayoutOrder, card.LayoutOrder, gap.LayoutOrder = n * 3, n * 3 + 1, n * 3 + 2
                pg.Groups[n] = { Head = head, Card = card, Gap = gap, IsCollapsed = function() return collapsed end, SetCollapsed = setCollapsed }
                pg.W[colIdx] = pg.W[colIdx] + (32)
            end,
            OnRow = function(h) if placed then pg.W[colIdx] = pg.W[colIdx] + (h) end end,
        }
        return skin, card, setCollapsed
    end

    if title then
        local skin, card, setC = group(title, nil, sopts)
        for k, v in pairs(BuildElements(card, prefix .. "." .. title, skin)) do S[k] = v end
        S.SetCollapsed = function(_, c) setC(c) end
    end

    -- classic sub-tabs become stacked groups; pageMap = { SubTabName = "Page" } can send some to other pages
    function S:AddSubTabs(names, pageMap)
        local tabs = {}
        for _, n in ipairs(names) do
            local skin, card = group(n, pageMap and pageMap[n])
            tabs[n] = BuildElements(card, prefix .. "." .. n, skin)
        end
        return tabs
    end
    return S
end

function Library:CreateModernWindow(opts)
    opts = opts or {}
    local T = Library.Theme
    local W = { Tabs = {}, Current = nil, Style = "Modern" }
    local vp = Viewport()
    local SIDE = 176 -- wider sidebar = broader script title header (was 160)
    local HEAD = 56
    local SIDE_HEAD = 68
    local MIN_W, MIN_H = 600, 420
    local width = math.min((opts.Size and opts.Size.X) or 800, vp.X - 20)
    local height = math.min((opts.Size and opts.Size.Y) or 580, vp.Y - 40)
    local userName = opts.User or LocalPlayer.Name
    local LBL = Color3.fromRGB(212, 212, 218)

    local main = New("Frame", {
        Name = "Window", BackgroundColor3 = T.Widget, BackgroundTransparency = (Library.GlassValues()),
        Size = UDim2.new(0, width, 0, height), AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(0.5, 0, 0.5, 20), Visible = false, Parent = Root,
    })
    Library.CreatingWindowMain = main
    Corner(main, 18)
    RegisterPanel(main)
    ShadowFill(main, 18, { Spread = 14, Offset = 3, Strength = 0.135 })
    local mainStroke = Stroke(main, 0)
    mainStroke.Thickness = 0
    mainStroke.Enabled = false
    New("UIGradient", {
        Rotation = 90, Parent = mainStroke,
        Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.72), NumberSequenceKeypoint.new(1, 0.88) }),
    })
    W.Main = main
    -- faint frosted haze behind everything in the window: soft light at the top fading down, so the glass reads as frosted
    local haze = New("Frame", {
        Name = "Haze", BackgroundColor3 = WHITE, BackgroundTransparency = 0.955, BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 1, 0), ZIndex = 0, Parent = main,
    })
    Corner(haze, 18)
    New("UIGradient", {
        Rotation = 90, Parent = haze,
        Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) }),
    })

    -- custom background image (Library:SetBackgroundImage). Sits above the haze and below everything else, so the
    -- sidebar tint and the translucent cards show it through.
    local bgImg = New("ImageLabel", {
        Name = "BgImage", BackgroundTransparency = 1, Image = "", ImageTransparency = 1,
