    -- "Glass" option: translucent vs solid
    local function applyGlass(on, instant)
        if on ~= nil then Library.GlassOff = not on end
        local m, sd, cd = Library.GlassValues()
        local t = instant and 0 or 0.2
        haze.Visible = not Library.GlassOff
        Tween(main, { BackgroundTransparency = m }, t)
        Tween(sideFill, { BackgroundTransparency = sd }, t)
        for i = #Library.Cards, 1, -1 do
            local c = Library.Cards[i]
            if c.Parent then Tween(c, { BackgroundTransparency = cd }, t) else table.remove(Library.Cards, i) end
        end
    end
    W.SetGlass = applyGlass
    Library.ApplyGlass = applyGlass
    if Library.Flags["Options.User Interface/Glass"] == true then
        Library.GlassOff = false
    elseif Library.Flags["Options.User Interface/Glass"] == false then
        Library.GlassOff = true
    end
    applyGlass(nil, true)

    -- drag: an outline ("ghost") follows the cursor, the window itself stays put; on release it glides over
    local ghost = New("Frame", {
        Name = "DragGhost", BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0,
        AnchorPoint = main.AnchorPoint, Position = main.Position, Size = main.Size, Visible = false, ZIndex = 190, Parent = Root,
    })
    Corner(ghost, 18)
    New("UIGradient", {
        Rotation = 90, Parent = ghost,
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.9),
            NumberSequenceKeypoint.new(1, 0.97),
        }),
    })
    local ghostScale = New("UIScale", { Scale = 1, Parent = ghost })
    local ghostStroke = Stroke(ghost, 1, WHITE)
    ghostStroke.Thickness = 2
    AccentGradient(ghostStroke, 0.5)
    local ghostTag = New("ImageLabel", {
        Name = "DragTag", BackgroundTransparency = 1, ImageTransparency = 1, Image = "",
        ScaleType = Enum.ScaleType.Fit,
        AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0),
        Size = UDim2.fromOffset(470, 160), Rotation = -16, ZIndex = 191, Parent = ghost,
    })
    local patternGroup = New("CanvasGroup", {
        Name = "DragPattern", BackgroundTransparency = 1, GroupTransparency = 1,
        Size = UDim2.new(1, 0, 1, 0), ZIndex = 190, Parent = ghost,
    })
    Corner(patternGroup, 18)
    local glow = New("Frame", {
        BackgroundColor3 = Library.Theme.Accent, BorderSizePixel = 0, BackgroundTransparency = 0.82,
        Size = UDim2.new(1, 0, 1, 0), ZIndex = 190, Parent = patternGroup,
    })
    New("UIGradient", {
        Rotation = 90, Parent = glow,
        Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0.15) }),
    })
    local stripes = New("Frame", {
        BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 0), ZIndex = 190, Parent = patternGroup,
    })
    local patternStep, patternSize = 48, nil
    local function buildPattern()
        local w, h = ghost.Size.X.Offset, ghost.Size.Y.Offset
        if patternSize and patternSize.X == w and patternSize.Y == h then return end
        patternSize = Vector2.new(w, h)
        stripes:ClearAllChildren()
        local len = w + h
        local t, n = -h / 2 - patternStep * 4, 0
        while t <= w + h / 2 + patternStep * 4 do
            n = n + 1
            New("Frame", {
                BackgroundColor3 = Library.Theme.Accent, BorderSizePixel = 0,
                BackgroundTransparency = (n % 4 == 0) and 0.72 or 0.86,
                AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(t, h / 2),
                Size = UDim2.fromOffset(len, (n % 4 == 0) and 2 or 1), Rotation = -45,
                ZIndex = 190, Parent = stripes,
            })
            t = t + patternStep
        end
    end
    local function syncPattern()
        glow.BackgroundColor3 = Library.Theme.Accent
        for _, line in ipairs(stripes:GetChildren()) do
            line.BackgroundColor3 = Library.Theme.Accent
        end
    end
    local patternElapsed = 0
    Track(RunService.Heartbeat:Connect(function(dt)
        if not ghost.Visible or not Library.HudAnimations then
            patternElapsed = 0
            return
        end
        patternElapsed = patternElapsed + dt
        if patternElapsed < 1 / 30 then return end
        patternElapsed = patternElapsed % (1 / 30)
        stripes.Position = UDim2.fromOffset(0, (os.clock() * 16) % (patternStep * 4))
    end))
    task.spawn(function()
        waitForNetwork("drag-logo")
        if Library.Dead then return end
        local url = tostring(genv.LumaDragLogo or "https://i.imgur.com/ESeXuxX.png")
        local image
        if url:match("^rbxassetid://") then
            image = url
        elseif url:match("^%d+$") then
            image = "rbxassetid://" .. url
        elseif writefile and getcustomasset and isfile then
            local folder = Library.ConfigRoot or "Matcha"
            pcall(function()
                if makefolder and isfolder and not isfolder(folder) then makefolder(folder) end
            end)
            local path = folder .. "/drag_logo_imgur.png"
            if not isfile(path) then
                ldbg("drag-logo: HttpGet")
                local ok, data = pcall(function() return game:HttpGet(url) end)
                if ok and type(data) == "string" and #data > 100 then
                    pcall(writefile, path, data)
                end
            end
            if isfile(path) then
                local ok, asset = pcall(getcustomasset, path)
                if ok then image = asset end
            end
        end
        if ghostTag.Parent then
            ghostTag.Image = image or Library.LogoId
        end
    end)
    -- the real window goes see-through while it is being moved (Library.DragFade: 0 = no change, 1 = invisible)
    local fadeSaved
    local function fadeWindow(on)
        if on then
            if fadeSaved or (Library.DragFade or 0) <= 0 then return end
            fadeSaved = {}
            local k = math.clamp(Library.DragFade, 0, 0.97)
            local list = main:GetDescendants()
            list[#list + 1] = main
            for _, d in ipairs(list) do
                local props
                if d:IsA("UIStroke") then props = { "Transparency" }
                elseif d:IsA("GuiObject") then
                    props = { "BackgroundTransparency" }
                    if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then props[#props + 1] = "TextTransparency" end
                    if d:IsA("ImageLabel") or d:IsA("ImageButton") then props[#props + 1] = "ImageTransparency" end
                end
                if props then
                    local rec
                    for _, p in ipairs(props) do
                        local v = d[p]
                        if v < 1 then
                            rec = rec or {}
                            rec[p] = v
                            Tween(d, { [p] = v + (1 - v) * k }, 0.18)
                        end
                    end
                    if rec then fadeSaved[d] = rec end
                end
            end
        elseif fadeSaved then
            for d, rec in pairs(fadeSaved) do
                if d.Parent then
                    for p, v in pairs(rec) do Tween(d, { [p] = v }, 0.25) end
                end
            end
            fadeSaved = nil
        end
    end

    local dragging, pending, dragStart, dragOrigin, dragGoal, glide = false, false, nil, nil, nil, nil
    local noDrag = {} -- interactive things that live inside the drag handles (the config button...)
    -- while the window is being moved this invisible layer eats the mouse, so nothing underneath (toggles, sliders,
    -- dropdowns...) can be hovered, pressed or released by accident
    local sink = New("TextButton", {
        Name = "DragSink", Text = "", AutoButtonColor = false, BackgroundTransparency = 1, Active = true,
        Size = UDim2.new(1, 0, 1, 0), ZIndex = 185, Visible = false, Parent = Root,
    })
    local function clampCenter(pos) -- keeps the title bar reachable
        local v = Viewport()
        local h = main.Size.Y.Offset
        local cx = pos.X.Scale * v.X + pos.X.Offset
        local cy = pos.Y.Scale * v.Y + pos.Y.Offset
        cx = math.clamp(cx, 90, math.max(v.X - 90, 90))
        cy = math.clamp(cy - h / 2, 0, math.max(v.Y - 56, 0)) + h / 2
        return UDim2.new(pos.X.Scale, math.floor(cx - pos.X.Scale * v.X + 0.5), pos.Y.Scale, math.floor(cy - pos.Y.Scale * v.Y + 0.5))
    end
    local function stopDrag()
        pending = false
        Library.WindowDragging = false
        sink.Visible = false
        if not dragging then return end
        dragging = false
        local goal = dragGoal
        -- Snap the real window back in (it was hidden during the drag) and kill the ghost's visuals at once,
        -- then glide `main` the short remaining distance. Only `main` is tweened -- no per-descendant fade --
        -- so releasing a drag never hitches on a big window.
        ghost.BackgroundTransparency = 1
        patternGroup.GroupTransparency = 1
        ghostTag.ImageTransparency = 1
        main.Visible = true
        Tween(ghostStroke, { Transparency = 1 }, 0.16)
        local viewport = Viewport()
        local currentX = main.Position.X.Scale * viewport.X + main.Position.X.Offset
        local currentY = main.Position.Y.Scale * viewport.Y + main.Position.Y.Offset
        local goalX = goal.X.Scale * viewport.X + goal.X.Offset
        local goalY = goal.Y.Scale * viewport.Y + goal.Y.Offset
        local distance = (Vector2.new(goalX, goalY) - Vector2.new(currentX, currentY)).Magnitude
        if distance < 1 then
            main.Position = goal
            ghost.Visible = false
            return
        end
        local glideDuration = math.clamp(distance / 900, 0.035, 0.48)
        local activeGlide = Tween(main, { Position = goal }, glideDuration, Enum.EasingStyle.Quint)
        glide = activeGlide
        activeGlide.Completed:Connect(function(playbackState)
            if playbackState ~= Enum.PlaybackState.Completed or dragging or glide ~= activeGlide then
                return
            end
            glide = nil
            ghost.Visible = false
        end)
    end
    W.StopDrag = stopDrag
    local function startGhost()
        dragging = true
        Library.WindowDragging = true
        if glide then glide:Cancel(); glide = nil end
        sink.Visible = true
        BringToFront(main)
        ghost.AnchorPoint, ghost.Size, ghost.Position = main.AnchorPoint, main.Size, main.Position
        ghost.ZIndex = 190
        buildPattern()
        syncPattern()
        Tween(patternGroup, { GroupTransparency = 0 }, 0.3)
        ghost.Visible = true
        ghostScale.Scale = 0.985
        Tween(ghostScale, { Scale = 1 }, 0.35, Enum.EasingStyle.Quint)
        Tween(ghostStroke, { Transparency = 0.05 }, 0.15)
        Tween(ghost, { BackgroundTransparency = 0 }, 0.15)
        Tween(ghostTag, { ImageTransparency = 0.05 }, 0.2)
        -- Hide the real window entirely while dragging and move only the lightweight ghost. The old build kept
        -- `main` visible-but-faded (fadeWindow), which left the whole window rendering every frame of the drag
        -- and caused the lag. Nothing heavy is rendered now until the drag ends.
        main.Visible = false
    end
    local function dragWindow(handle)
        handle.InputBegan:Connect(function(i)
            if i.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
            if Library.ElementDragging or Library.Resizing then return end
            local pos = Pt(i)
            for _, f in ipairs(noDrag) do
                if f.Visible and Inside(f, pos) then return end
            end
            ClosePopup()
            if glide then glide:Cancel() glide = nil end
            -- the window only starts moving after a few pixels of real movement, so a plain click never drags it
            pending = true
            dragStart, dragOrigin = Vector2.new(i.Position.X, i.Position.Y), main.Position
            dragGoal = dragOrigin
        end)
    end
    Track(UIS.InputChanged:Connect(function(i)
        if (pending or dragging) and i.UserInputType == Enum.UserInputType.MouseMovement then
            local cur = Vector2.new(i.Position.X, i.Position.Y)
            if pending and (cur - dragStart).Magnitude >= 4 then
                pending = false
                startGhost()
            end
            if dragging then
                local d = (cur - dragStart) / Library.Scale
                dragGoal = clampCenter(UDim2.new(dragOrigin.X.Scale, dragOrigin.X.Offset + d.X, dragOrigin.Y.Scale, dragOrigin.Y.Offset + d.Y))
            end
        end
    end))
    Track(RunService.RenderStepped:Connect(function(dt)
        if dragging then
            if Library.HudAnimations then
                ghost.Position = ghost.Position:Lerp(dragGoal, 1 - math.exp(-dt * 24))
            else
                ghost.Position = dragGoal
            end
        end
    end))
    Track(UIS.InputEnded:Connect(function(i)
        if (pending or dragging) and i.UserInputType == Enum.UserInputType.MouseButton1 then
            stopDrag()
        end
    end))

    -- resize: drag any corner
    local resizing, rSX, rSY, rStart, rSize, rPos = false, 0, 0, nil, nil, nil
    local function makeCorner(sx, sy)
        local ax, ay = (sx > 0) and 1 or 0, (sy > 0) and 1 or 0
        local c = New("Frame", {
            BackgroundTransparency = 1, Active = true, Size = UDim2.new(0, 22, 0, 22),
            AnchorPoint = Vector2.new(ax, ay), Position = UDim2.new(ax, 0, ay, 0), ZIndex = 60, Parent = main,
        })
        local bars = {}
        local px, py = (ax == 0) and 9 or 13, (ay == 0) and 9 or 13
        for _, dim in ipairs({ Vector2.new(10, 2), Vector2.new(2, 10) }) do
            local b = New("Frame", {
                BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 61,
                AnchorPoint = Vector2.new(ax, ay), Position = UDim2.new(0, px, 0, py), Size = UDim2.new(0, dim.X, 0, dim.Y), Parent = c,
            })
            Corner(b, 1)
            bars[#bars + 1] = b
        end
        local function show(v)
            for _, b in ipairs(bars) do Tween(b, { BackgroundTransparency = v and 0.35 or 1 }, 0.15) end
        end
        local hover = false
        c.MouseEnter:Connect(function() hover = true; show(true) end)
        c.MouseLeave:Connect(function() hover = false; if not resizing then show(false) end end)
        c.InputBegan:Connect(function(i)
            if i.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
            ClosePopup()
            Library.Resizing = true
            resizing, rSX, rSY = true, sx, sy
            rStart = Vector2.new(i.Position.X, i.Position.Y)
            rSize = Vector2.new(main.Size.X.Offset, main.Size.Y.Offset)
            rPos = main.Position
            BringToFront(main)
            show(true)
        end)
        Track(UIS.InputEnded:Connect(function(i)
            if resizing and rSX == sx and rSY == sy and i.UserInputType == Enum.UserInputType.MouseButton1 then
                resizing = false
                Library.Resizing = false
                if not hover then show(false) end
            end
        end))
    end
    makeCorner(-1, -1); makeCorner(1, -1); makeCorner(-1, 1); makeCorner(1, 1)
    Track(UIS.InputChanged:Connect(function(i)
        if not resizing or i.UserInputType ~= Enum.UserInputType.MouseMovement then return end
        local d = (Vector2.new(i.Position.X, i.Position.Y) - rStart) / Library.Scale
        local v = Viewport()
        local nw = math.clamp(rSize.X + rSX * d.X, MIN_W, math.max(MIN_W, math.min(1500, v.X - 20)))
        local nh = math.clamp(rSize.Y + rSY * d.Y, MIN_H, math.max(MIN_H, v.Y - 20))
        nw, nh = math.floor(nw / 2) * 2, math.floor(nh / 2) * 2 -- even sizes keep the text crisp (centre anchor)
        main.Size = UDim2.new(0, nw, 0, nh)
        main.Position = UDim2.new(rPos.X.Scale, rPos.X.Offset + rSX * (nw - rSize.X) / 2, rPos.Y.Scale, rPos.Y.Offset + rSY * (nh - rSize.Y) / 2)
    end))

    function W:SetSize(w, h)
        local v = Viewport()
        w = math.clamp(math.floor((w or main.Size.X.Offset) / 2) * 2, MIN_W, math.max(MIN_W, v.X - 20))
        h = math.clamp(math.floor((h or main.Size.Y.Offset) / 2) * 2, MIN_H, math.max(MIN_H, v.Y - 20))
        Tween(main, { Size = UDim2.new(0, w, 0, h) }, 0.3, Enum.EasingStyle.Quint)
    end

    local header = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(0, SIDE, 0, SIDE_HEAD), Parent = side })
    dragWindow(header)
    local title = New("Frame", {
        BackgroundTransparency = 1, Position = UDim2.new(0, 20, 0, 0), Size = UDim2.new(0, 0, 1, 0),
        AutomaticSize = Enum.AutomaticSize.X, Parent = header,
    })
    List(title, 8, H, LEFT, VCENTER)
    -- sidebar logo (replaces the title text)
    local logoFrame = New("Frame", {
        Name = "SideLogoFrame", BackgroundTransparency = 1, Size = UDim2.fromOffset(156, 68), Parent = title,
    })
    -- Always render the real Luma image logo (restored to the original look from before "perf: fix low
    -- textures"). Library.Logo registers the ImageLabel in Library.LogoImages, so the async asset loader swaps
    -- in the resolved texture once it's ready -- no drawn "L" fallback, which otherwise stuck whenever the
    -- window built before the logo asset finished loading (the usual case on a fresh inject).
    Library.Tint(Library.Logo({
        Name = "SideLogo", BackgroundTransparency = 1,
        ScaleType = Enum.ScaleType.Fit, Size = UDim2.fromOffset(156, 68), Parent = logoFrame,
