    -- top bar (config dropdown) + page area
    local top = New("Frame", { BackgroundTransparency = 1, Position = UDim2.new(0, SIDE, 0, 0), Size = UDim2.new(1, -SIDE, 0, HEAD), Parent = main })
    dragWindow(top)
    New("Frame", {
        BackgroundColor3 = T.Stroke, BackgroundTransparency = 0.93, BorderSizePixel = 0,
        Position = UDim2.new(0, 14, 0, HEAD - 1), Size = UDim2.new(1, -27, 0, 1), Parent = top,
    })
    local cfgBtn = New("TextButton", {
        Text = "", AutoButtonColor = false, BackgroundColor3 = T.Background, BackgroundTransparency = 0.1,
        Position = UDim2.new(0, 14, 0, 13), Size = UDim2.new(0, 190, 0, 30), Parent = top,
