    local cfgLbl = Text(cfgBtn, "No config", { Position = UDim2.new(0, 10, 0, 0), SizeUDim = UDim2.new(1, -34, 1, 0), Color = T.Text })
    Chevron(cfgBtn, UDim2.new(1, -14, 0.5, 0), T.TextDim)
    noDrag[#noDrag + 1] = cfgBtn -- pressing the config button must never start a window drag
    cfgBtn.MouseEnter:Connect(function() Tween(cfgBtn, { BackgroundTransparency = 0 }, 0.12) end)
    cfgBtn.MouseLeave:Connect(function() Tween(cfgBtn, { BackgroundTransparency = 0.1 }, 0.12) end)
    -- search (top right): filters every section row by its label
    local searchBox = New("Frame", {
        BackgroundColor3 = T.Background, BackgroundTransparency = 0.1, AnchorPoint = Vector2.new(1, 0),
        Position = UDim2.new(1, -14, 0, 13), Size = UDim2.new(0, 190, 0, 30), Parent = top,
    })
    Corner(searchBox, 8); Stroke(searchBox, 0.9)
    local sIcon = Icon(searchBox, "search", 14, T.TextDim)
    sIcon.AnchorPoint = Vector2.new(0, 0.5); sIcon.Position = UDim2.new(0, 10, 0.5, 0)
    local searchTb = New("TextBox", {
        Text = "", PlaceholderText = "Search", PlaceholderColor3 = T.TextDim, ClearTextOnFocus = false,
        BackgroundTransparency = 1, TextColor3 = T.Text, TextSize = 12, FontFace = F_MED, TextXAlignment = TLEFT,
        Position = UDim2.new(0, 32, 0, 0), Size = UDim2.new(1, -40, 1, 0), Parent = searchBox,
    })
    noDrag[#noDrag + 1] = searchBox
    -- autocomplete: type -> dropdown of matching features (tab > page > section). Click / Enter / arrow keys jump to it.
    local res = Library.Own(New("Frame", {
        Visible = false, BackgroundColor3 = T.Popup, BackgroundTransparency = 0.04, AnchorPoint = Vector2.new(1, 0),
        Size = UDim2.new(0, 310, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, ZIndex = 250, Parent = Root,
    }))
    Corner(res, 12); Stroke(res, 0.86); Pad(res, 6, 6, 6, 6); List(res, 2)
    local results, sel, rowBtns = {}, 1, {}

    local function esc(t) return (t:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")) end
    local function buildIndex()
        local idx = {}
        for _, tab in ipairs(W.Tabs) do
            if not tab.Hidden then
                idx[#idx + 1] = { Name = tab.Name, Sub = "Tab", Tab = tab, Page = tab.Pages[1] }
                for _, pg in ipairs(tab.Pages) do
                    local pgName = (#tab.Pages > 1) and pg.Name or nil
                    if pgName then idx[#idx + 1] = { Name = pg.Name, Sub = tab.Name .. "  ›  Page", Tab = tab, Page = pg } end
                    for _, g in ipairs(pg.Groups) do
                        local where = tab.Name .. (pgName and ("  ›  " .. pgName) or "")
                        local gname = g.Head.Text
                        idx[#idx + 1] = { Name = (gname:sub(1, 1) .. gname:sub(2):lower()), Sub = where .. "  ›  Section", Tab = tab, Page = pg, Group = g }
                        for _, r in ipairs(g.Card:GetChildren()) do
                            if r:IsA("GuiObject") then
                                for _, d in ipairs(r:GetDescendants()) do
                                    if (d:IsA("TextLabel") or d:IsA("TextButton")) and d.Text ~= "" then
                                        idx[#idx + 1] = { Name = d.Text, Sub = where .. "  ›  " .. (gname:sub(1, 1) .. gname:sub(2):lower()),
                                            Tab = tab, Page = pg, Group = g, Row = r }
                                        break
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        return idx
    end

    local function flash(row)
        local f = New("Frame", {
            BackgroundColor3 = Library.Theme.Accent, BackgroundTransparency = 0.72, BorderSizePixel = 0,
            Size = UDim2.new(1, 0, 1, 0), ZIndex = 20, Parent = row,
        })
        Corner(f, 8)
        task.spawn(function()
            for _ = 1, 2 do
                Tween(f, { BackgroundTransparency = 0.45 }, 0.25); task.wait(0.28)
                Tween(f, { BackgroundTransparency = 0.8 }, 0.35); task.wait(0.38)
            end
            Tween(f, { BackgroundTransparency = 1 }, 0.3); task.wait(0.32)
            f:Destroy()
        end)
    end

    local function closeResults() res.Visible = false end
    local function goTo(e)
        closeResults()
        searchTb.Text = ""
        searchTb:ReleaseFocus()
        if not W.SelectTab then return end
        W.SelectTab(e.Tab, e.Page)
        if not e.Group then return end
        task.spawn(function()
            if e.Group.IsCollapsed() and e.Group.SetCollapsed then e.Group.SetCollapsed(false); task.wait(0.35) end
            task.wait(0.45) -- let the page finish sliding in
            local sf = e.Page.Grp:FindFirstChildOfClass("ScrollingFrame")
            local target = e.Row or e.Group.Card
            if sf and target and target.Parent then
                local y = target.AbsolutePosition.Y - sf.AbsolutePosition.Y + sf.CanvasPosition.Y - 70
                local maxY = math.max(sf.AbsoluteCanvasSize.Y - sf.AbsoluteSize.Y, 0)
                Tween(sf, { CanvasPosition = Vector2.new(0, math.clamp(y, 0, maxY)) }, 0.35, Enum.EasingStyle.Quint)
            end
            if e.Row then task.wait(0.2); flash(e.Row) end
        end)
    end

    local function paintSel()
        for i, b in ipairs(rowBtns) do
            Tween(b, { BackgroundTransparency = (i == sel) and 0.55 or 1 }, 0.08)
        end
    end

    local function refreshResults()
        for _, b in ipairs(rowBtns) do b:Destroy() end
        rowBtns, results, sel = {}, {}, 1
        local q = searchTb.Text:lower():gsub("^%s+", ""):gsub("%s+$", "")
        if q == "" then closeResults() return end
        local scored = {}
        for _, e in ipairs(buildIndex()) do
            local n = e.Name:lower()
            local p = n:find(q, 1, true)
            if p then
                local score = (p == 1 and 0 or (n:sub(p - 1, p - 1) == " " and 1 or 2)) * 100 + #n
                if e.Row then score = score + (0) elseif e.Group then score = score + (40) else score = score + (20) end
                scored[#scored + 1] = { e = e, score = score, p = p }
            end
        end
        table.sort(scored, function(a, b) return a.score < b.score end)
        local hex = Library.Theme.Accent:ToHex()
        for i = 1, math.min(#scored, 7) do
            local it = scored[i]
            results[i] = it.e
            local nm = it.e.Name
            local rich = esc(nm:sub(1, it.p - 1)) .. ("<font color='#%s'><b>%s</b></font>"):format(hex, esc(nm:sub(it.p, it.p + #q - 1))) .. esc(nm:sub(it.p + #q))
            local b = New("TextButton", {
                Text = "", AutoButtonColor = false, BackgroundColor3 = T.Element, BackgroundTransparency = 1,
                LayoutOrder = i, Size = UDim2.new(1, 0, 0, 42), ZIndex = 251, Parent = res,
            })
            Corner(b, 8)
            New("TextLabel", {
                BackgroundTransparency = 1, RichText = true, Text = rich, TextColor3 = T.Text, TextSize = 12, FontFace = F_SEMI,
                TextXAlignment = TLEFT, Position = UDim2.new(0, 10, 0, 5), Size = UDim2.new(1, -20, 0, 18), ZIndex = 252, Parent = b,
            })
            New("TextLabel", {
                BackgroundTransparency = 1, Text = it.e.Sub, TextColor3 = T.TextDim, TextSize = 10, FontFace = F_MED,
                TextXAlignment = TLEFT, TextTruncate = Enum.TextTruncate.AtEnd,
                Position = UDim2.new(0, 10, 0, 23), Size = UDim2.new(1, -20, 0, 14), ZIndex = 252, Parent = b,
            })
            b.MouseEnter:Connect(function() sel = i; paintSel() end)
            b.MouseButton1Down:Connect(function() goTo(it.e) end) -- Down, so it wins against the box losing focus
            rowBtns[i] = b
        end
        if #scored == 0 then
            local b = New("TextLabel", {
                BackgroundTransparency = 1, Text = "No results", TextColor3 = T.TextDim, TextSize = 12, FontFace = F_MED,
                Size = UDim2.new(1, 0, 0, 34), ZIndex = 252, Parent = res,
            })
            rowBtns[1] = b
        end
        local sc = Library.Scale
        local rp = searchBox.AbsolutePosition - Root.AbsolutePosition
        res.Position = UDim2.new(0, (rp.X + searchBox.AbsoluteSize.X) / sc, 0, (rp.Y + searchBox.AbsoluteSize.Y + 6 * sc) / sc)
        res.Visible = true
        paintSel()
    end

    searchTb:GetPropertyChangedSignal("Text"):Connect(refreshResults)
    searchTb.Focused:Connect(function() if searchTb.Text ~= "" then refreshResults() end end)
    searchTb.FocusLost:Connect(function(enter)
        if enter and results[sel] then goTo(results[sel]) return end
        task.delay(0.2, function() if not searchTb:IsFocused() then closeResults() end end)
    end)
    Track(UIS.InputBegan:Connect(function(i)
        if not searchTb:IsFocused() or not res.Visible then return end
        if i.KeyCode == Enum.KeyCode.Down and #results > 0 then sel = sel % #results + 1; paintSel()
        elseif i.KeyCode == Enum.KeyCode.Up and #results > 0 then sel = (sel - 2) % #results + 1; paintSel()
        elseif i.KeyCode == Enum.KeyCode.Escape then searchTb.Text = ""; searchTb:ReleaseFocus(); closeResults() end
    end))
    Track(RunService.Heartbeat:Connect(function() if res.Visible and (Library.WindowDragging or not main.Visible) then res.Visible = false end end))
    Library.Search = function(text) searchTb.Text = text or "" end

    function Library.RefreshConfigBar() cfgLbl.Text = Library.CurrentConfig or "No config" end
    Library.RefreshConfigBar()

    local pages = New("Frame", {
        BackgroundTransparency = 1, Position = UDim2.new(0, SIDE + 14, 0, HEAD + 3), Size = UDim2.new(1, -(SIDE + 27), 1, -(HEAD + 12)), Parent = main,
    })

    -- pages (a tab can own several; each one is its own scrolling two-column page)
    local pageSeq = 0 -- creation order: decides which way a page slides when you switch tabs
    local function newPage(def, tab)
        local grp = New("CanvasGroup", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 0), Visible = false, Parent = pages })
        local sf = New("ScrollingFrame", {
            BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 0, Size = UDim2.new(1, 0, 1, 0),
            CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, Parent = grp,
        })
        Pad(sf, 2, 2, 2, 8)
        List(sf, 0)
        local inner = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = sf })
        List(inner, 14, H, LEFT, TOP)
        local function col()
            local c = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(0.5, -7, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = inner })
            List(c, 0)
            return c
        end
        local c1, c2 = col(), col()
        pageSeq = pageSeq + (1)
        local pg = { Name = def.Name, Icon = def.Icon, Grp = grp, Cols = { c1, c2 }, W = { 0, 0 }, Single = def.Single, Full = def.Full, Tab = tab, Seq = pageSeq }
        if pg.Full then
            -- one column spanning the ENTIRE window (for tabs with no right-hand panel)
            c1.Size = UDim2.new(1, 0, 0, 0)
            c2.Visible = false
        elseif pg.Single then
            -- one column on the left; the right half is kept free for a preview panel
            sf.Size = UDim2.new(0.5, -7, 1, 0)
            c1.Size = UDim2.new(1, 0, 0, 0)
            c2.Visible = false
        end
        pg.Groups = {}
        -- switch between one column (right half kept free) and two balanced columns, re-sorting every section
        function pg.SetLayout(single, skipSize)
            pg.Single = single and true or false
            if pg.Single then
                c1.Size = UDim2.new(1, 0, 0, 0); c2.Visible = false
            else
                c1.Size = UDim2.new(0.5, -7, 0, 0); c2.Visible = true
            end
            if not skipSize then sf.Size = pg.Single and UDim2.new(0.5, -7, 1, 0) or UDim2.new(1, 0, 1, 0) end
            pg.W = { 0, 0 }
            for i, g in ipairs(pg.Groups) do
                local col, idx = pg.Pick()
                g.Head.Parent, g.Card.Parent, g.Gap.Parent = col, col, col
                g.Head.LayoutOrder, g.Card.LayoutOrder, g.Gap.LayoutOrder = i * 3, i * 3 + 1, i * 3 + 2
                local h = 0
                if not g.IsCollapsed() then
                    h = g.Card.AbsoluteSize.Y / Library.Scale
                    if h <= 0 then h = #g.Card:GetChildren() * 36 end
                end
                pg.W[idx] = pg.W[idx] + (32 + h)
            end
        end
        function pg.Pick()
            local i = 1
            if not (pg.Single or pg.Full) and pg.W[2] < pg.W[1] then i = 2 end
            return pg.Cols[i], i
        end
        -- A full-width note pinned to the TOP of the page, above the two balanced columns (LayoutOrder -1,
        -- the columns live on `inner` at the default order 0). Used for warning banners. Not a section, so
        -- it never enters the column balancer. Returns the card + its label.
        function pg.AddBanner(text, bopts)
            bopts = bopts or {}
            local accent = bopts.Color or Color3.fromRGB(255, 96, 96)
            local wrap = New("Frame", {
                BackgroundTransparency = 1, LayoutOrder = -1,
                Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = sf,
            })
            Pad(wrap, 2, 0, 2, 14) -- bottom gap matches the 14px spacing between the columns below
            local card = New("Frame", {
                BackgroundColor3 = Library.Theme.Section, BackgroundTransparency = bopts.Transparency or 0.1,
                BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = wrap,
            })
            Corner(card, 12)
            Stroke(card, 0.5, accent)
            Pad(card, 14, 10, 14, 10)
            local label = New("TextLabel", {
                BackgroundTransparency = 1, Text = text, TextColor3 = accent,
                TextSize = bopts.Size or 12, FontFace = F_SEMI,
                TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
                TextWrapped = true, RichText = true,
                Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = card,
            })
            return card, label
        end
        return pg
    end

    -- navigation
    local selectTab
    local navAnimate = false -- true only for the rebuild that follows a tab switch (animates the selected item)
    local function rebuildNav()
        for _, c in ipairs(nav:GetChildren()) do c:Destroy() end
        List(nav, 3)
        local gidx, count, list = {}, 0, {}
        for _, t in ipairs(W.Tabs) do
            if not gidx[t.Group] then count = count + (1); gidx[t.Group] = count end
            if not t.Hidden then list[#list + 1] = t end
        end
        table.sort(list, function(a, b)
            return gidx[a.Group] * 1000 + (a.Order or a.Index) < gidx[b.Group] * 1000 + (b.Order or b.Index)
        end)

        local order = 0
        local function spacer(h)
            order = order + (1)
            New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, h), LayoutOrder = order, Parent = nav })
        end
        -- state: "on" (selected) | "soft" (parent of the selected page) | "off"
        local function navItem(label, iconName, sub, state, onClick)
            order = order + (1)
            local holder = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 32), LayoutOrder = order, Parent = nav })
            local item = New("TextButton", {
                Text = "", AutoButtonColor = false, BackgroundColor3 = T.Element,
                BackgroundTransparency = (state == "on") and 0.3 or ((state == "soft") and 0.65 or 1),
                Position = UDim2.new(0, sub and 12 or 0, 0, 0), Size = UDim2.new(1, sub and -12 or 0, 1, 0), Parent = holder,
            })
            Corner(item, 8)
            if state == "on" then
                local mark = New("Frame", {
                    BackgroundColor3 = WHITE, BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 0.5),
                    Position = UDim2.new(0, 3, 0.5, 0), Size = UDim2.new(0, 3, 0, navAnimate and 0 or 16), Parent = item,
                })
                Corner(mark, 2)
                AccentGradient(mark, 0.4, 0, 90, true)
                if navAnimate then
                    -- the highlight fades in and the marker grows out of the middle
                    item.BackgroundTransparency = 1
                    Tween(item, { BackgroundTransparency = 0.3 }, 0.28, Enum.EasingStyle.Quint)
                    Tween(mark, { Size = UDim2.new(0, 3, 0, 16) }, 0.4, Enum.EasingStyle.Back)
                end
            elseif state == "soft" and navAnimate then
                item.BackgroundTransparency = 1
                Tween(item, { BackgroundTransparency = 0.65 }, 0.28, Enum.EasingStyle.Quint)
            end
            local bright = state ~= "off"
            local ic = Icon(item, iconName, 16, bright and T.Text or T.TextDim)
            ic.AnchorPoint = Vector2.new(0, 0.5)
            ic.Position = UDim2.new(0, 10, 0.5, 0)
            Text(item, label, {
                Position = UDim2.new(0, 37, 0, 0), SizeUDim = UDim2.new(1, -40, 1, 0),
                Color = bright and T.Text or T.TextDim, Font = bright and F_SEMI or F_MED,
            })
            if state == "off" then
                item.MouseEnter:Connect(function() Tween(item, { BackgroundTransparency = 0.7 }, 0.1) end)
                item.MouseLeave:Connect(function() Tween(item, { BackgroundTransparency = 1 }, 0.1) end)
            end
            item.MouseButton1Click:Connect(onClick)
        end

        local lastGroup
        for _, t in ipairs(list) do
            if t.Group ~= lastGroup then
                if lastGroup then spacer(3) end
                lastGroup = t.Group
                order = order + (1)
                local gl = New("TextLabel", {
                    BackgroundTransparency = 1, Text = t.Group, TextColor3 = Color3.fromRGB(122, 124, 140), TextSize = 11, FontFace = F_SEMI,
                    TextXAlignment = TLEFT, Size = UDim2.new(1, 0, 0, 24), LayoutOrder = order, Parent = nav,
                })
                Pad(gl, 12, 0, 0, 0)
            end
            if t.Flatten then
                -- the tab itself is hidden; its pages are the items (like Aimbot / Silent / Trigger)
                for _, pg in ipairs(t.Pages) do
                    navItem(pg.Name, pg.Icon or t.IconName, false, (W.CurrentPage == pg) and "on" or "off", function() selectTab(t, pg) end)
                end
            else
                local current = (W.Current == t)
                local expanded = current and #t.Pages > 1
                navItem(t.Name, t.IconName, false, current and (expanded and "soft" or "on") or "off", function()
                    if W.Current ~= t then selectTab(t) end
                end)
                if expanded then
                    -- sub-pages unfold under the tab, like Visuals > Players / Extras
                    for _, pg in ipairs(t.Pages) do
                        navItem(pg.Name, pg.Icon or t.IconName, true, (W.CurrentPage == pg) and "on" or "off", function()
                            if W.CurrentPage ~= pg then selectTab(t, pg) end
                        end)
                    end
                end
            end
        end
    end

    -- Tab switch animation: the old page fades out and slides away, the new page slides in from the direction you
    -- navigated (down the sidebar = from below, up = from above), and the selected sidebar item fades in.
    function selectTab(tab, pg, instant)
        pg = pg or tab.CurPage or tab.Pages[1]
        local old = W.CurrentPage
        local changed = old ~= pg
        local dir = (old and pg.Seq < old.Seq) and -1 or 1
        for _, t in ipairs(W.Tabs) do
            for _, p in ipairs(t.Pages) do
                local on = (p == pg)
                if p.Side then p.Side.Visible = on end
                p.Tok = (p.Tok or 0) + 1 -- cancels any pending fade started by an earlier switch
                local tok = p.Tok
                if on then
                    p.Grp.Visible = true
                    if changed and not instant then
                        p.Grp.GroupTransparency = 1
                        p.Grp.Position = UDim2.new(0, 0, 0, 22 * dir)
                        task.delay(0.08, function()
                            if p.Tok ~= tok then return end
                            Tween(p.Grp, { GroupTransparency = 0, Position = UDim2.new() }, 0.4, Enum.EasingStyle.Quint)
                        end)
                    else
                        p.Grp.GroupTransparency = 0
                        p.Grp.Position = UDim2.new()
                    end
                elseif p == old and changed and not instant and p.Grp.Visible then
                    Tween(p.Grp, { GroupTransparency = 1, Position = UDim2.new(0, 0, 0, -14 * dir) }, 0.14, Enum.EasingStyle.Quad)
                    task.delay(0.15, function()
                        if p.Tok == tok then p.Grp.Visible = false end
                    end)
                else
                    p.Grp.Visible = false
                end
            end
        end
        W.Current, W.CurrentPage, tab.CurPage = tab, pg, pg
        ClosePopup()
        navAnimate = changed and not instant
        rebuildNav()
        navAnimate = false
    end
    W.SelectTab = selectTab

    -- topts: Group ("AIMBOT"/"COMMON"), Order, Hidden, Flatten (pages become top-level items),
    --        Pages = { { Name, Icon, Single }, ... }, Single (for tabs without pages)
    function W:AddTab(name, icon, topts)
        topts = topts or {}
        local tab = {
            Name = name, IconName = icon, Group = topts.Group or "COMMON", Order = topts.Order, Hidden = topts.Hidden,
            Flatten = topts.Flatten, Index = #W.Tabs + 1, Pages = {}, PageByName = {},
        }
        for _, d in ipairs(topts.Pages or { { Name = name, Single = topts.Single, Full = topts.Full } }) do
            if type(d) == "string" then d = { Name = d } end
            local pg = newPage(d, tab)
            tab.Pages[#tab.Pages + 1] = pg
            tab.PageByName[d.Name] = pg
        end
        function tab:GetPage(n) return (n and tab.PageByName[n]) or tab.Pages[1] end

        -- (side is ignored here: the modern layout balances the columns itself; pageName picks the sub-page)
        function tab:AddSection(sideName, sectionTitle, pageName, sopts)
            return MakeModernSection(tab, sectionTitle, name, pageName, sopts)
        end

        -- A full-width banner pinned to the top of a page (above the columns). pageName picks the sub-page.
        function tab:AddBanner(text, pageName, bopts)
            return tab:GetPage(pageName).AddBanner(text, bopts)
        end

        -- preview panel INSIDE the window: right half of the page, fixed (doesn't scroll away). popts.Page picks the page.
        function tab:AddSidePanel(popts)
            popts = popts or {}
            local pg = tab:GetPage(popts.Page)
            local panel = New("Frame", {
                BackgroundTransparency = 1, Position = UDim2.new(0.5, 7, 0, 0),
                Size = popts.ModernHeight and UDim2.new(0.5, -7, 0, popts.ModernHeight) or UDim2.new(0.5, -7, 1, -4),
                Visible = false, Parent = pages,
            })
            New("UISizeConstraint", { MaxSize = Vector2.new(math.huge, 480), Parent = panel })
            local head = New("TextLabel", {
                BackgroundTransparency = 1, Text = string.upper(popts.Subtitle ~= "" and popts.Subtitle or (popts.Title or "Panel")),
                TextColor3 = Color3.fromRGB(122, 124, 140), TextSize = 11, FontFace = F_SEMI, TextXAlignment = TLEFT,
                Size = UDim2.new(1, 0, 0, 30), Parent = panel,
            })
            Pad(head, 3, 0, 0, 0)
            local pillBtn
            if popts.Pill then
                pillBtn = New("TextButton", {
                    Text = popts.Pill, AutoButtonColor = false, BackgroundTransparency = 1, TextColor3 = T.Text, TextSize = 11, FontFace = F_MED,
                    AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0, 17),
                    Size = UDim2.new(0, 0, 0, 20), AutomaticSize = Enum.AutomaticSize.X, Parent = panel,
                })
                Corner(pillBtn, 10); Stroke(pillBtn, 0.72); Pad(pillBtn, 9, 0, 9, 0)
                pillBtn.MouseButton1Click:Connect(function() Shine(pillBtn, 10) end)
            end
            local body = New("Frame", {
                BackgroundTransparency = 1,
                Position = UDim2.new(0, 0, 0, 30), Size = UDim2.new(1, 0, 1, -30), Parent = panel,
            })
            pg.Side = panel
            return panel, body, pillBtn
        end

        table.insert(W.Tabs, tab)
        if not W.Current and not tab.Hidden then selectTab(tab, nil, true) else rebuildNav() end
        return tab
    end

    -- user card (bottom of the sidebar)
    New("Frame", {
        BackgroundColor3 = T.Stroke, BackgroundTransparency = 0.93, BorderSizePixel = 0,
        AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 12, 1, -69), Size = UDim2.new(0, SIDE - 24, 0, 1), Parent = side,
    })
    local uCard = New("TextButton", {
        Text = "", AutoButtonColor = false, BackgroundColor3 = T.Section, BackgroundTransparency = 1,
        AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 10, 1, -10), Size = UDim2.new(0, SIDE - 20, 0, 50), Parent = side,
    })
    Corner(uCard, 10)
    local uOpen = false
    uCard.MouseEnter:Connect(function() Tween(uCard, { BackgroundTransparency = uOpen and 0.3 or 0.6 }, 0.12) end)
    uCard.MouseLeave:Connect(function() Tween(uCard, { BackgroundTransparency = uOpen and 0.45 or 1 }, 0.12) end)

    local avatars, thumb = {}, nil
    local function avatarCircle(parent, size)
        local av = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(0, size, 0, size), Parent = parent })
        local pic = New("ImageLabel", { BackgroundTransparency = 1, Image = thumb or "", Size = UDim2.new(1, 0, 1, 0), Parent = av })
        Corner(pic, size / 2)
        local letter = Text(av, string.upper(userName:sub(1, 1)), {
            AlignX = TCENTER, Color = T.TextDim, Size = math.floor(size * 0.34), Font = F_BOLD,
        })
        letter.Visible = (thumb == nil) -- only a fallback until the headshot loads
        avatars[#avatars + 1] = { Pic = pic, Letter = letter }
        return av
    end
    local uav = avatarCircle(uCard, 36)
    uav.AnchorPoint = Vector2.new(0, 0.5)
    uav.Position = UDim2.new(0, 10, 0.5, 0)
    Text(uCard, userName, { Position = UDim2.new(0, 56, 0, 9), SizeUDim = UDim2.new(1, -86, 0, 17), Font = F_SEMI, Truncate = Enum.TextTruncate.AtEnd })
    Text(uCard, opts.License or "Lifetime", { Position = UDim2.new(0, 56, 0, 26), SizeUDim = UDim2.new(1, -86, 0, 15), Color = T.TextDim, Size = 11 })
    local uChev = Icon(uCard, "chevron-right", 14, T.TextDim)
    uChev.AnchorPoint = Vector2.new(1, 0.5)
    uChev.Position = UDim2.new(1, -10, 0.5, 0)

    -- user popup (menu key, accent, design, quick toggles)
    local upop = Library.Own(New("CanvasGroup", {
        Visible = false, BackgroundColor3 = T.Popup, BackgroundTransparency = 0.04,
        Size = UDim2.new(0, 244, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, ZIndex = 200, Parent = Root,
    }))
    Corner(upop, 14); Stroke(upop, 0.88); Pad(upop, 14, 12, 14, 10); List(upop, 0)
    Shadow(upop, 14, { Spread = 16, Offset = 4, Strength = 0.45 })

    local ph = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 52), Parent = upop })
    local pav = avatarCircle(ph, 40)
    pav.AnchorPoint = Vector2.new(0, 0.5)
    pav.Position = UDim2.new(0, 0, 0.5, -2)
    task.spawn(function()
        local ok, img = pcall(Players.GetUserThumbnailAsync, Players, LocalPlayer.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size100x100)
        if ok and img then
            thumb = img
            for _, a in ipairs(avatars) do
