    Text(ph, userName, { Position = UDim2.new(0, 52, 0, 8), SizeUDim = UDim2.new(1, -52, 0, 17), Font = F_SEMI })
    Text(ph, opts.License or "Lifetime", { Position = UDim2.new(0, 52, 0, 26), SizeUDim = UDim2.new(1, -52, 0, 15), Color = T.TextDim, Size = 11 })

    local uE = BuildElements(upop, "UserMenu", { RowH = 32, NoDividers = true })
    uE:AddDivider()
    uE:AddKeybind({ Name = "Menu Key", Icon = "keyboard", Flag = "UserMenu.MenuKey", Default = "alt",
        OnChange = function(k) Library:SetMenuKey(k) end })
    uE:AddColor({ Name = "Style", Icon = "droplet", Flag = "UserMenu.Style", Default = T.Accent, NoAlpha = true, DeferDragCallback = true,
        Callback = function(c)
            Library:SetAccent(c)
            local ao = Library.Options["AccentColor"]
            if ao then ao:Set(c) end
        end })
    uE:AddDivider()
    -- quick toggles drive the library directly (no Options tab needed): glass, full-screen blur, dark backdrop
    local getState = {
        Glass = function() return not Library.GlassOff end,
        Blur = function() return Library.BlurOn == true end,
        ["Dark Background"] = function() return Library.DarkOn == true end,
    }
    local setState = {
        Glass = function(v) if Library.ApplyGlass then pcall(Library.ApplyGlass, v and true or false, false) end end,
        Blur = function(v) Library:SetBlur(v and true or false) end,
        ["Dark Background"] = function(v) Library:SetDarkBackground(v and true or false) end,
    }
    local mirrors = {}
    for _, m in ipairs({
        { "Glass", "layers" },
        { "Blur", "circle-dot" },
        { "Dark Background", "contrast" },
    }) do
        local mflag = "UserMenu." .. m[1]
        Library.NoSave[mflag] = true
        local apply = setState[m[1]]
        local tog = uE:AddToggle({ Name = m[1], Icon = m[2], Flag = mflag, Callback = function(v)
            if apply then apply(v) end
        end })
        mirrors[#mirrors + 1] = { Tog = tog, Get = getState[m[1]] }
    end

    uCard.MouseButton1Click:Connect(function()
        local lc = Library.PopupClosed
        if lc and lc.Frame == upop and os.clock() - lc.T < 0.3 then return end -- this very click just closed it
        if Library.Popup and Library.Popup.Frame == upop then ClosePopup() return end
        for _, m in ipairs(mirrors) do
            local cur = m.Get and m.Get()
            if cur ~= nil and m.Tog.Value ~= cur then m.Tog:SetRawValue(cur) end
        end
        local sc = Library.Scale
        local mp = main.AbsolutePosition - Root.AbsolutePosition
        upop.AnchorPoint = Vector2.new(0, 1)
        upop.Position = UDim2.new(0, mp.X / sc + SIDE + 2, 0, mp.Y / sc + main.AbsoluteSize.Y / sc - 10)
        uOpen = true
        Tween(uCard, { BackgroundTransparency = 0.45 }, 0.15)
        OpenPopup(upop, uCard, function()
            uOpen = false
            Tween(uCard, { BackgroundTransparency = 1 }, 0.2)
        end, true)
    end)

    -- presets popup (config list)
    local presets = Library.Own(New("CanvasGroup", {
        Visible = false, BackgroundColor3 = T.Popup, BackgroundTransparency = 0.04,
        Size = UDim2.new(0, 372, 0, 430), ZIndex = 200, Parent = Root,
    }))
    Corner(presets, 12); Stroke(presets, 0.88)
    Shadow(presets, 12, { Spread = 14, Offset = 4, Strength = 0.45 })
    RegisterPanel(presets) -- a real floating panel: comes to the front when clicked, stays open until closed
    local presetsScale = New("UIScale", { Scale = 1, Parent = presets })
    -- drag handle over the whole header (the buttons on the right sit on top of it)
    local cfgHandle = New("Frame", { BackgroundTransparency = 1, Active = true, Size = UDim2.new(1, -120, 0, 48), ZIndex = 1, Parent = presets })

    local pTitle = New("Frame", {
        BackgroundColor3 = T.Section, BackgroundTransparency = 0.3, Position = UDim2.new(0, 10, 0, 10), Size = UDim2.new(0, 94, 0, 30), Parent = presets,
    })
    Corner(pTitle, 8)
    local pcloud = Icon(pTitle, "cloud", 14, T.Text)
    pcloud.AnchorPoint = Vector2.new(0, 0.5)
    pcloud.Position = UDim2.new(0, 10, 0.5, 0)
    Text(pTitle, "Presets", { Position = UDim2.new(0, 31, 0, 0), SizeUDim = UDim2.new(1, -34, 1, 0), Font = F_SEMI })

    local function iconBtn(x, iconName, cb)
        local b = New("TextButton", {
            Text = "", AutoButtonColor = false, BackgroundColor3 = T.Section, BackgroundTransparency = 0.3,
            AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, x, 0, 10), Size = UDim2.new(0, 30, 0, 30), Parent = presets,
        })
        Corner(b, 8)
        local ic = Icon(b, iconName, 15, T.TextDim)
        ic.AnchorPoint = Vector2.new(0.5, 0.5)
        ic.Position = UDim2.new(0.5, 0, 0.5, 0)
        b.MouseEnter:Connect(function() Tween(b, { BackgroundTransparency = 0.1 }, 0.1); Tween(ic, { ImageColor3 = T.Text }, 0.1) end)
        b.MouseLeave:Connect(function() Tween(b, { BackgroundTransparency = 0.3 }, 0.1); Tween(ic, { ImageColor3 = T.TextDim }, 0.1) end)
        b.MouseButton1Click:Connect(function()
            Shine(b, 8, 0.6)
            if cb then task.spawn(cb) end
        end)
        return b
    end

    local search = New("TextBox", {
        Text = "", PlaceholderText = "Search", PlaceholderColor3 = T.TextDim, ClearTextOnFocus = false,
        BackgroundColor3 = T.Section, BackgroundTransparency = 0.3, TextColor3 = T.Text, TextSize = 12, FontFace = F_MED,
        TextXAlignment = TLEFT, Position = UDim2.new(0, 10, 0, 50), Size = UDim2.new(1, -20, 0, 32), Parent = presets,
    })
    Corner(search, 8); Pad(search, 34, 0, 10, 0)
    local sicon = Icon(presets, "search", 14, T.TextDim)
    sicon.Position = UDim2.new(0, 20, 0, 59)

    local plist = New("ScrollingFrame", {
        BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 2, ScrollBarImageColor3 = T.TextDim,
        Position = UDim2.new(0, 10, 0, 92), Size = UDim2.new(1, -20, 1, -150), CanvasSize = UDim2.new(),
        AutomaticCanvasSize = Enum.AutomaticSize.Y, Parent = presets,
    })
    List(plist, 8)

    ICON_ALIASES.x = { "x", "close" }
    local function rebuildPresets()
        for _, c in ipairs(plist:GetChildren()) do
            if c:IsA("GuiObject") then c:Destroy() end
        end
        local q = search.Text:lower()
        local shown = 0
        for i, name in ipairs(Library:ListConfigs()) do
            if q == "" or name:lower():find(q, 1, true) then
                shown = shown + (1)
                local cur = (Library.CurrentConfig == name)
                local row = New("TextButton", {
                    Text = "", AutoButtonColor = false, BackgroundColor3 = T.Section, BackgroundTransparency = cur and 0.35 or 0.7,
                    LayoutOrder = i, Size = UDim2.new(1, 0, 0, 36), Parent = plist,
                })
                Corner(row, 8); Stroke(row, 0.9)
                Text(row, name, {
                    Position = UDim2.new(0, 12, 0, 0), SizeUDim = UDim2.new(1, -92, 1, 0), Color = LBL,
                    Font = cur and F_SEMI or F_MED, Truncate = Enum.TextTruncate.AtEnd,
                })
                local dots = DotsButton(row)
                dots.AnchorPoint = Vector2.new(1, 0.5)
                dots.Position = UDim2.new(1, -8, 0.5, 0)
                local acts = New("Frame", {
                    BackgroundTransparency = 1, Visible = false, AnchorPoint = Vector2.new(1, 0.5),
                    Position = UDim2.new(1, -6, 0.5, 0), Size = UDim2.new(0, 246, 0, 24), Parent = row,
                })
                local isAuto = (Library:GetAutoload() == name)
                local badge
                if isAuto then
                    badge = New("TextLabel", {
                        BackgroundColor3 = T.Accent, BackgroundTransparency = 0.8, Text = "AUTO", TextColor3 = T.Text, TextSize = 9, FontFace = F_BOLD,
                        AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -34, 0.5, 0), Size = UDim2.new(0, 38, 0, 16), Parent = row,
                    })
                    Corner(badge, 8)
                end
                List(acts, 4, H, RIGHT, VCENTER)
                -- Overwrite / Delete need a second click ("Sure?") so a stray click can't destroy a config
                for _, def in ipairs({ { "Load", 44 }, { "Autoload", 64 }, { "Overwrite", 74 }, { "Delete", 52 } }) do
                    local a, w = def[1], def[2]
                    local ab = New("TextButton", {
                        Text = (a == "Autoload" and isAuto) and "Unset auto" or a, AutoButtonColor = false, BackgroundColor3 = T.Element, BackgroundTransparency = 0.5,
                        TextColor3 = (a == "Delete") and T.Enemy or T.TextDim, TextSize = 11, FontFace = F_MED,
                        Size = UDim2.new(0, w, 0, 24), Parent = acts,
                    })
                    Corner(ab, 6)
                    ab.MouseEnter:Connect(function() Tween(ab, { BackgroundTransparency = 0.25 }, 0.1) end)
                    ab.MouseLeave:Connect(function() Tween(ab, { BackgroundTransparency = 0.5 }, 0.1) end)
                    local armed = false
                    ab.MouseButton1Click:Connect(function()
                        if a == "Load" then Library:LoadConfig(name) return end
                        if a == "Autoload" then
                            if Library:GetAutoload() == name then Library:SetAutoload(nil) else Library:SetAutoload(name) end
                            return
                        end
                        if not armed then
                            armed = true
                            ab.Text = "Sure?"
                            task.delay(2, function()
                                if armed and ab.Parent then armed = false; ab.Text = a end
                            end)
                            return
                        end
                        armed = false
                        ab.Text = a
                        if a == "Overwrite" then Library:SaveConfig(name) else Library:DeleteConfig(name) end
                    end)
                end
                dots.MouseButton1Click:Connect(function()
                    dots.Visible = false
                    acts.Visible = true
                end)
                row.MouseButton1Click:Connect(function() Library:LoadConfig(name) end)
            end
        end
        if shown == 0 then
            New("TextLabel", {
                BackgroundTransparency = 1, Text = (q ~= "") and "No matching configs" or "No configs yet", TextColor3 = T.TextDim, TextSize = 12, FontFace = F_MED,
                Size = UDim2.new(1, 0, 0, 36), Parent = plist,
            })
        end
    end
    function Library.RefreshPresets()
        if presets.Visible then rebuildPresets() end
    end
    search:GetPropertyChangedSignal("Text"):Connect(rebuildPresets)

    -- footer: name a config and save it (this is the "Save config" button)
    local divider = New("Frame", {
        BackgroundColor3 = T.Stroke, BackgroundTransparency = 0.93, BorderSizePixel = 0,
        AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 10, 1, -52), Size = UDim2.new(1, -20, 0, 1), Parent = presets,
    })
    local nameBox = New("TextBox", {
        Text = "", PlaceholderText = "Config name...", PlaceholderColor3 = T.TextDim, ClearTextOnFocus = false,
        BackgroundColor3 = T.Section, BackgroundTransparency = 0.3, TextColor3 = T.Text, TextSize = 12, FontFace = F_MED,
        TextXAlignment = TLEFT, AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 10, 1, -10),
        Size = UDim2.new(1, -112, 0, 32), Parent = presets,
    })
    Corner(nameBox, 8); Pad(nameBox, 10, 0, 10, 0); Stroke(nameBox, 0.9)
    local saveBtn = New("TextButton", {
        Text = "Save config", AutoButtonColor = false, BackgroundColor3 = T.Element, BackgroundTransparency = 0.35,
        TextColor3 = T.Text, TextSize = 12, FontFace = F_SEMI, AnchorPoint = Vector2.new(1, 1),
        Position = UDim2.new(1, -10, 1, -10), Size = UDim2.new(0, 92, 0, 32), Parent = presets,
    })
    Corner(saveBtn, 8); Stroke(saveBtn, 0.85)
    saveBtn.MouseEnter:Connect(function() Tween(saveBtn, { BackgroundTransparency = 0.15 }, 0.1) end)
    saveBtn.MouseLeave:Connect(function() Tween(saveBtn, { BackgroundTransparency = 0.35 }, 0.1) end)
    local saveArmed = false
    local function doSave()
        local nm = nameBox.Text:gsub("^%s+", ""):gsub("%s+$", "")
        if nm == "" then Library:Notify("Configs", "Type a name for the config first", 3) return end
        local exists = false
        for _, n in ipairs(Library:ListConfigs()) do
            if n:lower() == nm:lower() then exists = true break end
        end
        if exists and not saveArmed then -- same name -> ask once before overwriting
            saveArmed = true
            saveBtn.Text = "Overwrite?"
            task.delay(2, function()
                if saveArmed and saveBtn.Parent then saveArmed = false; saveBtn.Text = "Save config" end
            end)
            return
        end
        saveArmed = false
        saveBtn.Text = "Save config"
        if Library:SaveConfig(nm) then nameBox.Text = "" end
    end
    saveBtn.MouseButton1Click:Connect(function() Shine(saveBtn, 8, 0.6); doSave() end)
    nameBox.FocusLost:Connect(function(enter) if enter then doSave() end end)
    nameBox:GetPropertyChangedSignal("Text"):Connect(function()
        if saveArmed then saveArmed = false; saveBtn.Text = "Save config" end
    end)

    iconBtn(-10, "save", function() -- quick overwrite of the currently loaded config
        if Library.CurrentConfig then Library:SaveConfig(Library.CurrentConfig)
        else Library:Notify("Configs", "No config loaded - type a name below and press Save config", 3) end
    end)
    iconBtn(-46, "folder", function() Library:OpenConfigFolder() end)

    local cfgTok = 0
    local function closeCfg()
        if not presets.Visible then return end
        cfgTok = cfgTok + (1)
        local my = cfgTok
        Tween(presets, { GroupTransparency = 1 }, 0.14)
        Tween(presetsScale, { Scale = 0.96 }, 0.14)
        task.delay(0.15, function() if cfgTok == my then presets.Visible = false end end)
    end
    local function openCfg()
        cfgTok = cfgTok + (1)
        if not Library.CfgPlaced then -- first time: dock it next to the window (or inside it when there's no room)
            Library.CfgPlaced = true
            local sc = Library.Scale
            local mp = main.AbsolutePosition - Root.AbsolutePosition
            local x = (mp.X + main.AbsoluteSize.X) / sc + 12
            if (x + 372) * sc > Root.AbsoluteSize.X then x = mp.X / sc + SIDE + 8 end
            presets.Position = UDim2.new(0, x, 0, mp.Y / sc + 8)
        end
        search.Text = ""
        nameBox.Text = ""
        rebuildPresets()
        presets.GroupTransparency = 1
        presetsScale.Scale = 0.96
        presets.Visible = true
        BringToFront(presets)
        Tween(presets, { GroupTransparency = 0 }, 0.2)
        Tween(presetsScale, { Scale = 1 }, 0.28, Enum.EasingStyle.Quint)
    end
    iconBtn(-82, "x", closeCfg)
    W.CloseConfigs = closeCfg
    MakeDraggable(cfgHandle, presets)
    cfgBtn.MouseButton1Click:Connect(function()
        if presets.Visible and presets.GroupTransparency < 0.5 then closeCfg() else openCfg() end
    end)

    -- show / hide / destroy
    -- open: scale up + slide up + blur in.  close: scale down + slide down + blur out, then hidden.
    local uiScale = New("UIScale", { Scale = 1, Parent = main })
    local shown, closing, closeTok, closeRest = false, false, 0, nil
    -- close fade: everything in the window fades out while it shrinks; values are restored once it is hidden
    local closeSaved, closeTweens = nil, {}
    local function restoreClose()
        for _, tw in ipairs(closeTweens) do pcall(function() tw:Cancel() end) end
        closeTweens = {}
        if not closeSaved then return end
        for d, rec in pairs(closeSaved) do
            if d.Parent then
                for p, v in pairs(rec) do pcall(function() d[p] = v end) end
            end
        end
        closeSaved = nil
    end
    local function fadeOutWindow(t)
        restoreClose()
        -- Fading the window out tweens EVERY descendant (thousands on a large menu) which stutters the close.
        -- Off by default: the scale + slide on `main` already reads as a close. Set Library.CloseFade = true to restore it.
        if not Library.CloseFade then return end
        closeSaved = {}
        local list = main:GetDescendants()
        list[#list + 1] = main
        for _, d in ipairs(list) do
            local props
            if d:IsA("UIStroke") then props = { "Transparency" }
            elseif d:IsA("GuiObject") and d.Visible then
                props = { "BackgroundTransparency" }
                if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then props[#props + 1] = "TextTransparency" end
                if d:IsA("ImageLabel") or d:IsA("ImageButton") then props[#props + 1] = "ImageTransparency" end
            end
            if props then
                local rec, goal
                for _, p in ipairs(props) do
                    local v = d[p]
                    if v < 1 then
                        rec, goal = rec or {}, goal or {}
                        rec[p] = v
                        goal[p] = 1
                    end
                end
                if rec then
                    closeSaved[d] = rec
                    closeTweens[#closeTweens + 1] = Tween(d, goal, t, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
                end
            end
        end
    end
    function W:SetVisible(v)
        v = v and true or false
        if not v and not shown then
            return
        end
        closeTok = closeTok + (1)
        local my = closeTok
        local st = RevealState[main]
        if v then
            if shown then return end
            Library.WindowAnimating = Library.HudAnimations
            shown = true
            if closing then -- re-opened mid-close: snap back to the resting spot and treat as hidden
                closing = false
                if closeRest then main.Position = closeRest end
                main.Visible = false
            end
            uiScale.Scale = 0.93
            Reveal(main, true, 22)
            Tween(uiScale, { Scale = 1 }, 0.38, Enum.EasingStyle.Quint)
            BringToFront(main)
            Blur.Enabled = Library.BlurOn
            if Library.BlurOn then
                Blur.Size = 0
                Tween(Blur, { Size = Library.BlurSize }, 0.4)
            end
            if Library.HudAnimations then
                task.delay(0.4, function()
                    if closeTok == my and shown then
                        Library.WindowAnimating = false
                        if Library.WindowShadowSync then Library.WindowShadowSync(true) end
                    end
                end)
            elseif Library.WindowShadowSync then
                Library.WindowShadowSync(true)
            end
            Library:RefreshBackdrop()
        else
            if not shown then shown = false return end
            shown = false
            ClosePopup()
            if W.CloseConfigs then W.CloseConfigs() end
            if W.StopDrag then W.StopDrag() end
            if glide then glide:Cancel(); glide = nil end
            if st and st.Tween then -- cut a running open animation short
                st.Tween:Cancel(); st.Tween = nil
                if st.Rest then main.Position = st.Rest end
            end
            Library.WindowAnimating = Library.HudAnimations
            if not Library.HudAnimations then
                closing = false
                main.Visible = false
                main.Position = closeRest or main.Position
                uiScale.Scale = 1
                Blur.Enabled = false
                Library.WindowAnimating = false
                if Library.WindowShadowSync then Library.WindowShadowSync(true) end
                if st then st.Rest = main.Position end
                Library:RefreshBackdrop()
                return
            end
            -- Close is a quick slide-down + shrink, then hide. No per-descendant fade (fadeOutWindow) -- that
            -- mass transparency tween on every element is what made opening/closing hitch. Matches aba.lua.
            closing, closeRest = true, main.Position
            Tween(main, { Position = closeRest + UDim2.new(0, 0, 0, 12) }, 0.26, Enum.EasingStyle.Cubic, Enum.EasingDirection.In)
            Tween(uiScale, { Scale = 0.9 }, 0.26, Enum.EasingStyle.Cubic, Enum.EasingDirection.In)
            if Library.BlurOn then Tween(Blur, { Size = 0 }, 0.26) end
            task.delay(0.27, function()
                if closeTok ~= my then return end
                closing = false
                main.Visible = false
                main.Position = closeRest
                uiScale.Scale = 1
                Blur.Enabled = false
                Library.WindowAnimating = false
                if Library.WindowShadowSync then Library.WindowShadowSync(true) end
                if st then st.Rest = main.Position end
                Library:RefreshBackdrop()
            end)
        end
    end
    function W:Toggle()
        local visible = not shown
        if Library:IsAutomationActive() then
            Library.AutomationWindowWasVisible = visible
        end
        W:SetVisible(visible)
    end
    function W:IsOpen() return shown end

    W.KeyConn = Track(UIS.InputBegan:Connect(function(i, gp)
        if gp then return end
        if i.KeyCode == Library.MenuKey then W:Toggle() end
    end))

    function W:Destroy()
        if W.KeyConn then W.KeyConn:Disconnect() end
        pcall(function() ghost:Destroy() end)
        for i = #Library.Panels, 1, -1 do
            if Library.Panels[i] == main then table.remove(Library.Panels, i) end
        end
        main:Destroy()
    end

    Library.Window = W
    Library.CreatingWindowMain = nil
    return W
end

function Library:CreateWindow(opts)
    return Library:CreateModernWindow(opts)
end

-- ============================================================================
-- Standalone floating window (feature visualizers / HUDs / lists).
-- A glass, rounded, draggable, themed panel that matches the main menu and lives in the library GUI
-- (so it follows the theme + Glass toggle and is cleaned up on Unload), but is independent of the menu key.
-- Returns { Frame, Body, Header, Show, Hide, Toggle, IsOpen, SetTitle, SetSize, OnClose, Section, AddHeaderButton }.
-- Build custom content into `.Body`; call `:Section(prefix)` for a scrolling body of native controls.
-- ============================================================================
function Library:CreateFloatingWindow(opts)
    opts = opts or {}
    local T = Library.Theme
    local size = opts.Size or UDim2.fromOffset(360, 300)
    local HEADER = opts.HeaderHeight or 38
    local win = {}

    local outer = New("Frame", {
        Name = opts.Name or "LumaWindow", BackgroundColor3 = T.Widget,
        BackgroundTransparency = select(3, Library.GlassValues()),
        AnchorPoint = Vector2.new(0.5, 0.5), Position = opts.Position or UDim2.new(0.5, 0, 0.5, 0),
        Size = size, Visible = false, ZIndex = 50, Parent = Root,
    })
    Corner(outer, 16)
    RegisterPanel(outer)
    ShadowFill(outer, 16, { Spread = 12, Offset = 3, Strength = 0.14 })
    local stroke = Stroke(outer, 0.42)
    New("UIGradient", {
        Rotation = 90, Parent = stroke,
        Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.72), NumberSequenceKeypoint.new(1, 0.9) }),
    })
    Library.Cards[#Library.Cards + 1] = outer -- track the Glass toggle like the menu's cards

    local header = New("Frame", { Name = "Header", BackgroundTransparency = 1, Active = true, Size = UDim2.new(1, 0, 0, HEADER), ZIndex = 51, Parent = outer })
    local titleLbl = Text(header, opts.Title or "Window", { Position = UDim2.new(0, 14, 0, 0), SizeUDim = UDim2.new(1, -92, 1, 0), Color = T.Text, Font = F_SEMI, Truncate = Enum.TextTruncate.AtEnd })

    -- right-aligned header button strip (close sits here, plus any AddHeaderButton)
    local btnStrip = New("Frame", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -8, 0.5, 0), Size = UDim2.new(0, 0, 0, 24), AutomaticSize = Enum.AutomaticSize.X, ZIndex = 52, Parent = header })
    List(btnStrip, 6, H, RIGHT, VCENTER)
    local function headerBtn(iconName, cb, order)
        local b = New("TextButton", {
            Text = "", AutoButtonColor = false, BackgroundColor3 = T.Section, BackgroundTransparency = 0.5,
            Size = UDim2.new(0, 24, 0, 24), LayoutOrder = order or 0, ZIndex = 52, Parent = btnStrip,
        })
        Corner(b, 7)
        local ic = Icon(b, iconName, 14, T.TextDim)
        ic.AnchorPoint = Vector2.new(0.5, 0.5); ic.Position = UDim2.new(0.5, 0, 0.5, 0)
        b.MouseEnter:Connect(function() Tween(b, { BackgroundTransparency = 0.2 }, 0.1); Tween(ic, { ImageColor3 = T.Text }, 0.1) end)
        b.MouseLeave:Connect(function() Tween(b, { BackgroundTransparency = 0.5 }, 0.1); Tween(ic, { ImageColor3 = T.TextDim }, 0.1) end)
        b.MouseButton1Click:Connect(function() Shine(b, 7, 0.6); if cb then task.spawn(cb) end end)
        return b
    end

    New("Frame", {
        BackgroundColor3 = T.Stroke, BackgroundTransparency = 0.9, BorderSizePixel = 0,
        Position = UDim2.new(0, 10, 0, HEADER), Size = UDim2.new(1, -20, 0, 1), ZIndex = 51, Parent = outer,
    })

    local body = New("Frame", {
        Name = "Body", BackgroundTransparency = 1, Position = UDim2.new(0, 0, 0, HEADER + 2),
        Size = UDim2.new(1, 0, 1, -(HEADER + 2)), ZIndex = 51, Parent = outer,
    })

    -- light, live drag from the header (no ghost: these windows track the cursor directly)
    local dragging, startPos, startAbs = false, nil, nil
    header.InputBegan:Connect(function(i)
        if i.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
        dragging = true
        startPos, startAbs = outer.Position, Vector2.new(i.Position.X, i.Position.Y)
        BringToFront(outer)
    end)
    Track(UIS.InputChanged:Connect(function(i)
        if dragging and i.UserInputType == Enum.UserInputType.MouseMovement then
            local d = (Vector2.new(i.Position.X, i.Position.Y) - startAbs) / Library.Scale
            outer.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
        end
    end))
    Track(UIS.InputEnded:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 then dragging = false end
    end))

    win.Frame, win.Body, win.Header = outer, body, header
    Library.SilentWindows[win] = true
    function win:IsOpen() return outer.Visible end
    function win:Show()
        if Library.SilentMode then
            win._silentVisible = true
            outer.Visible = false
            return
        end
        outer.Visible = true
        BringToFront(outer)
    end
    function win:Hide()
        win._silentVisible = false
        outer.Visible = false
    end
    function win:Toggle()
        if Library.SilentMode then
            win._silentVisible = not win._silentVisible
            outer.Visible = false
            return
        end
        outer.Visible = not outer.Visible
        if outer.Visible then BringToFront(outer) end
    end
    function win:SetVisible(v) if v then self:Show() else self:Hide() end end
    function win:SetTitle(t) titleLbl.Text = tostring(t or "") end
    function win:SetSize(w, h) outer.Size = UDim2.fromOffset(w, h) end
    function win:SetPosition(p) outer.Position = p end
    function win:AddHeaderButton(iconName, cb) return headerBtn(iconName, cb, -1) end
    function win:OnClose(fn) win._onClose = fn end

    local closeBtn = headerBtn("x", function()
        win:Hide()
        if opts.OnClose then task.spawn(opts.OnClose) end
        if win._onClose then task.spawn(win._onClose) end
    end, 100)
    win.CloseButton = closeBtn

    -- A scrolling body of native controls (toggles/sliders/labels/...). Rows parent straight to the
    -- scroll frame via a no-op skin, so this is the same control set as a menu section.
    function win:Section(prefix)
        local pad = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 0), Parent = body })
        Pad(pad, 12, 8, 12, 10)
        local sf = New("ScrollingFrame", {
            BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 2, ScrollBarImageColor3 = T.TextDim,
            ScrollingDirection = Enum.ScrollingDirection.Y, Size = UDim2.new(1, 0, 1, 0),
            CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, Parent = pad,
        })
        List(sf, 0)
        return BuildElements(sf, prefix or (opts.Title or "Win"), { RowH = 36, Reveal = function() end, OnRow = function() end })
    end

    return win
end

-- background image
-- Library:SetBackgroundImage(12345678)            -- Roblox image asset ID (number, "rbxassetid://123" or a full url); "" clears it
-- Library:SetBackgroundOpacity(0..1)              -- 1 = fully visible image
-- Library:SetBackgroundFit("Crop"|"Fit"|"Stretch"|"Tile")
-- Note: use the IMAGE id of the asset (a Decal's id shows nothing in many games - get the image id from the Decal).
Library.BgImageId = ""
Library.BgOpacity = 0.75 -- the sidebar and cards sit on top of the image, so a low value is hard to see
local BG_FITS = { Crop = Enum.ScaleType.Crop, Fit = Enum.ScaleType.Fit, Stretch = Enum.ScaleType.Stretch, Tile = Enum.ScaleType.Tile }

function Library:SetBackgroundImage(id)
    local img = Library.Window and Library.Window.BgImage
    if not img then return false end
    local s = (tostring(id or ""):gsub("%s+", ""))
    Library.BgImageId = s
    if s == "" then
        img.Image = ""
        img.Visible = false
        return true
    end
    local url
    if s:find("://", 1, true) then
        url = s
    elseif s:match("^%d+$") then
        url = "rbxassetid://" .. s
    elseif s:match("%.%w+$") and isfile and getcustomasset and isfile(s) then
        -- a local image file from your executor's workspace folder, e.g. "Matcha/bg.png"
        local ok, a = pcall(getcustomasset, s)
        if ok then url = a end
    else
        local n = s:match("%d+")
        url = n and ("rbxassetid://" .. n) or nil
    end
    if not url then
        Library:Notify("Background", "That isn't a valid asset ID", 3)
        return false
    end
    img.Image = url
    img.ImageTransparency = 1
    img.Visible = true
    Tween(img, { ImageTransparency = 1 - Library.BgOpacity }, 0.4)

    local my = (Library.BgToken or 0) + 1
    Library.BgToken = my
    task.spawn(function()
        -- a Decal id renders nothing in an ImageLabel: if the asset turns out to be a Decal, swap in its real image
        if url:match("^rbxassetid://%d+$") and game.GetObjects then
            local ok, objs = pcall(function() return game:GetObjects(url) end)
            local o = ok and type(objs) == "table" and objs[1] or nil
            if o and (o:IsA("Decal") or o:IsA("Texture")) and o.Texture ~= "" and Library.BgToken == my then
                img.Image = o.Texture
            end
            if o then pcall(function() o:Destroy() end) end
        end
        if Library.BgToken ~= my then return end
        pcall(function() game:GetService("ContentProvider"):PreloadAsync({ img }) end)
        if Library.BgToken == my and not img.IsLoaded then
            Library:Notify("Background", "Image failed to load - use an Image ID (not a Decal ID) of a public, approved asset", 5)
        end
    end)
    return true
end

function Library:SetBackgroundOpacity(a)
    Library.BgOpacity = math.clamp(tonumber(a) or Library.BgOpacity, 0, 1)
    local img = Library.Window and Library.Window.BgImage
    if img and img.Visible then Tween(img, { ImageTransparency = 1 - Library.BgOpacity }, 0.15) end
end

function Library:SetBackgroundFit(name)
    local img = Library.Window and Library.Window.BgImage
    if img and BG_FITS[name] then img.ScaleType = BG_FITS[name] end
end

-- widget base
-- Widget pills have NO border any more: they get a drop shadow instead (like the real menu).
local function WidgetPill(parent, radius)
    local f = New("Frame", { BackgroundColor3 = Library.Theme.Widget, BackgroundTransparency = 0.08, ZIndex = 100, Parent = parent })
    Corner(f, radius or 12)
    Shadow(f, radius or 12, { Spread = 9, Offset = 2, Strength = 0.35 })
    return f
end

-- WIDGETS (glass style, matches real Matcha)
-- Real widgets are near-black translucent pills: no borders, drop shadow, pills sized to fit.

local GLASS = {
    Near = Color3.fromRGB(19, 19, 25),
    Text = Color3.fromRGB(224, 226, 230),
    Dim = Color3.fromRGB(150, 156, 162),
    KeyText = Color3.fromRGB(172, 175, 180),
}

-- edge: pass a number to get a hairline border (keystrokes use it). nil = no border at all.
local function Glass(parent, radius, transparency, edge)
    local f = New("Frame", {
        BackgroundColor3 = GLASS.Near, BackgroundTransparency = transparency or 0.15,
        BorderSizePixel = 0, ZIndex = 100, Parent = parent,
    })
    Corner(f, radius or 8)
    local s = New("UIStroke", {
        Color = WHITE, Transparency = edge or 1, Thickness = 1, Enabled = edge ~= nil,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = f,
    })
    return f, s
end

-- reliable text width: let a hidden TextLabel measure it (falls back to Measure)
local probe
local function TextW(text, size, font)
    local ok, w = pcall(function()
        if not (probe and probe.Parent) then
            probe = New("TextLabel", {
                BackgroundTransparency = 1, TextTransparency = 1, RichText = true,
                Size = UDim2.new(0, 600, 0, 30), Position = UDim2.new(0, -9999, 0, 0), Parent = Library.Gui,
            })
        end
        probe.FontFace, probe.TextSize, probe.Text = font, size + Library.TextBoost, text
        return probe.TextBounds.X
    end)
    if ok and w and w > 0 then return math.ceil(w) + 2 end
    return Measure(text, size, font)
end

-- branding
-- getgenv().LumaLogo = "Luma/logo.png" (executor workspace file) | image asset id | url   -> optional logo for MakeLumaLogo
Library.Brand = {
    Name = tostring(genv.LumaName or "Luma"),
    Logo = genv.LumaLogo,
    Color = Color3.fromRGB(150, 176, 236),  -- periwinkle accent
    Color2 = Color3.fromRGB(100, 130, 212),
}

local function LumaLogoImage()
    local l = Library.Brand.Logo
    if not l or l == "" then return nil end
    l = tostring(l)
    if l:find("://", 1, true) then return l end
    if l:match("^%d+$") then return "rbxassetid://" .. l end
    if isfile and getcustomasset and isfile(l) then
        local ok, a = pcall(getcustomasset, l)
        if ok then return a end
    end
    return nil
end

-- a drawn blue "L" on a dark rounded tile (or your logo image if Library.Brand.Logo is set). Not used by default any more.
function Library.MakeLumaLogo(parent, size)
    local B = Library.Brand
    local box = New("Frame", { BackgroundColor3 = Color3.fromRGB(12, 13, 18), BorderSizePixel = 0, Size = UDim2.fromOffset(size, size), Parent = parent })
    local rad = math.floor(size * 0.28)
    Corner(box, rad)
    New("UIStroke", { Color = WHITE, Transparency = 0.8, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = box })
    local img = LumaLogoImage()
    if img then
        local il = New("ImageLabel", { BackgroundTransparency = 1, Image = img, Size = UDim2.new(1, 0, 1, 0), ScaleType = Enum.ScaleType.Fit, Parent = box })
        Corner(il, rad)
        return box
    end
    local function bar(x, y, w, h)
        local b = New("Frame", { BackgroundColor3 = WHITE, BorderSizePixel = 0, Position = UDim2.new(x, 0, y, 0), Size = UDim2.new(w, 0, h, 0), Parent = box })
        Corner(b, math.max(1, math.floor(size * 0.07)))
        New("UIGradient", { Color = ColorSequence.new(B.Color, B.Color2), Rotation = 90, Parent = b })
    end
    bar(0.30, 0.22, 0.16, 0.56)
    bar(0.30, 0.62, 0.42, 0.16)
    return box
end

-- watermark
function Library:CreateWatermark(opts)
    opts = opts or {}
    local user = opts.User or LocalPlayer.Name
    local TS = 15 -- text size (bigger watermark)
    ICON_ALIASES.external = { "square-arrow-out-up-right", "external-link", "map-pin" }
    ICON_ALIASES.fpsicon = { "chart-no-axes-column", "bar-chart-3", "bar-chart", "monitor" }

    local wm, wmStroke = Glass(Root, 8, 0.2, 0.6) -- hairline border: animated blue gradient (see below)
    Shadow(wm, 8, { Spread = 9, Offset = 2, Strength = 0.28 })
    wm.AnchorPoint = Vector2.new(0.5, 0)
    wm.Position = UDim2.new(0.5, 0, 0, 72)
    wm.Size = UDim2.new(0, 0, 0, 34)
    wm.AutomaticSize = Enum.AutomaticSize.X
    Pad(wm, 14, 0, 10, 0)
    List(wm, 18, H, LEFT, VCENTER)
    MakeDraggable(wm, wm)

    local order = 0

    -- brand block: logo image, then a thin divider
    local B = Library.Brand
    do
        order = order + (1)
        local brand = New("Frame", {
            Name = "LumaBrand", BackgroundTransparency = 1, LayoutOrder = order, Size = UDim2.new(0, 0, 1, 0),
            AutomaticSize = Enum.AutomaticSize.X, Parent = wm,
        })
        List(brand, 8, H, LEFT, VCENTER)
        local lumaText = New("TextLabel", {
            Name = "LumaText", BackgroundTransparency = 1, Text = "luma", TextColor3 = WHITE, TextSize = 19,
            FontFace = F_BOLD, TextXAlignment = TLEFT, LayoutOrder = 1,
            Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, Parent = brand,
        })
        local lumaGrad = New("UIGradient", { Parent = lumaText })
        local lt0 = os.clock()
        order = order + (1)
        New("Frame", { Name = "LumaDivider", BackgroundColor3 = WHITE, BackgroundTransparency = 0.86, BorderSizePixel = 0, LayoutOrder = order, Size = UDim2.new(0, 1, 0, 16), Parent = wm })

        wmStroke.Color = WHITE
        local sg = New("UIGradient", {
            Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, B.Color),
                ColorSequenceKeypoint.new(0.5, B.Color2),
                ColorSequenceKeypoint.new(1, B.Color),
            }),
            Parent = wmStroke,
        })
        local t0 = os.clock()
        local watermarkAnimationElapsed = 0
        local lastAccent = Library.Theme.Accent
        local lastAccent2 = Library.UseAccent2 and Library.Theme.Accent2 or lastAccent:Lerp(WHITE, 0.6)
        lumaGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, lastAccent),
            ColorSequenceKeypoint.new(0.5, lastAccent2),
            ColorSequenceKeypoint.new(1, lastAccent),
        })
        Track(RunService.Heartbeat:Connect(function(dt)
            if not wm.Visible then return end
            watermarkAnimationElapsed = watermarkAnimationElapsed + dt
            if watermarkAnimationElapsed < 1 / 30 then return end
            watermarkAnimationElapsed = watermarkAnimationElapsed % (1 / 30)

            local accent = Library.Theme.Accent
            local accent2 = Library.UseAccent2 and Library.Theme.Accent2 or accent:Lerp(WHITE, 0.6)
            if accent ~= lastAccent or accent2 ~= lastAccent2 then
                lumaGrad.Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, accent),
                    ColorSequenceKeypoint.new(0.5, accent2),
                    ColorSequenceKeypoint.new(1, accent),
                })
                lastAccent, lastAccent2 = accent, accent2
            end

            if not Library.HudAnimations then return end
            local now = os.clock()
            lumaGrad.Offset = Vector2.new(math.sin((now - lt0) * 1.6), 0)
            sg.Rotation = ((now - t0) * 50) % 360
        end))
    end

    local function group()
        order = order + (1)
        local g = New("Frame", {
            BackgroundTransparency = 1, LayoutOrder = order, Size = UDim2.new(0, 0, 1, 0),
            AutomaticSize = Enum.AutomaticSize.X, Parent = wm,
        })
        List(g, 7, H, LEFT, VCENTER)
        return g
    end
    local function fmt(n, unit) return ("<b>%s</b> <font color='rgb(150,156,162)'>%s</font>"):format(n, unit) end

    -- fixed = a template string used to reserve width so the pill doesn't jitter while numbers change
    local function pair(iconName, text, fixed)
        local g = group()
        local wic = Icon(g, iconName, 16, WHITE)
        wic.LayoutOrder = 1
        Library.Tint(wic, "ImageColor3")
        local lbl
        if fixed then
            lbl = New("TextLabel", {
                BackgroundTransparency = 1, Text = text, RichText = true, TextColor3 = GLASS.Text, TextSize = TS,
                FontFace = F_SEMI, TextXAlignment = TLEFT, Size = UDim2.new(0, TextW(fixed, TS, F_SEMI), 1, 0), Parent = g,
            })
        else
            lbl = AutoText(g, text, GLASS.Text, TS, F_SEMI)
        end
        lbl.LayoutOrder = 2
        return lbl
    end

    local fps = pair("fpsicon", fmt("0", "FPS"), fmt("000", "FPS"))
    local ms = pair("signal", fmt("0", "MS"), fmt("000", "MS"))
    local clock = pair("clock", "00:00:00", "00:00:00")
    pair("user", user)

    order = order + (1)
    local avatar = New("Frame", {
        BackgroundTransparency = 1, LayoutOrder = order, Size = UDim2.new(0, 26, 0, 26), Parent = wm,
    })
    Corner(avatar, 13)
    local letter = Text(avatar, string.upper(user:sub(1, 1)), { AlignX = TCENTER, Color = Color3.fromRGB(150, 156, 162), Size = 12, Font = F_BOLD })
    task.spawn(function()
        local ok, img = pcall(Players.GetUserThumbnailAsync, Players, LocalPlayer.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48)
        if ok and img and avatar.Parent then
            local pic = New("ImageLabel", { BackgroundTransparency = 1, Image = img, Size = UDim2.new(1, 0, 1, 0), Parent = avatar })
            Corner(pic, 13)
            letter.Visible = false
        end
    end)

    local started, frames, last = os.clock(), 0, os.clock()
    Track(RunService.RenderStepped:Connect(function()
        if not wm.Visible then
            frames, last = 0, os.clock()
            return
        end
        frames = frames + (1)
        local now = os.clock()
        if now - last >= 0.5 then
            local fv = math.floor(frames / (now - last) + 0.5)
            fps.Text = fmt(("%d"):format(fv), "FPS")
            frames, last = 0, now
            local ok, ping = pcall(function() return Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
            local mv = math.floor((ok and ping or 0) + 0.5)
            ms.Text = fmt(("%d"):format(mv), "MS")
            -- quality colours: green = good, yellow = ok, red = bad
            Tween(fps, { TextColor3 = fv >= 55 and Color3.fromRGB(120, 225, 150) or (fv >= 30 and Color3.fromRGB(245, 205, 90) or Color3.fromRGB(255, 100, 100)) }, 0.25)
            Tween(ms, { TextColor3 = mv <= 0 and GLASS.Text or (mv <= 70 and Color3.fromRGB(120, 225, 150) or (mv <= 140 and Color3.fromRGB(245, 205, 90) or Color3.fromRGB(255, 100, 100))) }, 0.25)
            local e = math.floor(now - started)
            clock.Text = ("%02d:%02d:%02d"):format(e // 3600, (e % 3600) // 60, e % 60)
        end
    end))
    Library.Watermark = wm
    Library:TrackSilentWidget("Watermark", wm)
    return wm
end

-- hotkey list (floating)
-- every row is TWO near-black pills: [toggle][name] or [key][name]  (compact in v4)
function Library:CreateHotkeyList()
    local holder = New("Frame", {
        BackgroundTransparency = 1, Position = UDim2.new(0, 60, 0.55, 0), ZIndex = 100,
        Size = UDim2.new(0, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.XY, Parent = Root,
    })
    List(holder, 5, V, LEFT)

    local head = Glass(holder, 7, 0.4)
    Shadow(head, 7, { Spread = 6, Offset = 1, Strength = 0.26 })
    head.LayoutOrder = 0
    head.Size = UDim2.new(0, 0, 0, 27)
    head.AutomaticSize = Enum.AutomaticSize.X
    Pad(head, 11, 0, 12, 0)
    List(head, 7, H, LEFT, VCENTER)
    local hic = Icon(head, "list", 15, WHITE)
    hic.LayoutOrder = 1
    Library.Tint(hic, "ImageColor3")
    AutoText(head, "Hotkeys", WHITE, 14, F_BOLD).LayoutOrder = 2
    MakeDraggable(head, holder)

    local rows = {}
    local function pill(parent, order, pad)
        local p = Glass(parent, 6, 0.4)
        Shadow(p, 6, { Spread = 5, Offset = 1, Strength = 0.24 })
        p.LayoutOrder = order
        p.Size = UDim2.new(0, 0, 0, 24)
        p.AutomaticSize = Enum.AutomaticSize.X
        Pad(p, pad or 10, 0, pad or 10, 0)
        List(p, 6, H, LEFT, VCENTER)
        return p
    end

    local function createRow(entry, name)
        local row = New("Frame", {
            BackgroundTransparency = 1, LayoutOrder = 1,
            Size = UDim2.new(0, 0, 0, 24), AutomaticSize = Enum.AutomaticSize.X,
            Visible = false, Parent = holder,
        })
        List(row, 5, H, LEFT, VCENTER)

        local key = pill(row, 1)
        local keyText = AutoText(key, "", GLASS.Text, 13, F_MED)
        local namePill = pill(row, 2)
        local nameText = AutoText(namePill, name, GLASS.Text, 13, F_MED)
        local state
        if entry.Toggle then
            local statePill = pill(row, 3)
            local track = New("Frame", {
                BackgroundColor3 = Library.Theme.Track,
                Size = UDim2.new(0, 18, 0, 10),
                Parent = statePill,
            })
            Corner(track, 5)
            local knob = New("Frame", {
                BackgroundColor3 = Library.Theme.TextDim,
                Size = UDim2.new(0, 6, 0, 6),
                Position = UDim2.new(0, 2, 0.5, 0),
                AnchorPoint = Vector2.new(0, 0.5),
                Parent = track,
            })
            Corner(knob, 3)
            state = { Track = track, Knob = knob }
        end

        return {
            Frame = row,
            Key = keyText,
            Name = nameText,
            State = state,
        }
    end

    function Library.RefreshHotkeys()
        local entries = {}
        for flag, entry in pairs(Library.Keybinds) do
            if type(entry) == "table" and entry.Bind then
                local key = tostring(entry.Bind.Key or "none")
                local keyLower = key:lower()
                if key ~= "" and keyLower ~= "none" and keyLower ~= "n/a" then
                    entries[#entries + 1] = {
                        Entry = entry,
                        Flag = tostring(entry.Flag or flag),
                        Name = tostring(entry.Name or entry.Flag or flag or "Keybind"),
                        Key = key,
                    }
                end
            end
        end
        table.sort(entries, function(a, b)
            if a.Name == b.Name then
                return a.Flag < b.Flag
            end
            return a.Name < b.Name
        end)

        local visibleEntries = {}
        for index, item in ipairs(entries) do
            local entry = item.Entry
            local row = rows[entry]
            if not row then
                row = createRow(entry, item.Name)
                rows[entry] = row
            end
            row.Frame.LayoutOrder = index
            row.Key.Text = Cap(item.Key)
            row.Name.Text = item.Name
            if row.State then
                local enabled = Library.Flags[item.Flag] == true
                if entry.Toggle then enabled = entry.Toggle.Value == true end
                row.State.Track.BackgroundColor3 = enabled and Library.Theme.Accent or Library.Theme.Track
                row.State.Knob.Position = enabled and UDim2.new(1, -2, 0.5, 0)
                    or UDim2.new(0, 2, 0.5, 0)
                row.State.Knob.AnchorPoint = enabled and Vector2.new(1, 0.5)
                    or Vector2.new(0, 0.5)
                row.State.Knob.BackgroundColor3 = enabled and Library.Theme.Background or Library.Theme.TextDim
            end
            row.Frame.Visible = true
            visibleEntries[entry] = true
        end

        for entry, row in pairs(rows) do
            if not visibleEntries[entry] then
                row.Frame.Visible = false
            end
        end
    end

    Library.Hotkeys = holder
    Library:TrackSilentWidget("Hotkeys", holder)
    Library.RefreshHotkeys()
    return holder
end

-- array list
-- Styles: "Clean" (default, like the real one), "Bar", "Bracket", "Underline", "Glow"
function Library:CreateArrayList()
    local holder = New("Frame", {
        BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -16, 0, 64), ZIndex = 100,
        Size = UDim2.new(0, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.XY, Parent = Root,
    })
    List(holder, 6, V, RIGHT)
    local cache, building, again = {}, false, false
    local DIM = "rgb(150,156,162)"

    local function buildEntry(e, idx)
        local T = Library.Theme
        local cfg = Library.ArrayCfg
        local ts, style = cfg.TextSize, cfg.Style
        local plain = e.Name .. (e.Info and (" " .. e.Info) or "")
        local rich = e.Name .. (e.Info and (" <font color='" .. DIM .. "'>" .. e.Info .. "</font>") or "")
        if style == "Bracket" then
            local ac = cfg.AccentLine and Rgb(Library.GetAccent2()) or DIM
            rich = ("<font color='%s'>[</font> %s <font color='%s'>]</font>"):format(ac, rich, ac)
            plain = "[ " .. plain .. " ]"
        end
        local p, st = Glass(holder, 7, 0.45)
        Shadow(p, 7, { Spread = 6, Offset = 1, Strength = 0.3 })
        p.LayoutOrder = idx
        p.Size = UDim2.new(0, 0, 0, ts + 13)
        p.AutomaticSize = Enum.AutomaticSize.X
        Pad(p, 10, 0, (style == "Bar" and cfg.AccentLine) and 16 or 10, 0)
        if not cfg.Background then p.BackgroundTransparency = 1 end
        local lbl = AutoText(p, rich, cfg.Gradient and WHITE or GLASS.Text, ts, F_MED)
        local grad
        if cfg.Gradient then
            -- colours are written every frame by the flow updater below (one gradient across the whole list)
            grad = New("UIGradient", { Rotation = 90, Parent = lbl })
        end
        if cfg.AccentLine and style ~= "Clean" then
            local phase = idx * 0.2
            if style == "Bar" then
                local b = New("Frame", {
                    BackgroundColor3 = WHITE, BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 0.5),
                    Position = UDim2.new(1, -5, 0.5, 0), Size = UDim2.new(0, 2, 0, ts - 2), Parent = p,
                })
                Corner(b, 1)
                AccentGradient(b, 0.45, phase, 90)
            elseif style == "Underline" then
                local u = New("Frame", {
                    BackgroundColor3 = WHITE, BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 1),
                    Position = UDim2.new(0, 10, 1, -2), Size = UDim2.new(0, TextW(plain, ts, F_MED), 0, 2), Parent = p,
                })
                Corner(u, 1)
                AccentGradient(u, 0.45, phase)
            elseif style == "Glow" then
                -- soft halo (stacked fills, no stroke). The pill is made near-opaque so the halo only shows outside it.
                -- (halo is tighter now: Spread 5 / Strength 0.45, was 9 / 0.5)
                p.BackgroundTransparency = 0.1
                Shadow(p, 7, { Spread = 5, Offset = 0, Strength = 0.45, Color = T.Accent:Lerp(Library.GetAccent2(), 0.5) })
            end
        end
        return p, lbl, grad
    end

    local function refresh()
        local cfg = Library.ArrayCfg
        local list = {}
        for _, f in pairs(Library.Features) do
            if f.Toggle.Value then
                local info = f.InfoFlag and Library.Flags[f.InfoFlag]
                list[#list + 1] = { Name = f.Name, Info = (info ~= nil) and tostring(info) or nil }
            end
        end
        table.sort(list, function(a, b)
            local la, lb = #a.Name + #(a.Info or ""), #b.Name + #(b.Info or "")
            if la ~= lb then return la > lb end
            return a.Name < b.Name
        end)
        local seen = {}
        for idx, e in ipairs(list) do
            local sig = table.concat({ e.Name, tostring(e.Info), cfg.TextSize, tostring(cfg.Background), tostring(cfg.AccentLine), cfg.Style, tostring(cfg.Gradient) }, "|")
            local c = cache[e.Name]
            if c and c.Sig == sig and c.Frame.Parent then
                c.Frame.LayoutOrder = idx
            else
                if c then c.Frame:Destroy() end
                local f, lbl, grad = buildEntry(e, idx)
                cache[e.Name] = { Frame = f, Sig = sig, Label = lbl, Grad = grad }
                Shine(f, 7, 0.7)
            end
            seen[e.Name] = true
        end
        for name, c in pairs(cache) do
            if not seen[name] then c.Frame:Destroy(); cache[name] = nil end
        end
    end

    function Library.RefreshArray(force)
        if force == true then
            for _, c in pairs(cache) do c.Sig = "" end
        end
        if building then again = true return end
        building = true
        task.spawn(function()
            repeat
                again = false
                local ok, err = pcall(refresh)
                if not ok then warn("[Matcha] array list: " .. tostring(err)) end
            until not again or Library.Dead
            building = false
        end)
    end

    -- ONE continuous theme gradient across every entry, flowing bottom -> top.
    -- Each label gets the slice of the shared palette that matches where it sits in the list.
    local gAcc = 0
    Track(RunService.RenderStepped:Connect(function(dt)
        if not Library.HudAnimations or not holder.Visible or not Library.ArrayCfg.Gradient then return end
        gAcc = gAcc + (dt)
        if gAcc < 1 / 30 then return end
        gAcc = 0
        local sc, T = Library.Scale, Library.Theme
        local a, b = T.Accent, Library.GetAccent2()
        -- both accents identical (e.g. default white/white)? fade towards a darker shade so the flow is still visible
        if (a.R - b.R) ^ 2 + (a.G - b.G) ^ 2 + (a.B - b.B) ^ 2 < 0.02 then b = a:Lerp(Color3.new(0, 0, 0), 0.5) end
        local top = holder.AbsolutePosition.Y
        local period = math.max(holder.AbsoluteSize.Y / sc, 120)
        local phase = AnimTime * Library.ArrayCfg.GradSpeed
        for _, c in pairs(cache) do
            local l, g = c.Label, c.Grad
            if l and g and l.Parent and g.Parent then
                local y0 = (l.AbsolutePosition.Y - top) / sc
                local h = l.AbsoluteSize.Y / sc
                local keys = {}
                for k = 0, 5 do
                    local x = (y0 + h * k / 5) / period + phase -- phase grows => pattern moves UP
                    local m = 0.5 - 0.5 * math.cos(x * 2 * math.pi)
                    keys[#keys + 1] = ColorSequenceKeypoint.new(k / 5, a:Lerp(b, m))
                end
                g.Color = ColorSequence.new(keys)
            end
        end
    end))

    MakeDraggable(holder, holder)
    Library:TrackSilentWidget("ArrayList", holder)
    Library.RefreshArray()
    return holder
end

-- keystrokes (WASD + space + LMB/RMB with CPS)
-- Intentionally NO shadow here (matches the real one).
function Library:CreateKeystrokes()
    local KEY, G = 40, 4
    local W = KEY * 3 + G * 2 -- 128
    local f = New("Frame", {
        BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -40),
        Size = UDim2.new(0, W, 0, 156), Visible = false, ZIndex = 100, Parent = Root,
    })
    local keys = {}
    local function key(id, text, x, y, w, h)
        local k, ks = Glass(f, 6, 0.15, 0.93)
        k.Position, k.Size = UDim2.new(0, x, 0, y), UDim2.new(0, w, 0, h)
        local l = Text(k, text, { AlignX = TCENTER, Color = GLASS.KeyText, Size = 13, Font = F_BOLD })
        keys[id] = { Frame = k, Label = l, Stroke = ks }
        return k
    end
    key("W", "W", KEY + G, 0, KEY, KEY)
    key("A", "A", 0, KEY + G, KEY, KEY)
    key("S", "S", KEY + G, KEY + G, KEY, KEY)
    key("D", "D", (KEY + G) * 2, KEY + G, KEY, KEY)
    local sy = (KEY + G) * 2
    local space = key("Space", "", 0, sy, W, 16)
    local dash = New("Frame", {
        BackgroundColor3 = Color3.fromRGB(205, 208, 212), BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(0.5, 0, 0.5, 0), Size = UDim2.new(0, 24, 0, 2), Parent = space,
    })
    Corner(dash, 1)
    local my = sy + 20
    local mw = (W - G) / 2
    key("LMB", "LMB", 0, my, mw, 30)
    key("RMB", "RMB", mw + G, my, mw, 30)

    local cpsL, cpsR = {}, {}
    local function cpsLabel(x)
        return Text(f, "0 CPS", {
            Position = UDim2.new(0, x, 0, my + 33), SizeUDim = UDim2.new(0, mw, 0, 12),
            AlignX = TCENTER, Size = 10, Color = Color3.fromRGB(228, 230, 233), Font = F_BOLD,
        })
    end
    local lblL, lblR = cpsLabel(0), cpsLabel(mw + G)

    -- pressed look: translucent grey fill + light outline + white text (like the real widget)
    local PRESSED = Color3.fromRGB(148, 150, 155)
    local function paint(id, down)
        local k = keys[id]
        if not k then return end
        Tween(k.Frame, { BackgroundColor3 = down and Library.Theme.Accent:Lerp(Color3.new(0, 0, 0), 0.42) or GLASS.Near, BackgroundTransparency = down and 0.2 or 0.15 }, 0.08)
        Tween(k.Stroke, { Transparency = down and 0.3 or 0.93 }, 0.08)
        Tween(k.Label, { TextColor3 = down and WHITE or GLASS.KeyText }, 0.08)
    end
    local function idOf(i)
        local ut = i.UserInputType
        if ut == Enum.UserInputType.Keyboard then
            local n = i.KeyCode.Name
            if keys[n] and n ~= "LMB" and n ~= "RMB" then return n end
        elseif ut == Enum.UserInputType.MouseButton1 then return "LMB"
        elseif ut == Enum.UserInputType.MouseButton2 then return "RMB" end
    end
    Track(UIS.InputBegan:Connect(function(i)
        local id = idOf(i)
        if not id then return end
        paint(id, true)
        if id == "LMB" then cpsL[#cpsL + 1] = os.clock() elseif id == "RMB" then cpsR[#cpsR + 1] = os.clock() end
    end))
    Track(UIS.InputEnded:Connect(function(i)
        local id = idOf(i)
        if id then paint(id, false) end
    end))

    local acc = 0
    Track(RunService.Heartbeat:Connect(function(dt)
        acc = acc + (dt)
        if acc < 0.1 then return end
        acc = 0
        local now = os.clock()
        while cpsL[1] and now - cpsL[1] > 1 do table.remove(cpsL, 1) end
        while cpsR[1] and now - cpsR[1] > 1 do table.remove(cpsR, 1) end
        lblL.Text = #cpsL .. " CPS"
        lblR.Text = #cpsR .. " CPS"
    end))

    MakeDraggable(f, f)
    Library:TrackSilentWidget("Keystrokes", f)
    return f
end

-- lag notifier
function Library:CreateLagNotifier()
    local T = Library.Theme
    local p = WidgetPill(Root, 13)
    p.AnchorPoint = Vector2.new(0.5, 0)
    p.Position = UDim2.new(0.5, 0, 0, 104)
    p.Size = UDim2.new(0, 0, 0, 30)
    p.AutomaticSize = Enum.AutomaticSize.X
    p.Visible = false
    Pad(p, 14, 0, 14, 0)
    List(p, 8, H, CENTER, VCENTER)
    Icon(p, "triangle-alert", 13, Color3.fromRGB(255, 190, 80))
    local lbl = AutoText(p, "Lag detected", T.Text, 12, F_SEMI)
    local hideAt = 0
    Track(RunService.Heartbeat:Connect(function(dt)
        if not Library.Widgets.LagEnabled then return end
        if dt > 0.2 then
            lbl.Text = ("Lag detected  <font color='rgb(140,140,148)'>%dms</font>"):format(dt * 1000)
            p.Visible = true
            hideAt = os.clock() + 2
        elseif p.Visible and os.clock() > hideAt then
            p.Visible = false
        end
    end))
    Library:TrackSilentWidget("LagNotifier", p)
    return p
end

-- music overlay
function Library:CreateMusicOverlay()
    local T = Library.Theme
    local card = WidgetPill(Root, 14)
    card.Position = UDim2.new(0, 60, 1, -150)
    card.Size = UDim2.new(0, 260, 0, 70)
    card.Visible = false
    local mic = Icon(card, "music", 20, T.Text)
    mic.Position = UDim2.new(0, 14, 0, 12)
    Library.Tint(mic, "ImageColor3")
    local title = Text(card, "Not playing", { Position = UDim2.new(0, 48, 0, 10), SizeUDim = UDim2.new(1, -60, 0, 16), Font = F_SEMI })
    local sub = Text(card, "Play something to get started", { Position = UDim2.new(0, 48, 0, 26), SizeUDim = UDim2.new(1, -60, 0, 14), Color = T.TextDim, Size = 11 })
    local track = New("Frame", { BackgroundColor3 = T.Track, Position = UDim2.new(0, 14, 0, 48), Size = UDim2.new(1, -28, 0, 3), Parent = card })
    Corner(track, 2)
    local fill = New("Frame", { BackgroundColor3 = WHITE, Size = UDim2.new(0, 0, 1, 0), Parent = track })
    Corner(fill, 2)
    AccentGradient(fill, 0.4)
    local t1 = Text(card, "0:00", { Position = UDim2.new(0, 14, 0, 53), SizeUDim = UDim2.new(0.5, 0, 0, 14), Color = T.TextDim, Size = 10 })
    local t2 = Text(card, "-0:00", { Position = UDim2.new(0.5, 0, 0, 53), SizeUDim = UDim2.new(0.5, -14, 0, 14), Color = T.TextDim, Size = 10, AlignX = TRIGHT })
    MakeDraggable(card, card)
    function Library:SetMusic(t, a, progress, elapsed, remaining)
        title.Text, sub.Text = t or "Not playing", a or "Play something to get started"
        fill.Size = UDim2.new(math.clamp(progress or 0, 0, 1), 0, 1, 0)
        t1.Text, t2.Text = elapsed or "0:00", remaining or "-0:00"
    end
    Library:TrackSilentWidget("Music", card)
    return card
end

-- target HUD
-- Library:SetTarget(player|nil)   Library:SetTargetHud(bool)   Library:SetTargetFollow(bool)
-- Library:CycleTarget()           Library.TargetHit(amount, simulate)
-- Takes damage -> card flashes red for ~1s, spawns particles + a floating damage number.
function Library:CreateTargetHUD()
    local T = Library.Theme
    local HURT = Color3.fromRGB(255, 78, 78)        -- only the AVATAR is tinted with this
    local AV_BG = Color3.fromRGB(14, 14, 16)
    local H_CARD = 76
    local AV_X, AV_Y, AV = 13, 14, 48

    -- invisible holder: owns position / anchor / visibility / width
    local card = New("Frame", {
        Name = "TargetHUD", BackgroundTransparency = 1, ZIndex = 100,
        Size = UDim2.new(0, 240, 0, H_CARD), AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.62, 0),
        Visible = false, Parent = Root,
    })
    -- the visible card; it scales around its own centre on hit
    local body = New("Frame", {
        Name = "Body", BackgroundColor3 = Color3.fromRGB(30, 30, 34), BackgroundTransparency = 0.04, ZIndex = 100,
        AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), Size = UDim2.new(1, 0, 1, 0), Parent = card,
    })
    Corner(body, 14)
    Shadow(body, 14, { Spread = 12, Offset = 3, Strength = 0.4 })
    local pop = New("UIScale", { Scale = 1, Parent = body })

    local avatar = New("ImageLabel", {
        BackgroundColor3 = AV_BG, Image = "", ImageColor3 = WHITE,
        Position = UDim2.new(0, AV_X, 0, AV_Y), Size = UDim2.new(0, AV, 0, AV), Parent = body,
    })
    Corner(avatar, 11)
    local nameL = Text(body, "", {
        Position = UDim2.new(0, 76, 0, 18), SizeUDim = UDim2.new(0, 110, 0, 24), Size = 14, Font = F_SEMI,
        Truncate = Enum.TextTruncate.AtEnd,
    })
    local hpL = Text(body, "100", {
        Position = UDim2.new(1, -14, 0, 18), AnchorPoint = Vector2.new(1, 0), SizeUDim = UDim2.new(0, 44, 0, 24),
        AlignX = TRIGHT, Size = 14, Font = F_BOLD,
    })
    local track = New("Frame", {
        BackgroundColor3 = Color3.fromRGB(62, 62, 68), Position = UDim2.new(0, 76, 0, 47), Size = UDim2.new(1, -90, 0, 9), Parent = body,
    })
    Corner(track, 5)
    -- soft "recent damage" trail; only visible while the bar is catching down
    local trail = New("Frame", {
        BackgroundColor3 = Color3.fromRGB(190, 190, 198), BackgroundTransparency = 0.55, Size = UDim2.new(1, 0, 1, 0),
        Visible = false, Parent = track,
    })
    Corner(trail, 5)
    local fill = New("Frame", { BackgroundColor3 = WHITE, Size = UDim2.new(1, 0, 1, 0), Parent = track })
    Corner(fill, 5)
    AccentGradient(fill, 0.4)

    local target, hum, hpConn, charConn = nil, nil, nil, nil
    local lastHealth, hitId, trailId, restoreId = 100, 0, 0, 0
    local shownFrac, shownHp, shownMax = 1, 100, 100
    local followActive, fixedPos = false, card.Position
    local cycleIdx = 0
    local avTween

    -- the card grows with long names (min 240 wide like the real one)
    local function resize()
        local nameW = TextW(nameL.Text, 14, F_SEMI)
        local w = math.clamp(nameW + 134, 240, 420)
        card.Size = UDim2.new(0, w, 0, H_CARD)
        nameL.Size = UDim2.new(0, w - 130, 0, 24)
    end

    -- particles spray out of the AVATAR
    local function burst()
        local rng = Random.new()
        local cx, cy = AV_X + AV / 2, AV_Y + AV / 2
        for _ = 1, 18 do
            local sz = rng:NextInteger(3, 6)
            local ang = rng:NextNumber() * math.pi * 2
            local dist = rng:NextNumber(26, 64)
            local white = rng:NextNumber() < 0.25
            local pt = New("Frame", {
                BackgroundColor3 = white and Color3.fromRGB(255, 226, 226)
                    or Color3.fromRGB(255, rng:NextInteger(60, 110), rng:NextInteger(60, 100)),
                BorderSizePixel = 0, Size = UDim2.new(0, sz, 0, sz), AnchorPoint = Vector2.new(0.5, 0.5),
                Rotation = rng:NextInteger(0, 90),
                Position = UDim2.new(0, cx + math.cos(ang) * 14, 0, cy + math.sin(ang) * 14), ZIndex = 20, Parent = body,
            })
            Corner(pt, 2)
            local life = 0.45 + rng:NextNumber() * 0.45
            Tween(pt, {
                Position = UDim2.new(0, cx + math.cos(ang) * dist, 0, cy + math.sin(ang) * dist + 16), -- slight fall
                BackgroundTransparency = 1, Size = UDim2.new(0, 1, 0, 1), Rotation = pt.Rotation + rng:NextInteger(-200, 200),
            }, life, Enum.EasingStyle.Quad)
            Debris:AddItem(pt, life + 0.2)
        end
    end

    -- hit reaction: whole card shrinks a touch and springs back; ONLY the avatar goes red + shakes + sprays particles
    local function hit()
        hitId = hitId + (1)
        local id = hitId
        Tween(pop, { Scale = 0.93 }, 0.05, Enum.EasingStyle.Quad)
        task.delay(0.05, function()
            if Library.Dead or id ~= hitId then return end
            Tween(pop, { Scale = 1 }, 0.45, Enum.EasingStyle.Back) -- Back easing overshoots slightly = springy
        end)

        if avTween then avTween:Cancel() end
        avatar.ImageColor3 = HURT
        avatar.BackgroundColor3 = Color3.fromRGB(70, 14, 18)
        task.delay(0.14, function()
            if Library.Dead or id ~= hitId then return end
            avTween = Tween(avatar, { ImageColor3 = WHITE, BackgroundColor3 = AV_BG }, 0.55, Enum.EasingStyle.Quad)
        end)
        task.spawn(function()
            for _, dx in ipairs({ -3, 3, -2, 2, -1, 0 }) do
                if Library.Dead or id ~= hitId then return end
                avatar.Position = UDim2.new(0, AV_X + dx, 0, AV_Y)
                task.wait(0.03)
            end
        end)
        burst()
    end

    local function setHealth(hp, max)
        max = (max and max > 0) and max or 100
        shownHp, shownMax = hp, max
        local f = math.clamp(hp / max, 0, 1)
        hpL.Text = tostring(math.floor(hp + 0.5))
        Tween(fill, { Size = UDim2.new(f, 0, 1, 0) }, 0.2)
        trailId = trailId + (1)
        local tid = trailId
        if f >= shownFrac then
            trail.Visible = false
            trail.Size = UDim2.new(f, 0, 1, 0)
        else
            if not trail.Visible then trail.Size = UDim2.new(shownFrac, 0, 1, 0) end
            trail.Visible = true
            task.delay(0.35, function()
                if Library.Dead or tid ~= trailId or not trail.Parent then return end
                local tw = Tween(trail, { Size = UDim2.new(f, 0, 1, 0) }, 0.3)
                tw.Completed:Connect(function() if tid == trailId then trail.Visible = false end end)
            end)
        end
        shownFrac = f
    end

    -- amount optional; simulate = true also drops the displayed health for a moment (used for the click/test preview)
    Library.TargetHit = function(amount, simulate)
        amount = amount or math.random(8, 24)
        hit()
        if simulate then
            setHealth(math.max(0, shownHp - amount), shownMax)
            restoreId = restoreId + (1)
            local rid = restoreId
            task.delay(2.2, function()
                if Library.Dead or rid ~= restoreId then return end
                if hum and hum.Parent then setHealth(hum.Health, hum.MaxHealth) else setHealth(shownMax, shownMax) end
            end)
        end
    end

    local function bindHumanoid(h)
        if hpConn then hpConn:Disconnect() hpConn = nil end
        hum = h
        if not h then setHealth(0, 100) return end
        lastHealth = h.Health
        setHealth(h.Health, h.MaxHealth)
        hpConn = h.HealthChanged:Connect(function(hp)
            setHealth(hp, h.MaxHealth)
            if hp < lastHealth then hit() end
            lastHealth = hp
        end)
    end

    local function bindPlayer(plr)
        if charConn then charConn:Disconnect() charConn = nil end
        target = plr
        if not plr then bindHumanoid(nil) return end
        nameL.Text = plr.Name .. ((plr.DisplayName ~= plr.Name) and (" <font color='rgb(140,140,148)'>(" .. plr.DisplayName .. ")</font>") or "")
        resize()
        avatar.Image = ""
        task.spawn(function()
            local ok, img = pcall(Players.GetUserThumbnailAsync, Players, plr.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size100x100)
            if ok and img and target == plr and avatar.Parent then avatar.Image = img end
        end)
        local ch = plr.Character
        bindHumanoid(ch and ch:FindFirstChildOfClass("Humanoid"))
        charConn = plr.CharacterAdded:Connect(function(c)
            bindHumanoid(c:WaitForChild("Humanoid", 5))
        end)
    end

    function Library.RefreshTargetHud()
        local want = Library.Target or (Library.TargetHudOn and LocalPlayer or nil)
        if want ~= target then bindPlayer(want) end
        card.Visible = Library.TargetHudOn and target ~= nil
    end
    function Library:SetTarget(plr)
        Library.Target = plr
        Library.RefreshTargetHud()
    end
    function Library:SetTargetHud(on)
        Library.TargetHudOn = on
        Library.RefreshTargetHud()
        if on then Shine(card, 16, 0.6) end
    end
    function Library:SetTargetFollow(on)
        Library.TargetFollow = on
    end
    function Library:CycleTarget()
        local list = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer then list[#list + 1] = p end
        end
        if #list == 0 then
            Library:SetTarget(nil)
            Library:Notify("Target HUD", "No other players in the server - previewing yourself", 3)
            return
        end
        cycleIdx = (cycleIdx % #list) + 1
        Library:SetTarget(list[cycleIdx])
    end
    Track(Players.PlayerRemoving:Connect(function(p)
        if Library.Target == p then Library:SetTarget(nil) end
    end))

    local function restoreFixed()
        followActive = false
        card.AnchorPoint = Vector2.new(0.5, 0)
        card.Position = fixedPos
        card.Visible = Library.TargetHudOn and target ~= nil
    end

    -- auto-target the nearest player
    local nearAcc = 0
    function Library:SetTargetNearest(on)
        Library.TargetNearest = on and true or false
        if on then nearAcc = 1 end -- pick one immediately
    end
    Track(RunService.Heartbeat:Connect(function(dt)
        if not Library.TargetNearest then return end
        nearAcc = nearAcc + (dt)
        if nearAcc < 0.2 then return end
        nearAcc = 0
        local mine = LocalPlayer.Character
        local myRoot = mine and mine:FindFirstChild("HumanoidRootPart")
        if not myRoot then return end
        local best, bd, curD = nil, math.huge, nil
        for _, pl in ipairs(Players:GetPlayers()) do
            if pl ~= LocalPlayer then
                local c = pl.Character
                local r = c and c:FindFirstChild("HumanoidRootPart")
                local h = c and c:FindFirstChildOfClass("Humanoid")
                if r and h and h.Health > 0 then
                    local d = (r.Position - myRoot.Position).Magnitude
                    if d < bd then best, bd = pl, d end
                    if pl == Library.Target then curD = d end
                end
            end
        end
        -- small hysteresis so two players at similar distance don't make the card flicker between them
        if best and best ~= Library.Target and curD and bd > curD - 3 then best = Library.Target end
        if best ~= Library.Target then Library:SetTarget(best) end
    end))

    -- follow mode: card sits BESIDE the target, flips sides near screen edges
    local sideRight, lastSide = true, nil
    Track(RunService.RenderStepped:Connect(function(dt)
        if not followActive then fixedPos = card.Position end
        local want = Library.TargetHudOn and target ~= nil
        local follow = want and Library.TargetFollow and target ~= LocalPlayer
        if followActive and not follow then restoreFixed() lastSide = nil end
        if not follow then return end

        local ch = target.Character
        local root = ch and (ch:FindFirstChild("HumanoidRootPart") or ch:FindFirstChild("UpperTorso") or ch:FindFirstChild("Torso"))
        local cam = workspace.CurrentCamera
        local goalX, goalY
        if root and cam then
            local sc = Library.Scale
            local c, on = cam:WorldToViewportPoint(root.Position)
            if on and c.Z > 0 then
                local r = cam:WorldToViewportPoint(root.Position + cam.CFrame.RightVector * 2.6)
                local off = math.max(math.abs(r.X - c.X) / sc, 34) -- px from the body centre to the card edge
                local cx, cardW, vpx = c.X / sc, card.AbsoluteSize.X / sc, Viewport().X
                local rightFits = cx + off + 8 + cardW <= vpx
                local leftFits = cx - off - 8 - cardW >= 0
                if sideRight and not rightFits and leftFits then sideRight = false
                elseif not sideRight and not leftFits and rightFits then sideRight = true end
                goalX = sideRight and (cx + off + 8) or (cx - off - 8)
                goalY = c.Y / sc
            end
        end

        if not followActive then followActive = true; lastSide = nil end
        if goalX then
            local goal = UDim2.new(0, goalX, 0, goalY)
            if lastSide ~= sideRight then
                lastSide = sideRight
                card.AnchorPoint = sideRight and Vector2.new(0, 0.5) or Vector2.new(1, 0.5)
                card.Position = goal
            end
            card.Visible = true
            card.Position = card.Position:Lerp(goal, 1 - math.exp(-dt * 22))
        else
            card.Visible = false
        end
    end))

    -- click the card = fake damage (just to show the hit animation)
    local downAt
    body.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 then
            downAt = Vector2.new(i.Position.X, i.Position.Y)
        end
    end)
    Track(UIS.InputEnded:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 and downAt then
            local up = Vector2.new(i.Position.X, i.Position.Y)
            local wasClick = (up - downAt).Magnitude < 5 -- a drag doesn't count
            downAt = nil
            if wasClick and card.Visible then Library.TargetHit(nil, true) end
        end
    end))

    MakeDraggable(body, card, function() return not followActive end)
    Library:TrackSilentWidget("TargetHUD", card)
    return card
end

-- ESP preview (spinning 3D noob)
-- Library:CreateESPPreview(tab, { Page = "Players", Prefix = "Visuals" })
-- Draws a spinning dummy and mirrors your ESP settings live. It reads these flags (Prefix defaults to the tab name):
--   <Prefix>.ESP/Enabled  ESP/Outline  Box/Enabled  Box/Fill Box  Name/Enabled  Name/Type  Health/Health Bar  Health/Health Based
--   Health/Health Text  Indicators/Distance  Equipped Item  Skeleton  Head Dot  Head Dot Glow  Chams/Enabled  Chams/Filled
--   Tracer/Enabled  Tracer/Origin     and colour flags BoxColor NameColor HealthColor DistanceColor ItemColor SkeletonColor
--   HeadDotColor ChamsColor TracerColor.   (use a Single = true page so the right half of the window is free for it)
function Library:CreateESPPreview(tab, popts)
    popts = popts or {}
    local T = Library.Theme
    local PFX = popts.Prefix or tab.Name
    local panel, body, pillBtn = tab:AddSidePanel({ Title = "ESP", Subtitle = "Preview", Pill = "3D", Page = popts.Page })

    local view = New("ViewportFrame", {
        BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 0),
        Ambient = Color3.fromRGB(165, 165, 165), LightColor = Color3.fromRGB(255, 255, 255),
        LightDirection = Vector3.new(-0.6, -1, -0.8), Parent = body,
    })
    local yellow, blue, green = Color3.fromRGB(245, 205, 48), Color3.fromRGB(13, 105, 172), Color3.fromRGB(164, 189, 71)
    local model = Instance.new("Model")
    local originals = {}
    local function part(name, size, pos, color)
        local p = Instance.new("Part")
        p.Name, p.Size, p.Position, p.Color = name, size, pos, color
        p.Anchored, p.Material = true, Enum.Material.SmoothPlastic
        p.TopSurface, p.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
        p.Parent = model
        originals[p] = color
        return p
    end
    local head = part("Head", Vector3.new(2, 1, 1), Vector3.new(0, 4.5, 0), yellow)
    local hm = Instance.new("SpecialMesh")
    hm.MeshType, hm.Scale = Enum.MeshType.Head, Vector3.new(1.25, 1.25, 1.25)
    hm.Parent = head
    pcall(function()
        local face = Instance.new("Decal")
        face.Texture, face.Face = "rbxasset://textures/face.png", Enum.NormalId.Front
        face.Parent = head
    end)
    local torso = part("Torso", Vector3.new(2, 2, 1), Vector3.new(0, 3, 0), blue)
    part("LeftArm", Vector3.new(1, 2, 1), Vector3.new(-1.5, 3, 0), yellow)
    part("RightArm", Vector3.new(1, 2, 1), Vector3.new(1.5, 3, 0), yellow)
    part("LeftLeg", Vector3.new(1, 2, 1), Vector3.new(-0.5, 1, 0), green)
    part("RightLeg", Vector3.new(1, 2, 1), Vector3.new(0.5, 1, 0), green)
    model.PrimaryPart = torso
    model.Parent = view

    local DIST = 10.5
    local cam = Instance.new("Camera")
    cam.FieldOfView = 40
    cam.CFrame = CFrame.lookAt(Vector3.new(0, 3, DIST), Vector3.new(0, 3, 0))
    cam.Parent = view
    view.CurrentCamera = cam

    -- 2D overlay drawn on top of the 3D view
    local ov = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 0), ZIndex = 5, Parent = body })
    local function frame(props)
        props.ZIndex = 6
        props.BorderSizePixel = 0
        props.Parent = ov
        return New("Frame", props)
    end
    local function label(size, font)
        return New("TextLabel", {
            BackgroundTransparency = 1, TextSize = size, FontFace = font or F_SEMI, RichText = true, TextColor3 = WHITE,
            Size = UDim2.new(0, 160, 0, 14), AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 7, Visible = false, Parent = ov,
        })
    end
    local function line() return frame({ AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = WHITE, Size = UDim2.new(0, 0, 0, 1), Visible = false }) end

    local boxF = frame({ BackgroundColor3 = WHITE, BackgroundTransparency = 1, Visible = false })
    local boxS = Stroke(boxF, 0, WHITE)
    boxS.Thickness = 1.5
    local hpTrack = frame({ BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.35, Visible = false })
    local hpFill = frame({ BackgroundColor3 = Color3.new(0, 1, 0), AnchorPoint = Vector2.new(0, 1), Visible = false })
    local nameL, distL, itemL, hpText = label(11), label(10, F_MED), label(10, F_MED), label(9, F_BOLD)
    local skel = {}
    for i = 1, 9 do skel[i] = line() end
    local tracer = line()
    local dot = frame({ AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = WHITE, Size = UDim2.new(0, 7, 0, 7), Visible = false })
    Corner(dot, 4)
    -- head dot glow: slightly smaller halo (15px, was 20px)
    local glow = frame({ AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = WHITE, BackgroundTransparency = 0.7, Size = UDim2.new(0, 15, 0, 15), Visible = false })
    Corner(glow, 8)

    local function setLine(l, a, b, color, th, vis)
        l.Visible = vis
        if not vis then return end
        local d = b - a
        l.Position = UDim2.new(0, (a.X + b.X) / 2, 0, (a.Y + b.Y) / 2)
        l.Size = UDim2.new(0, d.Magnitude, 0, th)
        l.Rotation = math.deg(math.atan2(d.Y, d.X))
        l.BackgroundColor3 = color
    end

    local angle, t, spin = math.pi, 0, true
    if pillBtn then
        pillBtn.MouseButton1Click:Connect(function()
            spin = not spin
            pillBtn.Text = spin and "3D" or "2D"
            if not spin then angle = math.pi end
        end)
    end

    local pconn
    pconn = Track(RunService.RenderStepped:Connect(function(dt)
        if not panel.Parent then pconn:Disconnect() return end
        if not panel.Visible then return end
        t = t + (dt)
        if spin then angle = angle + (dt * 0.9) end
        model:PivotTo(CFrame.new(0, 3, 0) * CFrame.Angles(0, angle, 0))

        local sz = body.AbsoluteSize / Library.Scale
        local W, Hh = sz.X, sz.Y
        local ppu = Hh / (2 * DIST * math.tan(math.rad(20)))
        local ca = math.cos(angle - math.pi)
        local function P(x, y) return Vector2.new(W / 2 + x * ca * ppu, Hh / 2 - (y - 3) * ppu) end

        local F = Library.Flags
        local on = F[PFX .. ".ESP/Enabled"] and true or false
        local function col(key, default) return F[key] or default or WHITE end
        local function tr(key) return 1 - (F[key .. "_Alpha"] or 1) end -- picker transparency (0 = solid)

        -- chams
        local ch = on and F[PFX .. ".Chams/Enabled"]
        for p, orig in pairs(originals) do
            p.Color = ch and col("ChamsColor") or orig
            local base = ch and (F[PFX .. ".Chams/Filled"] and 0.1 or 0.6) or 0
            p.Transparency = base + (1 - base) * (ch and tr("ChamsColor") or 0)
        end

        -- box
        local top, bottom = Hh / 2 - (5.45 - 3) * ppu, Hh / 2 + 3 * ppu
        local halfW = 1.3 * ppu
        local boxOn = on and F[PFX .. ".Box/Enabled"]
        boxF.Visible = boxOn and true or false
        if boxOn then
            boxF.Position = UDim2.new(0, W / 2 - halfW, 0, top)
            boxF.Size = UDim2.new(0, halfW * 2, 0, bottom - top)
            boxS.Color = col("BoxColor")
            boxF.BackgroundColor3 = col("BoxColor")
            boxS.Transparency = tr("BoxColor")
            boxF.BackgroundTransparency = F[PFX .. ".Box/Fill Box"] and (1 - 0.18 * (1 - tr("BoxColor"))) or 1
        end

        local outline = F[PFX .. ".ESP/Outline"] and 0.3 or 1
        -- name
        local nameOn = on and F[PFX .. ".Name/Enabled"]
        nameL.Visible = nameOn and true or false
        if nameOn then
            nameL.Position = UDim2.new(0, W / 2, 0, top - 10)
            nameL.Text = (F[PFX .. ".Name/Type"] == "Display") and LocalPlayer.DisplayName or LocalPlayer.Name
            nameL.TextColor3 = col("NameColor")
            nameL.TextTransparency = tr("NameColor")
            nameL.TextStrokeTransparency = math.max(outline, tr("NameColor"))
        end
        -- health
        local hp = 0.675 + 0.325 * math.sin(t * 0.9)
        local hpOn = on and F[PFX .. ".Health/Health Bar"]
        hpTrack.Visible, hpFill.Visible = hpOn and true or false, hpOn and true or false
        if hpOn then
            local x = W / 2 - halfW - 7
            hpTrack.Position = UDim2.new(0, x - 1, 0, top - 1)
            hpTrack.Size = UDim2.new(0, 4, 0, bottom - top + 2)
            hpFill.Position = UDim2.new(0, x, 0, bottom)
            hpFill.Size = UDim2.new(0, 2, 0, (bottom - top) * hp)
            hpFill.BackgroundTransparency = tr("HealthColor")
            hpFill.BackgroundColor3 = F[PFX .. ".Health/Health Based"] and Color3.fromHSV(hp * 0.33, 1, 1) or col("HealthColor", Color3.new(0, 1, 0))
        end
        local htOn = on and F[PFX .. ".Health/Health Text"]
        hpText.Visible = htOn and true or false
        if htOn then
            hpText.Position = UDim2.new(0, W / 2 - halfW - 18, 0, bottom - (bottom - top) * hp)
            hpText.Text = tostring(math.floor(hp * 100))
            hpText.TextStrokeTransparency = outline
        end
        -- distance / item
        local dOn = on and F[PFX .. ".Indicators/Distance"]
        distL.Visible = dOn and true or false
        if dOn then
            distL.Position = UDim2.new(0, W / 2, 0, bottom + 9)
            distL.Text = "[ 24m ]"
            distL.TextColor3 = col("DistanceColor")
            distL.TextTransparency = tr("DistanceColor")
            distL.TextStrokeTransparency = math.max(outline, tr("DistanceColor"))
        end
        local iOn = on and F[PFX .. ".Indicators/Equipped Item"]
        itemL.Visible = iOn and true or false
        if iOn then
            itemL.Position = UDim2.new(0, W / 2, 0, bottom + (dOn and 21 or 9))
            itemL.Text = "Linked Sword"
            itemL.TextColor3 = col("ItemColor")
            itemL.TextTransparency = tr("ItemColor")
            itemL.TextStrokeTransparency = math.max(outline, tr("ItemColor"))
        end
        -- skeleton (follows the spin)
        local sOn = on and F[PFX .. ".Indicators/Skeleton"]
        local sc = col("SkeletonColor")
        local neck, pelvis = P(0, 4.0), P(0, 2.0)
        local shL, shR = P(-1.0, 3.8), P(1.0, 3.8)
        local hdL, hdR = P(-1.5, 2.2), P(1.5, 2.2)
        local knL, knR, ftL, ftR = P(-0.5, 1), P(0.5, 1), P(-0.5, 0), P(0.5, 0)
        setLine(skel[1], P(0, 4.6), neck, sc, 1.5, sOn and true or false)
        setLine(skel[2], neck, pelvis, sc, 1.5, sOn and true or false)
        setLine(skel[3], shL, shR, sc, 1.5, sOn and true or false)
        setLine(skel[4], shL, hdL, sc, 1.5, sOn and true or false)
        setLine(skel[5], shR, hdR, sc, 1.5, sOn and true or false)
        setLine(skel[6], pelvis, knL, sc, 1.5, sOn and true or false)
        setLine(skel[7], knL, ftL, sc, 1.5, sOn and true or false)
        setLine(skel[8], pelvis, knR, sc, 1.5, sOn and true or false)
        setLine(skel[9], knR, ftR, sc, 1.5, sOn and true or false)
        local sa = tr("SkeletonColor")
        for _, l in ipairs(skel) do l.BackgroundTransparency = sa end
        -- head dot
        local hdOn = on and F[PFX .. ".Indicators/Head Dot"]
        dot.Visible = hdOn and true or false
        glow.Visible = (hdOn and F[PFX .. ".Indicators/Head Dot Glow"]) and true or false
        if hdOn then
            local hp2 = P(0, 4.5)
            dot.Position = UDim2.new(0, hp2.X, 0, hp2.Y)
            dot.BackgroundTransparency = tr("HeadDotColor")
            glow.BackgroundTransparency = 1 - 0.3 * (1 - tr("HeadDotColor"))
            dot.BackgroundColor3 = col("HeadDotColor")
            glow.Position = dot.Position
            glow.BackgroundColor3 = col("HeadDotColor")
        end
        -- tracer
        local trOn = on and F[PFX .. ".Tracer/Enabled"]
        local origin = F[PFX .. ".Tracer/Origin"] or "Top"
        local oy = (origin == "Bottom") and Hh or ((origin == "Center") and Hh / 2 or 0)
        setLine(tracer, Vector2.new(W / 2, oy), Vector2.new(W / 2, bottom), col("TracerColor"), 1, trOn and true or false)
        tracer.BackgroundTransparency = tr("TracerColor")
    end))

    -- collapse to the side: the preview shrinks to a thin strip on the right edge and the settings widen to fill the page.
    -- Click the "PREVIEW" header (chevron points right) to collapse, click the strip (chevron points left) to bring it back.
    do
        local pg = tab:GetPage(popts.Page)
        local sf = pg and pg.Grp and pg.Grp:FindFirstChildOfClass("ScrollingFrame")
        local fullPos, fullSize = panel.Position, panel.Size
        local STRIP = 34
        local collapsed = false
        local head = panel:FindFirstChildOfClass("TextLabel")

        local chev = Chevron(panel, UDim2.new(0, 88, 0, 15), T.TextDim)
        chev.Rotation = -90 -- points right: "push to the side"
        local hit = New("TextButton", {
            Text = "", AutoButtonColor = false, BackgroundTransparency = 1,
            Size = UDim2.new(0, 104, 0, 30), ZIndex = 5, Parent = panel,
        })

        -- the collapsed strip
        local strip = New("TextButton", {
            Text = "", AutoButtonColor = false, BackgroundColor3 = T.Section, BackgroundTransparency = 0.5,
            Size = UDim2.new(1, 0, 1, -4), Visible = false, ZIndex = 5, Parent = panel,
        })
        Corner(strip, 10); Stroke(strip, 0.9)
        local schev = Chevron(strip, UDim2.new(0.5, 0, 0, 22), T.TextDim)
        schev.Rotation = 90 -- points left: "bring it back"
        local sText = New("TextLabel", {
            BackgroundTransparency = 1, Text = "PREVIEW", TextColor3 = T.TextDim, TextSize = 10, FontFace = F_SEMI,
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), Size = UDim2.new(0, 90, 0, 14),
            Rotation = 90, Parent = strip,
        })

        local function hover(btn, targets, normalBg)
            btn.MouseEnter:Connect(function()
                for _, c in ipairs(targets) do
                    if c:IsA("Frame") then Tween(c, { BackgroundColor3 = T.Text }, 0.1) end
                    if c:IsA("TextLabel") then Tween(c, { TextColor3 = T.Text }, 0.1) end
                end
                if normalBg then Tween(btn, { BackgroundTransparency = 0.3 }, 0.1) end
            end)
            btn.MouseLeave:Connect(function()
                for _, c in ipairs(targets) do
                    if c:IsA("Frame") then Tween(c, { BackgroundColor3 = T.TextDim }, 0.1) end
                    if c:IsA("TextLabel") then Tween(c, { TextColor3 = T.TextDim }, 0.1) end
                end
                if normalBg then Tween(btn, { BackgroundTransparency = 0.5 }, 0.1) end
            end)
        end
        hover(hit, chev:GetChildren(), false)
        local sTargets = { sText }
        for _, c in ipairs(schev:GetChildren()) do sTargets[#sTargets + 1] = c end
        hover(strip, sTargets, true)

        local function setCollapsed(c)
            collapsed = c
            local ti = Enum.EasingStyle.Quint
            if c then
                body.Visible = false
                if head then head.Visible = false end
                chev.Visible, hit.Visible = false, false
                if pillBtn then pillBtn.Visible = false end
                strip.Visible = true
                Tween(panel, { Position = UDim2.new(1, -STRIP, 0, 0), Size = UDim2.new(0, STRIP, fullSize.Y.Scale, fullSize.Y.Offset) }, 0.25, ti)
                if pg then pg.SetLayout(false, true) end -- two balanced columns, sections re-sorted
                if sf then Tween(sf, { Size = UDim2.new(1, -(STRIP + 10), 1, 0) }, 0.25, ti) end
            else
                strip.Visible = false
                Tween(panel, { Position = fullPos, Size = fullSize }, 0.25, ti)
                if pg then pg.SetLayout(true, true) end -- back to one column
                if sf then Tween(sf, { Size = UDim2.new(0.5, -7, 1, 0) }, 0.25, ti) end
                task.delay(0.18, function()
                    if collapsed or not panel.Parent then return end
                    body.Visible = true
                    if head then head.Visible = true end
                    chev.Visible, hit.Visible = true, true
                    if pillBtn then pillBtn.Visible = true end
                end)
            end
        end
        hit.MouseButton1Click:Connect(function() setCollapsed(true) end)
        strip.MouseButton1Click:Connect(function() setCollapsed(false) end)
        Library.ESPPreviewSetCollapsed = setCollapsed
        if popts.Collapsed then setCollapsed(true) end
    end

    Library:TrackSilentWidget("ESPPreview", panel)
    return panel
end

-- widget visibility
function Library:TrackSilentWidget(name, widget)
    Library.Widgets[name] = widget
    if Library.SilentMode and typeof(widget) == "Instance" then
        Library.SilentWidgetVisibility[name] = widget.Visible
        widget.Visible = false
    end
    return widget
end

function Library:SetWidget(name, visible)
    if name == "LagNotifier" then
        if Library.SilentMode then
            Library.SilentWidgetVisibility[name] = visible == true
            Library.Widgets.LagEnabled = false
        else
            Library.Widgets.LagEnabled = visible
        end
        return
    end
    local w = Library.Widgets[name]
    if w and typeof(w) == "Instance" then
        if Library.SilentMode then
            Library.SilentWidgetVisibility[name] = visible == true
            w.Visible = false
            return
        end
        w.Visible = visible
        if visible then Shine(w, 14, 0.6) end
    end
end

-- notifications
local notifHolder = New("Frame", {
    BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -16, 1, -16),
    Size = UDim2.new(0, 360, 1, -32), ZIndex = 300, Parent = Root,
})
List(notifHolder, 6, V, RIGHT, BOTTOM)
local activeNotifications = {}

function Library:SetSilentMode(enabled)
    enabled = enabled == true
    if Library.SilentMode == enabled then return end
    Library.SilentMode = enabled
    if enabled then
        for _, notification in ipairs(notifHolder:GetChildren()) do
            notification:Destroy()
        end
        activeNotifications = {}
        for name, widget in pairs(Library.Widgets) do
            if name == "LagEnabled" then
                continue
            end
            if typeof(widget) == "Instance" then
                Library.SilentWidgetVisibility[name] = widget.Visible
                widget.Visible = false
            end
        end
        if Library.Widgets.LagEnabled ~= nil then
            Library.SilentWidgetVisibility.LagNotifier = Library.Widgets.LagEnabled
            Library.Widgets.LagEnabled = false
        end
        for win in pairs(Library.SilentWindows) do
            if win.Frame and win.Frame.Parent then
                win._silentVisible = win.Frame.Visible
                win.Frame.Visible = false
            else
                Library.SilentWindows[win] = nil
            end
        end
    else
        for name, visible in pairs(Library.SilentWidgetVisibility) do
            if name == "LagNotifier" then
                Library.Widgets.LagEnabled = visible
            else
                local widget = Library.Widgets[name]
                if typeof(widget) == "Instance" then
                    widget.Visible = visible == true
                end
            end
            Library.SilentWidgetVisibility[name] = nil
        end
        for win in pairs(Library.SilentWindows) do
            if win.Frame and win.Frame.Parent then
                win.Frame.Visible = win._silentVisible == true
                win._silentVisible = nil
            else
                Library.SilentWindows[win] = nil
            end
        end
    end
end

local function findNotification(title, body, icon, create)
    local byBody = activeNotifications[title]
    if not byBody and create then byBody = {}; activeNotifications[title] = byBody end
    if not byBody then return nil end
    local byIcon = byBody[body]
    if not byIcon and create then byIcon = {}; byBody[body] = byIcon end
    if not byIcon then return nil end
    return byIcon[icon], byIcon, byBody
end

local function forgetNotification(entry, title, body, icon, byIcon, byBody)
    if byIcon[icon] == entry then byIcon[icon] = nil end
    if next(byIcon) == nil then byBody[body] = nil end
    if next(byBody) == nil then activeNotifications[title] = nil end
end

local function dismissNotification(entry, title, body, icon, byIcon, byBody)
    if entry.Dismissed or not entry.Frame.Parent then return end
    entry.Dismissed = true
    entry.Timer = entry.Timer + 1
    forgetNotification(entry, title, body, icon, byIcon, byBody)
    Tween(entry.Frame, { BackgroundTransparency = 1 }, 0.25)
    Tween(entry.Title, { TextTransparency = 1 }, 0.25)
    if entry.Body then Tween(entry.Body, { TextTransparency = 1 }, 0.25) end
    Tween(entry.Icon, { ImageTransparency = 1 }, 0.25)
    task.delay(0.3, function()
        if entry.Frame.Parent then entry.Frame:Destroy() end
    end)
end

local function expireNotification(entry, title, body, icon, byIcon, byBody, duration)
    entry.Timer = entry.Timer + 1
    local timer = entry.Timer
    task.delay(duration, function()
        if Library.Dead or entry.Timer ~= timer or not entry.Frame.Parent then return end
        dismissNotification(entry, title, body, icon, byIcon, byBody)
    end)
end

-- Library:Notify("Title", "Body text", seconds, icon)   (or Notify("text", seconds))
function Library:Notify(title, body, duration, icon)
    if Library.SilentMode then return end
    local T = Library.Theme
    if type(body) == "number" then duration, body = body, nil end
    title, body, icon = tostring(title or ""), body and tostring(body) or "", tostring(icon or "sparkles")
    duration = tonumber(duration) or 3
    local existing, byIcon, byBody = findNotification(title, body, icon, false)
    if existing and existing.Frame.Parent then
        existing.Count = existing.Count + 1
        existing.CountLabel.Text = "x " .. existing.Count
        existing.CountLabel.Visible = true
        expireNotification(existing, title, body, icon, byIcon, byBody, duration)
        return
    end
    local n = New("Frame", {
        BackgroundColor3 = T.Widget, BackgroundTransparency = 1, Size = UDim2.new(0, 0, 0, body ~= "" and 56 or 34),
        AutomaticSize = Enum.AutomaticSize.X, Parent = notifHolder,
    })
    Corner(n, 14)
    Shadow(n, 14, { Spread = 10, Offset = 2, Strength = 0.35 }) -- fades in/out with the card's own transparency
    Pad(n, 14, 0, 18, 0)
    local row = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, Parent = n })
    List(row, 12, H, LEFT, VCENTER)
    local notifIcon = Icon(row, icon, 22, T.Text)
    Library.Tint(notifIcon, "ImageColor3")
    local col = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(0, 0, 0, body ~= "" and 34 or 16), AutomaticSize = Enum.AutomaticSize.X, Parent = row })
    List(col, 2, V, LEFT, VCENTER)
    local l1 = New("TextLabel", {
        BackgroundTransparency = 1, Text = title, TextColor3 = T.Text, TextTransparency = 1, TextSize = 12, FontFace = F_SEMI,
        TextXAlignment = TLEFT, Size = UDim2.new(0, 0, 0, 16), AutomaticSize = Enum.AutomaticSize.X, Parent = col,
    })
    local l2
    if body ~= "" then
        l2 = New("TextLabel", {
            BackgroundTransparency = 1, Text = body, TextColor3 = T.TextDim, TextTransparency = 1, TextSize = 11, FontFace = F_MED,
            TextXAlignment = TLEFT, Size = UDim2.new(0, 0, 0, 14), AutomaticSize = Enum.AutomaticSize.X, Parent = col,
        })
    end
    local count = New("TextLabel", {
        BackgroundColor3 = T.Section, BackgroundTransparency = 0.15, Text = "", TextColor3 = T.Accent,
        TextSize = 10, FontFace = F_SEMI, AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.new(0, 0, 0, 18), Visible = false, Parent = row,
    })
    Corner(count, 9)
    Pad(count, 7, 0, 7, 0)
    local entry = { Frame = n, Title = l1, Body = l2, Icon = notifIcon, CountLabel = count, Count = 1, Timer = 0 }
    local _, entryByIcon, entryByBody = findNotification(title, body, icon, true)
    entryByIcon[icon] = entry
    n.MouseEnter:Connect(function()
        dismissNotification(entry, title, body, icon, entryByIcon, entryByBody)
    end)
    Tween(n, { BackgroundTransparency = 0.06 }, 0.25); Tween(l1, { TextTransparency = 0 }, 0.25)
    if l2 then Tween(l2, { TextTransparency = 0 }, 0.25) end
    Shine(n, 14, 0.65)
    expireNotification(entry, title, body, icon, entryByIcon, entryByBody, duration)
end

-- themes (presets)
-- Each preset tints the dark neutrals and sets the accent. Accent 2 is NOT touched by presets: it stays
-- white until the user (or a loaded config) changes it.
local PRESET_BASE = {
    Background = Color3.fromRGB(25, 26, 34), Section = Color3.fromRGB(36, 37, 47), Element = Color3.fromRGB(54, 56, 68),
    ElementOff = Color3.fromRGB(60, 62, 74), Track = Color3.fromRGB(44, 46, 58), Popup = Color3.fromRGB(28, 29, 38),
    Widget = Color3.fromRGB(17, 18, 24), TextDim = Color3.fromRGB(152, 154, 168),
}
local PRESET_NEAR = Color3.fromRGB(19, 19, 25)
Library.Presets = {
    { Name = "Dark",      Tint = Vector3.new(0, 0, 0),      Accent = Color3.fromRGB(255, 255, 255) },
    { Name = "Luma",      Tint = Vector3.new(-10, -8, 10),  Accent = Color3.fromRGB(150, 176, 236) },
    { Name = "Midnight",  Tint = Vector3.new(-12, -12, 8),  Accent = Color3.fromRGB(140, 160, 255) },
    { Name = "Ocean",     Tint = Vector3.new(-14, -3, 6),   Accent = Color3.fromRGB(90, 200, 230) },
    { Name = "Forest",    Tint = Vector3.new(-12, 3, -8),   Accent = Color3.fromRGB(120, 220, 140) },
    { Name = "Matcha",    Tint = Vector3.new(-10, 2, -14),  Accent = Color3.fromRGB(160, 210, 105) },
    { Name = "Rose",      Tint = Vector3.new(8, -12, -4),   Accent = Color3.fromRGB(255, 130, 170) },
    { Name = "Crimson",   Tint = Vector3.new(10, -14, -12), Accent = Color3.fromRGB(255, 90, 90) },
    { Name = "Amethyst",  Tint = Vector3.new(2, -12, 12),   Accent = Color3.fromRGB(190, 140, 255) },
    { Name = "Mocha",     Tint = Vector3.new(8, 2, -10),    Accent = Color3.fromRGB(230, 180, 130) },
    { Name = "Graphite",  Tint = Vector3.new(6, 6, 6),      Accent = Color3.fromRGB(205, 205, 210) },
}
Library.PresetNames = {}
for _, pr in ipairs(Library.Presets) do Library.PresetNames[#Library.PresetNames + 1] = pr.Name end
Library.CurrentPreset = "Dark"

local function Shift(c, v, k)
    local function ch(x, d) return math.clamp(math.floor(x * 255 + d * k + 0.5), 0, 255) end
    return Color3.fromRGB(ch(c.R, v.X), ch(c.G, v.Y), ch(c.B, v.Z))
end
local function Pack(c) return math.floor(c.R * 255 + 0.5) * 65536 + math.floor(c.G * 255 + 0.5) * 256 + math.floor(c.B * 255 + 0.5) end

local THEME_KEYS = { "Background", "Section", "Element", "ElementOff", "Track", "Popup", "Widget", "TextDim" }

function Library:ApplyTheme(name)
    local preset
    for _, pr in ipairs(Library.Presets) do if pr.Name == name then preset = pr break end end
    if not preset then return false end
    local T = Library.Theme

    -- map every old neutral colour to its new value, then recolour what is already on screen
    local map = {}
    local function add(old, new) local k = Pack(old); if not map[k] and Pack(old) ~= Pack(new) then map[k] = new end end
    for _, key in ipairs(THEME_KEYS) do
        local new = Shift(PRESET_BASE[key], preset.Tint, key == "TextDim" and 0.5 or 1)
        add(T[key], new)
        T[key] = new
    end
    local newNear = Shift(PRESET_NEAR, preset.Tint, 1)
    add(GLASS.Near, newNear)
    GLASS.Near = newNear

    local function fix(inst, prop)
        local n = map[Pack(inst[prop])]
        if n then inst[prop] = n end
    end
    for _, d in ipairs(Library.Gui:GetDescendants()) do
        if d:IsA("GuiObject") then
            fix(d, "BackgroundColor3")
            if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then fix(d, "TextColor3") end
            if d:IsA("TextBox") then fix(d, "PlaceholderColor3") end
            if d:IsA("ImageLabel") or d:IsA("ImageButton") then fix(d, "ImageColor3") end
        elseif d:IsA("UIStroke") then
            fix(d, "Color")
        end
    end

    Library.CurrentPreset = preset.Name
    Library:SetAccent(preset.Accent, nil)
    local ao = Library.Options["AccentColor"]
    if ao then ao:Set(preset.Accent) end
    return true
end

-- Library:SetThemeColor("Background"|"Section"|"Element"|"ElementOff"|"Track"|"Popup"|"Widget"|"TextDim"|"WidgetGlass"|"Accent"|"Accent2", Color3)
-- recolours everything already on screen (same technique as ApplyTheme) and every control created afterwards.
function Library.GetWidgetGlass() return GLASS.Near end

function Library:SetThemeColor(key, c)
    if typeof(c) ~= "Color3" then return false end
    if key == "Accent" then Library:SetAccent(c, nil) return true end
    if key == "Accent2" then Library:SetAccent(nil, c) return true end
    local T = Library.Theme
    local old
    if key == "WidgetGlass" then old = GLASS.Near else old = T[key] end
    if not old or Pack(old) == Pack(c) then return old ~= nil end
    if key == "WidgetGlass" then GLASS.Near = c else T[key] = c end
    local from, to = Pack(old), c
    local function fix(inst, prop)
        if Pack(inst[prop]) == from then inst[prop] = to end
    end
    for _, d in ipairs(Library.Gui:GetDescendants()) do
        if d:IsA("GuiObject") then
            fix(d, "BackgroundColor3")
            if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then fix(d, "TextColor3") end
            if d:IsA("TextBox") then fix(d, "PlaceholderColor3") end
            if d:IsA("ImageLabel") or d:IsA("ImageButton") then fix(d, "ImageColor3") end
        elseif d:IsA("UIStroke") then
            fix(d, "Color")
        end
    end
    if Library.SideFill and Library.SideFill.Parent then Library.SideFill.BackgroundColor3 = Library.SideColor() end
    if Library.RefreshHotkeys then Library.RefreshHotkeys() end
    return true
end

-- configs (save / load flags to JSON)
local FS = {
    write = writefile, read = readfile, isfile = isfile, isfolder = isfolder,
    mkfolder = makefolder, list = listfiles, del = delfile,
}
-- Configs live in the original Luma folder, flat (one <name>.json per config) -- the exact place and
-- layout the previous (Obsidian) UI used, NOT a separate "Matcha" folder. This keeps your old presets and
-- autoload.txt right where they were, so they're picked up with no migration. genv.LumaConfigFolder can
-- override the folder name if ever needed.
Library.ConfigRoot = tostring(genv.LumaConfigFolder or "Luma-Rewrite-Configs")
Library.ConfigDir = Library.ConfigRoot
Library.MemConfigs = {} -- fallback when the executor has no file functions
Library.NoSave = { ConfigName = true }

local function CanFS() return FS.write ~= nil and FS.read ~= nil and FS.list ~= nil and FS.isfolder ~= nil and FS.mkfolder ~= nil end
local function EnsureDir()
    if not CanFS() then return false end
    pcall(function() if not FS.isfolder(Library.ConfigRoot) then FS.mkfolder(Library.ConfigRoot) end end)
    pcall(function() if not FS.isfolder(Library.ConfigDir) then FS.mkfolder(Library.ConfigDir) end end)
    return true
end
local function CleanName(n)
    n = tostring(n or ""):gsub("[^%w _%-%.]", ""):gsub("^%s+", ""):gsub("%s+$", "")
    return n:sub(1, 40)
end
local function EncodeValue(v)
    local t = typeof(v)
    if t == "Color3" then return { t = "c", r = v.R, g = v.G, b = v.B } end
    if t == "boolean" or t == "number" or t == "string" then return v end
    if t == "table" then
        -- Multi-dropdown value is a set { ["Option Name"] = true, ... }. Without this branch EncodeValue
        -- returned nil for it, so SaveConfig silently skipped EVERY multi-select (the Auto Defense Filters,
        -- "Disable During Chime Countdown", etc.) and none of them restored on load. Encode as an array of
        -- the selected names; setValue() accepts the array form on load and rebuilds the set.
        local out = {}
        for k, val in pairs(v) do
            if val then out[#out + 1] = tostring(k) end
        end
        table.sort(out)
        return out
    end
    return nil
end

-- Translate a legacy (Obsidian SaveManager) config's { objects = { {type, idx, value/...}, ... } } array
-- into this library's { flag = value } table. Field names match the Obsidian Parser's Save() output. Shared
-- by LoadConfig (read old presets in place) and the migration helpers.
local function LegacyObjectsToFlags(objects)
    local flags = {}
    for _, o in ipairs(objects) do
        local idx, t = o.idx, o.type
        if type(idx) == "string" then
            if t == "Toggle" then
                flags[idx] = o.value == true
            elseif t == "Slider" then
                local n = tonumber(o.value)
                if n ~= nil then flags[idx] = n end
            elseif t == "Dropdown" then
                if o.value ~= nil then flags[idx] = o.value end
            elseif t == "Input" then
                if type(o.text) == "string" then flags[idx] = o.text end
            elseif t == "KeyPicker" then
                if type(o.key) == "string" then flags[idx] = o.key end
            elseif t == "ColorPicker" then
                local c = Color3.fromHSV(tonumber(o.hue) or 0, tonumber(o.sat) or 0, tonumber(o.vib) or 0)
                flags[idx] = { t = "c", r = c.R, g = c.G, b = c.B, a = 1 - (tonumber(o.transparency) or 0) }
            end
        end
    end
    return flags
end

local function getWidgetPositions()
    local positions = {}
    for name, widget in pairs(Library.Widgets) do
        if typeof(widget) == "Instance" and widget:IsA("GuiObject") then
            local position = widget.Position
            local anchor = widget.AnchorPoint
            positions[name] = {
                xScale = position.X.Scale,
                xOffset = position.X.Offset,
                yScale = position.Y.Scale,
                yOffset = position.Y.Offset,
                anchorX = anchor.X,
                anchorY = anchor.Y,
            }
        end
    end
    return positions
end

local function applyWidgetPositions(positions)
    if type(positions) ~= "table" then return end
    for name, saved in pairs(positions) do
        local widget = Library.Widgets[name]
        if type(saved) == "table" and typeof(widget) == "Instance" and widget:IsA("GuiObject")
            and type(saved.xScale) == "number" and type(saved.xOffset) == "number"
            and type(saved.yScale) == "number" and type(saved.yOffset) == "number" then
            widget.Position = UDim2.new(saved.xScale, saved.xOffset, saved.yScale, saved.yOffset)
            if type(saved.anchorX) == "number" and type(saved.anchorY) == "number" then
                widget.AnchorPoint = Vector2.new(saved.anchorX, saved.anchorY)
            end
        end
    end
end

function Library:ListConfigs()
    local out = {}
    if CanFS() and EnsureDir() then
        local ok, files = pcall(FS.list, Library.ConfigDir)
        if ok and type(files) == "table" then
            for _, f in ipairs(files) do
                local n = tostring(f):match("([^/\\]+)%.json$")
                if n then out[#out + 1] = n end
            end
        end
    else
        for n in pairs(Library.MemConfigs) do out[#out + 1] = n end
    end
    table.sort(out, function(a, b) return a:lower() < b:lower() end)
    return out
end

function Library:RefreshConfigs()
    if Library.ConfigListBox then Library.ConfigListBox:SetValues(Library:ListConfigs()) end
    if Library.RefreshPresets then Library.RefreshPresets() end
end

function Library:SaveConfig(name)
    name = CleanName(name)
    if name == "" then Library:Notify("Configs", "Type a config name first", 3) return false end
    local flags, count = {}, 0
    for flag in pairs(Library.Options) do
        if not Library.NoSave[flag] then
            local ev = EncodeValue(Library.Flags[flag])
            if ev ~= nil then
                local o = Library.Options[flag]
                if type(ev) == "table" and o and o.Alpha then ev.a = o.Alpha end -- colour transparency
                flags[flag] = ev; count = count + (1)
            end
        end
    end
    local ok, json = pcall(function()
        return HttpService:JSONEncode({
            version = 1,
            name = name,
            flags = flags,
            widgets = getWidgetPositions(),
        })
    end)
    if not ok then Library:Notify("Configs", "Could not encode config", 3) return false end
    if CanFS() and EnsureDir() then
        local wok = pcall(FS.write, Library.ConfigDir .. "/" .. name .. ".json", json)
        if not wok then Library:Notify("Configs", "Could not write the file", 3) return false end
    else
        Library.MemConfigs[name] = json
    end
    Library:RefreshConfigs()
    if Library.ConfigListBox then Library.ConfigListBox:Select(name, false) end
    Library.CurrentConfig = name
    if Library.RefreshConfigBar then Library.RefreshConfigBar() end
    if Library.RefreshPresets then Library.RefreshPresets() end
    Library:Notify("Configs", ("Saved '%s' (%d options)"):format(name, count), 3)
    return true
end

-- config autoload: the chosen config name is stored in <ConfigRoot>/autoload.txt and loaded a moment after the window is built
Library.MemAutoload = nil
function Library:GetAutoload()
    if CanFS() then
        local path = Library.ConfigRoot .. "/autoload.txt"
        local ok, v = pcall(function() return FS.isfile(path) and FS.read(path) or nil end)
        if ok and v then
            -- Normalize exactly like SaveConfig/SetAutoload (CleanName) so a name WITH spaces still
            -- matches its saved file. The old gsub("%s+","") stripped INTERNAL spaces too, turning
            -- "pvp build" into "pvpbuild", so autoload silently failed for any spaced config name.
            v = CleanName(v)
            return v ~= "" and v or nil
        end
        return nil
    end
    return Library.MemAutoload
end

function Library:SetAutoload(name)
    name = name and CleanName(name) or nil
    if name == "" then name = nil end
    if CanFS() and EnsureDir() then
        pcall(FS.write, Library.ConfigRoot .. "/autoload.txt", name or "")
    end
    Library.MemAutoload = name
    if Library.RefreshPresets then Library.RefreshPresets() end
    Library:Notify("Configs", name and ("'" .. name .. "' will load automatically") or "Autoload turned off", 3)
    return true
end

function Library:RunAutoload()
    if Library.AutoloadDone then return false end
    Library.AutoloadDone = true
    local name = Library:GetAutoload()
    if not name then return false end
    for _, n in ipairs(Library:ListConfigs()) do
        if n == name then return Library:LoadConfig(name) end
    end
    return false
end

function Library:LoadConfig(name)
    name = CleanName(name)
    if name == "" then Library:Notify("Configs", "Pick a config first", 3) return false end
    local json
    if CanFS() and EnsureDir() then
        local path = Library.ConfigDir .. "/" .. name .. ".json"
        local ok, data = pcall(function() return FS.isfile(path) and FS.read(path) or nil end)
        json = ok and data or nil
    else
        json = Library.MemConfigs[name]
    end
    if not json then Library:Notify("Configs", "Config '" .. name .. "' not found", 3) return false end
    local ok, data = pcall(function() return HttpService:JSONDecode(json) end)
    if not ok or type(data) ~= "table" then
        Library:Notify("Configs", "That config file is corrupted", 3)
        return false
    end
    -- Accept legacy (Obsidian) presets saved as { objects = {...} }: translate to flags in place so old
    -- configs sitting in the folder load directly, no separate migration pass needed.
    if type(data.flags) ~= "table" then
        if type(data.objects) == "table" then
            data.flags = LegacyObjectsToFlags(data.objects)
        else
            Library:Notify("Configs", "That config file is corrupted", 3)
            return false
        end
    end
    -- theme preset first so the saved accent colours land on top of it
    local keys = {}
    for k in pairs(data.flags) do keys[#keys + 1] = k end
    table.sort(keys, function(a, b)
        if a == "ThemePreset" then return b ~= "ThemePreset" end
        if b == "ThemePreset" then return false end
        return a < b
    end)
    local applied = 0
    for _, k in ipairs(keys) do
        local opt, v = Library.Options[k], data.flags[k]
        if opt and not Library.NoSave[k] then
            local good = pcall(function()
                if type(v) == "table" and v.t == "c" then
                    opt:Set(Color3.new(v.r, v.g, v.b), true, v.a)
                else
                    opt:Set(v)
                end
            end)
            if good then applied = applied + (1) end
        end
    end
    applyWidgetPositions(data.widgets)
    if Library.RefreshHotkeys then Library.RefreshHotkeys() end
    if Library.ConfigListBox then Library.ConfigListBox:Select(name, false) end
    Library.CurrentConfig = name
    if Library.RefreshConfigBar then Library.RefreshConfigBar() end
    if Library.RefreshPresets then Library.RefreshPresets() end
    Library:Notify("Configs", ("Loaded '%s' (%d options)"):format(name, applied), 3)
    return true
end

-- One-time import of configs saved by the previous (Obsidian-UI) build. Those live in a different folder
-- ("Luma-Rewrite-Configs/<name>.json") and a different shape ({ objects = { { type, idx, value/... } } }); the
-- feature flag names were kept across the rewrite, so each object is translated into this library's
-- { flags = { flag = value } } format and dropped into the native config folder. A native config of the same
-- name is never overwritten, so re-running this is safe.
function Library:MigrateLegacyConfigs(legacyFolder)
    legacyFolder = tostring(legacyFolder or genv.LumaLegacyConfigFolder or "Luma-Rewrite-Configs")
    if not CanFS() then return 0 end
    local okf, isf = pcall(FS.isfolder, legacyFolder)
    if not okf or not isf then return 0 end
    if not EnsureDir() then return 0 end
    local okl, files = pcall(FS.list, legacyFolder)
    if not okl or type(files) ~= "table" then return 0 end
    local migrated = 0
    for _, f in ipairs(files) do
        local name = tostring(f):match("([^/\\]+)%.json$")
        if name then
            local newPath = Library.ConfigDir .. "/" .. name .. ".json"
            local okx, exists = pcall(FS.isfile, newPath)
            if not (okx and exists) then
                local okr, raw = pcall(FS.read, tostring(f))
                local decoded
                if okr and raw then
                    local okd, d = pcall(function() return HttpService:JSONDecode(raw) end)
                    if okd then decoded = d end
                end
                if type(decoded) == "table" and type(decoded.objects) == "table" then
                    local flags = LegacyObjectsToFlags(decoded.objects)
                    local oke, json = pcall(function() return HttpService:JSONEncode({ version = 1, name = name, flags = flags }) end)
                    if oke and pcall(FS.write, newPath, json) then migrated = migrated + 1 end
                end
            end
        end
    end
    -- carry the autoload choice over if the native side doesn't have one yet
    pcall(function()
        local legacyAuto = legacyFolder .. "/autoload.txt"
        local nativeAuto = Library.ConfigRoot .. "/autoload.txt"
        if FS.isfile(legacyAuto) and not FS.isfile(nativeAuto) then
            -- CleanName (keeps internal spaces); the old gsub("%s+","") turned "pvp build" into "pvpbuild"
            -- so a spaced autoload name never matched its file.
            local nm = CleanName(FS.read(legacyAuto) or "")
            if nm ~= "" then FS.write(nativeAuto, nm) end
        end
    end)
    return migrated
end

-- Bring back configs that the earlier "Matcha"-folder builds saved. Those are already in this library's
-- native shape, so they copy straight across (no translation). Non-destructive: never overwrites a config
-- already in the real folder, and safe to re-run. Lets anyone who ran a "Matcha" build keep presets saved
-- while configs were wrongly stored there.
function Library:MigrateMatchaConfigs(matchaRoot)
    matchaRoot = tostring(matchaRoot or genv.MatchaFolder or "Matcha")
    if not CanFS() then return 0 end
    local matchaDir = matchaRoot .. "/configs"
    local okf, isf = pcall(FS.isfolder, matchaDir)
    if not okf or not isf then return 0 end
    if not EnsureDir() then return 0 end
    local okl, files = pcall(FS.list, matchaDir)
    if not okl or type(files) ~= "table" then return 0 end
    local migrated = 0
    for _, f in ipairs(files) do
        local name = tostring(f):match("([^/\\]+)%.json$")
        if name then
            local newPath = Library.ConfigDir .. "/" .. name .. ".json"
            local okx, exists = pcall(FS.isfile, newPath)
            if not (okx and exists) then
                local okr, raw = pcall(FS.read, tostring(f))
                if okr and raw and pcall(FS.write, newPath, raw) then migrated = migrated + 1 end
            end
        end
    end
    -- carry the autoload choice over if the real folder doesn't already have one
    pcall(function()
        local matchaAuto = matchaRoot .. "/autoload.txt"
        local nativeAuto = Library.ConfigRoot .. "/autoload.txt"
        if FS.isfile(matchaAuto) and not FS.isfile(nativeAuto) then
            local nm = CleanName(FS.read(matchaAuto) or "")
            if nm ~= "" then FS.write(nativeAuto, nm) end
        end
    end)
    -- Delete the old Matcha folder now that its configs are safely in the real folder. Order matters for
    -- safety: only remove a config file once its copy is confirmed present (so nothing is ever lost), remove
    -- the autoload copy once the real one exists, then drop the emptied "configs" subfolder and the Matcha
    -- root -- but the root ONLY if nothing else remains, so a user-supplied custom font (Matcha/font.ttf) is
    -- never nuked. Folder removal needs a deleter the executor exposes; with only delfile we still clear the
    -- files and leave the (now-empty) dirs.
    pcall(function()
        local function globalFn(n)
            local g = (getgenv and getgenv()[n]) or rawget(_G, n)
            return type(g) == "function" and g or nil
        end
        local delFolder = globalFn("delfolder") or globalFn("deldir") or globalFn("removefolder")
        if FS.del then
            local rem = FS.list(matchaDir)
            if type(rem) == "table" then
                for _, f in ipairs(rem) do
                    local name = tostring(f):match("([^/\\]+)%.json$")
                    if name then
                        local okx, exists = pcall(FS.isfile, Library.ConfigDir .. "/" .. name .. ".json")
                        if okx and exists then pcall(FS.del, tostring(f)) end
                    end
                end
            end
            local matchaAuto = matchaRoot .. "/autoload.txt"
            if FS.isfile(matchaAuto) and FS.isfile(Library.ConfigRoot .. "/autoload.txt") then
                pcall(FS.del, matchaAuto)
            end
        end
        if delFolder then
            local sub = FS.list(matchaDir)
            if type(sub) == "table" and #sub == 0 then pcall(delFolder, matchaDir) end
            local root = FS.list(matchaRoot)
            if type(root) == "table" and #root == 0 then pcall(delFolder, matchaRoot) end
        end
    end)
    return migrated
end

function Library:DeleteConfig(name)
    name = CleanName(name)
    if name == "" then
        Library:Notify("Configs", "Pick a config first", 3)
        return false
    end
    if CanFS() and EnsureDir() then
        if not FS.del then
            Library:Notify("Configs", "File deletion is unavailable", 4)
            return false
        end
        local path = Library.ConfigDir .. "/" .. name .. ".json"
        local existsOk, exists = pcall(FS.isfile, path)
        if existsOk and not exists then
            Library:Notify("Configs", "Config '" .. name .. "' not found", 3)
            return false
        end
        local ok, err = pcall(FS.del, path)
        if not ok then
            Library:Notify("Configs", "Could not delete the file: " .. tostring(err):sub(1, 100), 4)
            return false
        end
    elseif not Library.MemConfigs[name] then
        Library:Notify("Configs", "Config '" .. name .. "' not found", 3)
        return false
    end
    Library.MemConfigs[name] = nil
    if Library.CurrentConfig == name then
        Library.CurrentConfig = nil
        if Library.RefreshConfigBar then Library.RefreshConfigBar() end
    end
    Library:RefreshConfigs()
    Library:Notify("Configs", "Deleted '" .. name .. "'", 3)
    return true
end

-- Opens the configs folder in the file explorer. Roblox executors don't share one API for that, so this tries every
-- opener we know about; if none exists it copies the path to your clipboard instead. If you know your workspace path,
-- set getgenv().MatchaWorkspacePath = "C:\\path\\to\\workspace" BEFORE loading to make the explorer fallback work.
function Library:OpenConfigFolder()
    EnsureDir()
    local rel = Library.ConfigDir
    local function fn(name)
        local f = (getgenv and getgenv()[name]) or rawget(_G, name)
        return type(f) == "function" and f or nil
    end
    local opened = false
    for _, name in ipairs({ "openfolder", "open_folder", "showfolder", "revealfolder", "openinexplorer", "openexplorer" }) do
        local f = fn(name)
        if f and pcall(f, rel) then opened = true break end
    end
    local abs = genv.MatchaWorkspacePath and (tostring(genv.MatchaWorkspacePath):gsub("[/\\]+$", "") .. "\\" .. rel:gsub("/", "\\")) or nil
    if not opened and abs then
        for _, name in ipairs({ "shellexecute", "ShellExecute", "runcmd" }) do
            local f = fn(name)
            if f and pcall(f, "explorer.exe", '"' .. abs .. '"') then opened = true break end
        end
        if not opened and type(os.execute) == "function" then
            opened = pcall(os.execute, 'start "" explorer "' .. abs .. '"')
        end
    end
    if opened then
        Library:Notify("Configs", "Opened the configs folder", 3)
        return true
    end
    local shown = abs or ("workspace/" .. rel)
    local copy = fn("setclipboard") or fn("toclipboard") or fn("set_clipboard")
    if copy and pcall(copy, shown) then
        Library:Notify("Configs", "Your executor can't open folders - path copied: " .. shown, 5)
    else
        Library:Notify("Configs", "Your executor can't open folders. Configs are in: " .. shown, 5)
    end
    return false
end

function Library:Unload()
    Library.Dead = true
    for _, c in ipairs(Library.Conns) do pcall(function() c:Disconnect() end) end
    Library.Conns = {}
    pcall(function() Blur:Destroy() end)
    pcall(function() if PB.Dof then PB.Dof:Destroy() end end)
    pcall(function() if PB.Part then PB.Part:Destroy() end end)
    pcall(function() Gui:Destroy() end)
    if genv.MatchaLibrary == Library then genv.MatchaLibrary = nil end
end

-- demo menu (UI showcase)
-- Library:CreateDemo()  builds a UI showcase: Controls (every control type), Layout, Widgets, an ESP preview and the real Options tab.
-- It runs by itself ~1s after the library loads IF your script hasn't created a window.  getgenv().LumaDemo = false  turns that off.
-- Nothing here is a fake feature: the controls just demonstrate the UI. The Options tab is wired to the real library settings.
function Library:CreateDemo(dopts)
    dopts = dopts or {}
    local lp = game:GetService("Players").LocalPlayer
    local W = Library:CreateWindow({ Title = dopts.Title or Library.Brand.Name, User = lp.Name, License = dopts.License or "Lifetime" })
