        t:AddToggle({ Name = "Hold Keybind", Flag = "Showcase.ToggleHold", Display = "Hold Demo" }):AddKeybind({ Default = "none", Mode = "Hold" })
        t:AddToggle({ Name = "With Color", Flag = "Showcase.ToggleColor" }):AddColorPicker({ Flag = "Showcase.ToggleColor.Color", Default = Library.Brand.Color })
        t:AddToggle({ Name = "Keybind + Color", Flag = "Showcase.ToggleBoth", Display = "Both Demo" }):AddKeybind({ Default = "none", Mode = "Toggle" }):AddColorPicker({ Flag = "Showcase.ToggleBoth.Color", Default = Library.Brand.Color2 })

