        end
        return false
    end
    function Library:CloseAllDropdowns() end
    function Library:UpdateDependencyBoxes() end

    function Library:MakeDraggable(inst, cutoff, limit)
        inst.Active = true
        inst.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
            if not Mouse then return end
            local objPos = Vector2.new(Mouse.X - inst.AbsolutePosition.X, Mouse.Y - inst.AbsolutePosition.Y)
            if objPos.Y > (cutoff or 40) * Library:GetInstanceScale(inst) then return end
            while UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
                inst.Position = UDim2.new(0, Mouse.X - objPos.X + (inst.AbsoluteSize.X * inst.AnchorPoint.X),
                    0, Mouse.Y - objPos.Y + (inst.AbsoluteSize.Y * inst.AnchorPoint.Y))
