        tip.BorderSizePixel = 0
        tip.TextColor3 = Library.FontColor
        tip.FontFace = Library.Font
        tip.TextSize = 14
        tip.Text = "  " .. tostring(infoStr) .. "  "
        tip.AutomaticSize = Enum.AutomaticSize.XY
        tip.ZIndex = 5000
        tip.Visible = false
        tip.Parent = Library.ScreenGui
        local c = Instance.new("UICorner"); c.CornerRadius = UDim.new(0, 6); c.Parent = tip
        local me = hoverInstance.MouseEnter:Connect(function()
            if Mouse then tip.Position = UDim2.fromOffset(Mouse.X + 15, Mouse.Y + 12) end
            tip.Visible = true
        end)
        local ml = hoverInstance.MouseLeave:Connect(function() tip.Visible = false end)
