        return win
    end

    function Library:CreateInfoLogger() return ensureInfoLogger() or { Destroy = function() end } end
    function Library:RefreshInfoLogger() end
    function Library:UpdateInfoLoggerSize() end -- window is fixed-size with a scrolling body now

    -- Wipe every line currently in the logger.
    function Library:ClearInfoLogger()
        local data = Library.InfoLoggerData
