        for _, l in ipairs(data.ContainerLabels) do
            pcall(function() l:Destroy() end)
        end
        data.ContainerLabels = {}
    end

    function Library:SetInfoLoggerVisibility(v)
        local win = ensureInfoLogger()
        if win then win:SetVisible(v == true) end
    end

    function Library:AddTextToInfoLogger(text, copyText, copyFunc, expiry)
        local win = ensureInfoLogger()
        if not win then return nil end
        local data = Library.InfoLoggerData
        data.ContainerLabels = data.ContainerLabels or {}

        local lbl = New("TextLabel", {
            BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 16), FontFace = Library.Font,
            TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, TextColor3 = Library.FontColor,
            Text = tostring(text or ""), TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 53,
            Parent = Library.InfoLoggerContainer,
        })

        -- No overflow cap: every logged line is kept (the scrolling body grows). Lines only ever leave
        -- via an explicit clear (blacklisting a key) or the optional expiry timer below.
        data.ContainerLabels[#data.ContainerLabels + 1] = lbl

        if copyText then
            lbl.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 then
                    pcall(setclipboard, copyText)
                    pcall(function() Library:Notify("Logger", "Copied: " .. tostring(copyText), 2) end)
                end
            end)
        end
        if copyFunc then
            lbl.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 then pcall(copyFunc) end
            end)
        end

        if expiry and type(expiry) == "number" and expiry > 0 then
            task.delay(expiry, function()
                if lbl and lbl.Parent then
                    local idx = table.find(data.ContainerLabels, lbl)
                    if idx then table.remove(data.ContainerLabels, idx) end
                    pcall(function() lbl:Destroy() end)
