		return true
	end
end)

---@param tbl table
---@param value any
---@return boolean
local manualTableFind = LPH_NO_VIRTUALIZE(function(tbl, value)
	for _, val in next, tbl do
		if val ~= value then
			continue
		end

		return true
	end
end)

---@param tbl table
---@return boolean
local hasNonBooleans = LPH_NO_VIRTUALIZE(function(tbl)
	for _, value in next, tbl do
		if typeof(value) == "boolean" then
			continue
		end

		return false
	end

	return true
end)

---@param tbl table
local getTableLength = LPH_NO_VIRTUALIZE(function(tbl)
	local count = 0

	for _ in next, tbl do
		count = count + 1
	end

	return count
end)

---@param tbl table
local validateKeys = LPH_NO_VIRTUALIZE(function(tbl)
	local allowedKeys = {
		["Left"] = true,
		["Right"] = true,
		["W"] = true,
		["A"] = true,
		["S"] = true,
		["D"] = true,
		["Thumbstick1"] = true,
		["C"] = true,
		["f"] = true,
		["H"] = true,
		["Space"] = true,
		["ctrl"] = true,
	}

	for key, _ in next, tbl do
		if allowedKeys[key] then
			continue
		end

		return false
	end

	return true
end)

---@return Vector3?
InputClient.getLastRollMoveDirection = LPH_NO_VIRTUALIZE(function()
	local rollFunction = InputClient.rollFunctionCache
	if not rollFunction then
		return nil
	end

	local lastRollMoveDirection = nil

	for _, upvalue in next, (REFLECT(debug.getupvalues, rollFunction) or {}) do
		if typeof(upvalue) ~= "Vector3" then
			continue
		end

		lastRollMoveDirection = upvalue
		break
	end

	if not lastRollMoveDirection then
		lastRollMoveDirection = Vector3.zero
	end

	if lastRollMoveDirection and typeof(lastRollMoveDirection) ~= "Vector3" then
		return nil
	end

	return lastRollMoveDirection
end)

---@return table?
InputClient.getHumanController = LPH_NO_VIRTUALIZE(function()
	---@note: Shouldn't be too many connections to PreSimulation.
	for _, connection in next, (REFLECT(getconnections, runService.PreSimulation) or {}) do
		local func = connection.Function
		if not func then
			continue
		end

		if REFLECT(iscclosure, func) or REFLECT(isexecutorclosure, func) then
			continue
		end

		local upvalues = REFLECT(debug.getupvalues, func)
		if not upvalues then
			continue
		end

		for _, upvalue in next, upvalues do
			if typeof(upvalue) ~= "table" then
				continue
			end

			if upvalue.Jumping == nil then
				continue
			end

			return upvalue
		end
	end

	return nil
end)

---@note: The game's input handler keeps the boolean input table as an upvalue on a RenderStepped
---connection whose constants include ".lastHBCheck". Find and return that table. Factored out of cache()
---so getInputData() can self-heal on demand. Main-thread callers only (combat actions + cache()), so it
---never runs from the cross-VM tostring hook -- the merge's anti-Kernel-panic guarantee stays intact.
local scanInputData = LPH_NO_VIRTUALIZE(function()
	for _, connection in next, (REFLECT(getconnections, runService.RenderStepped) or {}) do
		local func = connection.Function
		if not func then
			continue
		end

		if REFLECT(iscclosure, func) then
			continue
		end

		local consts = REFLECT(debug.getconstants, func)
		if type(consts) ~= "table" or not manualTableFind(consts, ".lastHBCheck") then
			continue
		end

		local upvalues = REFLECT(debug.getupvalues, func) or {}

		---@note: Only table with boolean values is the input table.
		for _, upvalue in next, upvalues do
			if typeof(upvalue) ~= "table" or REFLECT(getrawmetatable, upvalue) then
				continue
			end

			if not hasNonBooleans(upvalue) then
				continue
			end

			if getTableLength(upvalue) >= 1 and not validateKeys(upvalue) then
				continue
			end

			return upvalue
		end
	end

	return nil
end)

---Main-thread fallback: find the input table directly in the GC by its shape instead of via a connection
---marker. The game's input table is a plain table (no metatable) whose values are ALL booleans and whose
---keys are only ever input names (validateKeys' allowed set), and it always carries Right/f (the attack +
---block flags luma writes). getgc() already runs on the main thread in cache(), so this stays crash-safe --
---no cross-VM reflection. Among candidates, take the largest (the complete, live input state table).
local scanInputDataGC = LPH_NO_VIRTUALIZE(function()
	local best, bestLen = nil, 0

	for _, value in next, (REFLECT(getgc, true) or {}) do
		if type(value) == "table" and not REFLECT(getrawmetatable, value) and hasNonBooleans(value) then
			local len = getTableLength(value)
			if len >= 4 and validateKeys(value) and (value["Right"] ~= nil or value["Left"] ~= nil or value["f"] ~= nil) then
				if len > bestLen then
					best, bestLen = value, len
				end
			end
		end
	end

	return best
end)

---@return table?
InputClient.getInputData = LPH_NO_VIRTUALIZE(function()
	---@note: 4b50864 kept this table live by re-scanning on every tostring-hook tick, so it was never nil
	---when combat asked for it. The merge moved caching to a bounded ensureCached() that STOPS after the
	---first success; if its retry window misses the input table, inputDataCache stays nil forever and every
	---input-gated action (parry/dodge/feint/left) bails with "Cannot ... without input data." Self-heal:
	---scan on demand whenever the cache is empty. Once populated, this is a single nil check -- zero cost.
	if not inputDataCache then
		---@note: the connection-marker scan (.lastHBCheck on RenderStepped) is the fast path; the GC
		---shape-scan is the fallback for current Deepwoken, where that marker isn't reachable from a
		---main-thread scan.
		inputDataCache = scanInputData() or scanInputDataGC()
	end
	return inputDataCache
end)

---@param cframe CFrame
---@param ignoreChecks boolean
InputClient.left = LPH_NO_VIRTUALIZE(function(cframe, ignoreChecks, forceGround)
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return false
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return false
	end

	local character = players.LocalPlayer.Character
	if not character then
		return false
	end

	local humanoid = character:FindFirstChildWhichIsA("Humanoid")
	if not humanoid then
		return false
	end

	if effectReplicatorModule:HasEffect("InDialogue") then
		return false
	end

	local inputData = InputClient.getInputData()
	if not inputData then
		Logger.warn("Cannot left click without input data.")
		return false
	end

	local leftClickRemote = KeyHandling.getRemote("LeftClick")
	if not leftClickRemote then
		return false
	end

	if not ignoreChecks then
		if
			effectReplicatorModule:HasEffect("LightAttack")
			or effectReplicatorModule:HasEffect("CriticalAttack")
			or effectReplicatorModule:HasEffect("Followup")
			or effectReplicatorModule:HasEffect("Parried")
		then
			return false
		end
	end

	---@note: Missing M1-Hold and Input Buffering functionality but I don't think the caller cares about it.
	-- forceGround forces a grounded m1 (no aerial), matching PR's m1_hold no_aerials behavior.
	local aerial = (not forceGround) and inAirCheck() or false
	-- Mark this as our own fire so the UnreliableFireServer hook passes it through (no re-block / re-mixup)
	-- without needing checkcaller() -- see Game/SelfFire.
	local OK, ERR = pcall(SelfFire.wrap, function()
		unreliableFireServer(leftClickRemote, aerial, cframe, inputData)
	end)
	if not OK then return false, tostring(ERR) end
	return true
end)

