        local Action = getfenv().Action

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local distance = self:distance(self.entity)
        	local action = Action.new()
        	action._when = math.min(400 + distance * 7.5)
        	action._type = "Parry"
        	action.hitbox = Vector3.new(45, 20, 75)
        	action.name = string.format("(%.2f) Dynamic Crimson Rain Timing", distance)
        	return self:action(timing, action)
        end
    end,
    ["CrimsonRainRecall"] = function()
        ---@module Modules.Globals.ProjectileListener
        local ProjectileListener = getfenv().ProjectileListener

        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@type Action
        local Action = getfenv().Action

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---@module Game.Latency
        local Latency = getfenv().Latency

        -- Create listener for Fire Forge projectiles
        local plistener = ProjectileListener.new("CrimsonRain")

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	plistener:connect(function(child)
        		if not child.Name:match("BloodDagger") then
        			return
        		end

        		task.wait(0.01 - Latency.rtt())

        		local action = Action.new()
        		action._when = 40
        		action._type = "Parry"
        		action.name = "Crimson Rain Dagger"

        		local pt = PartTiming.new()
        		pt.uhc = true
        		pt.duih = true
        		pt.fhb = true
        		pt.name = "CrimsonRainProjectile"
        		pt.hitbox = Vector3.new(12, 12, 25)
        		pt.actions:push(action)
        		pt.cbm = true

        		Defense.cdpo(child, pt)
        	end)
        end
    end,
