        	timing.duih = true
        	timing.hitbox = Vector3.new(20, 20, 20)
        	timing.fhb = true

        	local actionTwo = Action.new()
        	actionTwo._when = 0
        	actionTwo._type = "Parry"
        	actionTwo.name = string.format("(2) (%.2f) Dynamic Flame Grab Timing", self.track.Speed)
        	self:action(timing, actionTwo)
        end
