        	end

        	local action = Action.new()
        	action._when = 0
        	action._type = "Parry"
        	action.name = "Shadow Slash Part"

        	local pt = PartTiming.new()
        	pt.uhc = true
        	pt.duih = true
        	pt.fhb = true
        	pt.name = "ShadowSlash"
        	pt.hitbox = Vector3.new(30, 25, 30)
            pt.hso = 15
        	pt.actions:push(action)
        	pt.cbm = true

        	Defense.cdpo(tracker:wait(), pt)
        end
