    ["SilentheartWarn"] = function()
        ---@type Action
        local Action = getfenv().Action

        -- Services.
        local players = game:GetService("Players")

        ---Look for attachment -> recolor.
        ---@return ParticleEmitter?
        local function getRecolorEmitter()
        	local character = players.LocalPlayer.Character
        	if not character then
        		return
        	end

        	local hrp = character:FindFirstChild("HumanoidRootPart")
        	if not hrp then
        		return
        	end

        	for _, child in next, hrp:GetChildren() do
        		if not child:IsA("Attachment") then
        			continue
        		end

        		local recolor = child:FindFirstChild("Recolor")
        		if not recolor then
        			continue
        		end

        		return recolor
        	end
        end

        ---Module function.
        ---@param self EffectDefender
        ---@param timing EffectTiming
        return function(self, timing)
        	local hrp = players.LocalPlayer.Character and players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        	if not hrp then
        		return
        	end

        	local recolor = nil

        	repeat
        		-- Wait.
        		task.wait()

        		-- Get recolor emitter.
        		recolor = getRecolorEmitter()
        	until recolor

        	local action = Action.new()
        	action._when = 250
        	action._type = "Parry"
        	action.ihbc = true
        	action.name = string.format("(%.6f - %.6f) Dynamic Relentless Hunt Timing", recolor.Speed.Min, recolor.Speed.Max)
        	return self:action(timing, action)
        end
    end,
    ["SinisterHalo"] = function()
        ---@module Features.Combat.Objects.RepeatInfo
        local RepeatInfo = getfenv().RepeatInfo

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---@module Game.Timings.PartTiming
        local PartTiming = getfenv().PartTiming

        -- Services.
        local players = game:GetService("Players")

        ---Module function.
        ---@param self PartDefender
        ---@param timing PartTiming
        return function(self, timing)
        	local humanoid = players.LocalPlayer
        		and players.LocalPlayer.Character
        		and players.LocalPlayer.Character:FindFirstChildOfClass("Humanoid")

        	if not humanoid then
        		return
        	end

        	for _, track in next, humanoid:GetPlayingAnimationTracks() do
        		if track.Animation.AnimationId == "rbxassetid://9919986614" then
        			return
        		end
        	end

        	local ntiming = PartTiming.new()
        	ntiming.name = "SinisterHaloRepeat"
        	ntiming.duih = true
        	ntiming.hitbox = Vector3.new(20, 20, 20)
        	ntiming.fhb = false
        	ntiming.ndfb = true
        	ntiming._rsd = 0
        	ntiming._rpd = 125
        	ntiming.imxd = 120
        	ntiming.imdd = 0
        	ntiming.mrt = 1.75

        	ntiming.rsd = function()
        		return ntiming._rsd / 1000
        	end

        	ntiming.rpd = function()
        		return ntiming._rpd / 1000
        	end

        	local info = RepeatInfo.new(ntiming, Latency.rdelay(), self:uid(10))
        	self:srpue(self.part, ntiming, info)
        end
    end,
    ["Smite"] = function()
        ---@class Action
        local Action = getfenv().Action

        return function(self, timing)
        	local shooty = self.part:FindFirstChild("Shooty")
        	if not shooty then
        		return
        	end

        	if not shooty.IsPlaying then
        		shooty.Played:Wait()
        	end

        	timing.duih = true
        	timing.hitbox = Vector3.new(7, 7, 7)
        	timing.fhb = false

        	local action = Action.new()
        	action._when = 350
        	action._type = "Parry"
        	action.hitbox = Vector3.new(0, 0, 0)
        	action.name = "Contact"
        	return self:action(timing, action)
        end
    end,
    ["SmoulderingHallow"] = function()
        ---@module Modules.Globals.ProjectileListener
        local ProjectileListener = getfenv().ProjectileListener

        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@type Action
        local Action = getfenv().Action

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---@module Game.Latency
        local Latency = getfenv().Latency

        -- Create listener for Smouldering Hallow projectiles
        local plistener = ProjectileListener.new("SmoulderingCrit")

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	if self:distance(self.entity) <= 20 then
        		local action = Action.new()
        		action._type = "Start Block"
        		action._when = 700
        		action.name = "Smouldering Crit Start Timing"
        		action.hitbox = Vector3.new(18, 18, 25)
        		self:action(timing, action)

        		local endAction = Action.new()
        		endAction._type = "End Block"
        		endAction._when = 2500
        		endAction.name = "Smouldering Crit End Timing"
        		return self:action(timing, endAction)
        	end

        	plistener:connect(function(child)
        		if not child.Name:match("PumpkinProjectile") then
        			return
        		end

        		local action = Action.new()
        		action._when = 0
        		action._type = "Parry"
        		action.name = "Pumpkin Part"

        		local pt = PartTiming.new()
        		pt.uhc = true
        		pt.duih = true
        		pt.fhb = false
        		pt.name = "PumpkinProjectile"
        		pt.hitbox = Vector3.new(25, 25, 25)
        		pt.actions:push(action)
        		pt.cbm = true

        		Defense.cdpo(child, pt)
        	end)
        end
    end,
