    ["EtherBarrage"] = [[
---@type PartTiming
local PartTiming = getfenv().PartTiming

---@type Action
local Action = getfenv().Action

---@type ProjectileTracker
---@diagnostic disable-next-line: unused-local
local ProjectileTracker = getfenv().ProjectileTracker

---@module Game.Latency
local Latency = getfenv().Latency

---Check if orbs have all been destroyed.
local function areOrbsStillParented(orbs)
	for _, orb in next, orbs do
		if not orb.Parent then
			continue
		end

		return true
	end

	return false
end

---Module function.
---@param self AnimatorDefender
---@param timing AnimationTiming
return function(self, timing)
	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		return
	end

	local tracker = ProjectileTracker.new(function(candidate)
		return candidate.Name == "IntBangsErudite"
	end)

	if self:distance(self.entity) <= 20 then
		local action = Action.new()
		action._when = 400
		action._type = "Start Block"
		action.name = "Close Ether Barrage Start"
		action.ihbc = true
		self:action(timing, action)

		local secondAction = Action.new()
		secondAction._when = 1300
		secondAction._type = "End Block"
		secondAction.name = "Close Ether Barrage End"
		secondAction.ihbc = true
		return self:action(timing, secondAction)
	end

	task.wait(0.05 - Latency.rtt())

	local model = tracker:wait()
	if not model then
		return
	end

	local orbs = {}

	for _, part in pairs(model:GetChildren()) do
		if not part:IsA("BasePart") then
			continue
		end

		if not part.Name:match("etherorb") then
			continue
		end

		orbs[#orbs + 1] = part
	end

	local blockStarted = false

	while task.wait() do
		for _, orb in next, orbs do
			if not areOrbsStillParented(orbs) then
				local secondAction = Action.new()
				secondAction._when = 0
				secondAction._type = "End Block"
				secondAction.name = "Ether Barrage End"
				secondAction.ihbc = true
				return self:action(timing, secondAction)
			end

			if not orb or not orb.Parent then
				continue
			end

			if self:distance(orb) >= 30 then
				continue
			end

			if blockStarted then
				continue
			end

			local action = Action.new()
			action._when = 0
			action._type = "Start Block"
			action.name = "Ether Barrage Start"
			action.ihbc = true
			self:action(timing, action)

			blockStarted = true
		end
	end
end

]],
    ["EthironBeam"] = [[
---@class Action
local Action = getfenv().Action

---@module Features.Combat.Objects.RepeatInfo
local RepeatInfo = getfenv().RepeatInfo

---@module Game.Latency
local Latency = getfenv().Latency

---Module function.
---@param self AnimatorDefender
---@param timing AnimationTiming
return function(self, timing)
	local hrp = self.entity:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return
	end

	local rarm3 = self.entity:FindFirstChild("RArm3")
	if not rarm3 then
		return
	end

	-- Beam.
	if rarm3:WaitForChild("Attach", 0.1) then
		local info = RepeatInfo.new(timing, Latency.rdelay(), self:uid(10))
		info.track = self.track

		timing.mat = 3000
		timing.fhb = false
		timing.ieae = true
		timing.iae = true
		timing.rpue = true
		timing.duih = false
		timing.imdd = 0
		timing.imxd = 1000
		timing._rsd = 800
		timing._rpd = 150
		return self:srpue(self.entity, timing, info)

	-- Blinding move
	else
		local action = Action.new()
		action._when = 1400
		action._type = "Parry"
