		action._type = "Parry"
		action.hitbox = Vector3.new(25, 20, 20)
		action.name = "Iron Birch Onslaught Timing"
		return self:action(timing, action)
	end

	local action = Action.new()
	action._when = 700
	action._type = "Parry"
	action.hitbox = Vector3.new(25, 20, 20)
	action.name = "Onslaught Timing"
	return self:action(timing, action)
