		tempTween(workspace.NPCs:FindFirstChild("TheDoor"):GetPivot(), 250)
	end)
	repeat
		pcall(function()
			fireProx(workspace.NPCs:FindFirstChild("TheDoor").InteractPrompt)
		end)
