-- Isolate each feature's init/detach: one feature erroring can no longer abort loading/unloading the rest.
-- This is the core of the re-execution fix -- before, a single throwing detach left every later module's
-- connections/threads/hooks leaked, and they piled up across teleports until the client died.
---@param module table
---@param method string
local function isolated(module, method)
	local fn = module[method]
	if type(fn) ~= "function" then
		return
	end

	local OK, ERR = pcall(fn)
	if not OK then
  local ERRORS = Features.errors
  if #ERRORS >= 20 then table.remove(ERRORS, 1) end
  ERRORS[#ERRORS + 1] = { method = method, message = tostring(ERR), at = os.clock() }
 end
end

---@note: Careful with features that have entire return LPH_NO_VIRTUALIZE(function() blocks. We assume that we don't care about what's placed in there.
function Features.init()
	for _, module in ipairs(INIT_ORDER) do
		isolated(module, "init")
	end

	if not armorshield or armorshield.current_role == "builder" then
		isolated(AnimationVisualizer, "init")
	end

	if not LPH_OBFUSCATED or shared.Luma.verbose then
		Logger.warn("Features initialized.")
	end
end

function Features.detach()
	-- Admin-panel-driven exploits: stop them no matter the game branch so their render loops
	-- (and the inspector's namecall hook) never survive an unload.
	isolated(AnimationFlooder, "detach")
	isolated(AnimationInspector, "detach")

	if not armorshield or armorshield.current_role == "builder" then
		isolated(AnimationVisualizer, "detach")
	end

	for _, module in ipairs(DETACH_ORDER) do
		isolated(module, "detach")
	end

	Logger.warn("Features detached.")
end

return Features

end)
__bundle_register("Features/Combat/AnimationInspector", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- Animation Inspector -- a live window listing every animation a selected player is CURRENTLY playing.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local MarketplaceService = game:GetService("MarketplaceService")

---@module GUI.Library
local Library = require("GUI/Library")
---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

local AnimationInspector = {}

-- Theme (pulled from the Luma Library so the window matches the menu).
local ACCENT  = Library.AccentColor     or Color3.fromRGB(243, 168, 214)
local MAIN    = Library.MainColor       or Color3.fromRGB(40, 32, 50)
local BG      = Library.BackgroundColor or Color3.fromRGB(28, 22, 36)
local FG      = Library.FontColor       or Color3.fromRGB(245, 238, 250)
local OUTLINE = Library.OutlineColor    or Color3.fromRGB(110, 86, 132)
local RISK    = Library.RiskColor       or Color3.fromRGB(255, 96, 128)
local MUTED   = Color3.fromRGB(168, 156, 182)

local MAX_ROWS = 100         -- hard cap so an AP-break flood can't spawn thousands
local UPDATE_INTERVAL = 0.06 -- ~16 Hz live-prop refresh
local LOG_FILE = "luma_animlog.txt"
local LOG_FLUSH_INTERVAL = 1.0

-- State
local running = false
local targetPlayer = nil
local targetName = nil

local win, subLabel, listFrame, emptyLabel

local rows = {}          -- track -> { frame, nameLabel, propLabel, assetId, stoppedConn }
local rowCount = 0

local animatorConn = nil
local charAddedConn = nil
local charRemovingConn = nil
local updateConn = nil
local updateAccum = 0

-- Namecall-hook capture (fade time isn't exposed on AnimationTrack any other way).
local playArgs = setmetatable({}, { __mode = "k" })
local hookActive = false
local oldNamecall = nil

-- Asset-name resolution.
local nameCache = {}     -- assetId -> name | false
local namePending = {}
local nameQueue = {}
local resolverRunning = false

-- File logging (name / id / priority and any changes to them).
local logBuffer = {}
local logFlushAccum = 0
local logSessionStart = 0

-- Small helpers
local function mk(class, props, parent)
	local inst = Instance.new(class)
	for key, value in pairs(props) do
		inst[key] = value
	end
	if parent then
		inst.Parent = parent
	end
	return inst
end

local function fmtNum(value, digits)
	if type(value) ~= "number" then
		return "?"
	end
	return string.format("%." .. (digits or 2) .. "f", value)
end

local function safeGet(fn, fallback)
	local ok, value = pcall(fn)
	if ok and value ~= nil then
		return value
	end
	return fallback
end

-- The real asset behind an AnimationId.
local function assetIdOf(animationId)
	local text = tostring(animationId or "")
	local viaQuery = text:match("[?&]id=(%d+)")
	if viaQuery then
		return tonumber(viaQuery)
	end
	return tonumber(text:match("(%d+)"))
end

-- Query junk (a `?` AND an `&`) beyond a plain asset reference = id-spoof tell.
local function isMutatedId(animationId)
	local text = tostring(animationId or "")
	return text:find("?", 1, true) ~= nil and text:find("&", 1, true) ~= nil
end

local function lookupName(assetId)
	local ok, info = pcall(function()
		return MarketplaceService:GetProductInfo(assetId, Enum.InfoType.Asset)
	end)
	local resolved = (ok and info and info.Name) or false
	nameCache[assetId] = resolved
	namePending[assetId] = nil
	return resolved
end

local function queueName(assetId)
	if not assetId or nameCache[assetId] ~= nil or namePending[assetId] then
		return
	end
	namePending[assetId] = true
	nameQueue[#nameQueue + 1] = assetId
end

-- One background worker chews through lookups (GetProductInfo yields + rate-limits).
local function startResolver()
	if resolverRunning then
		return
	end
	resolverRunning = true
	task.spawn(function()
		while running do
			local assetId = table.remove(nameQueue, 1)
			if assetId then
				lookupName(assetId)
				task.wait(0.3)
			else
				task.wait(0.25)
			end
		end
		resolverRunning = false
	end)
end

-- Window
local function buildWindow()
	if win then
		return
	end

	win = Library:CreateFloatingWindow({
		Name = "LumaAnimInspect",
		Title = "Animation Inspector",
		Size = UDim2.fromOffset(360, 420),
		Position = UDim2.fromOffset(120, 120),
	})
	-- Closing the window flips the menu toggle off (its OnChanged calls stop()).
	win:OnClose(function()
		local ok = pcall(function()
			local toggles = getgenv and getgenv().Toggles
			if toggles and toggles.AnimationInspector then
				toggles.AnimationInspector:SetValue(false)
				return true
			end
			return false
		end)
		if not ok then
			AnimationInspector.stop()
		end
	end)

	-- Sub-line (target · N playing) pinned to the top of the window body; the list sits below it.
	subLabel = mk("TextLabel", {
		Name = "Sub",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(6, 2),
		Size = UDim2.new(1, -12, 0, 13),
		Font = Enum.Font.Gotham,
		Text = "no target",
		TextColor3 = MUTED,
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Left,
	}, win.Body)

	-- Scrolling list of live rows.
	listFrame = mk("ScrollingFrame", {
		Name = "List",
		Position = UDim2.fromOffset(6, 18),
		Size = UDim2.new(1, -12, 1, -24),
		BackgroundColor3 = MAIN,
		BorderSizePixel = 0,
		ScrollBarThickness = 4,
		ScrollBarImageColor3 = ACCENT,
		CanvasSize = UDim2.new(0, 0, 0, 0),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
	}, win.Body)
	mk("UICorner", { CornerRadius = UDim.new(0, 4) }, listFrame)
	mk("UIListLayout", {
		FillDirection = Enum.FillDirection.Vertical,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 3),
	}, listFrame)
	mk("UIPadding", {
		PaddingTop = UDim.new(0, 4),
		PaddingBottom = UDim.new(0, 4),
		PaddingLeft = UDim.new(0, 4),
		PaddingRight = UDim.new(0, 4),
	}, listFrame)

	emptyLabel = mk("TextLabel", {
		Name = "Empty",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 40),
		Font = Enum.Font.Gotham,
		Text = "no animations playing",
		TextColor3 = MUTED,
		TextSize = 12,
	}, listFrame)
end

-- Rows
local function updateEmptyState()
	if emptyLabel then
		emptyLabel.Visible = rowCount == 0
	end
	if subLabel then
		local who = targetName or "no target"
		subLabel.Text = string.format("%s  ·  %d playing", who, rowCount)
	end
end

-- File logging -- name / id / priority, and any change to them, appended to a txt in the executor's workspace folder for later reading.
local function loggingEnabled()
	return Configuration.expectToggleValue("AnimInspectLogToFile") == true
end

local function writeLog(text)
	pcall(function()
		if appendfile then
			appendfile(LOG_FILE, text)
		elseif writefile and readfile and isfile then
			local existing = isfile(LOG_FILE) and readfile(LOG_FILE) or ""
			if #existing < 5 * 1024 * 1024 then
				writefile(LOG_FILE, existing .. text)
			end
		end
	end)
end

local function flushLog()
	if #logBuffer == 0 then
		return
	end
	local text = table.concat(logBuffer, "\n") .. "\n"
	logBuffer = {}
	writeLog(text)
end

local function logLine(text)
	if not loggingEnabled() then
		return
	end
	logBuffer[#logBuffer + 1] = string.format("[%8.2f] %s", os.clock() - logSessionStart, text)
	if #logBuffer >= 400 then
		flushLog()
	end
end

local function updateRow(row)
	local track = row.track
	local anim = safeGet(function() return track.Animation end)
	local animationId = anim and tostring(anim.AnimationId) or nil
	local mutated = isMutatedId(animationId)

	local assetId = row.assetId
	local resolved = assetId and nameCache[assetId] or nil
	local displayName = resolved or (anim and anim.Name ~= "" and anim.Name) or "?"
	if displayName == "Animation" and assetId then
		displayName = "id:" .. tostring(assetId)
	end

	local priorityName = tostring(safeGet(function() return track.Priority.Name end, "?"))

	row.nameLabel.Text = string.format("%s   ·   %s", displayName, priorityName)
	row.nameLabel.TextColor3 = mutated and RISK or FG

	local args = playArgs[track]
	local fade = args and fmtNum(args.fade) or "?"

	row.propLabel.Text = string.format(
		"spd %s · wt %s/%s · len %s · t %s · fade %s%s",
		fmtNum(safeGet(function() return track.Speed end)),
		fmtNum(safeGet(function() return track.WeightCurrent end)),
		fmtNum(safeGet(function() return track.WeightTarget end)),
		fmtNum(safeGet(function() return track.Length end)),
		fmtNum(safeGet(function() return track.TimePosition end)),
		fade,
		mutated and "  · MUTATED" or ""
	)

	row.idLabel.Text = "id " .. (animationId or "?")
	row.idLabel.TextColor3 = mutated and RISK or ACCENT

	-- Peak WeightCurrent across this track's life. WeightCurrent is ~0 for EVERY
	-- animation the instant it starts (they all ramp up from 0), so a single play-time
	-- read tells you nothing -- the tell for a 0-weight flood bait is that it NEVER
	-- ramps. Sample the peak here every update and log it on stop.
	row.peakWC = math.max(row.peakWC or 0, safeGet(function() return track.WeightCurrent end, 0) or 0)

	-- File log: one line on first sight, then any change to name / id / priority.
	local idStr = animationId or "?"
	if row.loggedId == nil then
		row.loggedName = displayName
		row.loggedId = idStr
		row.loggedPriority = priorityName
		logLine(string.format('[+] name="%s" id=%s priority=%s wt=%s spd=%s', displayName, idStr, priorityName,
			fmtNum(safeGet(function() return track.WeightTarget end)),
			fmtNum(safeGet(function() return track.Speed end))))
	else
		if idStr ~= row.loggedId then
			logLine(string.format("[~] id=%s  id: %s -> %s", row.loggedId, row.loggedId, idStr))
			row.loggedId = idStr
		end
		if displayName ~= row.loggedName then
			logLine(string.format('[~] id=%s  name: "%s" -> "%s"', row.loggedId, row.loggedName, displayName))
			row.loggedName = displayName
		end
		if priorityName ~= row.loggedPriority then
			logLine(string.format("[~] id=%s  priority: %s -> %s", row.loggedId, row.loggedPriority, priorityName))
			row.loggedPriority = priorityName
		end
	end
end

local function removeRow(track)
	local row = rows[track]
	if not row then
		return
	end
	if row.loggedId then
		logLine(string.format("[-] id=%s  (stopped) peakwc=%s", row.loggedId, fmtNum(row.peakWC or 0)))
	end
	rows[track] = nil
	rowCount = rowCount - 1
	if row.stoppedConn then
		pcall(function() row.stoppedConn:Disconnect() end)
	end
	if row.frame then
		row.frame:Destroy()
	end
	updateEmptyState()
end

local function addRow(track)
	if rows[track] or rowCount >= MAX_ROWS or not listFrame then
		return
	end

	local frame = mk("Frame", {
		Name = "Row",
		Size = UDim2.new(1, 0, 0, 54),
		BackgroundColor3 = BG,
		BorderSizePixel = 0,
	}, listFrame)
	mk("UICorner", { CornerRadius = UDim.new(0, 4) }, frame)
	mk("UIStroke", { Color = OUTLINE, Thickness = 1, Transparency = 0.4 }, frame)

	local nameLabel = mk("TextLabel", {
		Name = "Name",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(8, 4),
		Size = UDim2.new(1, -12, 0, 15),
		Font = Enum.Font.GothamSemibold,
		Text = "...",
		TextColor3 = FG,
		TextSize = 12,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, frame)

	local propLabel = mk("TextLabel", {
		Name = "Props",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(8, 20),
		Size = UDim2.new(1, -12, 0, 14),
		Font = Enum.Font.Code,
		Text = "",
		TextColor3 = MUTED,
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, frame)

	local idLabel = mk("TextLabel", {
		Name = "Id",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(8, 35),
		Size = UDim2.new(1, -12, 0, 13),
		Font = Enum.Font.Code,
		Text = "",
		TextColor3 = ACCENT,
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, frame)

	local anim = safeGet(function() return track.Animation end)
	local assetId = anim and assetIdOf(anim.AnimationId) or nil
	queueName(assetId)

	local row = { frame = frame, nameLabel = nameLabel, propLabel = propLabel, idLabel = idLabel, assetId = assetId, track = track }
	rows[track] = row
	rowCount = rowCount + 1

	-- DELETE the row the instant the animation ends.
	row.stoppedConn = track.Stopped:Connect(function()
		removeRow(track)
	end)

	updateRow(row)
	updateEmptyState()
end

local function clearRows()
	for track in pairs(rows) do
		removeRow(track)
	end
	rowCount = 0
	rows = {}
	updateEmptyState()
end

-- Live refresh loop: repaints visible rows and prunes tracks that stopped without firing .Stopped.
local function startUpdateLoop()
	if updateConn then
		return
	end
	updateConn = RunService.RenderStepped:Connect(function(dt)
		if not running then
			return
		end
		updateAccum = updateAccum + dt
		if updateAccum < UPDATE_INTERVAL then
			return
		end
		updateAccum = 0

		local dead = nil
		for track, row in pairs(rows) do
			if not safeGet(function() return track.IsPlaying end, false) then
				dead = dead or {}
				dead[#dead + 1] = track
			else
				updateRow(row)
			end
		end
		if dead then
			for _, track in ipairs(dead) do
				removeRow(track)
			end
		end

		logFlushAccum = logFlushAccum + UPDATE_INTERVAL
		if logFlushAccum >= LOG_FLUSH_INTERVAL then
			logFlushAccum = 0
			flushLog()
		end
	end)
end

-- Parallel-hook guard (see Game/Hooking.lua): on executors without parallel_hooks_allowed, install via a
-- read-only metatable swap so this __namecall hook can't be dispatched from an Actor parallel phase, which
-- is an illegal cross-phase op the engine Kernel panics on (RSL - panic: ...Kernel).
local parallelHooksAllowed = parallel_hooks_allowed
local hookmetamethod = (not parallelHooksAllowed)
	and function(target, method, hook)
		local metatable = getrawmetatable(target)
		setreadonly(metatable, false)
		local original = metatable[method]
		metatable[method] = hook
		setreadonly(metatable, true)
		return original
	end
	or hookmetamethod

-- Namecall hook -- capture the caller's Play(fade, weight, speed) args.
local function installHook()
	if hookActive then
		return
	end
	if not (hookmetamethod and getnamecallmethod and checkcaller) then
		return -- fade time simply stays "?" without exploit hook support
	end
	local ok = pcall(function()
		oldNamecall = hookmetamethod(game, "__namecall", function(self, ...)
			-- NOTE: deliberately NOT skipping checkcaller() calls.
			if not hookActive then
				return oldNamecall(self, ...)
			end
			if getnamecallmethod() == "Play" then
				local okClass, isTrack = pcall(game.IsA, self, "AnimationTrack")
				if okClass and isTrack then
					local a, b, c = ...
					playArgs[self] = {
						fade = type(a) == "number" and a or 0.1,
						weight = type(b) == "number" and b or 1,
						speed = type(c) == "number" and c or 1,
					}
				end
			end
			return oldNamecall(self, ...)
		end)
	end)
	hookActive = ok
end

local function removeHook()
	if not hookActive then
		return
	end
	hookActive = false
	if oldNamecall and hookmetamethod then
		pcall(function()
			hookmetamethod(game, "__namecall", oldNamecall)
		end)
		oldNamecall = nil
	end
end

-- Target binding
local function bindAnimator(animator, character)
	if animatorConn then
		pcall(function() animatorConn:Disconnect() end)
		animatorConn = nil
	end
	if not animator then
		return
	end

	animatorConn = animator.AnimationPlayed:Connect(function(track)
		if running then
			addRow(track)
		end
	end)

	-- Seed with whatever is already playing.
	for _, track in ipairs(safeGet(function() return animator:GetPlayingAnimationTracks() end, {})) do
		addRow(track)
	end
end

local function hookCharacter(character)
	clearRows()
	if not character then
		return
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
	if animator then
		bindAnimator(animator, character)
		return
	end
	-- Character just spawned; its Animator may not exist yet.
	task.spawn(function()
		local hum = character:WaitForChild("Humanoid", 5)
		local anim = hum and hum:WaitForChild("Animator", 5)
		if anim and running and targetPlayer and targetPlayer.Character == character then
			bindAnimator(anim, character)
		end
	end)
end

local function bindPlayer(player)
	if charAddedConn then
		pcall(function() charAddedConn:Disconnect() end)
		charAddedConn = nil
	end
	if charRemovingConn then
		pcall(function() charRemovingConn:Disconnect() end)
		charRemovingConn = nil
	end

	targetPlayer = player
	targetName = player and player.Name or nil

	if win then
		win:SetTitle(player and ("Animation Inspector — " .. player.Name) or "Animation Inspector")
	end
	updateEmptyState()

	if not player then
		clearRows()
		return
	end

	charAddedConn = player.CharacterAdded:Connect(function(character)
		if running and targetPlayer == player then
			hookCharacter(character)
		end
	end)
	charRemovingConn = player.CharacterRemoving:Connect(function()
		if running and targetPlayer == player then
			clearRows()
		end
	end)

	hookCharacter(player.Character)
end

local function resolveByName(name)
	if not name or name == "" then
		return nil
	end
	for _, p in ipairs(Players:GetPlayers()) do
		if p.Name == name then
			return p
		end
	end
	local lower = string.lower(name)
	for _, p in ipairs(Players:GetPlayers()) do
		if string.lower(p.Name) == lower or string.lower(p.DisplayName) == lower then
			return p
		end
	end
	return nil
end

-- Public API
function AnimationInspector.startByName(name)
	local player = resolveByName(name)
	if not player then
		pcall(function()
			Library:Notify("Animation Inspector: pick a player first.", 4)
		end)
		pcall(function()
			local toggles = getgenv and getgenv().Toggles
			if toggles and toggles.AnimationInspector then
				toggles.AnimationInspector:SetValue(false)
			end
		end)
		return
	end

	running = true
	if loggingEnabled() then
		logBuffer = {}
		logFlushAccum = 0
		logSessionStart = os.clock()
		pcall(function()
			if writefile then
				writefile(LOG_FILE, string.format(
					"=== Animation Inspector log | target=%s | %s ===\n",
					player.Name, os.date("%Y-%m-%d %H:%M:%S")
				))
			end
		end)
	end
	buildWindow()
	if win then
		win:Show()
	end
	installHook()
	startResolver()
	startUpdateLoop()
	bindPlayer(player)
end

function AnimationInspector.setTargetByName(name)
	if not running then
		return
	end
	local player = resolveByName(name)
	if player then
		bindPlayer(player)
	end
end

function AnimationInspector.stop()
	if not running then
		return
	end
	running = false

	if updateConn then
		pcall(function() updateConn:Disconnect() end)
		updateConn = nil
	end
	if animatorConn then
		pcall(function() animatorConn:Disconnect() end)
		animatorConn = nil
	end
	if charAddedConn then
		pcall(function() charAddedConn:Disconnect() end)
		charAddedConn = nil
	end
	if charRemovingConn then
		pcall(function() charRemovingConn:Disconnect() end)
		charRemovingConn = nil
	end

	clearRows()
	removeHook()
	flushLog()

	if win then
		pcall(function()
			win.Frame:Destroy()
		end)
		win = nil
		subLabel, listFrame, emptyLabel = nil, nil, nil
	end

	targetPlayer = nil
	targetName = nil
end

-- Full teardown (script detach): tear everything down for good.
function AnimationInspector.detach()
	AnimationInspector.stop()
end

return AnimationInspector
end)()

end)
__bundle_register("Features/Exploits/AnimationFlooder", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- Animation Flooder: plays the decoy attack-animation flood on a selected player's character.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")
---@module GUI.Library
local Library = require("GUI/Library")

local AnimationFlooder = {}

-- Fallback pool if the timing store isn't populated yet (same ids the AP breaker uses).
local FALLBACK_IDS = {
	"rbxassetid://9726608174",
	"rbxassetid://111647546998749",
	"rbxassetid://5064195992",
	"rbxassetid://6607519294",
	"rbxassetid://7600160919",
}
local MOVE_TYPES = { M1 = true, Mantra = true, Critical = true }
local FLOOD_PRIORITY = Enum.AnimationPriority.Action
local MAX_POOL = 200

-- State.
local running = false
local targetPlayer = nil
local targetName = nil
local currentAnimator = nil
local trackPool = {}
local accumulator = 0
local poolCursor = 0
local renderConn = nil
local charAddedConn = nil
local charRemovingConn = nil

-- Helpers
local function getIntensity()
	local value = Configuration.expectOptionValue("AnimationFlooderIntensity")
	if type(value) ~= "number" then
		return 8
	end
	return value
end

-- Attack animation ids straight out of the timing store; fall back to the hard list.
local function collectAttackIds()
	local ids, seen = {}, {}
	pcall(function()
		local TimingStore = require("Game/Timings/SaveManager")
		local list = TimingStore.as:list()
		for _, entry in ipairs(list) do
			if MOVE_TYPES[entry.tag] then
				local id = entry:id()
				if type(id) == "string" and id:match("%d") and not seen[id] then
					seen[id] = true
					ids[#ids + 1] = id
				end
			end
		end
	end)
	if #ids == 0 then
		ids = FALLBACK_IDS
	end
	return ids
end

local function destroyPool()
	for _, track in ipairs(trackPool) do
		pcall(function() track:Stop(0); track:Destroy() end)
	end
	trackPool = {}
	poolCursor = 0
end

-- Load our decoy pool onto the TARGET's animator.
local function loadPool(animator, idList)
	destroyPool()
	if type(idList) ~= "table" or #idList == 0 then
		return
	end

	local targetSize = math.min(MAX_POOL, math.max(#idList, 20))
	local cursor, attempts, maxAttempts = 0, 0, targetSize + #idList + 8
	while #trackPool < targetSize and attempts < maxAttempts do
		attempts = attempts + 1
		cursor = cursor % #idList + 1
		local id = idList[cursor]
		if not string.find(id, "://", 1, true) then
			id = "rbxassetid://" .. id
		end
		local animation = Instance.new("Animation")
		animation.AnimationId = id
		local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
		if ok and track then
			track.Looped = false
			pcall(function() track.Priority = FLOOD_PRIORITY end)
			trackPool[#trackPool + 1] = track
		end
	end
end

-- Target binding
local function bindCharacter(character)
	currentAnimator = nil
	destroyPool()
	if not character then
		return
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
	if animator then
		currentAnimator = animator
		loadPool(animator, collectAttackIds())
		return
	end
	-- Character just spawned; wait for its Animator.
	task.spawn(function()
		local hum = character:WaitForChild("Humanoid", 5)
		local anim = hum and hum:WaitForChild("Animator", 5)
		if anim and running and targetPlayer and targetPlayer.Character == character then
			currentAnimator = anim
			loadPool(anim, collectAttackIds())
		end
	end)
end

local function bindPlayer(player)
	if charAddedConn then
		pcall(function() charAddedConn:Disconnect() end)
		charAddedConn = nil
	end
	if charRemovingConn then
		pcall(function() charRemovingConn:Disconnect() end)
		charRemovingConn = nil
	end

	targetPlayer = player
	targetName = player and player.Name or nil

	if not player then
		currentAnimator = nil
		destroyPool()
		return
	end

	charAddedConn = player.CharacterAdded:Connect(function(character)
		if running and targetPlayer == player then
			bindCharacter(character)
		end
	end)
	charRemovingConn = player.CharacterRemoving:Connect(function()
		if running and targetPlayer == player then
			currentAnimator = nil
			destroyPool()
		end
	end)

	bindCharacter(player.Character)
end

local function resolveByName(name)
	if not name or name == "" then
		return nil
	end
	for _, p in ipairs(Players:GetPlayers()) do
		if p.Name == name then
			return p
		end
	end
	local lower = string.lower(name)
	for _, p in ipairs(Players:GetPlayers()) do
		if string.lower(p.Name) == lower or string.lower(p.DisplayName) == lower then
			return p
		end
	end
	return nil
end

-- Flood loop
local function startLoop()
	if renderConn then
		return
	end
	renderConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then
			return
		end
		local animator = currentAnimator
		if not animator or #trackPool == 0 then
			return
		end

		local interval = 1 / math.max(1, getIntensity())
		accumulator = math.min(accumulator + deltaTime, interval * 2)

		local burstsThisFrame = 0
		while accumulator >= interval and burstsThisFrame < 50 do
			accumulator = accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			-- Prefer an idle track; if all are mid-play, hard-restart the next one so a fresh AnimationPlayed still fires.
			local chosen = nil
			for _ = 1, #trackPool do
				poolCursor = poolCursor % #trackPool + 1
				local candidate = trackPool[poolCursor]
				if candidate and not candidate.IsPlaying then
					chosen = candidate
					break
				end
			end
			local recycled = false
			if not chosen then
				poolCursor = poolCursor % #trackPool + 1
				chosen = trackPool[poolCursor]
				recycled = chosen ~= nil
			end
			if chosen then
				pcall(function()
					if recycled then
						chosen:Stop(0)
					end
					chosen.Priority = FLOOD_PRIORITY
					chosen:Play(0.1, 1, 1)
				end)
			end
		end
	end)
end

-- Public API
function AnimationFlooder.startByName(name)
	local player = resolveByName(name)
	if not player then
		pcall(function() Library:Notify("Animation Flooder: pick a target player first.", 4) end)
		pcall(function()
			local toggles = getgenv and getgenv().Toggles
			if toggles and toggles.AnimationFlooder then
				toggles.AnimationFlooder:SetValue(false)
			end
		end)
		return
	end
	running = true
	startLoop()
	bindPlayer(player)
end

function AnimationFlooder.setTargetByName(name)
	if not running then
		return
	end
	local player = resolveByName(name)
	if player then
		bindPlayer(player)
	end
end

function AnimationFlooder.stop()
	if not running then
		return
	end
	running = false
	if renderConn then
		pcall(function() renderConn:Disconnect() end)
		renderConn = nil
	end
	if charAddedConn then
		pcall(function() charAddedConn:Disconnect() end)
		charAddedConn = nil
	end
	if charRemovingConn then
		pcall(function() charRemovingConn:Disconnect() end)
		charRemovingConn = nil
	end
	destroyPool()
	currentAnimator = nil
	targetPlayer = nil
	targetName = nil
	accumulator = 0
end

function AnimationFlooder.detach()
	AnimationFlooder.stop()
end

return AnimationFlooder
end)()

end)
__bundle_register("Features/Game/RevealAnimations", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local Maid = require("Utility/Maid")

	local Signal = require("Utility/Signal")

	local Configuration = require("Utility/Configuration")

	local Logger = require("Utility/Logger")

	local SaveManager = require("Game/Timings/SaveManager")

	local RevealAnimations = {}

	local runService = game:GetService("RunService")
	local players = game:GetService("Players")
	local collectionService = game:GetService("CollectionService")

	local revealAnimationsMaid = Maid.new()

	local renderStepped = Signal.new(runService.RenderStepped)

	local lastUpdateTime = 0
	local updateThrottleTime = 0.1
	local weightValue = 1
	local modifiedAnimations = {}
	local initialized = false

	local function RESTORE(TRACK, STATE)
		pcall(function()
			if math.abs(TRACK.WeightTarget - STATE.applied) < 0.001 then
				TRACK:AdjustWeight(STATE.original, 0)
			end
			if not STATE.hadTag then collectionService:RemoveTag(TRACK, "RevealAnimationsModified") end
		end)
		modifiedAnimations[TRACK] = nil
	end

	local function RESTORE_ALL()
		for TRACK, STATE in pairs(modifiedAnimations) do RESTORE(TRACK, STATE) end
	end

	local function checkAnimationTrack(animationTrack)
		local priority = animationTrack.Priority

		if
			priority == Enum.AnimationPriority.Action2
			or priority == Enum.AnimationPriority.Action3
			or priority == Enum.AnimationPriority.Action4
		then
			return 0
		end

		if priority == Enum.AnimationPriority.Core or priority == Enum.AnimationPriority.Idle then
			return weightValue
		end

		if animationTrack.WeightCurrent <= 0.01 then
			return weightValue
		end

		local threshold = tonumber(Configuration.expectOptionValue("RevealWeightThreshold")) or 0.5

		if animationTrack.WeightCurrent < threshold then
			return weightValue
		end

		return nil
	end

	local function updateRevealAnimations()
		if not Configuration.expectToggleValue("RevealAnimations") then
			RESTORE_ALL()
			return
		end

		local currentTime = os.clock()

		if currentTime - lastUpdateTime < updateThrottleTime then
			return
		end

		lastUpdateTime = currentTime
		for TRACK, STATE in pairs(modifiedAnimations) do
			if not TRACK.IsPlaying then RESTORE(TRACK, STATE) end
		end

		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return
		end

		for _, player in ipairs(players:GetPlayers()) do
			if player == localPlayer then
				continue
			end

			local character = player.Character

			if not character then
				continue
			end

			local humanoid = character:FindFirstChildOfClass("Humanoid")
			if not humanoid then
				continue
			end

			local animator = humanoid:FindFirstChildOfClass("Animator")
			if not animator then
				continue
			end

			local success, animationTracks = pcall(function()
				return animator:GetPlayingAnimationTracks()
			end)

			if not success then
				continue
			end

			for _, animationTrack in ipairs(animationTracks) do
				local ANIMATION = animationTrack.Animation
				if not ANIMATION or not SaveManager.as or SaveManager.as:index(tostring(ANIMATION.AnimationId)) ~= nil then
					continue
				end

				local adjustWeight = checkAnimationTrack(animationTrack)

				if adjustWeight ~= nil then
					pcall(function()
						local STATE = modifiedAnimations[animationTrack]
						if not STATE then
							STATE = { original = animationTrack.WeightTarget, applied = adjustWeight,
								hadTag = collectionService:HasTag(animationTrack, "RevealAnimationsModified") }
							modifiedAnimations[animationTrack] = STATE
						end
						STATE.applied = adjustWeight
						if math.abs(animationTrack.WeightTarget - adjustWeight) > 0.001 then
							animationTrack:AdjustWeight(adjustWeight, 0)
						end
						if not STATE.hadTag and not STATE.tagged then
							collectionService:AddTag(animationTrack, "RevealAnimationsModified")
							STATE.tagged = true
						end
					end)
				end
			end
		end
	end

	function RevealAnimations.init()
		if initialized then return end
		initialized = true
		if not LPH_OBFUSCATED or shared.Luma.verbose then
			Logger.warn("RevealAnimations initialized.")
		end
		revealAnimationsMaid:add(renderStepped:connect("RevealAnimations_RenderStepped", updateRevealAnimations))
	end

	function RevealAnimations.detach()
		initialized = false
		Logger.warn("RevealAnimations detached.")
		RESTORE_ALL()
		revealAnimationsMaid:clean()
	end

	return RevealAnimations
end)

end)
__bundle_register("Features/Game/OptimizeGame", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local OptimizeGame = {}

	---@module Utility.Signal
	local Signal = require("Utility/Signal")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	local optimizeGameMaid = Maid.new()

	local getinfo = getinfo or debug.getinfo
	local getconstants = getconstants or debug.getconstants

	local alive = false
	local seaHookedFn = nil
	local seaOldFn = nil
	local replicationRestores = {}
	local lowTexturesEnabled = false
	local lowTextureGeneration = 0
	local lowTextureOriginals = setmetatable({}, { __mode = "k" })
	local lowTextureConnections = setmetatable({}, { __mode = "k" })
	local lowTextureQueue = {}
	local lowTextureQueued = setmetatable({}, { __mode = "k" })
	local lowTextureQueueRunning = false
	local distantPartCullEnabled = false
	local distantPartCullDistance = 5000
	local distantPartCullGeneration = 0
	local distantPartCullElapsed = 0
	local distantPartCullUpdating = false
	local distantPartStates = setmetatable({}, { __mode = "k" })
	local treeLeafCullEnabled = false
	local treeLeafCullGeneration = 0

	-- Only fire a retry while the module is still attached, so retry loops can't keep running (and re-driving
	-- render connections) after a detach/re-exec.
	local function retry(callback)
		task.delay(1, function()
			if alive then
				callback()
			end
		end)
	end

	local LOW_TEXTURE = "rbxassetid://130143779"

	local function setLowTextureProperty(object, saved, property, value)
		if saved[property] == nil then
			saved[property] = object[property]
		end
		object[property] = value
	end

	local function watchLowTextureProperty(object, saved, property, lowValue)
		local connections = lowTextureConnections[object]
		if not connections then
			connections = {}
			lowTextureConnections[object] = connections
		end
		if connections[property] then return end

		connections[property] = object:GetPropertyChangedSignal(property):Connect(function()
			if not lowTexturesEnabled then return end
			local current = object[property]
			if current == lowValue then return end
			saved[property] = current
			object[property] = lowValue
		end)
	end

	local function applyLowTextures(object, generation)
		if not lowTexturesEnabled or generation ~= lowTextureGeneration or not object:IsDescendantOf(workspace) then
			return
		end
		local saved = lowTextureOriginals[object]
		if saved then
			return
		end
		saved = {}
		lowTextureOriginals[object] = saved

		if object:IsA("BasePart") then
			setLowTextureProperty(object, saved, "Material", Enum.Material.Plastic)
			setLowTextureProperty(object, saved, "Reflectance", 0)
			setLowTextureProperty(object, saved, "CastShadow", false)
			setLowTextureProperty(object, saved, "TopSurface", Enum.SurfaceType.Smooth)
			setLowTextureProperty(object, saved, "BottomSurface", Enum.SurfaceType.Smooth)
		end
		if object:IsA("MeshPart") then
			setLowTextureProperty(object, saved, "TextureID", "")
			watchLowTextureProperty(object, saved, "TextureID", "")
		elseif object:IsA("Decal") or object:IsA("Texture") then
			setLowTextureProperty(object, saved, "Transparency", 1)
		elseif object:IsA("SurfaceAppearance") then
			for _, property in ipairs({ "ColorMap", "MetalnessMap", "RoughnessMap", "NormalMap" }) do
				setLowTextureProperty(object, saved, property, "")
				watchLowTextureProperty(object, saved, property, "")
			end
		end

		if next(saved) == nil then
			lowTextureOriginals[object] = nil
		end
	end

	local function queueLowTexture(object, generation)
		if not lowTexturesEnabled or generation ~= lowTextureGeneration or lowTextureQueued[object] then
			return
		end

		lowTextureQueued[object] = true
		lowTextureQueue[#lowTextureQueue + 1] = object
		if lowTextureQueueRunning then return end

		lowTextureQueueRunning = true
		task.spawn(function()
			local index = 1
			while index <= #lowTextureQueue do
				if not lowTexturesEnabled or generation ~= lowTextureGeneration then break end

				local queuedObject = lowTextureQueue[index]
				lowTextureQueued[queuedObject] = nil
				applyLowTextures(queuedObject, generation)
				index = index + 1

				if index % 250 == 0 then task.wait() end
			end

			if generation == lowTextureGeneration then
				table.clear(lowTextureQueue)
				lowTextureQueueRunning = false
			end
		end)
	end

	local function restoreLowTextures()
		for object, properties in pairs(lowTextureOriginals) do
			local connections = lowTextureConnections[object]
			if connections then
				for _, connection in pairs(connections) do
					connection:Disconnect()
				end
				lowTextureConnections[object] = nil
			end
			for property, value in pairs(properties) do
				pcall(function() object[property] = value end)
			end
			lowTextureOriginals[object] = nil
		end
	end

	function OptimizeGame.setLowTextures(enabled)
		lowTexturesEnabled = enabled == true
		lowTextureGeneration = lowTextureGeneration + 1
		local generation = lowTextureGeneration
		if not lowTexturesEnabled then
			table.clear(lowTextureQueue)
			table.clear(lowTextureQueued)
			lowTextureQueueRunning = false
			restoreLowTextures()
			return
		end

		table.clear(lowTextureQueue)
		table.clear(lowTextureQueued)
		lowTextureQueueRunning = false
		task.spawn(function()
			local processed = 0
			for _, object in ipairs(workspace:GetDescendants()) do
				if not lowTexturesEnabled or generation ~= lowTextureGeneration then return end
				applyLowTextures(object, generation)
				processed = processed + 1
				if processed % 250 == 0 then task.wait() end
			end
		end)
	end

	local function localRootPart()
		local player = game:GetService("Players").LocalPlayer
		local character = player and player.Character
		return character and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart)
	end

	local function trackPart(part)
		local state = distantPartStates[part]
		if not state then
			state = {
				Original = part.LocalTransparencyModifier,
				HiddenByDistance = false,
				HiddenAsLeaves = false,
			}
			distantPartStates[part] = state
		end
		return state
	end

	local function applyTrackedPartVisibility(part, state)
		if not part.Parent then return end
		local hidden = state.HiddenByDistance or state.HiddenAsLeaves
		local current = part.LocalTransparencyModifier
		if hidden then
			if current ~= 1 then state.Original = current end
			part.LocalTransparencyModifier = 1
		else
			if current ~= state.Original then
				part.LocalTransparencyModifier = state.Original
			end
			if not distantPartCullEnabled and not treeLeafCullEnabled then
				distantPartStates[part] = nil
			end
		end
	end

	local function registerDistantPart(object)
		if distantPartCullEnabled and object:IsA("BasePart") and object:IsDescendantOf(workspace) then
			trackPart(object)
		end
	end

	local function registerTreeLeafObject(object)
		if not treeLeafCullEnabled or not object:IsDescendantOf(workspace) then return end
		local leafObject
		if string.lower(object.Name) == "leaves" then
			leafObject = object
		else
			local ancestor = object.Parent
			while ancestor and ancestor ~= workspace do
				if string.lower(ancestor.Name) == "leaves" then
					leafObject = object
					break
				end
				ancestor = ancestor.Parent
			end
		end
		if not leafObject then return end

		local function hideLeafPart(part)
			if not part:IsA("BasePart") then return end
			local state = trackPart(part)
			state.HiddenAsLeaves = true
			applyTrackedPartVisibility(part, state)
		end
		hideLeafPart(leafObject)
		if leafObject:IsA("BasePart") then return end
		for _, descendant in ipairs(leafObject:GetDescendants()) do
			hideLeafPart(descendant)
		end
	end

	local function distanceToPart(part, position)
		local localPosition = part.CFrame:PointToObjectSpace(position)
		local halfSize = part.Size * 0.5
		local nearestPoint = Vector3.new(
			math.clamp(localPosition.X, -halfSize.X, halfSize.X),
			math.clamp(localPosition.Y, -halfSize.Y, halfSize.Y),
			math.clamp(localPosition.Z, -halfSize.Z, halfSize.Z)
		)
		return (localPosition - nearestPoint).Magnitude
	end

	local function restoreDistantParts()
		for part, state in pairs(distantPartStates) do
			state.HiddenByDistance = false
			applyTrackedPartVisibility(part, state)
		end
	end

	local function updateDistantPartCulling()
		local root = localRootPart()
		if not root then return end
		local generation = distantPartCullGeneration
		local processed = 0
		for part, state in pairs(distantPartStates) do
			if not distantPartCullEnabled or generation ~= distantPartCullGeneration then return end
			if not part:IsDescendantOf(workspace) then
				if part.Parent then part.LocalTransparencyModifier = state.Original end
				distantPartStates[part] = nil
			else
				state.HiddenByDistance = distanceToPart(part, root.Position) > distantPartCullDistance
				applyTrackedPartVisibility(part, state)
			end
			processed = processed + 1
			if processed % 500 == 0 then
				task.wait()
				root = localRootPart()
				if not root then return end
			end
		end
	end

	function OptimizeGame.setDistantPartCullDistance(distance)
		distantPartCullDistance = math.clamp(tonumber(distance) or 5000, 500, 20000)
	end

	function OptimizeGame.setDistantPartCulling(enabled)
		distantPartCullEnabled = enabled == true
		distantPartCullGeneration = distantPartCullGeneration + 1
		local generation = distantPartCullGeneration
		if optimizeGameMaid["DistantPartCull"] then
			optimizeGameMaid["DistantPartCull"]:Disconnect()
			optimizeGameMaid["DistantPartCull"] = nil
		end
		if not distantPartCullEnabled then
			restoreDistantParts()
			return
		end

		restoreDistantParts()
		task.spawn(function()
			local processed = 0
			for _, object in ipairs(workspace:GetDescendants()) do
				if not distantPartCullEnabled or generation ~= distantPartCullGeneration then return end
				registerDistantPart(object)
				if object:IsA("BasePart") then
					processed = processed + 1
					if processed % 500 == 0 then task.wait() end
				end
			end
		end)
		optimizeGameMaid["DistantPartCull"] = game:GetService("RunService").Heartbeat:Connect(function(deltaTime)
			if not distantPartCullEnabled then return end
			distantPartCullElapsed = distantPartCullElapsed + deltaTime
			if distantPartCullElapsed < 1 or distantPartCullUpdating then return end
			distantPartCullElapsed = 0
			distantPartCullUpdating = true
			task.spawn(function()
				updateDistantPartCulling()
				distantPartCullUpdating = false
			end)
		end)
	end

	function OptimizeGame.setTreeLeafCulling(enabled)
		treeLeafCullEnabled = enabled == true
		treeLeafCullGeneration = treeLeafCullGeneration + 1
		local generation = treeLeafCullGeneration
		if not treeLeafCullEnabled then
			for part, state in pairs(distantPartStates) do
				state.HiddenAsLeaves = false
				applyTrackedPartVisibility(part, state)
			end
			return
		end

		task.spawn(function()
			local processed = 0
			for _, object in ipairs(workspace:GetDescendants()) do
				if not treeLeafCullEnabled or generation ~= treeLeafCullGeneration then return end
				if string.lower(object.Name) == "leaves" then
					registerTreeLeafObject(object)
					processed = processed + 1
					if processed % 100 == 0 then task.wait() end
				end
			end
		end)
	end

	local initialized = false
	local ranVisuals = false

	---@param obj Instance
	local function downgradeObject(obj)
		if obj:IsA("BasePart") then
			obj.Material = Enum.Material.Plastic
			obj.Reflectance = 0
			obj.CastShadow = false
		end

		if obj:IsA("Texture") or obj:IsA("Decal") then
			obj.Texture = LOW_TEXTURE
		elseif obj:IsA("SurfaceAppearance") then
			obj.ColorMap = LOW_TEXTURE
			obj.MetalnessMap = ""
			obj.RoughnessMap = ""
			obj.NormalMap = ""
		end

		if obj:IsA("ParticleEmitter") then
			obj.Enabled = false
			obj.Rate = 0
			obj.Speed = NumberRange.new(0)
		end

		if obj:IsA("PointLight") or obj:IsA("SpotLight") or obj:IsA("SurfaceLight") then
			obj.Enabled = false
			obj.Brightness = 0
			obj.Range = 2
		end
	end

	function OptimizeGame.runAggressive()
		if ranVisuals then
			return
		end
		ranVisuals = true
		task.spawn(function()
			local count = 0
			for _, obj in next, game:GetDescendants() do
				pcall(downgradeObject, obj)
				count = count + 1
				if count % 1000 == 0 then
					task.wait()
				end
			end
			Logger.notify("Aggressively optimized %d objects.", count)
		end)
	end

	local function setupSeaClient()
		local sea_client_func

		local function scan(objects)
			for _, object in next, objects do
				if typeof(object) ~= "function" or not getinfo(object).source:find("SeaClient") then
					continue
				end
				if not table.find(getconstants(object), "getWaveAt") then
					continue
				end

				sea_client_func = object
				break
			end
		end
		
		if filtergc then
			pcall(function()
				scan(filtergc("function", {
					IgnoreExecutor = false,
					Constants = { "getWaveAt" },
				}))
			end)
		end

		if not sea_client_func then
			scan(getgc(false))
		end

		if not sea_client_func then
			return Logger.warn("Failed to get SeaClient function.")
		end

		-- When throttled, hand back the LAST real result instead of nil. The old hook returned nothing
		-- on a skipped frame, so anything sampling the sea (floating objects, the local player while
		-- swimming) got nil and jittered -- that was the "lag". Returning the previous value is never
		-- worse than nil. os.clock + an inline Toggles read (no expectToggleValue call) keep the
		-- per-invocation cost near zero on this very hot function.
		local SEA_INTERVAL = 1 / 20
		local last_allowed_call = 0
		local cached = { n = 0 }
		local cachedArgs = { n = 0 }

		---@note: The cached result is only valid for the exact arguments it was computed with.
		local function sameArgs(...)
			local count = select("#", ...)
			if cachedArgs.n ~= count then
				return false
			end

			for index = 1, count do
				if cachedArgs[index] ~= (select(index, ...)) then
					return false
				end
			end

			return true
		end

		local old
		old = hookfunction(sea_client_func, function(...)
			local optimizeToggle = Toggles and Toggles.OptimizeGame
			if
				optimizeToggle
				and optimizeToggle.Value
				and os.clock() - last_allowed_call < SEA_INTERVAL
				and sameArgs(...)
			then
				return table.unpack(cached, 1, cached.n)
			end

			last_allowed_call = os.clock()
			cachedArgs = table.pack(...)
			cached = table.pack(old(...))
			return table.unpack(cached, 1, cached.n)
		end)

		seaHookedFn = sea_client_func
		seaOldFn = old
	end

	-- LowGraphics attribute state.
	local forcingLowGraphics = false
	local originalLowGraphics = nil

	---Force the LowGraphics player attribute while optimizing. WorldClient skips ambient VFX
	---(wind trails, glitches, bubbles, meteors, sail bones, despawn tweens) when it's set.
	---@param enabled boolean
	local function updateLowGraphics(enabled)
		local localPlayer = game:GetService("Players").LocalPlayer
		if not localPlayer then
			return
		end

		if enabled then
			if not forcingLowGraphics then
				originalLowGraphics = localPlayer:GetAttribute("LowGraphics")
				forcingLowGraphics = true
			end

			if localPlayer:GetAttribute("LowGraphics") ~= true then
				localPlayer:SetAttribute("LowGraphics", true)
			end
		elseif forcingLowGraphics then
			forcingLowGraphics = false
			localPlayer:SetAttribute("LowGraphics", originalLowGraphics)
		end
	end

	local function setupWorldClient()
		local last_world_client_func
		local function apply()
			task.wait(1)

			local hi = "WorldClient"
			local cns = getconnections(game:GetService("RunService").PreRender)

			local conn
			for _, object in next, cns do
				local func = object.Function
				if not func or not getinfo(func).source:find(hi) then
					continue
				end

				if last_world_client_func == func then
					return task.delay(1, apply)
				end

				last_world_client_func = func

				-- Crash fix (macOS/macsploit): getconnections() objects on macsploit expose only
				-- .Function and :Disconnect() - the Synapse-style :Disable() method is absent, so the
				-- original object:Disable() raised "attempt to call a nil value (method 'Disable')".
				-- On a worker-thread VM that error unwinds through the executor's native trampoline into
				-- the same NULL+0x28 SIGSEGV documented for conn:Fire(). Neutralize the connection through
				-- whatever the executor actually supports and record whether it stuck: if we cannot silence
				-- the game's own render connection we must NOT install the manual re-fire below, or every
				-- frame renders twice.
				local disabled = false
				if type(object.Disable) == "function" then
					disabled = pcall(function()
						object:Disable()
					end)
				end
				if not disabled then
					-- macsploit path: no :Disable(); try the writable .Enabled flag it exposes on
					-- getconnections objects, and confirm the write actually took.
					disabled = pcall(function()
						object.Enabled = false
					end) and object.Enabled == false
				end
				if not disabled and type(object.Disconnect) == "function" then
					-- Last resort: drop the native listener entirely. We re-fire .Function ourselves
					-- below, so a hard disconnect still yields exactly one render per throttled frame.
					disabled = pcall(function()
						object:Disconnect()
					end)
				end
				if not disabled then
					-- Could not neutralize the render connection on this executor; skip the manual
					-- optimization for this UI rather than double-firing WorldClient. Retry later in
					-- case the connection set changes.
					last_world_client_func = nil
					return task.delay(1, apply)
				end

				conn = object
			end

			if not conn then
				return
			end

			-- Crash fix (macOS/macsploit): conn:Fire() on a getconnections() object dereferences the
			-- executor's cached connection_data inside its Fire path with no liveness check - a
			-- freed/stale pointer after reconnections or respawns produces the NULL+0x28 read we
			-- SIGSEGV'd on. conn.Function is null-safe by comparison, so invoke the listener directly
			-- and wrap in pcall - a defunct connection degrades to a skipped frame, not a dead process.
			local function fireConnection(delta)
				return pcall(function()
					conn.Function(delta)
				end)
			end

			---@note: Re-enable the original connection on cleanup, otherwise WorldClient stays dead after detach.
			optimizeGameMaid["WorldClientRestore"] = function()
				pcall(function()
					if type(conn.Enable) == "function" then
						conn:Enable()
					else
						conn.Enabled = true
					end
				end)
			end

			local last_update = tick()
			optimizeGameMaid["WorldClientRender"] = game:GetService("RunService").PreRender:Connect(function()
				local now = tick()
				local enabled = Configuration.expectToggleValue("OptimizeGame")

				updateLowGraphics(enabled)

				if enabled and now - last_update < 1 / 15 then
					return
				end

				---@note: WorldClient feeds this into SmoothDamp - it must be the real elapsed time.
				local dt = now - last_update
				last_update = now

				return fireConnection(dt)
			end)
		end

		apply()

		local players = game:GetService("Players")
		local localPlayer = players.LocalPlayer
		if localPlayer then
			optimizeGameMaid:add(localPlayer.PlayerGui.ChildAdded:Connect(function(object)
				if not Configuration.expectToggleValue("OptimizeGame") then
					return
				end
				if object.Name ~= "WorldClient" then
					return
				end

				apply()
			end))
		end
	end

	-- PR's opti_clouds: the game drives cloud/entity replication rendering from a RenderStepped
	-- connection inside PlayerScripts.Replication. We neutralize the game's own connection and
	-- re-drive its function at 10Hz, so replication rendering costs a fraction of the frames without
	-- disappearing. Mirrors setupWorldClient's crash-safe handling for macsploit.
	local function setupReplication()
		local last_replication_func

		local function apply()
			local rep_func

			for _, object in next, getconnections(game:GetService("RunService").RenderStepped) do
				local func = object.Function
				if not func or not getinfo(func).source:find("PlayerScripts.Replication") then
					continue
				end

				if last_replication_func == func then
					return retry(apply)
				end

				last_replication_func = func

				-- Same macsploit-safe neutralization as setupWorldClient: the getconnections object may
				-- lack :Disable(); fall back to the writable .Enabled flag, then a hard :Disconnect(). Each
				-- path records a `restore` closure so detach can hand the game's own render connection back
				-- instead of leaving it neutralized across a re-exec.
				local restore = nil
				if type(object.Disable) == "function" and pcall(object.Disable, object) then
					restore = function()
						if type(object.Enable) == "function" then
							object:Enable()
						else
							object.Enabled = true
						end
					end
				end
				if not restore and pcall(function()
					object.Enabled = false
				end) and object.Enabled == false then
					restore = function()
						object.Enabled = true
					end
				end
				if not restore and type(object.Disconnect) == "function" and pcall(object.Disconnect, object) then
					restore = function()
						game:GetService("RunService").RenderStepped:Connect(func)
					end
				end
				if not restore then
					last_replication_func = nil
					return retry(apply)
				end

				replicationRestores[#replicationRestores + 1] = restore
				rep_func = func
				break
			end

			if not rep_func then
				-- Replication connection not present yet (early join); retry.
				return retry(apply)
			end

			-- Re-drive at 10Hz. Invoke rep_func directly (null-safe) rather than conn:Fire() to avoid
			-- the macsploit SIGSEGV, wrapped in pcall so a defunct connection degrades to a skipped frame.
			local last_update = tick()
			optimizeGameMaid["ReplicationRender"] = game:GetService("RunService").RenderStepped:Connect(function()
				local delta = tick() - last_update

				if not Configuration.expectToggleValue("OptimizeGame") then
					last_update = tick()
					return pcall(rep_func, delta)
				end

				if delta < 1 / 10 then
					return
				end
				last_update = tick()

				return pcall(rep_func, delta)
			end)
		end

		apply()
	end

	function OptimizeGame.init()
		if initialized then
			return
		end
		initialized = true
		alive = true

		-- Gate the render-connection manipulation on the toggle. setupSeaClient / setupReplication use
		-- getconnections to neutralize the game's OWN render connections and re-drive the game's render
		-- functions each frame for higher FPS; only run them when OptimizeGame is enabled.
		--
		-- setupWorldClient is DELIBERATELY NOT CALLED. It re-drove Deepwoken's WorldClient PreRender function
		-- from our own main-VM PreRender connection; WorldClient runs in the game's parallel Actor render
		-- phase, so calling its function from our serial connection ran parallel-context Lua in the wrong
		-- phase -- the illegal cross-phase op the engine Kernel-panics on, on the RENDER thread
		-- (RBXCRASH: FatalRuntimeError (RSL - panic: ...Kernel)), randomly ~40 min in, independent of every
		-- other toggle. This is EXACTLY what Project Rain does: PR's optimize_game defines opti_world_client
		-- but its enable() only ever spawns opti_sea + opti_clouds and never opti_world_client -- the same one
		-- it abandoned. setupWorldClient stays defined below (like PR's dead opti_world_client) but unused.
		if Configuration.expectToggleValue("OptimizeGame") then
			task.spawn(setupSeaClient)
			task.spawn(setupReplication)
		end

		local descendantAddedSignal = Signal.new(game.DescendantAdded)
		optimizeGameMaid:add(descendantAddedSignal:connect("OptimizeGame_DescendantAdded", function(obj)
			if ranVisuals then
				task.defer(pcall, downgradeObject, obj)
			end
			if lowTexturesEnabled and obj:IsDescendantOf(workspace) then
				queueLowTexture(obj, lowTextureGeneration)
			end
			task.defer(registerDistantPart, obj)
			task.defer(registerTreeLeafObject, obj)
		end))

		if not LPH_OBFUSCATED or shared.Luma.verbose then
			Logger.warn("OptimizeGame initialized.")
		end
	end

	function OptimizeGame.detach()
		alive = false
		optimizeGameMaid:clean()

		for _, restore in ipairs(replicationRestores) do
			pcall(restore)
		end
		table.clear(replicationRestores)

		if seaHookedFn and seaOldFn then
			pcall(hookfunction, seaHookedFn, seaOldFn)
		end
		seaHookedFn = nil
		seaOldFn = nil

		updateLowGraphics(false)
		OptimizeGame.setLowTextures(false)
		OptimizeGame.setDistantPartCulling(false)
		OptimizeGame.setTreeLeafCulling(false)
		initialized = false
		ranVisuals = false
		Logger.warn("OptimizeGame detached.")
	end

	return OptimizeGame
end)()

end)
__bundle_register("Features/Automation/AutoProg", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto Prog: PR's auto progression, luma-native. Ties the Auto Builder (invest attribute points +
-- pick talent/mantra cards toward the pre/post spread) together with a farm (Auto Ferryman or Auto
-- Saramed) that earns the points, with a small state machine:
--
--   DOING_PRESHRINE  -- farm + build the pre spread; when the pre attributes are met, KICK to shrine.
--   DOING_POSTSHRINE -- farm + build the post spread; when the final attributes are met, KICK (done).
--
-- No persistence: after the kick, rejoin, re-execute luma, and press "Start Postshrine" (or "Start
-- Preshrine") to continue. The in-progress build + farm resume across the farm's own server hops via
-- their own MemStorage state.
--
-- Omits PR's Trial of One / Brutus fortitude / depths escape / rejoin-slot machinery (PR-only infra).

---@module Features.Automation.AutoBuilder
local AutoBuilder = require("Features/Automation/AutoBuilder")

---@module Features.Automation.AutoFerryman
local AutoFerryman = require("Features/Automation/AutoFerryman")

---@module Features.Automation.AutoSaramed
local AutoSaramed = require("Features/Automation/AutoSaramed")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Game.InputClient
local InputClient = require("Game/InputClient")

local players = game:GetService("Players")
local runService = game:GetService("RunService")

local AutoProg = {}

local CHECK_INTERVAL = 1.0
local MANTRA_INTERVAL = 1.5
local MANTRA_AIM_DURATION = 1.0
local MANTRA_AIM_BIND_NAME = "AutoProg_MantraAim"

-- In-memory only: "NULL" | "DOING_PRESHRINE" | "DOING_POSTSHRINE".
local state = "NULL"

local progMaid = Maid.new()
local lastCheck = 0
local lastMantraUse = 0
local nextMantraIndex = 1

local function farmMethod()
	return Configuration.expectOptionValue("AutoProgFarmMethod") or "Ferryman"
end

local function startFarm()
	-- Each farm self-guards on location (teleports/hops if we're not there) and is idempotent.
	local distance = Configuration.expectOptionValue("AutoProgAttachDistance")
	if farmMethod() == "Saramed" then
		AutoSaramed.attachDistanceOverride = distance
		AutoFerryman.attachDistanceOverride = nil
		AutoSaramed.start()
	else
		AutoFerryman.attachDistanceOverride = distance
		AutoSaramed.attachDistanceOverride = nil
		AutoFerryman.start()
	end
end

local function stopFarms()
	pcall(runService.UnbindFromRenderStep, runService, MANTRA_AIM_BIND_NAME)
	pcall(AutoFerryman.stop)
	pcall(AutoSaramed.stop)
	AutoFerryman.attachDistanceOverride = nil
	AutoSaramed.attachDistanceOverride = nil
end

function AutoProg.setAttachDistance(distance)
	if not AutoProg.isRunning() then
		return
	end

	distance = math.clamp(tonumber(distance) or 12, 1, 30)
	if farmMethod() == "Saramed" then
		AutoSaramed.attachDistanceOverride = distance
	else
		AutoFerryman.attachDistanceOverride = distance
	end
end

local function aimAtTarget(target)
	local targetRoot = target and target:FindFirstChild("HumanoidRootPart")
	local camera = workspace.CurrentCamera
	if not targetRoot or not camera then
		return false
	end

	pcall(runService.UnbindFromRenderStep, runService, MANTRA_AIM_BIND_NAME)
	local function updateAim()
		local currentCamera = workspace.CurrentCamera
		local currentRoot = target.Parent and target:FindFirstChild("HumanoidRootPart")
		if not currentCamera or not currentRoot then
			pcall(runService.UnbindFromRenderStep, runService, MANTRA_AIM_BIND_NAME)
			return
		end
		currentCamera.CFrame = CFrame.lookAt(currentCamera.CFrame.Position, currentRoot.Position)
	end

	updateAim()
	runService:BindToRenderStep(
		MANTRA_AIM_BIND_NAME,
		Enum.RenderPriority.Camera.Value + 1,
		updateAim
	)
	task.delay(MANTRA_AIM_DURATION, function()
		pcall(runService.UnbindFromRenderStep, runService, MANTRA_AIM_BIND_NAME)
	end)
	return true
end

local function useAttunementMantra()
	if not Configuration.expectToggleValue("AutoProgUseAttunementMantras")
		or os.clock() - lastMantraUse < MANTRA_INTERVAL then
		return
	end

	local excludedMantras = Configuration.expectOptionValue("AutoProgExcludedMantras") or {}
	local player = players.LocalPlayer
	local backpack = player and player:FindFirstChildOfClass("Backpack")
	local character = player and player.Character
	if not backpack then
		return
	end

	local candidates = {}
	local function collect(container)
		if not container then return end
		for _, tool in ipairs(container:GetChildren()) do
			if not tool:IsA("Tool") or not tool.Name:find("Mantra:", 1, true)
				or tool.Name:find("RecalledMantra:", 1, true) then
				continue
			end

			local defaultName = tool:GetAttribute("DefaultName")
			local filterName = type(defaultName) == "string" and defaultName or tool.Name
			if excludedMantras[filterName] or excludedMantras[tool.Name] then
				continue
			end
			table.insert(candidates, tool)
		end
	end
	collect(backpack)
	collect(character)
	if #candidates == 0 then
		return
	end

	if nextMantraIndex > #candidates then
		nextMantraIndex = 1
	end
	local tool = candidates[nextMantraIndex]
	nextMantraIndex = nextMantraIndex % #candidates + 1
	if tool.Enabled == false then
		return
	end

	local target
	if farmMethod() == "Saramed" then
		target = AutoSaramed.getCombatTarget()
	else
		target = AutoFerryman.getCombatTarget()
	end
	if not target or not aimAtTarget(target) then
		return
	end

	lastMantraUse = os.clock()
	InputClient.amantra(tool)
end

---Aim the builder at a spread, start building (invest + pick), and run the farm.
---@param phase "pre"|"post"
local function runPhase(phase)
	AutoBuilder.setTarget(phase)
	AutoBuilder.startPicking()
	startFarm()
end

---Stop everything and kick with a message.
---@param message string
local function endRun(message)
	state = "NULL"
	AutoBuilder.stopPicking()
	stopFarms()

	pcall(function()
		players.LocalPlayer:Kick(message)
	end)
end

---Start a phase from the UI.
---@param phase "pre"|"post"
---@return boolean
function AutoProg.start(phase)
	if phase ~= "pre" and phase ~= "post" then
		return false
	end

	if not AutoBuilder.current then
		Logger.notify("Auto Prog: load a build first.")
		return false
	end

	state = phase == "post" and "DOING_POSTSHRINE" or "DOING_PRESHRINE"
	runPhase(phase)

	Logger.notify(
		string.format(
			"Auto Prog: %s started (farming %s).",
			phase == "post" and "postshrine" or "preshrine",
			farmMethod()
		)
	)

	return true
end

---@return boolean
function AutoProg.startPreshrine()
	return AutoProg.start("pre")
end

---@return boolean
function AutoProg.startPostshrine()
	return AutoProg.start("post")
end

function AutoProg.stop()
	state = "NULL"
	pcall(runService.UnbindFromRenderStep, runService, MANTRA_AIM_BIND_NAME)
	AutoBuilder.stopPicking()
	stopFarms()
	Logger.notify("Auto Prog: stopped.")
end

---@return boolean
function AutoProg.isRunning()
	return state == "DOING_PRESHRINE" or state == "DOING_POSTSHRINE"
end

-- The state-machine watcher: kicks to shrine when preshrine is done, and kicks when the build is
-- finished. Armed once at init.
function AutoProg.init()
	local renderStepped = Signal.new(runService.RenderStepped)

	progMaid:add(renderStepped:connect("AutoProg_Watch", function()
		if os.clock() - lastCheck < CHECK_INTERVAL then
			return
		end
		lastCheck = os.clock()

		if AutoProg.isRunning() then
			useAttunementMantra()
		end

		if state == "DOING_PRESHRINE" then
			if AutoBuilder.shrineReady() then
				endRun(
					'Auto Prog: preshrine done. shrine, then rejoin and press "Start Postshrine".'
				)
			end
		elseif state == "DOING_POSTSHRINE" then
			if AutoBuilder.finished() then
				endRun("Auto Prog: build finished. :)")
			end
		end
	end))

	if not LPH_OBFUSCATED or (shared.Luma and shared.Luma.verbose) then
		Logger.warn("Auto Prog initialized.")
	end
end

function AutoProg.detach()
	pcall(runService.UnbindFromRenderStep, runService, MANTRA_AIM_BIND_NAME)
	progMaid:clean()
end

return AutoProg

end)
__bundle_register("Features/Automation/FishFarm", function(require, _LOADED, __bundle_register, __bundle_modules)
local FishFarm = {}

---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

local players = game:GetService("Players")
local runService = game:GetService("RunService")

local renderStepped = Signal.new(runService.RenderStepped)

local fishFarmMaid = Maid.new()

local fishFarmTimestamp = os.clock()

local wasActivated = false

local updateFishFarm = LPH_NO_VIRTUALIZE(function()
	if os.clock() - fishFarmTimestamp < 0.1 then
		return
	end

	fishFarmTimestamp = os.clock()

	AntiAFK.stop("FishFarm")

	if not Configuration.expectToggleValue("AutoFish") then
		return
	end

	AntiAFK.start("FishFarm")

	local localPlayer = players.LocalPlayer
	local localPlayerCharacter = localPlayer.Character
	if not localPlayerCharacter then
		return
	end

	local humanoid = localPlayerCharacter:FindFirstChild("Humanoid")
	if not humanoid then
		return
	end

	local backpack = localPlayer:FindFirstChild("Backpack")
	if not backpack then
		return
	end

	local characterRod = localPlayerCharacter:FindFirstChild("Fishing Rod")
	local backpackRod = backpack:FindFirstChild("Fishing Rod")

	if not characterRod then
		return backpackRod and humanoid:EquipTool(backpackRod)
	end

	local handle = characterRod:FindFirstChild("Handle")
	local rod = handle and handle:FindFirstChild("Rod")
	local bobby = rod and rod:FindFirstChild("bobby")
	if not bobby then
		return
	end

	local addBait = characterRod:FindFirstChild("AddBait")
	if not addBait then
		return
	end

	---@todo: add fish meat lol
	local baitTable = {
		"Plumfruit",
		"Pomar",
		"Gobletto",
		"Squid",
		"Dentifilo",
		"Seaweed Bundle",
		"Urchin",
		"Browncap",
		"Chum",
		"Calabash",
		"Pufferfish",
		"Redd",
	}

	for _, baitName in next, baitTable do
		local bait = backpack:FindFirstChild(baitName)
		if not bait then
			continue
		end

		if bobby:FindFirstChild("bait") then
			break
		end

		return addBait:FireServer(bait)
	end

	local hook = bobby:FindFirstChild("hook")
	if not hook then
		return
	end

	if hook.Transparency ~= 1.0 then
		wasActivated = not wasActivated
		return wasActivated and characterRod:Deactivate() or characterRod:Activate()
	end

	local inputUpdate = characterRod:FindFirstChild("InputUpdate")
	if not inputUpdate then
		return
	end

	local playerGui = localPlayer:FindFirstChild("PlayerGui")
	if not playerGui then
		return
	end

	local fishingGui = playerGui:FindFirstChild("FishingGui")
	if not fishingGui or not fishingGui.Enabled then
		return
	end

	local mainFrame = fishingGui:FindFirstChild("MainFrame")
	if not mainFrame then
		return
	end

	local holdA = mainFrame:FindFirstChild("HoldA")
	local holdS = mainFrame:FindFirstChild("HoldS")
	local holdD = mainFrame:FindFirstChild("HoldD")
	if not holdA or not holdS or not holdD then
		return
	end

	inputUpdate:FireServer({
		a = holdA.Visible,
		s = holdS.Visible,
		d = holdD.Visible,
	})
end)

function FishFarm.init()
	fishFarmMaid:add(renderStepped:connect("FishFarm_RenderStepped", updateFishFarm))

	if not LPH_OBFUSCATED or shared.Luma.verbose then
		Logger.warn("Fish Farm initialized.")
	end
end

function FishFarm.detach()
	fishFarmMaid:clean()

	Logger.warn("Fish Farm detached.")
end

return FishFarm

end)
__bundle_register("Features/Game/AnimationVisualizer", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	---@note: This code is UI code. It is ugly on purpose and lazily made.
	local AnimationVisualizer = {}

