	frameForwards.TextColor3 = Color3.new()
	frameForwards.Text = ""
	frameForwards.Position = UDim2.new(0.323, 99, 0.835, -2)
	frameForwards.BackgroundColor3 = Library.MainColor
	frameForwards.BorderColor3 = Color3.new()
	frameForwards.TextSize = 14
	frameForwards.Size = UDim2.new(0, 69, 0, 20)
	frameForwards.Parent = inner

	local iconThree = Instance.new("ImageLabel")
	iconThree.Name = "Icon"
	iconThree.ScaleType = Enum.ScaleType.Crop
	iconThree.BorderColor3 = Color3.new()
	iconThree.BackgroundColor3 = Library.FontColor
	iconThree.Image = "rbxassetid://10734961809"
	iconThree.BackgroundTransparency = 1
	iconThree.Position = UDim2.new(0.5, -8, 0.5, -8)
	iconThree.SizeConstraint = Enum.SizeConstraint.RelativeXX
	iconThree.BorderSizePixel = 0
	iconThree.Size = UDim2.new(0, 16, 0, 16)
	iconThree.Parent = frameForwards

	local animationTextbox = Instance.new("TextBox")
	animationTextbox.Name = "AnimationTextbox"
	animationTextbox.CursorPosition = -1
	animationTextbox.TextColor3 = Library.FontColor
	animationTextbox.Text = "rbxassetid://0"
	animationTextbox.BackgroundColor3 = Library.MainColor
	animationTextbox.Position = UDim2.new(0.323, -78, 0.835, -24)
	animationTextbox.BorderColor3 = Color3.new()
	animationTextbox.FontFace = Font.new("rbxasset://fonts/families/RobotoMono.json")
	animationTextbox.TextSize = 14
	animationTextbox.Size = UDim2.new(0, 246, 0, 15)
	animationTextbox.Parent = inner

	local currentPlaybackData = nil
	local currentTrack = nil
	local isPaused = false
	local timeElapsed = 0.0

	---@param value number
	---@param min number
	---@param max number
	---@param minSize number
	---@param maxSize number
	local function mapSliderValue(value, min, max, minSize, maxSize)
		return (1 - ((value - min) / (max - min))) * minSize + ((value - min) / (max - min)) * maxSize
	end

	---@param enter boolean
	---@param _ InputObject
	local function onIdFocusLost(enter, _)
		if not enter then
			return
		end

		currentTrack = nil
		currentPlaybackData = nil

		---@type PlaybackData
		local playbackData = Defense.agpd(animationTextbox.Text)
		if not playbackData then
			return AnimationVisualizer.message("No Playback Data Found")
		end

		for _, descendant in next, viewportFrame:GetDescendants() do
			if descendant.ClassName ~= "Model" then
				continue
			end

			descendant:Destroy()
		end

		local entity = playbackData.entity:Clone()
		entity.Parent = worldModel
		entity:PivotTo(CFrame.new(0, 0, 0))

		if not entity.PrimaryPart then
			return AnimationVisualizer.message("No Primary Part Found")
		end

		local _, bbs = entity:GetBoundingBox()
		camera.CFrame =
			CFrame.lookAt(entity.PrimaryPart.Position - Vector3.new(0, 0, bbs.Magnitude), entity.PrimaryPart.Position)

		local animator = entity:FindFirstChildWhichIsA("Animator", true)
		if not animator then
			return AnimationVisualizer.message("No Animator Found")
		end

		for _, track in next, animator:GetPlayingAnimationTracks() do
			track:Stop()
		end

		local animation = Instance.new("Animation")
		animation.AnimationId = animationTextbox.Text

		currentPlaybackData = playbackData
		currentTrack = animator:LoadAnimation(animation)

		currentTrack:Play(0.0, 100, 0.0)
		currentTrack.Priority = Enum.AnimationPriority.Action
		currentTrack.Looped = true
		visualizerMaid:mark(currentTrack.DidLoop:Connect(function()
			timeElapsed = 0.0
		end))

		timeElapsed = 0.0

		viewportFrame.Visible = true
		noViewportFrame.Visible = false
	end

	---@param timePosition number
	---@param animationLength number
	---@return number?
	local function getTimeElapsedFromTp(timePosition, animationLength)
		if not currentPlaybackData then
			return nil
		end

		if timePosition <= 0 then
			return 0.0
		end

		local currentPos = 0
		local elapsed = 0
		local dt = 0.01
		local iterations = 0

		while currentPos < timePosition do
			local speed = currentPlaybackData:last(elapsed) or 1
			local stepSize = speed * dt

			iterations = iterations + 1

			---@note: We can calculate how many iterations this should likely take based on the length (e.g 4 seconds) of the animation.
			if iterations >= math.max(((animationLength * 100) * 10), 1000) then
				break
			end

			if currentPos + stepSize > timePosition then
				local remainingTime = (timePosition - currentPos) / speed
				elapsed = elapsed + remainingTime
				break
			end

			currentPos = currentPos + stepSize
			elapsed = elapsed + dt
		end

		return elapsed
	end

	---@param delta number
	local function onPlaybackLoop(delta)
		if not enabled then
			return
		end

		iconTwo.Image = isPaused and "rbxassetid://10734923549" or "rbxassetid://10734919336"

		local mhs = sliderOuter.AbsoluteSize.X
		local hs = currentTrack and mapSliderValue(currentTrack.TimePosition, 0.0, currentTrack.Length, 0, mhs) or 0.0

		sliderText.Text = (currentTrack and currentPlaybackData)
				and string.format(
					"%.3f/%.3f (%ims)",
					currentTrack.TimePosition,
					currentTrack.Length,
					math.round((getTimeElapsedFromTp(currentTrack.TimePosition, currentTrack.Length) or 0.0) * 1000)
				)
			or "0.000 / ??? (???ms)"

		sliderFill.Visible = not (hs == 0)
		sliderFill.Size = UDim2.new(0, math.max(math.ceil(hs), 1), 1, 0)
		hideBorderRight.Visible = not (hs == mhs or hs == 0)

		speedText.Text = currentTrack and string.format("Speed (%.2f)", currentTrack.Speed) or "Speed (???)"

		if currentTrack and isPaused then
			speedText.Text = string.format(
				"Speed (%.2f)",
				currentPlaybackData:last(getTimeElapsedFromTp(currentTrack.TimePosition, currentTrack.Length) or 0.0)
					or 0.0
			)
		end

		if not currentTrack or not currentPlaybackData then
			return
		end

		if isPaused then
			return currentTrack:AdjustSpeed(0.0)
		end

		timeElapsed = timeElapsed + delta

		currentTrack:AdjustSpeed(currentPlaybackData:last(timeElapsed) or 0.0)
	end

	local function togglePlayStop()
		if not currentTrack then
			return
		end

		if not currentTrack.IsPlaying then
			return
		end

		isPaused = not isPaused
	end

	local function onFrameBackwards()
		if not currentTrack then
			return
		end

		currentTrack.TimePosition = math.max(currentTrack.TimePosition - 0.01, 0)
	end

	local function onFrameForwards()
		if not currentTrack then
			return
		end

		currentTrack.TimePosition = math.min(currentTrack.TimePosition + 0.01, currentTrack.Length)
	end

	---@param input InputObject
	---@param gameProcessed boolean
	local function onSliderInputBegan(input, gameProcessed)
		if gameProcessed then
			return
		end

		if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
			return
		end

		while enabled and userInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
			if not currentTrack then
				return
			end

			isPaused = true

			local mouse = players.LocalPlayer:GetMouse()
			local sliderOuterSize = sliderOuter.AbsoluteSize.X
			local mouseX = math.clamp(mouse.X - sliderOuter.AbsolutePosition.X, 0, sliderOuterSize)
			local newTimePosition = mapSliderValue(mouseX, 0, sliderOuterSize, 0, currentTrack.Length)

			currentTrack.TimePosition = newTimePosition

			runService.PreRender:Wait()
		end

		timeElapsed = getTimeElapsedFromTp(currentTrack.TimePosition, currentTrack.Length) or 0.0
	end

	---@param input InputObject
	---@param gameProcessed boolean
	local function outerFrameInputBegan(input, gameProcessed)
		if gameProcessed then
			return
		end

		if input.KeyCode == Enum.KeyCode.Space then
			return togglePlayStop()
		end

		if input.KeyCode == Enum.KeyCode.Right then
			return onFrameForwards()
		end

		if input.KeyCode == Enum.KeyCode.Left then
			return onFrameBackwards()
		end
	end

	---@param state boolean
	function AnimationVisualizer.visible(state)
		enabled = state
		if win then
			win:SetVisible(state)
		end
	end

	---@param message string
	function AnimationVisualizer.message(message)
		viewportFrame.Visible = false
		noViewportFrame.Visible = true
		textLabel.Text = message
	end

	function AnimationVisualizer.init()
		win = Library:CreateFloatingWindow({
			Name = "LumaAnimationVisualizer",
			Title = "Animation Visualizer",
			Size = UDim2.fromOffset(260, 340),
			Position = UDim2.new(0.27, 0, 0.216, 0),
		})
		inner.Parent = win.Body
		-- Closing the window just hides it; the playback loop stays wired so reopening resumes instantly.
		win:OnClose(function()
			enabled = false
		end)
		win:SetVisible(enabled)

		Library:AddToRegistry(hideBorderRight, {
			BackgroundColor3 = "AccentColor",
		}, true)

		Library:AddToRegistry(sliderFill, {
			BackgroundColor3 = "AccentColor",
		}, true)

		Library:AddToRegistry(playStop, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(animationTextbox, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
			TextColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(icon, {
			ImageColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(iconTwo, {
			ImageColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(iconThree, {
			ImageColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(textLabel, {
			TextColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(speedText, {
			TextColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(noViewportFrame, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(frameBackwards, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(frameForwards, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(viewportFrame, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(sliderOuter, {
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(sliderInner, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(sliderFill, {
			BackgroundColor3 = "AccentColor",
			BorderColor3 = "AccentColorDark",
		}, true)

		Library:AddToRegistry(hideBorderRight, {
			BackgroundColor3 = "AccentColor",
		}, true)

		Library:AddToRegistry(sliderText, {
			TextColor3 = "FontColor",
		}, true)

		viewportFrame.CurrentCamera = camera

		AnimationVisualizer.message("Waiting For Animation ID")

		local idFocusLost = Signal.new(animationTextbox.FocusLost)
		local preRender = Signal.new(runService.PreRender)
		local playStopClicked = Signal.new(playStop.MouseButton1Click)
		local outerInputBegan = Signal.new(win.Frame.InputBegan)
		local frameBackwardsClick = Signal.new(frameBackwards.MouseButton1Click)
		local frameForwardsClick = Signal.new(frameForwards.MouseButton1Click)
		local sliderInputBegan = Signal.new(sliderOuter.InputBegan)

		visualizerMaid:add(sliderInputBegan:connect("AnimationVisualizer_SliderInputBegan", onSliderInputBegan))
		visualizerMaid:add(frameForwardsClick:connect("AnimationVisualizer_FrameForwardsClick", onFrameForwards))
		visualizerMaid:add(frameBackwardsClick:connect("AnimationVisualizer_FrameBackwardsClick", onFrameBackwards))
		visualizerMaid:add(outerInputBegan:connect("AnimationVisualizer_OuterInputBegan", outerFrameInputBegan))
		visualizerMaid:add(playStopClicked:connect("AnimationVisualizer_PlayStopClicked", togglePlayStop))
		visualizerMaid:add(preRender:connect("AnimationVisualizer_PlaybackLoop", onPlaybackLoop))
		visualizerMaid:add(idFocusLost:connect("AnimationVisualizer_IdFocusLost", onIdFocusLost))

		Library.AnimationVisualizerFrame = win.Frame
	end

	function AnimationVisualizer.detach()
		visualizerMaid:clean()
		enabled = false
		if win then
			win:Hide()
		end
	end

	return AnimationVisualizer
end)()

end)
__bundle_register("Features/Combat/ExpApBreaker", function(require, _LOADED, __bundle_register, __bundle_modules)

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Game.Timings.SaveManager
local TimingStore = require("Game/Timings/SaveManager")

local RunService = game:GetService("RunService")
local Players = game:GetService("Players")

local PRIORITY_ORDER = {
	Enum.AnimationPriority.Core,
	Enum.AnimationPriority.Idle,
	Enum.AnimationPriority.Movement,
	Enum.AnimationPriority.Action,
	Enum.AnimationPriority.Action2,
	Enum.AnimationPriority.Action3,
	Enum.AnimationPriority.Action4,
}
local PRIORITY_INDEX = {}
for index, priority in ipairs(PRIORITY_ORDER) do
	PRIORITY_INDEX[priority] = index
end
local ACTION_INDEX = PRIORITY_INDEX[Enum.AnimationPriority.Action]
local BOOST_OFFSET = PRIORITY_INDEX[Enum.AnimationPriority.Action4] - PRIORITY_INDEX[Enum.AnimationPriority.Action]
local ACTION3_INDEX = PRIORITY_INDEX[Enum.AnimationPriority.Action3]
local ACTION4_INDEX = PRIORITY_INDEX[Enum.AnimationPriority.Action4]

local function boostPriority(priority)
	local index = PRIORITY_INDEX[priority] or ACTION4_INDEX
	return PRIORITY_ORDER[math.clamp(index + BOOST_OFFSET, ACTION3_INDEX, ACTION4_INDEX)]
end

local loadedTrackRegistry = setmetatable({}, { __mode = "k" })

local ApBreaker = { force = false }

local function getOption(name, fallback)
	local value = Configuration.expectOptionValue(name)
	if value == nil then
		return fallback
	end
	return value
end

local ANIM_LIMIT = 60
local function underAnimationLimit(animator)
	if Configuration.expectToggleValue("ApBreakerDontHitAnimLimit") == false then
		return true
	end
	if not animator then
		return true
	end
	local ok, playing = pcall(function() return animator:GetPlayingAnimationTracks() end)
	if not ok or type(playing) ~= "table" then
		return true
	end
	return #playing < ANIM_LIMIT
end

local FALLBACK_AGGRESSIVE2_ANIMATION_IDS = {
	"rbxassetid://9726608174",
	"rbxassetid://111647546998749",
	"rbxassetid://5064195992",
	"rbxassetid://6607519294",
	"rbxassetid://7600160919",
}
local AGGRESSIVE2_MOVE_TYPES = { M1 = true, Mantra = true, Critical = true }
local AGGRESSIVE2_PRIORITY = Enum.AnimationPriority.Action

local function collectKnownAttackAnimationIds()
	local ids, seen = {}, {}
	pcall(function()
		local list = TimingStore.as:list()
		for _, entry in ipairs(list) do
			if AGGRESSIVE2_MOVE_TYPES[entry.tag] then
				local id = entry:id()
				if type(id) == "string" and id:match("%d") and not seen[id] then
					seen[id] = true
					ids[#ids + 1] = id
				end
			end
		end
	end)
	return ids
end

local ULTIMATE_IDLE_COVER_ID = "rbxassetid://180435571"
local ULTIMATE_IDLE_FADE = 0.2
local ULTIMATE_COVER_REPLAY = 0.3

local function startUltimateMode(character)
	if not character then return function() end end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return function() end end
	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then return function() end end

	local trackPool = {}
	local trackPoolSet = {}
	local poolSize = 0

	local stopped = false

	local function loadDecoyTracks(idList, spread)
		for _, track in next, trackPool do
			pcall(function() track:Stop(0); track:Destroy() end)
		end
		trackPool = {}
		trackPoolSet = {}
		poolSize = 0
		if type(idList) ~= "table" or #idList == 0 then return end

		local targetPoolSize = math.min(200, math.max(#idList, 20))
		local cursor, attempts, maxAttempts = 0, 0, targetPoolSize + #idList + 8
		while #trackPool < targetPoolSize and attempts < maxAttempts and not stopped do
			attempts = attempts + 1
			cursor = cursor % #idList + 1
			local id = idList[cursor]
			if not string.find(id, "://", 1, true) then
				id = "rbxassetid://" .. id
			end
			local animation = Instance.new("Animation")
			animation.AnimationId = id
			local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
			if ok and track then
				loadedTrackRegistry[track] = true
				track.Looped = false
				trackPool[#trackPool + 1] = track
				trackPoolSet[track] = true
			end

			if spread and attempts % 20 == 0 then
				task.wait()
			end
		end
		poolSize = #trackPool

		if stopped then
			for _, track in next, trackPool do
				pcall(function() track:Stop(0); track:Destroy() end)
			end
		end
	end

	local knownIds = collectKnownAttackAnimationIds()
	local usingFallbackIds = false
	if #knownIds == 0 then
		knownIds = FALLBACK_AGGRESSIVE2_ANIMATION_IDS
		usingFallbackIds = true
	end
	loadDecoyTracks(knownIds)

	local maskTrack = nil
	local maskSet = {}
	do
		local animation = Instance.new("Animation")
		animation.AnimationId = ULTIMATE_IDLE_COVER_ID
		local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
		if ok and track then
			loadedTrackRegistry[track] = true
			track.Looped = true
			maskTrack = track
			maskSet[track] = true
		end
	end
	local lastMaskPlay = 0

	local running = true
	local aggressive2Accumulator = 0
	local poolCursor = 0
	local framesSinceCheck = 0
	local fallbackRefreshTimer = 0
	local lastPlayTime = os.clock()
	local originalPriorities = setmetatable({}, { __mode = "k" })
	local function detectRealAttack(maskVisualEnabled)
		local realAttackPlaying = false
		for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
			if trackPoolSet[track] then
				if track.Priority ~= AGGRESSIVE2_PRIORITY then
					pcall(function() track.Priority = AGGRESSIVE2_PRIORITY end)
				end
			elseif not maskSet[track] and not loadedTrackRegistry[track] and track.Animation and track.Animation.AnimationId then
				local savedPriority = originalPriorities[track]
				if savedPriority == nil then
					savedPriority = track.Priority
					originalPriorities[track] = savedPriority
				end
				local boosted = boostPriority(savedPriority)
				pcall(function() track.Priority = boosted end)
				if (PRIORITY_INDEX[boosted] or 0) > ACTION_INDEX and track.WeightCurrent > 0.5 then
					realAttackPlaying = true
				end
			end
		end
		if maskTrack and maskVisualEnabled then
			realAttackPlaying = true
		end
		return realAttackPlaying
	end

	local function restoreForeignPriorities()
		for track, priority in pairs(originalPriorities) do
			pcall(function() track.Priority = priority end)
		end
		originalPriorities = setmetatable({}, { __mode = "k" })
	end

	local renderSteppedConn
	renderSteppedConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then return end
		if not character.Parent then
			running = false
			return
		end

		if usingFallbackIds then
			fallbackRefreshTimer = fallbackRefreshTimer + deltaTime
			if fallbackRefreshTimer >= 1.5 then
				fallbackRefreshTimer = 0
				local refreshed = collectKnownAttackAnimationIds()
				if #refreshed > 0 then
					usingFallbackIds = false
					task.spawn(loadDecoyTracks, refreshed, true)
				end
			end
		end

		if poolSize == 0 then return end

		local maskVisualEnabled = Configuration.expectToggleValue("ExpApBreakerMaskVisual") ~= false

		local shouldRunAggressive2 = true
		if maskVisualEnabled then
			shouldRunAggressive2 = detectRealAttack(maskVisualEnabled)
		elseif next(originalPriorities) ~= nil then
			restoreForeignPriorities()
		end

		if maskTrack then
			if maskVisualEnabled then
				local now = os.clock()
				if not maskTrack.IsPlaying then
					pcall(function()
						maskTrack.Priority = Enum.AnimationPriority.Action2
						maskTrack:Play(0, 1, 1)
					end)
					lastMaskPlay = now
				elseif now - lastMaskPlay >= ULTIMATE_COVER_REPLAY then
					lastMaskPlay = now
					pcall(function()
						local position = maskTrack.TimePosition
						maskTrack:Stop(0)
						maskTrack.Priority = Enum.AnimationPriority.Action2
						maskTrack:Play(0, 1, 1)
						maskTrack.TimePosition = position
					end)
				end
			elseif maskTrack.IsPlaying then
				pcall(function() maskTrack:Stop(ULTIMATE_IDLE_FADE) end)
			end
		end

		if maskVisualEnabled and not shouldRunAggressive2 then
			for _, track in next, trackPool do
				if track.IsPlaying then
					pcall(function() track:Stop(0) end)
				end
			end
			framesSinceCheck = 0
			aggressive2Accumulator = 0
			return
		end

		framesSinceCheck = framesSinceCheck + 1
		if maskVisualEnabled and framesSinceCheck < 3 then return end

		local intensity = getOption("ExpApBreakerAggressive2Intensity", 200)
		local interval = 1 / math.max(1, intensity)
		aggressive2Accumulator = math.min(aggressive2Accumulator + deltaTime, interval * 2)

		if not underAnimationLimit(animator) then
			return
		end

		local burstsThisFrame = 0
		while aggressive2Accumulator >= interval and burstsThisFrame < 50 do
			aggressive2Accumulator = aggressive2Accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			local chosenTrack = nil
			local fallbackZeroLenTrack = nil
			for _ = 1, poolSize do
				poolCursor = poolCursor % poolSize + 1
				local candidate = trackPool[poolCursor]
				if candidate and not candidate.IsPlaying then
					if candidate.Length > 0 then
						chosenTrack = candidate
						break
					elseif not fallbackZeroLenTrack then
						fallbackZeroLenTrack = candidate
					end
				end
			end
			if not chosenTrack and os.clock() - lastPlayTime > 8 then
				chosenTrack = fallbackZeroLenTrack
			end
			if chosenTrack then
				pcall(function()
					chosenTrack.Priority = AGGRESSIVE2_PRIORITY
					chosenTrack:Play(0.1, 1, 1)
				end)
				lastPlayTime = os.clock()
			end
		end
	end)

	return function()
		running = false
		stopped = true
		if renderSteppedConn then
			renderSteppedConn:Disconnect()
			renderSteppedConn = nil
		end
		restoreForeignPriorities()
		if maskTrack then
			pcall(function() maskTrack:Stop(0); maskTrack:Destroy() end)
			maskTrack = nil
		end
		for _, track in next, trackPool do
			pcall(function() track:Stop(0); track:Destroy() end)
		end
	end
end

local FADE_TIME_FLOOD_FADE = 99999
local FADE_TIME_FLOOD_PRIORITY = Enum.AnimationPriority.Action

local function startFadeTimeFloodMode(character)
	if not character then return function() end end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return function() end end
	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then return function() end end

	local trackPool = {}
	local function destroyPool()
		for _, track in next, trackPool do
			pcall(function() track:Stop(0); track:Destroy() end)
		end
		trackPool = {}
	end

	local function loadPool(idList)
		destroyPool()
		if type(idList) ~= "table" or #idList == 0 then return end
		local targetSize = math.min(200, math.max(#idList, 20))
		local cursor, attempts, maxAttempts = 0, 0, targetSize + #idList + 8
		while #trackPool < targetSize and attempts < maxAttempts do
			attempts = attempts + 1
			cursor = cursor % #idList + 1
			local id = idList[cursor]
			if not string.find(id, "://", 1, true) then
				id = "rbxassetid://" .. id
			end
			local animation = Instance.new("Animation")
			animation.AnimationId = id
			local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
			if ok and track then
				loadedTrackRegistry[track] = true
				track.Looped = false
				trackPool[#trackPool + 1] = track
			end
		end
	end

	local ids = collectKnownAttackAnimationIds()
	local usingFallback = false
	if #ids == 0 then
		ids = FALLBACK_AGGRESSIVE2_ANIMATION_IDS
		usingFallback = true
	end
	loadPool(ids)

	local running = true
	local accumulator = 0
	local poolCursor = 0
	local fallbackRefreshTimer = 0
	local renderConn
	renderConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then return end
		if not character.Parent then
			running = false
			return
		end

		if usingFallback then
			fallbackRefreshTimer = fallbackRefreshTimer + deltaTime
			if fallbackRefreshTimer >= 1.5 then
				fallbackRefreshTimer = 0
				local refreshed = collectKnownAttackAnimationIds()
				if #refreshed > 0 then
					loadPool(refreshed)
					usingFallback = false
				end
			end
		end

		local poolSize = #trackPool
		if poolSize == 0 then return end

		local intensity = getOption("ExpApBreakerAggressive2Intensity", 200)
		local interval = 1 / math.max(1, intensity)
		accumulator = math.min(accumulator + deltaTime, interval * 2)

		if not underAnimationLimit(animator) then
			return
		end

		local burstsThisFrame = 0
		while accumulator >= interval and burstsThisFrame < 50 do
			accumulator = accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			local chosen = nil
			for _ = 1, poolSize do
				poolCursor = poolCursor % poolSize + 1
				local candidate = trackPool[poolCursor]
				if candidate and not candidate.IsPlaying then
					chosen = candidate
					break
				end
			end
			if chosen then
				pcall(function()
					chosen.Priority = FADE_TIME_FLOOD_PRIORITY
					chosen:Play(FADE_TIME_FLOOD_FADE, 1, 1)
				end)
			end
		end
	end)

	return function()
		running = false
		if renderConn then
			pcall(function() renderConn:Disconnect() end)
			renderConn = nil
		end
		destroyPool()
	end
end

