-- ---- Blatant Flood tuning --------------------------------------------------
local FULL_BLATANT_POOL_TARGET = 150
local FULL_BLATANT_FADE_HIGH = 99999

-- All known animation ids (every tag), not just attack tags.
local function collectAllKnownAnimationIds()
	local ids, seen = {}, {}
	pcall(function()
		local list = TimingStore.as:list()
		for _, entry in ipairs(list) do
			local id = entry:id()
			if type(id) == "string" and id:match("%d") and not seen[id] then
				seen[id] = true
				ids[#ids + 1] = id
			end
		end
	end)
	return ids
end

local function numericAnimId(id)
	if type(id) ~= "string" then
		return nil
	end
	return id:match("id=(%d+)") or id:match("(%d+)%s*$") or id:match("(%d+)")
end

local function randomPriority()
	return PRIORITY_ORDER[math.random(1, #PRIORITY_ORDER)]
end
local function randomWeight()
	if math.random() < 0.5 then
		return math.random() * 0.15
	end
	return math.random() * 9.5 + 0.5
end
local function randomFade()
	if math.random() < 0.5 then
		return math.random() * 0.15
	end
	return FULL_BLATANT_FADE_HIGH
end
local function randomSpeed()
	if math.random() < 0.5 then
		return math.random() * 0.9 + 0.1
	end
	return math.random() * 24 + 1
end

-- ---- Blatant Flood ---------------------------------------------------------
-- Floods every known timing at a high rate with randomized properties AND blanks the animation id
-- of your real attacks to nothing -- so inside the storm the enemy's auto-parry can't even read
-- what you threw, let alone parry it. It does NOT stop your real attacks: they still land, just
-- with an empty (unresolvable) id. Ids are blanked the instant the attack plays (AnimationPlayed)
-- with a per-frame backstop.
local function startBlatantFloodMode(character)
	if not character then return function() end end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return function() end end
	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then return function() end end

	local trackPool = {}
	local function destroyPool()
		for _, track in next, trackPool do
			pcall(function() track:Stop(0); track:Destroy() end)
		end
		trackPool = {}
	end

	-- Numeric ids of the moves you actually throw (M1 / Mantra / Critical) -- these are the ones an
	-- enemy has timings for, so blanking exactly these is what defeats their parry.
	local attackIdSet = {}
	local function rebuildAttackIdSet()
		attackIdSet = {}
		for _, id in ipairs(collectKnownAttackAnimationIds()) do
			local n = numericAnimId(id)
			if n then
				attackIdSet[n] = true
			end
		end
	end

	-- Tracks whose id we've already blanked, so we don't touch them every frame.
	local obfuscated = setmetatable({}, { __mode = "k" })
	local function obfuscateRealAttack(track)
		if loadedTrackRegistry[track] or obfuscated[track] or not track.Animation then
			return
		end
		local n = numericAnimId(track.Animation.AnimationId)
		if n and attackIdSet[n] then
			obfuscated[track] = true
			-- Blank the id to nothing: the track keeps playing (your attack still lands) but the
			-- replicated id becomes empty, so the enemy can't resolve a timing for it.
			pcall(function()
				track.Animation.AnimationId = ""
			end)
		end
	end

	local function loadPool(idList)
		destroyPool()
		if type(idList) ~= "table" or #idList == 0 then return end
		local target = math.min(FULL_BLATANT_POOL_TARGET, math.max(#idList, 40))
		local cursor, attempts, maxAttempts = 0, 0, target + #idList + 16
		while #trackPool < target and attempts < maxAttempts do
			attempts = attempts + 1
			cursor = cursor % #idList + 1
			local id = idList[cursor]
			if not string.find(id, "://", 1, true) then
				id = "rbxassetid://" .. id
			end
			local animation = Instance.new("Animation")
			animation.AnimationId = id
			local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
			if ok and track then
				loadedTrackRegistry[track] = true
				track.Looped = false
				trackPool[#trackPool + 1] = track
			end
		end
	end

	local ids = collectAllKnownAnimationIds()
	local usingFallback = false
	if #ids == 0 then
		ids = FALLBACK_AGGRESSIVE2_ANIMATION_IDS
		usingFallback = true
	end
	loadPool(ids)
	rebuildAttackIdSet()

	local running = true
	local accumulator = 0
	local poolCursor = 0
	local fallbackRefreshTimer = 0

	-- Blank real attacks the instant they start (before the next frame can leak the id).
	local animPlayedConn = animator.AnimationPlayed:Connect(function(track)
		if running then
			obfuscateRealAttack(track)
		end
	end)

	local renderConn
	renderConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then return end
		if not character.Parent then
			running = false
			return
		end

		-- Per-frame backstop for any real attack the AnimationPlayed hook missed.
		for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
			obfuscateRealAttack(track)
		end

		if usingFallback then
			fallbackRefreshTimer = fallbackRefreshTimer + deltaTime
			if fallbackRefreshTimer >= 1.5 then
				fallbackRefreshTimer = 0
				local refreshed = collectAllKnownAnimationIds()
				if #refreshed > 0 then
					loadPool(refreshed)
					rebuildAttackIdSet()
					usingFallback = false
				end
			end
		end

		local poolSize = #trackPool
		if poolSize == 0 then return end

		-- Rate is user-tunable (default 60/s). Each Play() replicates to the server, so a very high
		-- rate saturates your uplink and spikes YOUR ping -- keep this modest; 40-80/s already buries
		-- the real swing in noise. Burst cap scales with rate so a low rate can't batch a huge frame.
		local rate = getOption("BlatantFloodRate", 60)
		rate = math.clamp(tonumber(rate) or 60, 1, 300)
		local burstCap = math.max(4, math.ceil(rate / 10))
		local interval = 1 / rate
		accumulator = math.min(accumulator + deltaTime, interval * burstCap)

		local burstsThisFrame = 0
		while accumulator >= interval and burstsThisFrame < burstCap do
			accumulator = accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			poolCursor = poolCursor % poolSize + 1
			local track = trackPool[poolCursor]
			if track then
				pcall(function()
					if track.IsPlaying then
						track:Stop(0)
					end
					track.Priority = randomPriority()
					track:Play(randomFade(), randomWeight(), randomSpeed())
				end)
			end
		end
	end)

	return function()
		running = false
		if animPlayedConn then
			pcall(function() animPlayedConn:Disconnect() end)
			animPlayedConn = nil
		end
		if renderConn then
			pcall(function() renderConn:Disconnect() end)
			renderConn = nil
		end
		destroyPool()
	end
end

-- Blatant Flood runs as its own standalone toggle, independent of the AP Breaker mode system.
local blatantFloodActive = false
local blatantFloodCleanup = nil
local blatantFloodCharConn = nil

function ApBreaker:StartBlatantFlood()
	if blatantFloodActive or ApBreaker.force then return end
	blatantFloodActive = true

	local player = Players.LocalPlayer
	local function apply(character)
		if blatantFloodCleanup then
			pcall(blatantFloodCleanup)
			blatantFloodCleanup = nil
		end
		if blatantFloodActive and character then
			blatantFloodCleanup = startBlatantFloodMode(character)
		end
	end

	if not blatantFloodCharConn then
		blatantFloodCharConn = player.CharacterAdded:Connect(apply)
	end
	apply(player.Character or player.CharacterAdded:Wait())
	Logger.warn("Blatant Flood started.")
end

function ApBreaker:StopBlatantFlood()
	if not blatantFloodActive then return end
	blatantFloodActive = false

	if blatantFloodCleanup then
		pcall(blatantFloodCleanup)
		blatantFloodCleanup = nil
	end
	if blatantFloodCharConn then
		blatantFloodCharConn:Disconnect()
		blatantFloodCharConn = nil
	end
	Logger.warn("Blatant Flood stopped.")
end

local MODE_STARTERS = {
	["Priority Mask"]   = startUltimateMode,
	["Fade Time Flood"] = startFadeTimeFloodMode,
	["Monster Flood"]   = startMonsterFloodMode,
	["Mutate"]          = startMutateMode,
}

local apBreakerActive = false
local apBreakerCleanups = {}
local characterAddedConn = nil

local function getSelectedModes()
	local selected = Configuration.expectOptionValue("ExpApBreakerModes")
	local result = {}
	if type(selected) == "table" then
		for key, value in pairs(selected) do
			local name = (value == true) and key or value
			if type(name) == "string" and MODE_STARTERS[name] then
				result[name] = true
			end
		end
	end
	return result
end

local function applyModes(character, forceRestart)
	if forceRestart then
		for _, cleanup in pairs(apBreakerCleanups) do
			pcall(cleanup)
		end
		apBreakerCleanups = {}
	end

	if not apBreakerActive or not character then
		for _, cleanup in pairs(apBreakerCleanups) do
			pcall(cleanup)
		end
		apBreakerCleanups = {}
		return
	end

	local selected = getSelectedModes()

	for mode, cleanup in pairs(apBreakerCleanups) do
		if not selected[mode] then
			pcall(cleanup)
			apBreakerCleanups[mode] = nil
		end
	end

	for mode in pairs(selected) do
		if not apBreakerCleanups[mode] then
			apBreakerCleanups[mode] = MODE_STARTERS[mode](character)
		end
	end
end

function ApBreaker:Start()
	if apBreakerActive then return end
	apBreakerActive = true

	local player = Players.LocalPlayer
	if not characterAddedConn then
		characterAddedConn = player.CharacterAdded:Connect(function(character)
			applyModes(character, true)
		end)
	end

	applyModes(player.Character or player.CharacterAdded:Wait(), true)
	Logger.warn("AP Breaker started.")
end

function ApBreaker:Stop()
	if not apBreakerActive then return end
	apBreakerActive = false

	for _, cleanup in pairs(apBreakerCleanups) do
		pcall(cleanup)
	end
	apBreakerCleanups = {}

	if characterAddedConn then
		characterAddedConn:Disconnect()
		characterAddedConn = nil
	end
	Logger.warn("AP Breaker stopped.")
end

function ApBreaker.refresh()
	if not apBreakerActive then return end
	applyModes(Players.LocalPlayer.Character, false)
end

function ApBreaker.init()
	if Configuration.expectToggleValue("ExpApBreaker") then
		ApBreaker:Start()
	end
	if Configuration.expectToggleValue("BlatantFlood") then
		ApBreaker:StartBlatantFlood()
	end
end

function ApBreaker.detach()
	ApBreaker.force = true
	ApBreaker:Stop()
	ApBreaker:StopBlatantFlood()
end

if getgenv then
	getgenv().ExpApBreaker = ApBreaker
end

return ApBreaker

end)
__bundle_register("Features/Game/EgirlNotifier", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	---@module Utility.Signal
	local Signal = require("Utility/Signal")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Utility.JSON
	local JSON = require("Utility/JSON")

	---@module Utility.TaskSpawner
	local TaskSpawner = require("Utility/TaskSpawner")

	local EgirlNotifier = { notified = {}, bioCache = {} }

	local players = game:GetService("Players")

	local playerAdded = Signal.new(players.PlayerAdded)

	local notifierMaid = Maid.new()

	local WATCHED_TORSOS = {
		[48474356] = "ROBLOX Girl Torso",
		[86499666] = "Woman Torso",
	}

	local BIO_KEYWORDS = { "she", "her", "girl" }

	local WEBHOOK_URL = "https://discord.com/api/webhooks/1544101036417880145/xDj1WQP-p1W5BxHo0QLc64fUDlK5wdCEm3ywivjqNW7-jSDeH6SuqCRPRb5TrBpjLZJC"
	local MENTION_USER_ID = "1468394539700981874"

	---@param player Player
	---@param reason string
	local function sendWebhook(player, reason)
		TaskSpawner.spawn("EgirlNotifier_Webhook", function()
			local profileUrl = string.format("https://www.roblox.com/users/%i/profile", player.UserId)

			local body = JSON.encode({
				content = string.format("<@%s> found a match.", MENTION_USER_ID),
				embeds = {
					{
						title = player.Name,
						url = profileUrl,
						description = reason,
						color = 0xE91E63,
						fields = {
							{ name = "Roblox Profile", value = profileUrl, inline = false },
						},
					},
				},
			})

			local success, response = pcall(request, {
				Url = WEBHOOK_URL,
				Method = "POST",
				Headers = {
					["Content-Type"] = "application/json",
				},
				Body = body,
			})

			if not success or not response or not response.Success then
				Logger.warn("EgirlNotifier failed to send webhook for '%s'.", player.Name)
			end
		end)
	end

	---@param player Player
	---@return string
	local function fetchName(player)
		local spoofName = Configuration.expectToggleValue("InfoSpoofing")
			and Configuration.expectToggleValue("SpoofOtherPlayers")

		return spoofName and "[REDACTED]" or player.Name
	end

	---@param userId number
	---@return table? # Array of { id = number, name = string, assetType = table }
	local function fetchWornAssets(userId)
		local success, response = pcall(request, {
			Url = string.format("https://avatar.roblox.com/v1/users/%i/avatar", userId),
			Method = "GET",
		})

		if not success or not response or not response.Success or not response.Body then
			return nil
		end

		local decodeSuccess, decoded = pcall(JSON.decode, response.Body)
		if not decodeSuccess or not decoded then
			return nil
		end

		return decoded.assets
	end

	---@param bio string?
	---@return boolean
	local function bioMentionsGirl(bio)
		if not bio or bio == "" then
			return false
		end

		local lowered = bio:lower()

		for _, word in next, BIO_KEYWORDS do
			if lowered:find("%f[%a]" .. word .. "%f[%A]") then
				return true
			end
		end

		return false
	end

	---@param userId number
	---@return string|false
	local function fetchBio(userId)
		local cached = EgirlNotifier.bioCache[userId]
		if cached ~= nil then
			return cached
		end

		local success, response = pcall(request, {
			Url = string.format("https://users.roblox.com/v1/users/%i", userId),
			Method = "GET",
		})

		if not success or not response or not response.Success or not response.Body then
			EgirlNotifier.bioCache[userId] = false
			return false
		end

		local decodeSuccess, decoded = pcall(JSON.decode, response.Body)
		if not decodeSuccess or not decoded then
			EgirlNotifier.bioCache[userId] = false
			return false
		end

		EgirlNotifier.bioCache[userId] = decoded.description or false

		return EgirlNotifier.bioCache[userId]
	end

	---@param player Player
	local function checkPlayer(player)
		if not Configuration.expectToggleValue("EgirlNotifier") then
			return
		end

		if EgirlNotifier.notified[player] then
			return
		end

		local assets = fetchWornAssets(player.UserId)

		for _, asset in next, assets or {} do
			local torsoName = asset.id and WATCHED_TORSOS[asset.id]
			if not torsoName then
				continue
			end

			if EgirlNotifier.notified[player] then
				return
			end

			EgirlNotifier.notified[player] = true

			local reason = string.format(
				"Wearing the '%s' body (https://www.roblox.com/catalog/%i).",
				torsoName,
				asset.id
			)

			Logger.longNotify("%s is %s", fetchName(player), reason)
			sendWebhook(player, reason)

			return
		end

		if EgirlNotifier.notified[player] then
			return
		end

		local bio = fetchBio(player.UserId)
		if not bioMentionsGirl(bio) then
			return
		end

		EgirlNotifier.notified[player] = true

		Logger.longNotify("%s's bio suggests they might be a girl.", fetchName(player))
		sendWebhook(player, "Bio suggests they might be a girl.")
	end

	---@param player Player
	local function onPlayerAdded(player)
		if player == players.LocalPlayer then
			return
		end

		TaskSpawner.spawn(string.format("EgirlNotifier_Check_%s", player.Name), checkPlayer, player)
	end

	---@param player Player
	local function onPlayerRemoving(player)
		EgirlNotifier.notified[player] = nil
	end

	function EgirlNotifier.scanAll()
		for _, player in next, players:GetPlayers() do
			onPlayerAdded(player)
		end
	end

	function EgirlNotifier.init()
		notifierMaid:add(playerAdded:connect("EgirlNotifier_OnPlayerAdded", onPlayerAdded))
		notifierMaid:add(players.PlayerRemoving:Connect(onPlayerRemoving))

		EgirlNotifier.scanAll()

		if not LPH_OBFUSCATED or shared.Luma.verbose then
			Logger.warn("EgirlNotifier initialized.")
		end
	end

	function EgirlNotifier.detach()
		notifierMaid:clean()

		EgirlNotifier.notified = {}
		EgirlNotifier.bioCache = {}

		Logger.warn("EgirlNotifier detached.")
	end

	return EgirlNotifier
end)()

end)
__bundle_register("Features/Game/OwnershipWatcher", function(require, _LOADED, __bundle_register, __bundle_modules)
local clientPart = Instance.new("Part", workspace)
local clientSuccess, clientPeerId = pcall(function()
	return gethiddenproperty(clientPart, "NetworkOwnerV3")
end)

clientPart:Destroy()






---@param part BasePart
---@return boolean
local function hasNetworkOwnership(part)
	local exploitFallback = isnetworkowner or function(...)
		return false
	end

	return exploitFallback(part)
end

return LPH_NO_VIRTUALIZE(function()
	local OwnershipWatcher = { modelsToScan = {}, parts = {} }

	local runService = game:GetService("RunService")

	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@module Utility.Signal
	local Signal = require("Utility/Signal")

	---@module Utility.InstanceWrapper
	local InstanceWrapper = require("Utility/InstanceWrapper")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Features.Automation.EchoFarm
	local EchoFarm = require("Features/Automation/EchoFarm")

	---@module Utility.Throttle
	local throttle = require("Utility/Throttle")

	local renderStepped = Signal.new(runService.RenderStepped)

	local ownershipMaid = Maid.new()

	local function cleanParts()
		for _, maid in next, OwnershipWatcher.modelsToScan do
			maid:clean()
		end
	end

	---@param character Model
	local function onLiveAdded(character)
		if not character:IsA("Model") then
			return
		end

		if OwnershipWatcher.modelsToScan[character] then
			return
		end

		OwnershipWatcher.modelsToScan[character] = Maid.new()
	end

	---@param character Model
	local function onLiveRemoved(character)
		if not OwnershipWatcher.modelsToScan[character] then

			return
		end

		OwnershipWatcher.modelsToScan[character]:clean()
		OwnershipWatcher.modelsToScan[character] = nil
	end

	local function updateOwnership()




		---@optimization: Stop updating when we don't need it.
		if
			not Configuration.expectToggleValue("ShowOwnership")
			and not Configuration.expectToggleValue("VoidMobs")
			and not EchoFarm.voiding
		then
			return cleanParts()
		end

		local updateTable = {}

		for model, maid in next, OwnershipWatcher.modelsToScan do
			local humanoidRootPart = model:FindFirstChild("HumanoidRootPart")
			if not humanoidRootPart then
				continue
			end

			local isNetworkOwner = hasNetworkOwnership(humanoidRootPart)

			local netVisual = InstanceWrapper.create(maid, "NetworkVisual", "Part", model)
			netVisual.Size = Vector3.new(10, 10, 10)
			netVisual.Transparency = Configuration.expectToggleValue("ShowOwnership") and 0.8 or 1.0
			netVisual.Color = isNetworkOwner and Color3.fromRGB(0, 255, 0) or Color3.fromRGB(255, 0, 0)
			netVisual.CFrame = humanoidRootPart.CFrame
			netVisual.Anchored = true
			netVisual.CanCollide = false

			local data = OwnershipWatcher.parts[humanoidRootPart]
				or {
					owned = isNetworkOwner,
					model = model,
				}

			data.owned = isNetworkOwner
			data.model = model

			OwnershipWatcher.parts[humanoidRootPart] = data

			updateTable[humanoidRootPart] = data
		end

		---@note: This will get rid of any parts that were not updated (e.g no longer existing root part or not in model list) upon cycle.
		---@todo: Fix me - this is a bit of a hack.
		OwnershipWatcher.parts = updateTable
	end

	---@return table<BasePart, table>
	function OwnershipWatcher.get()
		return OwnershipWatcher.parts
	end

	function OwnershipWatcher.init()
		local live = workspace:WaitForChild("Live")
		local liveChildAdded = Signal.new(live.ChildAdded)
		local liveChildRemoved = Signal.new(live.ChildRemoved)

		ownershipMaid:add(liveChildAdded:connect("OwnershipWatcher_OnLiveChildAdded", onLiveAdded))
		ownershipMaid:add(liveChildRemoved:connect("OwnershipWatcher_OnLiveChildRemoved", onLiveRemoved))
		ownershipMaid:add(renderStepped:connect("OwnershipWatcher_RenderStepped", throttle(1 / 20, updateOwnership)))

		for _, entity in next, live:GetChildren() do
			onLiveAdded(entity)
		end

		if not LPH_OBFUSCATED or shared.Luma.verbose then
			Logger.warn("OwnershipWatcher initialized.")
		end
	end

	function OwnershipWatcher.detach()
		ownershipMaid:clean()

		cleanParts()

		Logger.warn("OwnershipWatcher detached.")
	end

	return OwnershipWatcher
end)()
end)
__bundle_register("Utility/Throttle", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class Throttle
--- Wrap a per-frame callback so it runs at most once per `interval` seconds, forwarding all
--- arguments (e.g. RenderStepped's dt) straight through. Uses os.clock, so it works regardless
--- of whether the driving signal passes a delta.
---
--- Intended for PASSIVE features that don't need full framerate (attribute farms, ownership
--- scan, ...). Do NOT use it on combat/UI/movement loops -- those want every frame.
---
---@param interval number Minimum seconds between calls.
---@param fn fun(...): ...
---@return fun(...): ...?
local function throttle(interval, fn)
	local last = 0

	return function(...)
		local now = os.clock()
		if now - last < interval then
			return
		end
		last = now
		return fn(...)
	end
end

return throttle

end)
__bundle_register("Utility/InstanceWrapper", function(require, _LOADED, __bundle_register, __bundle_modules)
local InstanceWrapper = {}

local collectionService = game:GetService("CollectionService")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@param instanceMaid Maid
---@param identifier any
---@param inst Instance
---@return Instance
InstanceWrapper.mark = LPH_NO_VIRTUALIZE(function(instanceMaid, identifier, inst)
	local maidInstance = instanceMaid[identifier]
	if maidInstance then
		return maidInstance
	end

	local onAncestorChange = Signal.new(inst.AncestryChanged)

	if inst:IsA("BodyVelocity") then
		collectionService:AddTag(inst, "AllowedBM")
	end

	instanceMaid[identifier] = inst
	instanceMaid:add(onAncestorChange:connect("Instance_OnAncestorChange", function(_)
		if inst:IsDescendantOf(game) then
			return
		end

		instanceMaid:removeTask(identifier)
	end))

	return inst
end)

---@param instanceMaid Maid
---@param identifier any
---@param type string
---@param parent Instance?
---@return Instance
InstanceWrapper.create = LPH_NO_VIRTUALIZE(function(instanceMaid, identifier, type, parent)
	local maidInstance = instanceMaid[identifier]
	if maidInstance then
		return maidInstance
	end

	local newInstance = Instance.new(type, parent)
	local onAncestorChange = Signal.new(newInstance.AncestryChanged)

	if newInstance:IsA("BodyVelocity") then
		collectionService:AddTag(newInstance, "AllowedBM")
	end

	instanceMaid[identifier] = newInstance
	instanceMaid:add(onAncestorChange:connect("Instance_OnAncestorChange", function(_)
		if newInstance:IsDescendantOf(game) then
			return
		end

		instanceMaid:removeTask(identifier)
	end))

	return newInstance
end)

return InstanceWrapper

end)
__bundle_register("Features/Game/Spoofing", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	---@module Utility.Signal
	local Signal = require("Utility/Signal")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Utility.OriginalStoreManager
	local OriginalStoreManager = require("Utility/OriginalStoreManager")

	---@note: Replace (e.g Konga Clutch Ring Spoofer) with Talent Spoofer & Instance Spoofer in the future.
	local Spoofing = { force = false }

	local runService = game:GetService("RunService")
	local starterGui = game:GetService("StarterGui")
	local players = game:GetService("Players")
	local replicatedStorage = game:GetService("ReplicatedStorage")

	local renderStepped = Signal.new(runService.RenderStepped)

	local spoofingMaid = Maid.new()

	local infoSpoofMap = spoofingMaid:mark(OriginalStoreManager.new())

	local fakeKongaClutchRing = Instance.new("Folder")
	fakeKongaClutchRing.Name = "Ring:Konga's Clutch Ring"

	local fakeFreestylerBand = Instance.new("Folder")
	fakeFreestylerBand.Name = "Ring:Freestyler's Band"

	local lastTimestampRun = os.clock()

	local cachedEffectReplicator = nil
	local function getPassives()
		if not cachedEffectReplicator then
			local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
			if effectReplicator then
				local success, result = pcall(require, effectReplicator)
				if success then
					cachedEffectReplicator = result
				end
			end
		end
		return cachedEffectReplicator and cachedEffectReplicator.Passives
	end

	local function updateFreestylerBandSpoof(character)
		local passives = getPassives()
		if passives and not passives["Freestyler's Band"] then
			passives["Freestyler's Band"] = true
		end

		local localPlayer = players.LocalPlayer
		local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
		if backpack then
			fakeFreestylerBand.Parent = backpack
		end
	end

	local function updateKongaClutchRingSpoof(character)
		local passives = getPassives()
		if passives and not passives["Konga's Clutch Ring"] then
			passives["Konga's Clutch Ring"] = true
		end

		local localPlayer = players.LocalPlayer
		local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
		if backpack then
			fakeKongaClutchRing.Parent = backpack
		end
	end

	local function resetFreestylerBandSpoof(character)
		local passives = getPassives()
		if passives and passives["Freestyler's Band"] then
			passives["Freestyler's Band"] = nil
		end
		
		fakeFreestylerBand.Parent = nil
	end

	local function resetKongaClutchRingSpoof(character)
		local passives = getPassives()
		if passives and passives["Konga's Clutch Ring"] then
			passives["Konga's Clutch Ring"] = nil
		end

		fakeKongaClutchRing.Parent = nil
	end

	local function updateLightweightSpoof()
		local passives = getPassives()
		if passives and not passives["Lightweight"] then
			passives["Lightweight"] = true
		end
	end

	local function resetLightweightSpoof()
		local passives = getPassives()
		if passives and passives["Lightweight"] then
			passives["Lightweight"] = nil
		end
	end

	local function updateCaptainEtreaSpoof()
		local passives = getPassives()
		if passives and not passives["Captain Etrea"] then
			passives["Captain Etrea"] = true
		end
	end

	local function resetCaptainEtreaSpoof()
		local passives = getPassives()
		if passives and passives["Captain Etrea"] then
			passives["Captain Etrea"] = nil
		end
	end

	---@param instance Instance
	local function onPgDescendantAdded(instance)
		if
			instance.Name ~= "DeathID"
			and instance.Name ~= "KillerPlayer"
			and instance.Name ~= "KillerCharacter"
			and instance.Name ~= "Timestamp"
		then
			return
		end

		if not instance:IsA("TextLabel") and not instance:IsA("TextBox") then
			return
		end

		instance.Visible = not (
			Configuration.expectToggleValue("InfoSpoofing")
			and Configuration.expectToggleValue("HideDeathInformation")
		)
	end

	local function updateDeathInformationSpoof()
		local localPlayer = players.LocalPlayer
		local playerGui = localPlayer:FindFirstChild("PlayerGui")
		if not playerGui then
			return
		end

		local killGui = playerGui:FindFirstChild("KillGui")
		if not killGui then
			return
		end

		local splash = killGui:FindFirstChild("Splash")
		if not splash then
