---@param child Instance
local onThrownChildAdded = LPH_NO_VIRTUALIZE(function(child)
	local name = child.Name

	if name == "MinistryCacheIndicator" then
		return emplaceObject(child, PartESP.new("MinistryCacheIndicator", child, "Ministry Cache Indicator"))
	end

	if name == "BigArtifact" and child:IsA("Model") then
		return emplaceObject(child, ModelESP.new("Artifact", child, "Artifact"))
	end

	if name == "BellMeteor" then
		return emplaceObject(child, ModelESP.new("BellMeteor", child, "Bell Meteor"))
	end

	if name == "ExplodeCrate" then
		return emplaceObject(child, PartESP.new("ExplosiveBarrel", child, "Explosive Barrel"))
	end

	if name == "BagDrop" then
		return emplaceObject(child, PartESP.new("BagDrop", child, "Bag"))
	end

	if name == "EventFeatherRef" then
		return emplaceObject(child, PartESP.new("OwlFeathers", child, "Owl Feathers"))
	end

	if name == "BoneSpear" then
		return emplaceObject(child, PartESP.new("BoneSpear", child, "Bone Spear"))
	end

	-- A chest carries a "LootName" attribute. The game names some chests "Chest" and some just "Model", so
	-- match on the attribute regardless of the child's name (cheap attribute read -- no WaitForChild, so no
	-- Thrown-flood pile-up).
	if child:GetAttribute("LootName") ~= nil then
		return emplaceObject(child, ChestESP.new("Chest", child, "Chest"))
	end

	if not child:IsA("Model") and not child:IsA("Part") then
		return
	end

	if child:FindFirstChild("LootUpdated") then
		return emplaceObject(child, ChestESP.new("Chest", child, "Chest"))
	end

	-- A chest is anything named "Chest", or carrying a LootName attribute / LootUpdated child / Lid child --
	-- regardless of its own name (chests also arrive named "Model").
	local function chestSignal()
		return child.Name == "Chest"
			or child:GetAttribute("LootName") ~= nil
			or child:FindFirstChild("LootUpdated") ~= nil
			or child:FindFirstChild("Lid") ~= nil
	end

	if chestSignal() then
		return emplaceObject(child, ChestESP.new("Chest", child, "Chest"))
	end

	-- Deferred chest detection: a chest can arrive in Thrown (often named "Model", not "Chest") BEFORE its
	-- LootName attribute / LootUpdated / Lid child has replicated, so none of the checks above catch it yet.
	-- Event-watch for any of those to appear instead of an inline WaitForChild("Lid", 2.5) per child -- that
	-- per-child 2.5s yield was the x1233 Visuals_ChestCheck pile-up on the farm-flooded Thrown folder. Gated to
	-- Models (unmatched parts aren't chests), event-driven, hard-timeout, self-disconnecting: a couple of
	-- connections for <=2.5s, never a yielding fiber per child.
	if not child:IsA("Model") then
		return
	end

	local chestWatchConnections = {}
	local chestWatchDone = false
	local function finishChestWatch(matched)
		if chestWatchDone then
			return
		end
		chestWatchDone = true
		for _, connection in ipairs(chestWatchConnections) do
			pcall(function() connection:Disconnect() end)
		end
		if matched and child.Parent then
			emplaceObject(child, ChestESP.new("Chest", child, "Chest"))
		end
	end

	chestWatchConnections[#chestWatchConnections + 1] = child.ChildAdded:Connect(function()
		if chestSignal() then
			finishChestWatch(true)
		end
	end)
	chestWatchConnections[#chestWatchConnections + 1] = child:GetAttributeChangedSignal("LootName"):Connect(function()
		if chestSignal() then
			finishChestWatch(true)
		end
	end)
	task.delay(2.5, function()
		finishChestWatch(false)
	end)
end)

