__bundle_register("Features/Visuals/Objects/InstanceESP", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@class InstanceESP
---@field identifier string
---@field maid Maid
---@field label string
---@field text TextLabel
---@field billboard BillboardGui
---@field instance Instance
local InstanceESP = {}
InstanceESP.__index = InstanceESP
InstanceESP.__type = "InstanceESP"

local playersService = game:GetService("Players")

local ESP_DISTANCE_FORMAT = "%s [%i]"

local function SET_IF_CHANGED(INSTANCE, PROPERTY, VALUE)
	if INSTANCE[PROPERTY] ~= VALUE then
		INSTANCE[PROPERTY] = VALUE
	end
end

---@param visible boolean
function InstanceESP:visible(visible)
	SET_IF_CHANGED(self.billboard, "Enabled", visible)
end

function InstanceESP:detach()
	self.maid:clean()
end

---@param self InstanceESP
---@param label string
---@param tags string[]
---@return string
InstanceESP.build = LPH_NO_VIRTUALIZE(function(self, label, tags)
	if #tags <= 0 then
		return label
	end

	local lines = {}
	local start = true

	for _, tag in next, tags do
		local line = lines[#lines] or label

		if not start and #line > Configuration.expectOptionValue("ESPSplitLineLength") then
			lines[#lines + 1] = tag
			continue
		end

		line = line .. " " .. tag

		lines[start and 1 or #lines] = line

		start = false
	end

	return table.concat(lines, "\n")
end)

---@param self InstanceESP
---@param position Vector3
---@param tags string[]
InstanceESP.update = LPH_NO_VIRTUALIZE(function(self, position, tags)
	local label = self.label
	local identifier = self.identifier

	if not Configuration.idToggleValue(identifier, "Enable") then
		return self:visible(false)
	end

	local localPlayer = playersService.LocalPlayer
	local localCharacter = localPlayer and localPlayer.Character

	if not localCharacter then
		return self:visible(false)
	end

	local localRoot = localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRoot then
		return self:visible(false)
	end

	local offset = localRoot.Position - position
	local distanceSquared = offset:Dot(offset)
	local maxDistance = Configuration.idOptionValue(identifier, "MaxDistance")

	if maxDistance < 0 or distanceSquared > maxDistance * maxDistance then
		return self:visible(false)
	end

	if Configuration.idToggleValue(identifier, "ShowDistance") then
		label = ESP_DISTANCE_FORMAT:format(label, math.sqrt(distanceSquared))
	end

	self:visible(true)

	local text = self.text
	SET_IF_CHANGED(text, "Text", self:build(label, tags))
	SET_IF_CHANGED(text, "TextColor3", Configuration.idOptionValue(identifier, "Color"))
	SET_IF_CHANGED(text, "TextSize", Configuration.expectOptionValue("FontSize"))
	SET_IF_CHANGED(text, "Font", Enum.Font[Configuration.expectOptionValue("Font")] or Enum.Font.Code)

	local transparency = 1 - (Configuration.idOptionValue(identifier, "TextOpacity") or 100) / 100
	SET_IF_CHANGED(text, "TextTransparency", transparency)
	SET_IF_CHANGED(text, "TextStrokeTransparency", transparency)
end)

function InstanceESP:setup()
	local billboardGui = Instance.new("BillboardGui")
	billboardGui.AlwaysOnTop = true
	billboardGui.Size = UDim2.new(1e5, 0, 1e5, 0)
	billboardGui.Enabled = false
	billboardGui.Adornee = self.instance
	billboardGui.Parent = workspace
	billboardGui.AutoLocalize = false

	local textLabel = Instance.new("TextLabel")
	textLabel.BackgroundTransparency = 1.0
	textLabel.Size = UDim2.new(1, 0, 1, 0)
	textLabel.TextStrokeTransparency = 0.0
	textLabel.Parent = billboardGui
	textLabel.AutoLocalize = false

	self.billboard = self.maid:mark(billboardGui)
	self.text = self.maid:mark(textLabel)
end

---@param instance Instance
---@param identifier string
---@param label string
function InstanceESP.new(instance, identifier, label)
	local self = setmetatable({}, InstanceESP)
	self.label = label
	self.instance = instance
	self.identifier = identifier
	self.maid = Maid.new()
	self:setup()
	return self
end

return InstanceESP

end)
