__bundle_register("Menu/VisualsTab", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module GUI.Icons
local Icons = require("GUI/Icons")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Features.Visuals.Visuals
local Visuals = require("Features/Visuals/Visuals")

---@module Features.Game.OptimizeGame
local OptimizeGame = require("Features/Game/OptimizeGame")

---@module Utility.JSON
local JSON = require("Utility/JSON")

---@module Features.Visuals.Objects.BuilderData
local BuilderData = require("Features/Visuals/Objects/BuilderData")

---@module Menu.UI
local UI = require("Menu/UI")

local VisualsTab = {}

---@param section table
function VisualsTab.initESPCustomization(section)
	UI.slider(section, "FontSize", "ESP Font Size", { Default = 16, Min = 4, Max = 24, Rounding = 0 })
	UI.slider(section, "ESPSplitLineLength", "ESP Split Line Length", { Default = 30, Min = 10, Max = 100, Rounding = 0 })

	local fonts = {}
	for _, font in next, Enum.Font:GetEnumItems() do
		if font == Enum.Font.Unknown then
			continue
		end

		table.insert(fonts, font.Name)
	end

	UI.dropdown(section, "Font", "ESP Fonts", { Default = 1, Values = fonts })
end

---@param section table
function VisualsTab.initESPOptimizations(section)
	UI.toggle(section, "ESPLimitUpdates", "ESP Limit Updates", true)
	UI.slider(section, "ESPRefreshRate", "ESP Refresh Rate", { Suffix = "f", Default = 30, Min = 1, Max = 144, Rounding = 0 })

	UI.toggle(section, "ESPSplitUpdates", "ESP Split Updates", false)
	UI.slider(section, "ESPSplitFrames", "ESP Split Frames", { Suffix = "f", Default = 32, Min = 1, Max = 64, Rounding = 0 })

	UI.toggle(section, "NoPersisentESP", "No Persistent ESP", false)
end

---@param section table
function VisualsTab.initWorldVisualsSection(section)
	UI.toggle(section, "OptimizeGame", "Optimize Game", false)
	UI.toggle(section, "LowTextures", "Low Textures", false, function(enabled)
		OptimizeGame.setLowTextures(enabled)
	end)
	UI.toggle(section, "HideTreeLeaves", "Hide Tree Leaves", false, function(enabled)
		OptimizeGame.setTreeLeafCulling(enabled)
	end)
	UI.toggle(section, "HideDistantIslands", "Hide Distant Parts", false, function(enabled)
		OptimizeGame.setDistantPartCulling(enabled)
	end)
	UI.slider(section, "DistantIslandHideDistance", "Part Hide Distance", {
		Default = 5000, Min = 500, Max = 20000, Rounding = 0, Suffix = " studs",
		Callback = function(distance)
			OptimizeGame.setDistantPartCullDistance(distance)
		end,
	})

	UI.toggle(section, "UseFastFlags", "Use Fast Flags For Session", false, function(state)
		if not state then
			return
		end

		local success, content = pcall(readfile, "fflags.json")
		if not success then
			return Logger.longNotify("Failed to load fflags.json. Make sure the file exists in your workspace.")
		end
		local decodeSuccess, fflags = pcall(game:GetService("HttpService").JSONDecode, game:GetService("HttpService"), content)
		if not decodeSuccess then
			return Logger.longNotify("fflags.json is not a valid JSON format.")
		end
		for index, value in next, fflags do
			pcall(function()
				setfflag(index, tostring(value))
			end)
		end
		Logger.notify("Fast Flags applied successfully for this session server hop to see changes.")
	end)

	UI.toggle(section, "ModifyFieldOfView", "Modify Field Of View", false)
	UI.slider(section, "FieldOfView", "Field Of View Slider", { Default = 90, Min = 0, Max = 120, Suffix = "°", Rounding = 0 })

	local modifyAmbienceToggle = UI.toggle(section, "ModifyAmbience", "Modify Ambience", false)
	UI.color(modifyAmbienceToggle, "AmbienceColor", Color3.fromHex("FFFFFF"))

	UI.toggle(section, "OriginalAmbienceColor", "Original Ambience Color", false)
	UI.slider(section, "OriginalAmbienceColorBrightness", "Original Ambience Brightness", { Default = 0, Min = 0, Max = 255, Suffix = "+", Rounding = 0 })
end

---@param section table
function VisualsTab.initVisualAssistanceSection(section)
	UI.toggle(section, "ChainOfPerfectionTracker", "Chain Of Perfection Tracker", false)
	UI.toggle(section, "SanityTracker", "Sanity Tracker", false)
	UI.toggle(section, "MysteryMantraRevealer", "Mystery Mantra Revealer", false)
	UI.toggle(section, "Roll2Revealer", "Roll 2 Revealer", false)

	UI.toggle(section, "BuildAssistance", "Build Assistance", false)
	UI.toggle(section, "ShrineDetectionOverride", "Shrine Detection Override", true)
	UI.dropdown(section, "ShrineOverrideState", "Shrine Override State", { Default = 1, Values = { "Pre-Shrine", "Post-Shrine", "Must Shrine" } })
	UI.toggle(section, "AutoFavourCards", "Auto Favour Cards", false)

	UI.input(section, "BuildAssistanceLink", "Build Assistance Link", "Enter your builder link here.", nil, function(value)
		-- Empty box (e.g. restored by a config load) -> do nothing, silently. Only complain when
		-- there's actual text that failed to parse.
		if type(value) ~= "string" or value:gsub("%s+", "") == "" then
			return
		end

		local headers = {
			["Content-Type"] = "application/json",
			["Accept"] = "application/json",
			["Origin"] = "https://deepwoken.co",
			["Referer"] = "https://deepwoken.co/builder",
			["Sec-Fetch-Site"] = "same-origin",
			["Sec-Fetch-Mode"] = "cors",
			["Sec-Fetch-Dest"] = "empty",
		}

		local id = value:match("[?&]id=([%w%d]+)") or value:match("^%s*([%w%d]+)%s*$")
		if not id then
			return Logger.notify("Invalid builder link. Please provide a valid builder URL or builder id.")
		end

		local bresponse = request({
			Url = "https://new.deepwoken.co/api/proxy/builds/" .. id,
			Method = "GET",
			Headers = headers,
		})

		if not bresponse or not bresponse.Success or not bresponse.Body then
			return Logger.notify("Invalid response while fetching builder response.")
		end

		local bsuccess, bresult = pcall(JSON.decode, bresponse.Body)
		if not bsuccess or not bresult then
			return Logger.notify("JSON error '%s' while deserializing builder response.", bresult)
		end

		Logger.notify("Successfully fetched build data.")

		local dresponse = request({
			Url = "https://new.deepwoken.co/api/proxy/get?type=all",
			Method = "GET",
			Headers = headers,
		})

		if not dresponse or not dresponse.Success or not dresponse.Body then
			return Logger.notify("Invalid response while fetching data response.")
		end

		local dsuccess, dresult = pcall(JSON.decode, dresponse.Body)
		if not dsuccess or not dresult then
			return Logger.notify("JSON error '%s' while deserializing data response.", dresult)
		end

		Logger.notify("Successfully created BuilderData object.")

		Visuals.bdata = BuilderData.new(bresult, dresult)
	end)
end

