end

---@param section table
function VisualsTab.initTargetHUDSection(section)
	UI.toggle(section, "TargetHUD", "Target HUD", false)
	UI.label(section, "Drag the panel to reposition it.")
end

function VisualsTab.init(window)
	local tab = window:AddTab("ESP", "eye", {
		Pages = {
			{ Name = "General" },
			{ Name = "Entities" },
			{ Name = "Objects" },
			{ Name = "World" },
		},
	})

	-- Alternate left/right columns per page so the many ESP sections spread evenly.
	local sideState = {}
	local function sec(page, title)
		local side = sideState[page] or "left"
		sideState[page] = (side == "left") and "right" or "left"
		return tab:AddSection(side, title, page)
	end

	VisualsTab.initESPCustomization(sec("General", "ESP Customization"))
	VisualsTab.initESPOptimizations(sec("General", "ESP Optimizations"))
	VisualsTab.initProximitySection(sec("General", "Player Proximity"))
	VisualsTab.initTargetHUDSection(sec("General", "Target HUD"))

	VisualsTab.addPlayerESP(VisualsTab.addEntityESP(VisualsTab.initBaseESPSection("Player", sec("Entities", "Player ESP"))))
	VisualsTab.addFilterESP(VisualsTab.addEntityESP(VisualsTab.initBaseESPSection("Mob", sec("Entities", "Mob ESP"))))
	VisualsTab.initBaseESPSection("NPC", sec("Entities", "NPC ESP"))

	VisualsTab.addChestESP(VisualsTab.initBaseESPSection("Chest", sec("Objects", "Chest ESP")))
	VisualsTab.initBaseESPSection("BagDrop", sec("Objects", "Bag ESP"))
	VisualsTab.addFilterESP(VisualsTab.initBaseESPSection("AreaMarker", sec("Objects", "Area Marker ESP")))
	VisualsTab.initBaseESPSection("VOIBoundaryESP", sec("Objects", "VOI Boundary ESP"))
	VisualsTab.initBaseESPSection("VOIWeaponESP", sec("Objects", "VOI Weapon ESP"))
	VisualsTab.initBaseESPSection("ShopESP", sec("Objects", "Shop ESP"))
	VisualsTab.initBaseESPSection("JobBoard", sec("Objects", "Job Board ESP"))
	VisualsTab.initBaseESPSection("Artifact", sec("Objects", "Artifact ESP"))
	VisualsTab.initBaseESPSection("WindrunnerOrb", sec("Objects", "Windrunner Orb ESP"))
	VisualsTab.initBaseESPSection("Whirlpool", sec("Objects", "Whirlpool ESP"))
	VisualsTab.initBaseESPSection("ExplosiveBarrel", sec("Objects", "Explosive Barrel ESP"))
	VisualsTab.initBaseESPSection("MinistryCacheIndicator", sec("Objects", "Ministry Cache ESP"))
	VisualsTab.initBaseESPSection("OwlFeathers", sec("Objects", "Owl Feathers ESP"))
	VisualsTab.addObeliskESP(VisualsTab.initBaseESPSection("Obelisk", sec("Objects", "Obelisk ESP")))
	VisualsTab.addBoneAltarESP(VisualsTab.initBaseESPSection("BoneAltar", sec("Objects", "Bone Altar ESP")))

	VisualsTab.initBaseESPSection("GuildDoor", sec("World", "Guild Door ESP"))
	VisualsTab.initBaseESPSection("GuildBanner", sec("World", "Guild Banner ESP"))
	VisualsTab.addFilterESP(VisualsTab.initBaseESPSection("Ingredient", sec("World", "Ingredient ESP")))
	VisualsTab.initBaseESPSection("BoneSpear", sec("World", "Bone Spear ESP"))
	VisualsTab.initBaseESPSection("ArmorBrick", sec("World", "Armor Brick ESP"))
	VisualsTab.initBaseESPSection("BellMeteor", sec("World", "Bell Meteor ESP"))
	VisualsTab.initBaseESPSection("RareObelisk", sec("World", "Rare Obelisk ESP"))
	VisualsTab.initBaseESPSection("HealBrick", sec("World", "Heal Brick ESP"))
	VisualsTab.initBaseESPSection("MantraObelisk", sec("World", "Mantra Obelisk ESP"))
	VisualsTab.initBaseESPSection("BRWeapon", sec("World", "BR Weapon ESP"))
	VisualsTab.initBaseESPSection("BellKey", sec("World", "Bell Key ESP"))
end

return VisualsTab

end)
__bundle_register("Menu/GameTab", function(require, _LOADED, __bundle_register, __bundle_modules)
local GameTab = {}

---@module GUI.Icons
local Icons = require("GUI/Icons")

---@module Features.Game.Spoofing
local Spoofing = require("Features/Game/Spoofing")

---@module Features.Game.EgirlNotifier
local EgirlNotifier = require("Features/Game/EgirlNotifier")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Environment
local Environment = require("Utility/Environment")

---@module Game.KeyHandling
local KeyHandling = require("Game/KeyHandling")

local players = game:GetService("Players")

---@module Features.Game.Tweening
local Tweening = require("Features/Game/Tweening")

---@module Features.Game.FakeVoid
local FakeVoid = require("Features/Game/FakeVoid")

---@module Menu.UI
local UI = require("Menu/UI")

-- All of these were groupbox builders on the old library. On the native Luma UI they take a
-- `section` (from tab:AddSection) and add controls through Menu/UI helpers. Dependency boxes are
-- flattened (every control sits directly in the section, always visible) and the obsidian
-- SyncToggleState keypickers become native toggle keybinds.

---@param section table
function GameTab.initMovementSection(section)
	local speedHackToggle = UI.toggle(section, "Speedhack", "Speedhack", false)
	UI.bind(speedHackToggle, "N/A", "Toggle")
	UI.slider(section, "SpeedhackSpeed", "Speedhack Speed", { Default = 200, Min = 0, Max = 300, Suffix = "/s", Rounding = 0 })

	local cframeSpeedToggle = UI.toggle(section, "CFrameSpeed", "CFrame Speed", false)
	UI.bind(cframeSpeedToggle, "N/A", "Toggle")
	UI.slider(section, "CFrameSpeedMultiplier", "CFrame Speed Multiplier", { Default = 1, Min = 1, Max = 20, Suffix = "x", Rounding = 1 })

	local flyToggle = UI.toggle(section, "Fly", "Fly", false)
	UI.bind(flyToggle, "N/A", "Toggle")
	UI.slider(section, "FlySpeed", "Fly Speed", { Default = 200, Min = 0, Max = 450, Suffix = "/s", Rounding = 0 })
	UI.slider(section, "FlyUpSpeed", "Spacebar Fly Speed", { Default = 150, Min = 0, Max = 450, Suffix = "/s", Rounding = 0 })

	local noclipToggle = UI.toggle(section, "NoClip", "NoClip", false)
	UI.bind(noclipToggle, "N/A", "Toggle")
	UI.toggle(section, "NoClipCollisionsKnocked", "Collisions While Knocked", false)

	local walkSpeedMultiplierToggle = UI.toggle(section, "WalkSpeedMultiplier", "Walkspeed Multiplier", false)
	UI.bind(walkSpeedMultiplierToggle, "N/A", "Toggle")
	UI.slider(section, "WalkSpeedMultiplierMinimum", "Walkspeed Multiplier Minimum", { Default = 1.5, Min = 1, Max = 2, Suffix = "x", Rounding = 2 })
	UI.slider(section, "WalkSpeedMultiplierMaximum", "Walkspeed Multiplier Maximum", { Default = 2, Min = 1, Max = 2, Suffix = "x", Rounding = 2 })

	UI.label(section, "Offset Up (1500)")
	UI.keybind(section, "OffsetUp", "Offset Up (1500)", "N/A", function()
		local localPlayer = players.LocalPlayer
		local character = localPlayer and localPlayer.Character
		if not character then
			return
		end

		character:TranslateBy(Vector3.new(0, 1500, 0))
	end)

	local ttbToggle = UI.toggle(section, "TweenToBack", "Tween To Back", false, function(state)
		if state then
			return
		end

		Tweening.stop("TweenToBack")
	end)
	UI.bind(ttbToggle, "N/A", "Toggle")

	UI.toggle(section, "StickyAttach", "Sticky Attach", false)
	UI.toggle(section, "AttachIgnorePlayers", "Ignore Players", true)
	UI.slider(section, "BackOffset", "Distance To Entity", { Default = 5, Min = -100, Max = 100, Suffix = "studs", Rounding = 0 })
	UI.slider(section, "HeightOffset", "Height Offset", { Default = 0, Min = -100, Max = 30, Suffix = "studs", Rounding = 0 })

	local tweenToObjectiveToggle = UI.toggle(section, "TweenToObjective", "Tween To Objectives", false)
	UI.bind(tweenToObjectiveToggle, "N/A", "Toggle")

	local infJumpToggle = UI.toggle(section, "InfiniteJump", "Infinite Jump", false)
	UI.bind(infJumpToggle, "N/A", "Toggle")
	UI.slider(section, "InfiniteJumpBoost", "Infinite Jump Boost", { Default = 50, Min = 0, Max = 500, Suffix = "/s", Rounding = 0 })

	UI.toggle(section, "AutoSprint", "Auto Sprint", false)
	UI.toggle(section, "AutoSprintOnCrouch", "Auto Sprint On Crouch", false)
	UI.toggle(section, "AutoSprintDelay", "Auto Sprint Delay", false)
	UI.slider(section, "AutoSprintDelayTime", "Auto Sprint Delay Time", { Default = 0.2, Min = 0, Max = 5, Suffix = "s", Rounding = 2 })

	UI.button(section, "Respawn Character", function()
		local character = players.LocalPlayer.Character
		if not character then
			return
		end

		local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
		if not humanoidRootPart then
			return
		end

		character:PivotTo(humanoidRootPart.CFrame * CFrame.new(0, 10000000, 0))
	end)

	local function dealSelfFallDamage()
		local remote = KeyHandling.getRemote("FallDamage")
		if not remote then
			return Logger.notify("Failed to find fall damage remote.")
		end

		remote:FireServer(Configuration.expectOptionValue("FallDamageAmount") or 0.0, false)
	end

	UI.button(section, "Deal Fall Damage To Self", dealSelfFallDamage)

	UI.label(section, "Deal Fall Damage Keybind")
	UI.keybind(section, "DealFallDamageKeybind", "Deal Fall Damage To Self", "N/A", function()
		dealSelfFallDamage()
	end)

	UI.slider(section, "FallDamageAmount", "Fall Damage Amount", { Default = 50, Min = 0, Max = 1000, Suffix = "hp", Rounding = 0 })
end

