---@param section table
function GameTab.initPlayerMonitoringSection(section)
	UI.toggle(section, "NotifyMod", "Mod Notifications", true)
	UI.toggle(section, "NotifyModSound", "Mod Notification Sound", false)
	UI.slider(section, "NotifyModSoundVolume", "Sound Volume", { Default = 10, Min = 0, Max = 20, Suffix = "v", Rounding = 2 })

	UI.toggle(section, "NotifyVoidWalker", "Void Walker Notifications", false)

	UI.toggle(section, "NotifyItems", "Item Notifications", false)
	local notifyItemsList = UI.dropdown(section, "NotifyItemsList", "Item List", { Default = {}, SaveValues = true, Multi = true, Values = {} })
	local itemLabel = UI.input(section, "NotifyItemsLabel", "Item Name", "Partial or exact item name.")

	UI.button(section, "Add Name To Filter", function()
		local itemLabelValue = itemLabel.Value

		if #itemLabelValue <= 0 then
			return Logger.notify("Please enter a valid item name.")
		end

		local notifyItemsListValues = notifyItemsList.Values

		if not table.find(notifyItemsListValues, itemLabelValue) then
			table.insert(notifyItemsListValues, itemLabelValue)
		end

		notifyItemsList:SetValues(notifyItemsListValues)
