---@module Features.Automation.EchoFarm
local EchoFarm = require("Features/Automation/EchoFarm")

---@module Features.Automation.AutoLayer2
local AutoLayer2 = require("Features/Automation/AutoLayer2")

---@module Features.Automation.AutoAuthority
local AutoAuthority = require("Features/Automation/AutoAuthority")

---@module Features.Automation.AutoDuke
local AutoDuke = require("Features/Automation/AutoDuke")

---@module Features.Automation.AutoMooneyrie
local AutoMooneyrie = require("Features/Automation/AutoMooneyrie")

---@module Features.Automation.AutoNotes
local AutoNotes = require("Features/Automation/AutoNotes")

---@module Features.Automation.AutoSaramed
local AutoSaramed = require("Features/Automation/AutoSaramed")

---@module Menu.AutoBuilderWindow
local AutoBuilderWindow = require("Menu/AutoBuilderWindow")

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Features.Automation.Objects.AutoLog
local AutoLog = require("Features/Automation/Objects/AutoLog")

---@module Menu.UI
local UI = require("Menu/UI")

---Add a per-automation "Auto Log Distance" slider (0-2000; 0 = off) to a section. The value is saved per
---automation in the AutoLog store (NOT in luma config saves): kept out of config saves (Library.NoSave),
---loaded from disk as the slider's default, and written back on every change.
---@param section table
---@param flag string unique Options key for the slider
---@param storeKey string automation id the distance is saved under
local function addAutoLogSlider(section, flag, storeKey)
	Library.NoSave[flag] = true
	return UI.slider(section, flag, "Auto Log Distance", {
		Min = 0,
		Max = 2000,
		Rounding = 0,
		Default = AutoLog.get(storeKey),
		Suffix = " studs",
		Callback = function(value)
			AutoLog.set(storeKey, value)
		end,
	})
end

---Per-automation tween (movement) speed slider. Default 100, range 50-300. Saved in configs normally.
---@param section table
---@param flag string unique Options key for the slider
local function addTweenSpeedSlider(section, flag)
	return UI.slider(section, flag, "Tween Speed", { Default = 100, Min = 50, Max = 300, Rounding = 0, Suffix = " studs/s" })
end

local function addAuthorityMissionToggle(section, flag, label, key)
	local saved = PersistentData.get("authorityMissionToggles")
	local default = true
	if type(saved) == "table" and type(saved[key]) == "boolean" then
		default = saved[key]
	end
	Library.NoSave[flag] = true
	return UI.toggle(section, flag, label, default, function(value)
		local current = PersistentData.get("authorityMissionToggles")
		if type(current) ~= "table" then
			current = {}
		end
		current[key] = value == true
		PersistentData.set("authorityMissionToggles", current)
	end)
end

---@param section table
function AutomationTab.initAttributeSection(section)
	local autoCharisma = UI.toggle(section, "AutoCharisma", "Auto Charisma Farm", false, function(enabled)
		Library:SetAutomationActive("AutoCharisma", enabled)
	end)
	UI.bind(autoCharisma, "N/A", "Toggle")
	UI.input(section, "CharismaCap", "Charisma Cap", nil, "75")

	local autoIntelligence = UI.toggle(section, "AutoIntelligence", "Auto Intelligence Farm", false, function(enabled)
		Library:SetAutomationActive("AutoIntelligence", enabled)
	end)
	UI.bind(autoIntelligence, "N/A", "Toggle")
	UI.input(section, "IntelligenceCap", "Intelligence Cap", nil, "75")
end

---@param section table
function AutomationTab.initFishFarmSection(section)
	local autoFish = UI.toggle(section, "AutoFish", "Auto Fish Farm", false, function(enabled)
		Library:SetAutomationActive("AutoFish", enabled)
	end)
	UI.bind(autoFish, "N/A", "Toggle")
end

---@param section table
function AutomationTab.initDebuggingSection(section)
	UI.button(section, "Start Deflect", function()
		QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_DEFLECT, "StartDeflect", nil)
	end)

	UI.button(section, "Start Deflect 0.1s", function()
