	UI.button(section, "Add Item Name To Filter", function()
		local itemName = itemNameInput.Value
		if #itemName <= 0 then
			return Logger.notify("Please enter a valid item name.")
		end

		local values = itemNameList.Values
		if not table.find(values, itemName) then
			table.insert(values, itemName)
		end

		itemNameList:SetValues(values)
		itemNameList:SetValue({})
		itemNameList:Display()
	end)

	UI.button(section, "Remove Selected Item Names", function()
		local values = itemNameList.Values
		local value = itemNameList.Value

		for selected, _ in next, value do
			local index = table.find(values, selected)
			if not index then
				continue
			end

			table.remove(values, index)
		end

		itemNameList:SetValues(values)
		itemNameList:SetValue({})
		itemNameList:Display()
	end)
end

---@param section table
function AutomationTab.initAutoBuilderSection(section)
	-- The tab only holds the link box + load button. The loaded build's stats, talents and mantras
	-- (preshrine on the left, postshrine on the right) live in a separate window that Load opens.
	local linkInput = UI.input(section, "AutoBuilderLink", "Builder Link", "deepwoken.co/builder?id=...")

	UI.button(section, "Load Build", function()
		local build = AutoBuilder.load(linkInput.Value)
		local classified = AutoBuilder.classified

		if build and classified then
			AutoBuilderWindow.show(build, classified)
		end
	end)

	-- A Mantra Hand always contains a special "Roll 2" card that grants 2 Talents instead of a Mantra.
	UI.toggle(section, "AutoBuilderOnlyRoll2", "Only Roll 2 For Mantras", false)

	-- Start/Stop button: shows "Start Preshrine"/"Start Postshrine" per the selected target, flips to
	-- "Stop" while picking is running. (The old DoubleClick arm is dropped; one branching callback instead.)
	local startButton
	local function startLabel()
		return AutoBuilder.target == "post" and "Start Postshrine" or "Start Preshrine"
	end

	local function applyState()
		if not startButton then
			return
		end
		startButton.Text = AutoBuilder.picking and "Stop" or startLabel()
	end

	startButton = UI.button(section, startLabel(), function()
		if AutoBuilder.picking then
			AutoBuilder.stopPicking()
		else
			AutoBuilder.startPicking()
		end
		applyState()
	end)

	-- Keep the button in sync with target changes (from the window) and start/stop (incl. a hop resume).
	AutoBuilder.onStateChanged = applyState

	applyState()
end

---@param section table
function AutomationTab.initAutoProgSection(section)
	local linkInput = UI.input(section, "AutoProgLink", "Builder Link", "deepwoken.co/builder?id=...")

	UI.button(section, "Load Build", function()
		local build = AutoBuilder.load(linkInput.Value)
		local classified = AutoBuilder.classified

		if build and classified then
			AutoBuilderWindow.show(build, classified)
		end
	end)

	UI.dropdown(section, "AutoProgFarmMethod", "Method", { Values = { "Ferryman", "Saramed" }, Default = "Ferryman" })
	UI.slider(section, "AutoProgAttachDistance", "Attach Distance", {
		Min = 1,
		Max = 30,
		Rounding = 0,
		Default = 12,
		Suffix = " studs",
		Callback = AutoProg.setAttachDistance,
	})
	UI.toggle(section, "AutoProgUseAttunementMantras", "Use Attunement Mantras", false)

	local excludedMantras = UI.dropdown(section, "AutoProgExcludedMantras", "Mantras to Exclude", {
		Values = {},
		Default = {},
		SaveValues = true,
		Multi = true,
		AllowNull = true,
	})
	local excludedMantraInput = UI.input(section, "AutoProgExcludedMantraInput", "Mantra Name", "Exact mantra name.")

	UI.button(section, "Add Mantra To Exclusion Filter", function()
		local name = tostring(excludedMantraInput.Value or ""):match("^%s*(.-)%s*$")
		if name == "" then
			return Logger.notify("Please enter a valid mantra name.")
		end

		local values = excludedMantras.Values
		local selected = excludedMantras.Value or {}
		if not table.find(values, name) then
			table.insert(values, name)
		end
		selected[name] = true

		excludedMantras:SetValues(values)
		excludedMantras:SetValue(selected)
		excludedMantras:Display()
	end)

	local function refreshMantras()
		local player = game:GetService("Players").LocalPlayer
		local values = excludedMantras.Values
		local selected = excludedMantras.Value
		local known = {}
		for _, name in ipairs(values) do
			known[name] = true
		end

		local function collect(container)
			if not container then return end
			for _, tool in ipairs(container:GetChildren()) do
				if tool:IsA("Tool") and tool.Name:find("Mantra:", 1, true)
					and not tool.Name:find("RecalledMantra:", 1, true) then
					local name = tool:GetAttribute("DefaultName")
					if type(name) == "string" and not known[name] then
						known[name] = true
						table.insert(values, name)
					end
				end
			end
		end

		collect(player and player:FindFirstChildOfClass("Backpack"))
		collect(player and player.Character)
		excludedMantras:SetValues(values)
		excludedMantras:SetValue(selected)
		excludedMantras:Display()
	end

	refreshMantras()
	UI.button(section, "Refresh Mantra Filter", refreshMantras)

	UI.button(section, "Start Preshrine", AutoProg.startPreshrine)
	UI.button(section, "Start Postshrine", AutoProg.startPostshrine)
	UI.button(section, "Stop", AutoProg.stop)
end

