function AutomationTab.init(window)
	-- Single page, no subtabs: every automation section stacks on one scrolling tab (balanced columns).
	local tab = window:AddTab("Auto", "bot")

	tab:AddBanner("WARNING: USING AUTOMATIONS THAT FLY FOR LONG PERIODS OF TIME CAN GET YOUR ACCOUNT FLAGGED. USE AT YOUR OWN RISK.")

	local side = "left"
	local function sec(title)
		local s = tab:AddSection(side, title)
		side = (side == "left") and "right" or "left"
		return s
	end

	AutomationTab.initGeneralSection(sec("General"))
	AutomationTab.initFishFarmSection(sec("Fish Farm"))
	AutomationTab.initAttributeSection(sec("Attribute Farm"))
	AutomationTab.initAutoLootSection(sec("Auto Loot"))

	AutomationTab.initAutoFerrymanSection(sec("Auto Ferryman"))
	AutomationTab.initAutoTo1Section(sec("Auto To1"))
	AutomationTab.initAutoSaramedSection(sec("Auto Saramed"))
	AutomationTab.initAutoMooneyrieSection(sec("Auto Mooneyrie"))
	AutomationTab.initEchoFarmSection(sec("Echo Farm"))
	AutomationTab.initAutoNotesSection(sec("Auto Notes"))

	AutomationTab.initAutoVoISection(sec("Auto VoI"))
	AutomationTab.initAutoTitusSection(sec("Auto Titus"))
	AutomationTab.initAutoLayer2Section(sec("Auto L2"))
	AutomationTab.initAutoAuthoritySection(sec("Auto Authority"))
	AutomationTab.initAutoDukeSection(sec("Auto Duke"))

	AutomationTab.initAutoBuilderSection(sec("Auto Builder"))
	AutomationTab.initAutoProgSection(sec("Auto Prog"))
end

return AutomationTab

end)
