---@param section table
function CombatTab.initAntiBreakerSection(section)
	-- Confirm before enabling: Anti-AP Breaker degrades your AP, so require explicit acceptance. The
	-- toggle snaps back off immediately and only re-enables on Confirm. `suppress` is cleared inside the
	-- callback (not after :Set) because this library fires toggle callbacks on a deferred thread.
	local suppress = false
	local dialogOpen = false
	local toggle
	toggle = UI.toggle(section, "AntiBreakerEnabled", "Anti-AP Breaker", false, function(state)
		if suppress then
			suppress = false
			return
		end
		if not state then
			return
		end
		suppress = true
		toggle:Set(false)
		if dialogOpen then
			return
		end
		dialogOpen = true
		confirmDialog("Anti-AP Breaker", "THIS WILL MAKE AP SIGNIFICANTLY WORSE", function(confirmed)
			dialogOpen = false
			if confirmed then
				suppress = true
				toggle:Set(true)
			end
		end)
	end)
	UI.bind(toggle, "N/A", "Toggle")

	UI.toggle(section, "AntiBreakerNotify", "Ap Break Notifications", false)
end

---@param tol table timing override list dropdown handle
local function refreshTimingOverrideList(tol)
	local overrideData = Library.OverrideData
	if not overrideData or not tol then
		return
	end

	local values = {}
	for rname, _ in next, overrideData do
		values[#values + 1] = rname
	end

	tol:SetValues(values)
end

---@param callback function
---@return function
local function timingOverrideCallback(callback)
	return function()
		local overrideData = Library.OverrideData
		if not overrideData then
			return false
		end

		local selectedTo = Configuration.expectOptionValue("TimingOverrideList")
		if not selectedTo or #selectedTo == 0 then
			return false
		end

		local override = overrideData[selectedTo]
		if not override then
			return false
		end

		callback(override)
	end
end

---@param section table
function CombatTab:initTimingsSection(section)
	self.tol = UI.dropdown(section, "TimingOverrideList", "Timing Override List", {
		Values = {},
		SaveValues = false,
		Multi = false,
		AllowNull = true,
		Searchable = true,
		Callback = function()
			self.dashInsteadOfParryRate:SetRawValue(0)
			self.failureRate:SetRawValue(0)
			self.ignoreAnimationEndRate:SetRawValue(0)
			self.reactToFeintsRate:SetRawValue(0)

			local overrideData = Library.OverrideData
			if not overrideData then
				return false
			end

			local selectedTo = Configuration.expectOptionValue("TimingOverrideList")
			if not selectedTo or #selectedTo == 0 then
				return false
			end

			local override = overrideData[selectedTo]
			if not override then
				return false
			end

			self.dashInsteadOfParryRate:SetRawValue(override.dipr or 0)
			self.failureRate:SetRawValue(override.fr or 0)
			self.ignoreAnimationEndRate:SetRawValue(override.iaer or 0)
			self.reactToFeintsRate:SetRawValue(override.rtfr or 0)
		end,
	})

	UI.divider(section)

	local names = {}
	local plist = { SaveManager.as, SaveManager.es, SaveManager.ss, SaveManager.ps }

	for _, pair in next, plist do
		for _, timing in next, pair:list() do
			names[#names + 1] = timing.name
		end
	end

	table.sort(names)

	self.ti = UI.dropdown(section, "TimingOverrideTimingList", "Timing List", {
		Values = names,
		Multi = false,
		AllowNull = true,
		Searchable = true,
	})

	UI.button(section, "Add Timing Override", function()
		if Library.OverrideData[self.ti.Value] then
			return Logger.notify("A timing override with that name already exists.")
		end

		local override = {
			fr = self.failureRate.Value,
			dipr = self.dashInsteadOfParryRate.Value,
			iaer = self.ignoreAnimationEndRate.Value,
			rtfr = self.reactToFeintsRate.Value,
		}

		Library.OverrideData[self.ti.Value] = override

		refreshTimingOverrideList(self.tol)

		self.tol:SetValue(self.ti.Value)
		self.tol:Display()
	end)

	UI.button(section, "Remove Selected Override", function()
		Library.OverrideData[self.tol.Value] = nil

		refreshTimingOverrideList(self.tol)

		self.tol:SetValue(nil)
		self.tol:Display()
	end)

	refreshTimingOverrideList(self.tol)
end

