---@param window table
function CombatTab.init(window)
	local tab = window:AddTab("Combat", "swords", {
		Pages = {
			{ Name = "Defense" },
			{ Name = "Targeting" },
			{ Name = "Assist" },
			{ Name = "Override" },
			{ Name = "Spoofers" },
		},
	})

	-- Defense page
	local autoDefenseToggle = CombatTab.initDefenseSection(tab:AddSection("left", "Auto Defense", "Defense"))
	CombatTab.initHumanizationSection(tab:AddSection("right", "Humanization", "Defense"), autoDefenseToggle)
	-- AP Breaker + Anti-AP Breaker now live under Auto Defense (the standalone Anti-Exploit tab was removed).
	CombatTab.initApBreakerSection(tab:AddSection("left", "AP Breaker", "Defense"))
	CombatTab.initAntiBreakerSection(tab:AddSection("right", "Anti-AP Breaker", "Defense"))

	-- Targeting page
	CombatTab.initCombatTargetingSection(tab:AddSection("left", "Targeting", "Targeting"))
	CombatTab.initCombatWhitelistSection(tab:AddSection("right", "Whitelist", "Targeting"))

	-- Assist page
	CombatTab.initAttackAssistanceSection(tab:AddSection("left", "Attack Assistance", "Assist"))
	CombatTab.initCombatAssistance(tab:AddSection("right", "Combat Assistance", "Assist"))
	CombatTab.initSilentAimSection(tab:AddSection("left", "Silent Aim", "Assist"))

	local extras = tab:AddSection("right", "Extras", "Assist")
	UI.toggle(extras, "AutoExtinguishFire", "Auto Extinguish Fire", false)
	local easyMantraFeint = UI.toggle(extras, "EasyMantraFeint", "Easy Mantra Feint", false)
	UI.bind(easyMantraFeint, "N/A", "Toggle")
	local easyRollCancel = UI.toggle(extras, "EasyRollCancel", "Easy Roll Cancel", false)
	UI.bind(easyRollCancel, "N/A", "Toggle")

	-- Override page
	CombatTab:initProbabilitiesSection(tab:AddSection("left", "Probabilities", "Override"))
	CombatTab:initTimingsSection(tab:AddSection("right", "Timing Overrides", "Override"))

	-- Spoofers page (GameTab provides this section)
	local GameTab = require("Menu/GameTab")
	GameTab.initSpoofersSection(tab:AddSection("left", "Spoofers", "Spoofers"))
end

return CombatTab

